  val nextRooms: ListBuffer[Room] = new ListBuffer[Room]
  var memo: mutable.HashMap[Int, Double] = new mutable.HashMap()

  def addNext(next: Room): Unit = {
    nextRooms += next
  }

  def expectation(aoki: Int): Double = {
    memo.getOrElseUpdate(aoki,
