const double PI = acos(-1);

vector<int> g[605];

int n, m;
const double INF = 1e9;

double memo1[605];
int maxV[605];
double solve1(int u) {
  double &res = memo1[u];
  if(res < 0) {
    if(u == n-1) {
      res = 0;
    } else {
      res = 0;
      for(int v : g[u]) {
        double cur = solve1(v);
        if(maxV[u] == -1 || solve1(maxV[u]) < cur) {
          maxV[u] = v;
        }
        res += cur + 1;
      }
      res /= g[u].size();
    }
  }
  return res;
}

double memo2[605][605];
double solve2(int u, int x) {
  double &res = memo2[u][x];
  if(res < 0) {
    if(u == n-1) {
      res = 0;
    } else if(x < u) {
      res = solve1(u);
    } else {
      res = 0;
      for(int v : g[u]) {
        if(u == x && maxV[u] == v) {
          continue;
        }
        double cur = solve2(v, x);
        res += cur + 1;
      }
      if(res == 0) { // forbidden
        res = INF;
      }
      res /= u == x ? (int)g[u].size() - 1 : (int)g[u].size();
    }
  }
  return res;
}

int main(void) {
  scanf("%d%d", &n, &m);
  REP(i, m) {
    int s, t;
    scanf("%d%d", &s, &t);
    --s;
    --t;
    g[s].push_back(t);
  }
  REP(i, n) {
    memo1[i] = -1;
    maxV[i] = -1;
    REP(j, n) {
      memo2[i][j] = -1;
    }
  }
  double res = solve1(0);
  // REP(i, n) {
  //   cerr << "> " << i << ": " << maxV[i] << " " << memo1[i] << endl;
  // }
  REP(i, n) {
    double cur = solve2(0, i);
    // cerr << ">> " << i << " : " << cur << endl;
    if(cur < res) {
      res = cur;
    }
  }
  printf("%.10f\n", res);

  return 0;
}

