vector<double> solve_expected(const vec<int, 2>& G) {
  int N = G.size();
  vector<double> dp(N, 0);
  dp[N - 1] = 0;
  for (int i = N - 2; i >= 0; i--) {
    for (int j : G[i]) dp[i] += dp[j];
    dp[i] /= G[i].size();
    dp[i] += 1;
  }
  return dp;
}

vector<double> solve_coef(const vec<int, 2>& G) {
  int N = G.size();
  vector<double> dp(N, 0);
  dp[0] = 1;
  for (int i = 0; i < N; i++) {
    for (int j : G[i]) dp[j] += dp[i] / G[i].size();
  }
  return dp;
}

int main() {
#ifdef DEBUG
  ifstream ifs("in.txt");
  cin.rdbuf(ifs.rdbuf());
#endif
  int N, M;
  while (cin >> N >> M) {
    vec<int, 2> G(N);
    for (int i = 0; i < M; i++) {
      int a, b;
      cin >> a >> b;
      --a;
      --b;
      G[a].push_back(b);
    }
    auto exp = solve_expected(G);
    auto coef = solve_coef(G);
    double res = exp[0];
    for (int i = 0; i < N; i++) {
      if (G[i].size() <= 1) continue;
      double expsum = 0;
      for (int j : G[i]) expsum += exp[j];
      for (int j : G[i]) {
        double oldVal = exp[i];
        double newVal = (expsum - exp[j]) / (G[i].size() - 1) + 1;
        double score = exp[0] + coef[i] * (newVal - oldVal);
        chmin(res, score);
      }
    }
    printf("%.20f\n", res);
  }
  return 0;
}

