double solve(int pos) {
	if (pos == N - 1)return 0.0;
	if (E_flag[pos])return E[pos];
	double ans = 0.0;
	for (int x : graph[pos])ans += solve(x);
	E_flag[pos] = 1;
	E[pos] = 1.0 + (ans / double(graph[pos].size()));
	return E[pos];
}

double solve2(int pos, int s, int t) {
	if (pos == N - 1)return 0.0;
	if (E_flag2[pos])return E2[pos];

	double ans = 0.0;

	if (pos < s) {
		for (int x : graph[pos])ans += solve2(x, s, t);
	}
	else if (pos == s) {
		for (int x : graph[pos]) {
			if (x != t)ans += solve(x);
		}
	}
	else {
		for (int x : graph[pos])ans += solve(x);
	}


	E_flag2[pos] = 1;
	E2[pos] = 1.0 + (ans / double(graph[pos].size() - (pos == s ? 1 : 0)));
	return E2[pos];
}

