void solve() {
  int n, m;
  cin >> n >> m;
  vector<vector<int> > G(n), G2(n);
  rep(i, m) {
    int a, b;
    cin >> a >> b;
    a--; b--;
    G[a].eb(b);
    G2[b].eb(a);
  }

  vector<double> dp(n);
  for (int i = n - 2; i >= 0; --i) {
    for (int nv : G[i]) {
      dp[i] += dp[nv];
    }
    dp[i] /= sz(G[i]);
    ++dp[i];
  }
  double ans = dp[0];

  rep(i, n) { // 始点iの辺を消す
    if (sz(G[i]) <= 1) continue;
    // dp[i] += dp[nv]において, dp[nv]最大の辺を消す
    vector<double> e;
    for (int nv : G[i]) e.eb(dp[nv]);
    sort(all(e));
    e.pop_back();

    vector<double> dp2(n);
    // 頂点iのdpの値は先に決める
    rep(j, sz(e)) dp2[i] += e[j];
    dp2[i] /= sz(e);
    ++dp2[i];

    for (int j = n - 2; j >= 0; --j) {
      if (j == i) continue;
      for (int nv : G[j]) dp2[j] += dp2[nv];
      dp2[j] /= sz(G[j]);
      ++dp2[j];
    }
    chmin(ans, dp2[0]);
  }
  cout << ans << endl;
}

