using namespace std;
using ll = long long;

ll N, M;
ll dels=-1, delt=-1;

double updatedp(vector<vector<ll>> &g,vector<double> &dp,ll v){
	if(v==N-1)return 0.;
	if(dp[v]>-0.1)return dp[v];
	double ans=0.;
	ll gvsize=g[v].size();
	for(ll nextv:g[v]){	
		if(v==dels && nextv==delt){
			gvsize--;
			continue;
		}
		ans+=updatedp(g,dp,nextv);
	}
	return dp[v]=1.+ans/gvsize;
}

