	vector<double> dptmp(N,-1.);
	double ans=updatedp(g,dptmp,0);

	vector<pair<ll,ll>> delpath;
	for(ll v=0;v<N;v++){
		if(g[v].size()==1)continue;
		double maxval=0.;
		ll tmps=-1,tmpt=-1;
		for(ll nextv:g[v]){
			if(maxval<dptmp[nextv]){
				maxval=dptmp[nextv];
				tmps=v;
				tmpt=nextv;
			}
		}
