	void dijkstra(int posStart) {
		val(posStart).dis = 0;
		std::multimap<int, VertexTmp>q;		//累計距離->頂点
		const int N = vertex.size();
		for (auto& edge : vertex[posStart].edges) {
			q.insert({ edge.w + val(posStart).dis ,VertexTmp{edge.next,posStart} });
