	//有向グラフであっても動作
	std::vector<std::vector<int>> warshallFloyd() {
		const int N = vertex.size();
		std::vector<std::vector<int>> res(vertex.size());
		for (int i = 0; i < N; ++i) {
			res[i].resize(N);
			for (int j = 0; j < N; ++j) {
				res[i][j] = INF;
			}
		}
		for (int i = 0; i < N; ++i) {
			for (auto& e : vertex[i].edges) {
				res[i][e.next] = e.w;
			}
		}
		for (int k = 0; k < N; k++) {       // 経由する頂点
			for (int i = 0; i < N; i++) {    // 始点
				for (int j = 0; j < N; j++) {  // 終点
					res[i][j] = min(res[i][j], res[i][k] + res[k][j]);
				}
			}
		}
		return res;
	}
	//二部グラフであるかの判定(O(V+E)？)
	//二部グラフの場合は白い頂点のid配列を返す
	//二部グラフじゃない場合は空
	std::vector<int> bipartiteGraph() {
		std::vector<int>res;
		const int N = vertex.size();
		std::vector<int> color(N, -1);
		function<bool(int, int, int)> dfs = [&](int u, int prev, int c) {
			color[u] = c;
			if (c == 1) {
				res.push_back(u);
			}
			for (auto& edge : vertex[u].edges) {
				int v = edge.next;
				if (v == prev)continue;
				if (color[v] == -1) {
					if (!dfs(v, u, 1 - c)) return false;
				}
				else if (color[v] != 1 - c) {
					return false;
				}
			}
			return true;
		};
		if (!dfs(0, -1, 0)) return {};
		return res;
	}
