	// 始点からの到達確率pを求める
	p[0] = 1.0;
	for (int i = 0; i < N; ++i)
	{
		const int d = SZ(adj[i]);
		for (int next : adj[i])
		{
			p[next] += p[i] / d;
		}
	}

	// 何もしないときの歩数の期待値eを求める
	double shortcut = 0.0;
	for (int i = N - 1; i >= 0; --i)
	{
		const int d = SZ(adj[i]);
		if (d > 0)
		{
			double sum = 0.0;
			double hi = 0.0;	// 最も次へいくのを防ぎたい場所の歩数期待値
			for (int next : adj[i])
			{
				sum += e[next];
				amax(hi, e[next]);
			}

			e[i] = 1 + sum / d;
			if (d > 1)
			{
				double blocked = 1 + (sum - hi) / (d - 1.0);
				amax(shortcut, p[i]*(e[i]- blocked));
			}
		}
	}





	printf("%.16f\n", e[0]-shortcut);

	return 0;
