void pre_dfs(ll now, ll par = -1){
    if(flag[now])return ;
    ld c = graph[now].size();
    // if(c == 0)return ;
    for(auto &to : graph[now]){
        pre_dfs(to, now);
        sub[now] += (sub[to] + 1.0) / c;
    }
    flag[now] = 1;
}

void dfs(ll now){
    if(flag[now])return ;
    ld c = graph[now].size();
    // if(c == 0)return ;
    dp[now] = 0.0;
    for(auto &to : graph[now]){
        dfs(to);
        dp[now] += (dp[to] + 1.0) / c;
    }
    flag[now] = 1;
}
