double slove(int p){
    dp[n]=0;
    for(int i=n-1;i>=1;i--){
        int all=G[i].size();
        if(!all||(i==p&&all==1)){dp[i]=0x3f3f3f3f;continue;};
        double MAX=0,ret=0;
        for(int j=0;j<all;j++){
            MAX=max(dp[G[i][j]]+1,MAX);
            ret+=1/double(all-(i==p))*(dp[G[i][j]]+1);
        }
        if(i==p)ret-=1/double(all-1)*MAX;
        dp[i]=ret;
    }
    return dp[1];
}

