long double cal()
{
    for(int i=0;i<=n;i++) dp[i]=0,psb[i]=0,vis[i]=false;
    psb[1]=1;
    vis[1]=true;
    bool f=true;
    for(int i=1;i<n;i++)
    {
        if(vis[i]==false) continue;
        int num=0;
        for(int j=0;j<g[i].size();j++) if(g[i][j].se) num++;
        if(num==0)
        {
            f=false;
            break;
        }
        long double x=1.0/num;
        for(int j=0;j<g[i].size();j++)
        {
            if(g[i][j].se==false) continue;
            vis[g[i][j].fi]=true;
            dp[g[i][j].fi]+=(dp[i]+psb[i])*x;
            psb[g[i][j].fi]+=psb[i]*x;
        }
    }
    if(vis[n]&&f)return dp[n];
    else return -1;
}
