double dfs(int node) {
    if(cached[node]) return dp[node];
    else cached[node] = true;

    if(node == n) {
        cached[node] = true;
        return 0.0;
    }

    double to = 0, max1 = 0;
    for(auto x: graph[node]) {
        double temp = dfs(x);
        to += temp;
        max1 = max(max1, temp);
    }
    int cnt = graph[node].size();
