int n;
long double memo[666][2];
bool done[666][2],g[666][666];

long double solve(int v, int t){
	int i,c=0;
	long double s=0.0,m=-INF;
	if(done[v][t]){
		return memo[v][t];
	}
	done[v][t] = true;
	if(v==(n-1)){
		return memo[v][t] = 0.0;
	}
	for(i=v; i<n; ++i){
		if(!g[v][i]){
			continue;
		}
		s += solve(i,0);
		++c;
	}
	if(!t){
		memo[v][t] = s/c+1.0;
		return memo[v][t];
	}
	memo[v][t] = INF;
	for(i=v; i<n; ++i){
		if(!g[v][i]){
			continue;
		}
		memo[v][t] = min(memo[v][t],(s-solve(i,0)+solve(i,1))/c);
		m = max(m,solve(i,0));
	}
	if(c>1){
		memo[v][t] = min(memo[v][t],(s-m)/(c-1));
	}else{
		memo[v][t] = min(memo[v][t],INF);
	}
	memo[v][t] += 1.0;
	return memo[v][t];
}

