    auto sorted_nodes = ts.sort();

    edges.push_back({INF, INF});

    double ret = 1e18;
    for (auto e : edges) {
        int s = e.from;
        int t = e.to;

        vector<double> dp(N, INF);
        dp[0] = 0;
        for (int node : sorted_nodes) {
            int num = 0;
            int sum = 0;

            for (int from : froms[node]) {
                if (from == s && node == t) continue;
                if (dp[from] >= INF) continue;
                ++num;
                sum += dp[from] + 1.0;
            }

            if (num > 0 && dp[node] == INF) dp[node] = 0;
            if (num > 0) dp[node] += 1.0 * sum / num;
        }

