/*
      x: 1001 1010  1100 1011 1101  1111
x & ~ x: 0001 0010  0100 0001 0001  0001
    sum: 1010 1100 10000 1100 1100 10000

####### Attention #######
S | (1 << i) -> S union {i}
S & ~(1 << i) -> S - {i}

# inclusion-exclusion principle
|U[i = 1 to n] Ai| = sum[i = 1 to n] |Ai| - sum[i < j]|Ai ^ Aj| + ... + (-1)^(n - 1) |^[i = 1 to n]Ai|
*/

const ll MAX_N = 200005;
const size_t MAX_BIT = 160 * 160 + 10;
typedef bitset<MAX_BIT> bts;
typedef vector<bts> vbt;
typedef vector<vbt> vbt2;
typedef vector<vbt2> vbt3;
const bool multiple_queries = false;

void solve(){
    // generate_array(size, min, max);
    ll n, m; in2(n, m);
    Graph graph(n);
    vpl paths(m);
    rep(i, m){
        ll a, b; in2(a, b); a--, b--;
        graph[a].pb({b, 1});
        paths[i] = {a, b};
    }

    vector<ld> dp(n, -1); dp[n - 1] = 0;
    auto dfs = [&](auto dfs, ll src, ll rm) -> ld{
        if (dp[src] > -EPS) return dp[src];
        ld ret = 0; ll a = -1, b = -1, deg = 0;
        if (rm != -1) tie(a, b) = paths[rm];
        for (auto& e: graph[src])
            if (a != src || b != e.to)
                ret += dfs(dfs, e.to, rm) + 1, deg++;

        return dp[src] = deg != 0 ? ret / ld(deg) : MOD;
    };

    dfs(dfs, 0, -1); ld ans = dp[0];
    rep(i, m){
        fill(all(dp), -1); dp[n - 1] = 0;
        dfs(dfs, 0, i);
        chmin(ans, dp[0]);
    }
    prl_nd(ans, 12);

    // ### DEBUG PART ###
    auto naive_solver = [&](){
    };
    #ifdef _LOCAL
        naive_solver();
    #endif
}

void test(ll num = 0, bool verbose = false){
    rep(i, max(1LL, num)){
        ll t = clock();
        if (verbose) prl4("\n#####", i + 1, "#####", "\n## Answer ##");
        solve();
        if (verbose) {prl(""); prl_time(t);}
    }
}

