int N;
vector<int> adjlist[599];
double dptable[600];
double dp(int v) {
	if (dptable[v] > -0.5) return dptable[v];
	if (v == N - 1) return dptable[v] = 0;
	dptable[v] = 0;
	for (int i: adjlist[v]) dptable[v] += dp(i) / adjlist[v].size();
	return ++dptable[v];
}
int main() {
	int M, s, t;
	scanf("%d %d", &N, &M);
	for (int i = 0; i < M; ++i) {
		scanf("%d %d", &s, &t);
		adjlist[s - 1].push_back(t - 1);
	}
	for (int i = 0; i < N; ++i) dptable[i] = -1;
	double ans = dp(0);
	for (int i = 0; i < N - 1; ++i) {
		for (int j = 0; j < N; ++j) dptable[j] = -1;
		if (adjlist[i].size() > 1) {
			double temp = 0, maxval = 0;
			for (int j: adjlist[i]) {
				temp += dp(j);
				maxval = max(maxval, dp(j));
			}
			temp -= maxval;
			temp /= (adjlist[i].size() - 1);
			dptable[i] = temp + 1;
			ans = min(ans, dp(0));
		}
	}
	printf("%.9lf", ans);
	return 0;
}

