int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N, M; cin >> N >> M;
    vector<vector<int>> G(N);
    for (int i = 0; i < M; i++) {
        int S, T; cin >> S >> T; S--, T--;
        G[S].push_back(T);
    }
    vector<double> X(N), P(N);
    P[0] = 1.0;
    for (int node = 0; node < N; node++) {
        for (auto next : G[node]) {
            P[next] += P[node] / G[node].size();
        }
    }
    X[N - 1] = 0;
    for (int node = N - 2; node >= 0; node--) {
        double sum = 0;
        for (auto next : G[node]) {
            sum += X[next];
        }
        X[node] = 1 + sum / G[node].size();
    }
    double orig = X[0];
    double ans = orig;
    for (int node = N - 2; node >= 0; node--) {
        if (G[node].size() == 1) continue;
        double sum = 0;
        double maxval = 0;
        for (auto next : G[node]) {
            sum += X[next];
            maxval = max(maxval, X[next]);
        }
        double ans2 = orig + P[node] * (-sum / G[node].size() + (sum - maxval) / (G[node].size() - 1));
        ans = min(ans, ans2);
    }
    cout << fixed << setprecision(9) << ans << endl;
    return 0;
}

