vector<ll> top_sort(const vector<vector<ll>> &edges) {
    ll N = edges.size();
	vector<ll> ret;
	vector<bool> road(N);
	vector<bool> used(N);
	function<bool(ll)> dfs = [&](ll now) {
		used[now] = true;
		road[now] = true;
		for(ll nxt : edges[now]) {
			if(road[nxt]) return false;
			if(used[nxt]) continue;
			if(!dfs(nxt)) return false;
		}
		ret.push_back(now);
		road[now] = false;
		return true;
	};
	for(ll i = 0; i < edges.size(); i++) {
		if(used[i]) continue;
		if(!dfs(i)) return vector<ll>(0);
	}
	reverse(ret.begin(), ret.end());
	return ret;
}

const double inf = 5e15;

V<double> memo1, memo2;

double dfs(ll cur, const VV<ll> &edges, V<double> &memo) {
    if(memo[cur] != -inf) return memo[cur];
    memo[cur] = 0;
    ll cnt = edges[cur].size();
    for(ll nxt : edges[cur]) memo[cur] += 1 + dfs(nxt, edges, memo);
    memo[cur] /= cnt;
    return memo[cur];
}

