bool isok(int i,vector<vector<int>> g){
    queue<int> q;
    q.push(0);
    vector<bool> seen(N,false);
    seen[0] = true;
    while (!q.empty())
    {
        int u = q.front();
        q.pop();
        for(int v:g[u]){
            if(u==Edge[i].first && v==Edge[i].second) continue;
            if(seen[v]) continue;
            if(v==N-1) return true;
            seen[v] = true;
            q.push(v);
        }
    }
    return seen[N-1];
}

