double solveG(vector<vector<int>> g){
    vector<double> dp(N+1,0);
    vector<double> pr(N+1,0);
    dp[0] = 0;
    pr[0] = 1;
    for (int i = 0; i < N; i++)
    {
        if(pr[i]==0) continue;
        for(auto u:g[i]){
            pr[u] += pr[i]/g[i].size();
        }
    }


    for (int i = 0; i < N; i++)
    {
        for(auto u:g[i]){
            dp[u] += dp[i]/g[i].size()+pr[i]/g[i].size();
        }
    }
    return dp[N-1];
}

