int main(int argc, char * argv[]) {
    int N, M;
    cin >> N >> M;
    vector<pair<int, int>> P(M);
    for (auto & x : P) {
        cin >> x.first >> x.second;
        x.first -= 1;
        x.second -= 1;
    }

    vector<vector<int>> dir(N);
    for (auto & p : P) {
        dir[p.first].push_back(p.second);
    }

    vector<double> E(N);

    for (int i = N - 2; i >= 0; --i) {
        double sum = 0;
        for (int next : dir[i]) {
            sum += E[next] + 1;
        }
        E[i] = sum / dir[i].size();
    }

    double best_opt = 0;
    map<int, double> deps;
    deps[0] = 1.0;

    while (deps.size() > 0) {
        int i = deps.begin()->first;
        if (dir[i].size() > 1) {
            double sum = 0, worst = -1;
            int worst_at = -1;
            for (int j : dir[i]) {
                if (E[j] > worst) {
                    worst = E[j];
                    worst_at = j;
                }
                sum += E[j];
            }
            double sol2 = (sum - worst) / (dir[i].size() - 1) + 1;
            best_opt = std::max(best_opt, (E[i] - sol2) * deps[i]);
        }
        for (int j : dir[i]) {
            deps[j] += deps[i] / dir[i].size();
        }
        deps.erase(i);
    }

    cout.precision(10);
    cout << E[0] - best_opt << endl;

    return 0;
}

