void execDp(vector<double> &dp,const int n,const vector<vector<int>> &edge){
    for(int i = n - 1; i > 0; i--){
        for(const auto x: edge[i]){
            dp[i] += (dp[x] + 1.0)/(double)edge[i].size();
        }
    }
}

double execDpNonChange(const vector<double> &dp,const int n,const vector<vector<int>> &edge,double minch){
    vector<double> tmpdp = dp;
    tmpdp[n] = minch;
    for(int i = n - 1; i > 0; i--){
        auto itr = lower_bound(edge[i].begin(),edge[i].end(),n+1);
        for(auto e = edge[i].begin(); e != itr; e++){
            tmpdp[i] -= dp[*e]/(double)edge[i].size();
            tmpdp[i] += tmpdp[*e]/(double)edge[i].size();
        }
    }
    return tmpdp[1];
}

