using namespace std;

double calc(vector<int> path[601], int N, int block)
{
    double dp[N + 1];
    dp[N] = 0.0;
    for (int i = N - 1; i >= 1; i--)
    {
        double sum = 0.0;
        double maxval = 0.0;
        int num = path[i].size();
        for (auto j : path[i])
        {
            sum += dp[j];
            if (maxval < dp[j]) maxval = dp[j];
        }
        if (i == block && num > 1)
        {
            sum -= maxval;
            num--;
        }
        dp[i] = sum / num + 1.0;
    }
    return dp[1];
}

void solve()
{
    int N, M;
    vector<int> path[601];
    cin >> N >> M;
    for (int i = 0; i < M; i++)
    {
        int s, t;
        cin >> s >> t;
        path[s].push_back(t);
    }
    double ans = calc(path, N, 1);
    for (int i = 2; i <= N; i++)
    {
        double a = calc(path, N, i);
        if (a < ans) ans = a;
    }
    cout << fixed << setprecision(7) << ans << endl;
}

int main(void)
{
    solve();
    return 0;
}

