  double ans = dp[0];
  rep(i,n){
    int best_to = -1;
    double best = -1;
    if(gSize[i] <= 1) continue;
    for(auto itr = G[i].begin(); itr != G[i].end(); itr++){
      int to = *itr;
      if(dp[to] > best){
        best_to = to;
        best = dp[to];
      }
    }

    double sum_new = 0.0;
    for(auto itr = G[i].begin(); itr != G[i].end(); itr++){
      int to = *itr;
      if(best_to == to) continue;
      sum_new += (dp[to] + 1.0) / (gSize[i] - 1.0);
    }
    func2(i,sum_new,true);

    chmin(ans,dp2[0]);
  }
  cout<<setprecision(10)<<ans<<endl;
  return 0;
}

