                int cnt = 0;
                complex<db> sum (0, 0);
                REP(j, i + 1, n + 1) {
                    if (adj[i][j])sum += expected[j], cnt += 1;
                }
                expected[i] = sum / complex<db> (cnt, 0) + complex<db> (1, 0);
            }
        }
    }

