	matrix<T> B(n, n + 1);
	for (int i = 0; i < n; ++i) {
		for (int j = 0; j < n; ++j) B[i][j] = A[i][j];
		B[i][n] = b[i];
	}
	for (int i = 0; i < n; ++i) {
		int pivot = i;
		for (int j = i; j < n; ++j) {
			if (std::abs(B[j][i]) > std::abs(B[pivot][i])) pivot = j;
			//if (!is_zero(B[j][i])) pivot = j;
		}
		if (i != pivot) swap(B[i], B[pivot]);
		if (is_zero(B[i][i])) return vector<T>(); // no solution
		for (int j = i + 1; j <= n; ++j) B[i][j] /= B[i][i];
		for (int j = 0; j < n; ++j) {
			if (i == j) continue;
			for (int k = i + 1; k <= n; ++k) B[j][k] -= B[j][i] * B[i][k];
		}
	}
	vector<T> x(n);
	for (int i = 0; i < n; ++i) x[i] = B[i][n];
	return x;
}

vector<ld> calc(const graph& G, const vector<int>& deg) {
	const int n = G.size();
	matrix<ld> A(n, n);
	vector<ld> b(n);
	for (int i = 0; i < n - 1; i++) {
		for (int j = 0; j < n; j++) if (G[i][j]) {
			A.get(i, j) = -(ld)1 / deg[i];
		}
		A.get(i, i) = 1;
		b[i] = 1;
	}
	A.get(n - 1, n - 1) = 1;
	auto res = gauss_jordan(A, b);
	assert(!res.empty());
	return res;
}

int main()
{
	cout << fixed << setprecision(8);
	int N, M;
	cin >> N >> M;
	graph G(N, vector<int>(N));
	vector<int> deg(N);
	for (int i = 0; i < M; i++) {
		int s, t;
		cin >> s >> t; --s, --t;
		G[s][t] = 1;
		deg[s]++;
	}
	auto ps = calc(G, deg);
	ld res = ps[0];
	for (int i = 0; i < N; i++) if (deg[i] > 1) {
		ld ma = -1, id = -1;
		for (int j = 0; j < N; j++) if (G[i][j]) {
			if (ps[j] > ma) {
				ma = ps[j];
				id = j;
			}
		}
		G[i][id]--;
		deg[i]--;
		res = min(res, calc(G, deg)[0]);
		G[i][id]++;
		deg[i]++;
	}
	cout << res << endl;
	return 0;
}

