	}

	vector<double> prob(n);
	prob[0] = 1;
	for(int i = 0; i < n - 1; ++i){
		double d = prob[i] / G[i].size();
		for(int t : G[i]){
			prob[t] += d;
		}
	}

	double ans = 0;
	vector<double> exp(n);
	for(int i = n - 2; i >= 0; --i){
