		double mx = 0;
		for(int t : G[i]){
			s += exp[t];
			mx = max(mx, exp[t]);
		}
		exp[i] = s / G[i].size() + 1;
		if(G[i].size() >= 2){
			double delta = (s - mx) / (G[i].size() - 1) - s / G[i].size();
			ans = min(ans, delta * prob[i]);
		}
	}
	ans += exp[0];
	printf("%.9f\n", ans);
}

