    vector<double> memo(n,-1);
    function<double(int)> rec = [&](int k) {
        double mx = 0;
        double res = 0;
        if(k == n-1)return 0.0;
        if(memo[k] != -1) return memo[k];
        for(auto x:nbs[k]) {
            double tmp = rec(x);
            chmax(mx,tmp);
            res += tmp * 1.0 / nbs[k].size();
        }
        res++;
        return memo[k] = res;
    };
    rec(0);
    rep(i,n) {
        if(nbs[i].size() > 1) {
            double mn = 1e+12;
            int to;
            for(auto x:nbs[i]) {
                if(chmin(mn, memo[i]-memo[x])) {
                    to = x;
                }
            }
            cand.emplace_back(i, to);
        }
    }
    double res = memo[0];
    function<void(int)> reset_memo =[&](int k) {
        for(auto x:parents[k]) {
            reset_memo(x);
        }
        memo[k] = -1;
        return;
    };
    for(auto x:cand) {
        nbs[x.first].erase(x.second);
        reset_memo(x.first);
        // rep(i,n) {
        //     memo[i] = -1;
        // }
        chmin(res, rec(0));
        nbs[x.first].insert(x.second);
    }
    printf("%.10lf\n",res);
    return 0;
}

