double solve(int u, int v)
{
    for(int i = n-1; i > u; --i) e[i] = ee[i];
    double sum = 0;
    for(int i = 0; i < l[u]; ++i)
    {
        if(vec[u][i] == v) continue;
        sum += e[vec[u][i]];
    }
    e[u] = sum/(l[u]-1)+1.0;
    for(int i = u-1; i > 0; --i)
    {
        sum = 0;
        for(int j = 0; j < l[i]; ++j)
            sum += e[vec[i][j]];
        e[i] = sum/l[i]+1.0;
    }
    return e[1];
}

