double dp[610];
int flag[610];

int main(){
	int N, M; cin >> N >> M;
	vector<int> G[N];
	for(int i=0; i<M; i++){
		int s, t; cin >> s >> t;
		s--; t--;
		G[s].push_back(t);
	}
	for(int i=N-2; i>=0; i--){
		for(int j=0; j<G[i].size(); j++){
			dp[i] += (dp[G[i][j]]+1)/G[i].size();
		}
	}
	queue<int> que;
	flag[0] = 1;
	que.push(0);
	while(que.size()){
		int aaa = que.front(); que.pop();
		for(int i=0; i<G[aaa].size(); i++){
			if(flag[G[aaa][i]] != 1){
				flag[G[aaa][i]] = 1;
				que.push(G[aaa][i]);
			}
		}
	}
	double ANS = dp[0];
	for(int i=0; i<N-1; i++){
		double dp2[N];
		int ma = -1, mai;
		for(int j=0; j<G[i].size(); j++){
			if(dp[G[i][j]] > ma){ ma = dp[G[i][j]]; mai = G[i][j]; }
		}
		dp2[i] = 0;
		if(G[i].size() == 1 && flag[i] == 1) continue;
		for(int j=i+1; j<N; j++) dp2[j] = dp[j];
		for(int j=0; j<G[i].size(); j++){
			if(G[i].size() == 1) dp2[i] = -1;
			else{
				if(G[i][j] != mai){
					dp2[i] += (dp[G[i][j]]+1)/(G[i].size()-1);
				}
			}
		}
		for(int j=i-1; j>=0; j--){
			double aa = 0;
			for(int k=0; k<G[j].size(); k++){
				aa += (dp2[G[j][k]]+1)/G[j].size();
			}
			dp2[j] = aa;
		}
		if(ANS > dp2[0]) ANS = dp2[0];
	}
	cout << setprecision(10) << ANS << endl;
	return 0;
}

