		if(SI(g.g[A]) == 1) { continue; }

		vector<double> p(n), e(n);
		p[0] = 1;
		inc(j, m) {
			if(j == i) { continue; }
			int a = g.e[j].FI;
			int b = g.e[j].SE;
			int q = SI(g.g[a]) - (a == A ? 1 : 0);
			assert(q > 0);
			p[b] += p[a] / q;
			e[b] += (e[a] + p[a]) / q;
		}

		setmin(ans, e[n - 1]);
	}

	printf("%.9f\n", ans);

	return 0;
}

