int main() {
    int N,M,i,j,s,t,mx,nxt;
    double ans;

    scanf("%d%d",&N,&M);
    for (i = 0;i < M;i++) {
        scanf("%d%d",&s,&t);
        adj[s][t] = true;
        deg[s]++;
    }

    for (i = N - 1;i > 0;i--) {
        for (nxt = 1;nxt <= N;nxt++) {
            if (adj[i][nxt])
                dp1[i] += dp1[nxt];
        }
        dp1[i] /= deg[i];
        dp1[i]++;
    }

    ans = INF;
    for (i = 1;i < N;i++) {
        mx = N + 1;
        for (nxt = 1;nxt <= N;nxt++) {
            if (adj[i][nxt] && dp1[nxt] > dp1[mx])
                mx = nxt;
        }

        if (mx <= N) {
            adj[i][mx] = false;
            deg[i]--;

            for (j = N - 1;j > 0;j--) {
                for (nxt = 1;nxt <= N;nxt++) {
                    if (adj[j][nxt])
                        dp2[j] += dp2[nxt];
                }
                dp2[j] /= deg[j];
                dp2[j]++;
            }

            chance[1] = 1;
            for (j = 1;j < N;j++) {
                for (nxt = 1;nxt <= N;nxt++) {
                    if (adj[j][nxt])
                        chance[nxt] += chance[j] / deg[j];
                }
            }

            if (abs(chance[N] - 1) <= EPS)
                ans = min(ans,dp2[1]);

