int N,M;
vector<vector<int> > G;
vector<vector<int> > m;
vector<pair<int, int> > P;
vector<vector<double> > dp;

double sol( int im, int inum  )
{
  if( dp[im][inum] > -0.00000001 )
    {
      return dp[im][inum];
    }

  int num = 0;
  double sm = 0.0;
  double mx = 0.0;

  for( const auto& elem : G[inum] )
    {
      double temp = sol(0,elem) + 1.0;
      sm += temp;

      if( m[inum][elem] )
	{
	  mx = max(temp,mx);
	}

      ++ num;
    }

  double res = 2e18;
  if( num  > 0 )
    {
      res = min(res,sm/num);
    }

  if( im == 1 and 1 < num )
    {
      res = min(res,(sm-mx)/(num-1));
    }

  return dp[im][inum] = res;

}




