void func(vvl &G, vector<long double> &DP, long double &ans, ll N, ll block) {
  DP[N] = 0;
  for (ll i = N - 2; i >= 0; i--) {
    long double sum = 0.0;
    long double maxi = 0.0;
    ll num = G[i].size();
    AUTO(g, G[i]) {
      sum += DP[g];
      maxi = max(DP[g], maxi);
    }
    if (i == block && num >= 2) {
      num--;
      sum -= maxi;
    }
    DP[i] = (sum / num) + 1;
  }
  ans = min(ans, DP[0]);
}

