using namespace std;

#define N_MAX 600

int N, M;
char table[N_MAX][N_MAX];
double memo[N_MAX];

double func(int index)
{
	if (memo[index] > 0.0l){
		return memo[index];
	}

	double ret = 0.0l;

	int cnt = 0;
	for (int i = 0; i < N; i++){
		if (0 == table[index][i]){
			continue;
		}
		cnt++;
	}

	for (int i = 0; i < N; i++){
		if (0 == table[index][i]){
			continue;
		}
		ret += (func(i) + 1.0l) / (double)cnt;
	}

	return memo[index] = ret;
}

void solv()
{
	scanf("%d%d", &N, &M);
	for (int i = 0; i < N; i++){
		fill(table[i], table[i] + N, 0);
	}
	for (int i = 0; i < M; i++){
		int s, t; scanf("%d%d", &s, &t);
		s--; t--;
		table[s][t] = 1;
	}

	fill(memo, memo + N, -10.0l);

	double def[N_MAX];
	for (int i = 0; i < N; i++){
		def[i] = func(i);
	}

	double ans = (double)(N * 2);
	for (int i = 0; i < N; i++){
		int index, cnt = 0; double val = -10.0l;
		for (int j = 0; j < N; j++){
			if (0 == table[i][j]){
				continue;
			}
			cnt++;
			if (def[j] > val){
				index = j;
				val = def[j];
			}
		}

		if (1 == cnt){
			continue;
		}

		table[i][index] = 0;
		fill(memo, memo + N, -10.0l);
		ans = min(ans, func(0));
		table[i][index] = 1;
	}

	printf("%.10lf", ans);

	return;
}

