        if(i!=j){
            int counter = adj[i].size();
            double exp = 0;
            for(auto k : adj[i]){
                exp += dp[k];
            }
            dp[i] = (double)1 + exp/(double)counter;
        }
        else{
            int _max = 0;
            int index = 0;
            int counter = adj[i].size()-1;
            double exp = 0;
            for(int k = 0; k < adj[i].size(); ++k){
