/* subroutines */

/* main */

int main() {
  int n, m;
  scanf("%d%d", &n, &m);

  for (int i = 0; i < m; i++) {
    int s, t;
    scanf("%d%d", &s, &t);
    s--, t--;
    nbrs[s].push_back(t);
  }

  rcs[0] = true;
  for (int i = 0; i < n; i++)
    if (rcs[i]) {
      vi &nbri = nbrs[i];
      for (vi::iterator vit = nbri.begin(); vit != nbri.end(); vit++) {
	int &j = *vit;
	rcs[j] = true;
      }
    }

  dp[n - 1] = 1.0;
  for (int i = n - 2; i >= 0; i--)
    if (rcs[i]) {
      vi &nbri = nbrs[i];
      int sz = nbri.size();

      dp[i] = 0.0;
      maxdpjs[i] = -1.0;
      for (vi::iterator vit = nbri.begin(); vit != nbri.end(); vit++) {
	int &j = *vit;
	dp[i] += (1.0 + dp[j]);
	if (maxdpjs[i] < dp[j]) maxdpjs[i] = dp[j];
      }
      dp[i] /= sz;
      //printf("%d: maxdpjs=%lf, sz=%d\n", i, maxdpjs[i], sz);
    }
  //for (int i = 0; i < n; i++) printf("%lf ", dp[i]); putchar('\n');
  //printf("%lf\n", dp[0]);
  double mind = dp[0];

  for (int i = n - 2; i >= 0; i--)
    if (rcs[i] && nbrs[i].size() > 1) {
      copy(dp, dp + n, tdp);

      int szi = nbrs[i].size();
      tdp[i] = (dp[i] * szi - (1.0 + maxdpjs[i])) / (szi - 1);

      for (int j = i - 1; j >= 0; j--)
	if (rcs[j]) {
	  vi &nbrj = nbrs[j];
	  int szj = nbrj.size();
	  tdp[j] = 0.0;

	  for (vi::iterator vit = nbrj.begin(); vit != nbrj.end(); vit++) {
	    int &jj = *vit;
	    tdp[j] += (1.0 + tdp[jj]);
	  }
	  tdp[j] /= szj;
	}

      if (tdp[0] > 0.0 && mind > tdp[0]) mind = tdp[0];
      //printf("%d: %lf\n", i, tdp[0]);
    }

  printf("%.10lf\n", mind - 1.0);
  return 0;
}

