const int mod=1000000007,MAX=603,INF=1<<30;
vector<int> F[MAX],G[MAX];
int N;
double preP[MAX],preQ[MAX],prechild[MAX];

double solve(pair<int,int> E){
    vector<double> P(MAX,INF),Q(MAX,0.0),child(MAX,0.0);//Pはそこにつくまでにかかる回数の期待値、Qはそこにいく確率,childは子の数
    P[0]=0.0;
    Q[0]=1.0;

    for(int i=0;i<N;i++){
        double cnt=0.0;
        for(int to:F[i]){
            if(i==E.first&&to==E.second) continue;
            cnt+=1.0;
            child[i]+=1.0;
        }
        for(int to:F[i]){
            if(i==E.first&&to==E.second) continue;
            Q[to]+=Q[i]/cnt;
        }
    }

    for(int i=1;i<N;i++){
        double cnt=0.0,sum=0.0;
        for(int from:G[i]){
            if(from==E.first&&i==E.second) continue;
            cnt+=Q[from]/child[from];
            sum+=(P[from]+1.0)*Q[from]/child[from];
        }
        if(cnt==0.0) continue;
        P[i]=sum/cnt;
        if(i==N-1&&0.9999999>cnt) return INF;
    }

    if(E==make_pair(-1,-1)){
        for(int i=0;i<N;i++) preP[i]=P[i];
        for(int i=0;i<N;i++) preQ[i]=Q[i];
        for(int i=0;i<N;i++) prechild[i]=child[i];
    }
    return P[N-1];
}

