    pass_prob[0] = 1.;
    for(LL i = 0; i < n; ++i){
        for(LL t: path[i]){
            pass_prob[t] += pass_prob[i] / path[i].size();
        }
    }
    for(LL i = n-2; i >= 0; --i){
        for(LL t: path[i]){
            exp_cost[i] += (exp_cost[t] + 1.) / path[i].size();
        }
    }
    cerr << pass_prob << endl;
    cerr << exp_cost << endl;

    double ans = exp_cost[0];
    for(LL i = 0; i < n; ++i){
        for(LL t: path[i]){
            if(path[i].size() <= 1) continue;
            double gain = exp_cost[i] - (exp_cost[i]*path.size() - (exp_cost[t] + 1.)) / (path.size()-1);
            ans = min(ans, exp_cost[0] - gain * pass_prob[i]);
        }
    }
    cout << ans << endl;
    return 0;
}

