int main() {
    int n, m; cin >> n >> m;
    vector<int> e[n];
    vector<double> d(n, 0), p(n, 0);
    for (int i = 0; i < m; i++) {
        int s, t; cin >> s >> t;
        e[s-1].emplace_back(t-1);
    }
    for (int i = n-1; i >= 0; i--) {
        if (e[i].size() == 0) continue;
        double x = 1.0 / e[i].size();
        for (auto &to: e[i]) {
            d[i] += (d[to] + 1) * x;
        }
    }
    p[0] = 1;
    for (int i = 0; i < n; i++) {
        if (e[i].size() == 0) continue;
        double x = 1.0 / e[i].size();
        for (auto &to: e[i]) {
            p[to] += p[i] * x;
        }
    }
    double ans = d[0];
    for (int i = 0; i < n; i++) {
        for (auto &j: e[i]) {
            // {i, j}
            double ij = 1.0 / e[i].size();
            double diff = -(1 + d[j]) * ij;
            if (e[i].size() > 1) {
                double ik = 1.0 / (e[i].size() - 1) - ij;
                for (auto &k: e[i]) {
                    if (j == k) continue;
                    diff += (1 + d[k]) * ik;
                }
                if (ans+diff > eps) ans = min(ans, d[0]+diff*p[i]);
            }    
        }
    }
    printf("%.12f\n", ans);
