double dp[600];

double E(int n, vector<vector<int>> &G){
    for (int i = 0; i < n; ++i) {
        dp[i] = 0;
    }
    double ans = 0;
    dp[0] = 1;
    for (int i = 0; i < n; ++i) {
        for (auto &&j : G[i]) {
            ans += dp[i]/G[i].size();
            dp[j] += dp[i]/G[i].size();
        }
    }
    if(!dp[n-1]) return INF<int>;
    return ans;
}

