vector<vector<int>> to;

double dfs(int curr, int cutFrom) 
{
    double ret = 0;
    if (done[curr]) {
        ret = dp[curr];
    } else {
        if (curr == cutFrom) {
            if (1 == to[curr].size()) {
                ret = dfs(to[curr].front(), cutFrom);
            } else {
                vector<double> temp;
                for (int next: to[curr]) {
                    temp.push_back(dfs(next, cutFrom));
                }
                sort(temp.begin(), temp.end());
                double sum = 0;
                rep(i, temp.size()-1) {
                    sum += temp[i];
                }
                ret = sum / (temp.size()-1);
            }
        } else {
            double p = 1.0 / to[curr].size();
            for (int next: to[curr]) {
                ret += p * dfs(next, cutFrom);
            }
        }
        ret += 1.0;
        dp[curr] = ret;
        done[curr] = true;
    }
    return ret;
}

