double get_e(int n, vector<vector<int>>& adj, vector<double>& e, int block_s, int block_t) {
    fill(e.begin(), e.end(), 0);
    for(int u = n - 1; u >= 1; u--) {
        int denom = adj[u].size();
        for(int v : adj[u]) {
            if(block_s == u and block_t == v) {
                denom--;
            } else {
                e[u] += (1 + e[v]);
            }
        }
        e[u] /= denom;
    }
    return e[1];
}
