std::vector<std::vector<int>> root_pair(std::vector<std::pair<int, int>> r, int n) {
	std::vector<std::vector<int>> ans(n);
	for (int i = 0; i < r.size(); ++i)
		ans[r[i].first].push_back(r[i].second);
	return ans;
}

long double exp_root(int n, int max, std::vector<std::pair<int, int>> r, int m, std::vector<long double> *ans, bool change, std::vector<std::vector<int>> v) {
	std::vector<long double> ans_tmp(*ans);
	for (int i = max; i >= 1; --i) {
		if (v[i].size() == 0) {
			ans_tmp[i] = -1;
			continue;
		}

		long double exp = 0;
		for (int j = 0; (unsigned)j < v[i].size(); ++j)
			if (ans_tmp[v[i][j]] == -1) {
				ans_tmp[i] = -1;
				break;
			}
			else exp += ans_tmp[v[i][j]];

		if (ans_tmp[i] != -1) ans_tmp[i] = exp / v[i].size() + 1;
	}

	if (change)
		*ans = ans_tmp;

	return ans_tmp[1];
}

long double erase_root(int n, std::vector<std::pair<int, int>> r, int m, int erase, std::vector<long double> ans, std::vector<std::vector<int>> v) {
	std::vector<std::pair<int, int>> tmp(r);
	tmp.erase(tmp.begin() + erase);

	std::vector<std::vector<int>> v_tmp(v);
	for (int i = 0; i < v[r[erase].first].size(); ++i)
		if (v[r[erase].first][i] == r[erase].second)
			v_tmp[r[erase].first].erase(v_tmp[r[erase].first].begin() + i);
	return exp_root(n, r[erase].first, tmp, m - 1, &ans, 0, v_tmp);
}

int main() {
	int n, m;
	std::cin >> n;
	std::cin >> m;

	std::vector<std::pair<int, int>> r(m);
	for (int i = 0; i < m; ++i) {
		std::cin >> r[i].first;
		std::cin >> r[i].second;
	}

	std::vector<std::vector<int>> v = root_pair(r, n);

	std::vector<long double> ans(n + 1, 0);
	long double min = exp_root(n, n - 1, r, m, &ans, 1, v);

	long double tmp;
	for (int i = 0; i < m; i++) 
		if ((tmp = erase_root(n, r, m, i, ans, v)) != -1 && tmp < min)
			min = tmp;

	std::cout << std::setprecision(10) << std::fixed << min << std::endl;
}

