ld go() {
	for(int i=1;i<=n;i++) E[i] = 0;
	E[n] = 0;
	for(int i=n-1;i>=1;i--) {
		int out = 0;
		for(int j:G[i]) {
			if(ok[i][j]) {
				E[i] += E[j];
				out++;
			}
		}
		if(out == 0) return INF;
		E[i] = E[i] / out + 1;
	}
	return E[1];
}

