		for(int j:G[i]) if(E[j] > E[argmax[i]]) argmax[i] = j;
	for(int i=1;i<n;i++) {
		ok[i][argmax[i]] = false;
		mn = min(mn, go());
		ok[i][argmax[i]] = true;
	}		
