vector<double> memo;
double dfs(int s,int i, vector<vector<int>> g){
    if(memo[s]) return memo[s];
    if(s==N-1) return memo[s] = 0;
    if(g[s].empty()) return memo[s] = N+1;
    if(s==Edge[i].first && g[s].size()==1) return N+1;
    double ret = 1;
    for(auto v:g[s]){
        if(s==Edge[i].first && v==Edge[i].second) continue;
        if(s!=Edge[i].first) ret += dfs(v,i,g)/g[s].size();
        else ret += dfs(v,i,g)/(g[s].size()-1);
    }
    return memo[s] = ret;
}

// 繋がってなかったらdfsの値が∞になるようにしてるから意味ない。
bool isok(int i,vector<vector<int>> g){
    queue<int> q;
    q.push(0);
    vector<bool> seen(N,false);
    seen[0] = true;
    while (!q.empty())
    {
        int u = q.front();
        q.pop();
        for(int v:g[u]){
            if(u==Edge[i].first && v==Edge[i].second) continue;
            if(seen[v]) continue;
            if(v==N-1) return true;
            seen[v] = true;
            q.push(v);
        }
    }
    return seen[N-1];
}

int solve(){
    double ans = N+1;
    for (int i = 0; i <= M; i++)
    {
        // if(isok(i,G)) 
        memo.assign(N,0);
        ans = min(ans,dfs(0,i,G));
    }
    cout << fixed << setprecision(10) << ans << endl;    
    return 0;
}   

int main()
{
    input();
    solve();
    return 0;
}

