using namespace std;
using ll = long long;
using P = pair<int, int>;

int N;

struct Edge {
    int to, id;
    Edge(int to, int id): to(to), id(id) {}
};

vector<int> paths[180005];  // その道を通るパスの集まり
vector<Edge> rooms[605];
vector<int> total;

vector<int> dfs(int x, int goal, int cnt) {
    // cntは通ったパスの数
    if (x == goal) {
        total.push_back(cnt);
        return {cnt};
    }
    vector<int> res;
    for (auto e : rooms[x]) {
        int next = e.to;
        int id = e.id;
        vector<int> counts = dfs(next, goal, cnt+1);
        for (int a : counts) {
            paths[id].push_back(a);
            res.push_back(a);
        }
    }
    return res;
}

int main() {
    int M;
    cin >> N >> M;
    rep(i, M) {
        int s, t;
        cin >> s >> t;
        --s; --t;
        rooms[s].emplace_back(t, i);
    }
    dfs(0, N-1, 0);
    int whole = accumulate(total.begin(), total.end(), 0);
    show(total);
    double ans = (double)whole / sz(total);
    rep(i, M) {
        int w = accumulate(paths[i].begin(), paths[i].end(), 0);
        if (w == whole) continue;
        double temp = (double)(whole - w) / (sz(total) - sz(paths[i]));
        if (temp < ans) ans = temp;
    }
    printf("%.10f\n", ans);
    return 0;
    // ll, 0, -, 1i, for s&g, debug
}

