int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N, M; cin >> N >> M;
    vector<vector<int>> G(N);
    for (int i = 0; i < M; i++) {
        int S, T; cin >> S >> T; S--, T--;
        G[S].push_back(T);
    }
    vector<double> X(N), P(N);
    P[0] = 1.0;
    for (int node = 0; node < N; node++) {
        for (auto next : G[node]) {
            P[next] += P[node] / G[node].size();
        }
    }
    X[N - 1] = 0;
    for (int node = N - 2; node >= 0; node--) {
        double sum = 0;
        for (auto next : G[node]) {
            sum += X[next];
        }
        X[node] = 1 + sum / G[node].size();
    }
    double orig = X[0];
    double ans = orig;
    for (int node = N - 2; node >= 0; node--) {
        if (G[node].size() == 1) continue;
        double sum = 0;
        double maxval = 0;
        for (auto next : G[node]) {
            sum += X[next];
            maxval = max(maxval, X[next]);
        }
        double ans2 = orig + P[node] * (-sum / G[node].size() + (sum - maxval) / (G[node].size() - 1));
        ans = min(ans, ans2);
    }
    cout << fixed << setprecision(9) << ans << endl;
    return 0;
}

#include <bits/stdc++.h>
#define N 605

using namespace std;

int n, m;
int deg[N], ideg[N], Outdeg[N];
bool G[N][N], iG[N][N];
double f[N], p[N], outp[N];

inline void cmin(double &u, double v) { if(u > v) u = v; }
inline void cmax(double &u, double v) { if(u < v) u = v; }

void build() {
	int u, v;
	cin >> n >> m;
	for(int i = 1; i <= m; ++i) {
		cin >> u >> v;
		G[u][v] = true, ++deg[v];
		iG[v][u] = true, ++ideg[u];
	}
	for(int i = 1; i <= n; ++i) {
		Outdeg[i] = ideg[i];
		if(Outdeg[i]) outp[i] = 1.0 / Outdeg[i];
	}
	return;
}

void topo_1() {
	queue<int> que;
	que.push(n);
	while(!que.empty()) {
		int u = que.front(); que.pop();
		for(int v = 1; v <= n; ++v) {
			if(!iG[u][v]) continue;
			f[v] += (1.0 + f[u]) * outp[v];
			if((--ideg[v]) == 0) que.push(v);
		}
	}
	return;
}
void topo_2() {
	queue<int> que;
	que.push(1), p[1] = 1.0;
	while(!que.empty()) {
		int u = que.front(); que.pop();
		for(int v = 1; v <= n; ++v) {
			if(!G[u][v]) continue;
			p[v] += p[u] * outp[u];
			if((--deg[v]) == 0) que.push(v);
		}
	}
	return;
}

int main() {
	ios :: sync_with_stdio(false);
	build();
	topo_1(), topo_2();
	double ans = f[1], res;
	double p_1, p_2, maxf;
	for(int i = 1; i <= n; ++i) {
		if(Outdeg[i] <= 1) continue;
		res = maxf = 0;
		p_1 = outp[i], p_2 = 1.0 / (Outdeg[i] - 1);
		for(int j = 1; j <= n; ++j) {
			if(!G[i][j]) continue;
			res += 1.0 + f[j];
			cmax(maxf, 1.0 + f[j]);
		}
		cmin(ans, f[1] + p[i] * ((res - maxf) * p_2 - res * p_1));
	}
	cout << fixed << setprecision(7) << ans << endl;
	return 0;
}

