struct vertex {
    int cnt = 0, bcnt = 0;
    double prob = 0.0, weight = 0.0;
    set<int> from, to;
};

int n, m;
pair<int, int> p[180000];
bool jdg[600];
vertex ver[600];

void dfs(int x) {
    if (++ver[x].cnt < ver[x].from.size()) return;
    for (auto &i : ver[x].to) {
        ver[i].prob += ver[x].prob / ver[x].to.size();
        dfs(i);
    }
}

void bdfs(int x) {
    if (++ver[x].bcnt < ver[x].to.size()) return;
    if (x != n - 1) ver[x].weight /= ver[x].to.size();
    for (auto &i : ver[x].from) {
        ver[i].weight += ver[x].weight + 1.0; 
        bdfs(i);
    }
}

int main() {
    scanf("%d %d", &n, &m);
    for (int i = 0; i < m; i++) scanf("%d %d", &p[i].first, &p[i].second);
    sort(p, p + m);
    jdg[0] = true;
    for (int i = 0; i < m; i++) {
        if (jdg[p[i].first - 1]) {
            jdg[p[i].second - 1] = true;
            ver[p[i].first - 1].to.emplace(p[i].second - 1);
            ver[p[i].second - 1].from.emplace(p[i].first - 1);
        }
    }

    ver[0].prob = 1.0; 
    dfs(0);
    bdfs(n - 1);

    double rdc = 0.0;
    for (int i = 0; i < m; i++) {
        if (!jdg[p[i].first - 1] || ver[p[i].first - 1].to.size() == 1) continue;
        double a = 0.0;
        for (auto &j : ver[p[i].first - 1].to) {
            if (j == p[i].second - 1) continue;
            a += ver[j].weight + 1.0;
        }
        a /= (ver[p[i].first - 1].to.size() - 1);
        rdc = min(rdc, (a - ver[p[i].first - 1].weight) * ver[p[i].first - 1].prob);
    }


    printf("%5.15lf\n", ver[0].weight + rdc);
    return 0;
}

