int N, M;
vector<vector<bool>> adj;
vector<int> out;
vector<double> dp;
vector<double> probability;

double solve_dp() {
    dp.assign(N, 0);

    for (int i = N - 2; i >= 0; i--) {
        double sum = 0;

        for (int j = i + 1; j < N; j++)
            if (adj[i][j])
                sum += dp[j] + 1;

        dp[i] = sum / out[i];
    }

    return dp[0];
}

void solve_probability() {
    probability.assign(N, 0);
    probability[0] = 1;

    for (int i = 0; i < N; i++)
        for (int j = i + 1; j < N; j++)
            if (adj[i][j])
                probability[j] += probability[i] / out[i];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cout << fixed << setprecision(12);

    cin >> N >> M;
    adj.assign(N, vector<bool>(N, false));
    out.assign(N, 0);

    for (int i = 0; i < M; i++) {
        int s, t;
        cin >> s >> t;
        s--; t--;
        adj[s][t] = true;
        out[s]++;
    }

    double base = solve_dp();
    double best = base;
    solve_probability();

    for (int s = 0; s < N; s++) {
        if (out[s] <= 1)
            continue;

        double worst = 0;

        for (int t = s + 1; t < N; t++)
            if (adj[s][t])
                worst = max(worst, dp[t]);

        double save = (worst - (dp[s] - 1)) / (out[s] - 1);
        best = min(best, base - probability[s] * save);
    }

    cout << best << '\n';
}

