#define fastInp cin.tie(0); cout.tie(0); ios_base::sync_with_stdio(0);

const ll SIZE = 1e6, INF = 1e9 * 1e9 + 10, MOD = 998244353;

ld dp[SIZE];
vector<vector<ll>> gr;
bool used[SIZE];

void bst(int v, int ch) {
	used[v] = 1;

	for (auto to : gr[v]) {
		if (!used[to]) {
			bst(to, ch);
		}
	}

	if (v != ch) {
		ld cur = 0;
		for (auto to : gr[v]) {
			cur += (dp[to] + 1) / ld(gr[v].size());
		}
		dp[v] = cur;
	}
	else {
		if (gr[v].size() == 0) {
			dp[v] = 0;
		}
		else if (gr[v].size() == 1) {
			dp[v] = dp[gr[v][0]] + 1;
		}
		else {
			pair<ld, ll> mx = { -1, -1 };
			for (int i = 0; i < gr[v].size(); i++) {
				mx = max(mx, { dp[gr[v][i]], i });
			}
			ld s = 0;
			for (int i = 0; i < gr[v].size(); i++) {
				if (mx.second != i) s += (dp[gr[v][i]] + 1);
			}
			s /= ld(gr[v].size() - 1);
			dp[v] = s;
		}
	}
}
int main()
{
	fastInp;

	ll n, m;
	cin >> n >> m;

	gr.resize(n);
	for (int i = 0; i < m; i++) {
		ll u, v;
		cin >> u >> v;
		u--; v--;
		gr[u].push_back(v);
	}

	ld ans = INF;
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < n; j++) used[j] = 0;
		bst(0, i);
		ans = min(ans, dp[0]);
	}
	cout.precision(8);
	cout << ans;
	return 0;
}

