//---------------------------------------------------------
void solve()
{
    ll N, M;
    in(N, M);
    vvll to(N);
    for1 (i, M) {
        ll s, t;
        in(s, t);
        --s;
        --t;
        to[s].push_back(t);
    }
    vll dis(N);
    for1 (i, N) {
        dis[i] = INF;
    }
    priority_queue<tll> q;
    vll prev(N);
    q.push(make_tuple(0, 0, -1));  // cost, loc, prev
    while (!q.empty()) {
        ll cost, loc, pre;
        tie(cost, loc, pre) = q.top();
        q.pop();
        if (dis[loc] > cost) {
            dis[loc] = cost;
            prev[loc] = pre;
            for (auto t : to[loc]) {
                q.push(make_tuple(cost - 1, t, loc));
            }
        }
    }
    ll maxprev = -1;
    ll maxloc = -1;
    ll maxto = -1;
    ll loc = N - 1;
    ll pre = N - 1;
    dump(loc, to[loc].size());
    while (true) {
        pre = loc;
        loc = prev[loc];
        dump(loc, to[loc].size());
        if (maxto < (ll)to[loc].size()) {
            maxto = to[loc].size();
            maxloc = loc;
            maxprev = pre;
        }
        if (loc == 0) {
            break;
        }
    }
    dump(maxto, maxloc, maxprev);
    if (maxloc != -1 && maxto >= 2) {
        auto it = find(all(to[maxloc]), maxprev);
        to[maxloc].erase(it);
    }

    vector<ld> dp(N);
    dp[0] = 0;
    for1 (i, N - 1) {
        ll cnt = to[i].size();
        for (ll t : to[i]) {
            dp[t] += (dp[i] + 1) / (ld)cnt;
        }
        dump(dp);
    }
    print(dp[N - 1]);
}
int main()
{
