void solve()
{
    ll N, M;
    in(N, M);
    vvll to(N);
    for1 (i, M) {
        ll s, t;
        in(s, t);
        --s;
        --t;
        to[s].push_back(t);
    }
    vector<ld> dp(N);
    rfor2 (i, N - 2, -1) {
        ld val = 0;
        for (ll t : to[i]) {
            val += dp[t];
        }
        val /= to[i].size();
        val += 1;
        dp[i] = val;
    }
    ld ans = dp[0];

    for1 (i, N - 1) {
        if (to[i].size() <= 1) {
            continue;
        }
        ll maxexp = 0;
        for2 (j, 1, (ll)to[i].size()) {
            if (dp[to[i][maxexp]] < dp[to[i][j]]) {
                maxexp = j;
            }
        }
        // dump(i, to[i][maxexp]);

        vector<ld> dp2(N);
        rfor2 (j, N - 2, -1) {
            ld val = 0;
            for (ll t : to[j]) {
                if (j == i && t == to[i][maxexp]) {
                    continue;
                }
                val += dp2[t];
            }
            if (j == i) {
                val /= to[j].size() - 1;
            }
            else {
                val /= to[j].size();
            }
            val += 1;
            dp2[j] = val;
        }
        chmin(ans, dp2[0]);
    }
    print(ans);
}

