const int N = 605;
const double INF = 1e14;

int n, m, u, v;

struct Edge{
	int nxt, to;
}edge[N*N];
int head[N], edgeNum, deg[N];
void addEdge(int from, int to){
	edge[++edgeNum] = (Edge){head[from], to};
	head[from] = edgeNum;
	deg[from]++;
}

double dp[N];
int tdeg[N];
double blockDP(int x){
	for(int i = 1; i <= n; i++){
		dp[i] = INF;
		tdeg[i] = deg[i];
	}
	dp[n] = 0;
	for(int i = n - 1; i >= 1; i--){
		double sumDP = 0, maxDP = 0;
		for(int k = head[i]; k; k = edge[k].nxt){
			maxDP = max(maxDP, dp[edge[k].to] == INF ? 0 : dp[edge[k].to]);
			sumDP += dp[edge[k].to];
		}
		if(i == x && tdeg[i] >= 2){
			sumDP -= maxDP;
			tdeg[i]--;
		}
		dp[i] = sumDP / tdeg[i] + 1;
	}
	return dp[1];
}

