ld first_solve(ll n){
  vector<ld> dist(605,0);
  for(int pos=n;pos>=1;pos--){
    for(int i=0;i<node[pos].size();i++){
      ll to=node[pos][i];
      ld now_cos=dist[pos]+1;
      now_cos/=(ld)edge_size[to];
      cos[to].push_back(P(now_cos,pos));
      dist[to]+=now_cos;
    }
  }
  return dist[1];
}
ld second_solve(ll n){
  vector<ld> dist(605,0);
  for(int pos=n;pos>=1;pos--){
    for(int i=0;i<node[pos].size();i++){
      ll to=node[pos][i];
      if(to==-1) continue;
      ld now_cos=dist[pos]+1;
      now_cos/=(ld)edge_size[to];
      dist[to]+=now_cos;
    }
  }
  return dist[1];
}
void dfs(ll pos){
  used[pos]=true;
  for(int i=0;i<dnode[pos].size();i++){
    ll to=dnode[pos][i];
    if(to==-1) continue;
    if(!used[to]){
      used[to]=true;
      dfs(to);
    }
  }
}
