class Solve
{
  int N;
  vector<vector<int>> V;
  vector<double> alpha, S, T;
  double total;

public:
  Solve(int N, vector<vector<int>> const &V) : N{N}, V(V), alpha(N, 0.0), S(N, 0.0), T(N, 0.0)
  {
    calc_alpha();
    calc_S();
    calc_T();
    total = S[N - 1];
  }

  void flush()
  {
    double ans{0.0};
    for (auto i = 0; i < N; ++i)
    {
      if (V[i].size() <= 1)
      {
        continue;
      }
      double Delta{0.0};
      for (auto j : V[i])
      {
        Delta += delta(i, j, delta(i));
      }
      for (auto j : V[i])
      {
        ch_min(ans, Delta + delta(i, j, delta_zero(i)));
      }
    }
    cout << fixed << setprecision(10) << ans + total << endl;
  }

private:
  double prob(int i)
  {
    assert(!V[i].empty());
    return 1.0 / V[i].size();
  }

  double delta(int i)
  {
    assert(V[i].size() > 1);
    return 1.0 / (V[i].size() - 1) - 1.0 / V[i].size();
  }

  double delta_zero(int i)
  {
    assert(V[i].size() > 1);
    return -1.0 / (V[i].size() - 1);
  }

  double delta(int u, int v, double d = 1.0)
  {
    return d * (S[u] + alpha[u] * T[v] + alpha[u]);
  }

  void calc_alpha()
  {
    alpha[0] = 1.0;
    for (auto i = 0; i < N - 1; ++i)
    {
      for (auto j : V[i])
      {
        alpha[j] += prob(i) * alpha[i];
      }
    }
  }

  void calc_S()
  {
    for (auto i = 0; i < N - 1; ++i)
    {
      for (auto j : V[i])
      {
        S[j] += alpha[i] * prob(i) * 1.0 + prob(i) * S[i];
      }
    }
  }

  void calc_T()
  {
    for (auto i = N - 2; i >= 0; --i)
    {
      for (auto j : V[i])
      {
        T[i] += prob(i) * (1.0 + T[j]);
      }
    }
  }
};

