        f[i] = 1 + sum/G[i].size();
    }
    double ans = f[1];
    rep(i, 1, n-1) {
        if(G[i].size() == 1)    continue;
        rep(j, 1, n) dp[j] = f[j];
        double sum = 0, maxx = 0;
        for(int p: G[i]) {
            sum += f[p];
            maxx = max(maxx, f[p]);
        }
        sum -= maxx;
        dp[i] = 1 + sum/(G[i].size()-1);
        per(j, i-1, 1) {
            sum = 0;
            for(int p: G[j]) {
                sum += dp[p];
            }
            dp[j] = 1 + sum/G[j].size();
        }
        ans = min(ans, dp[1]);
    }
    cout << ans << endl;
    return 0;
}

