void solve(){
	int n, m;
	cin >> n >> m;

	vector<vector<int>> adj(n + 1);
	while(m--){
		int s, t;
		cin >> s >> t;
		adj[s].push_back(t);
	}

	ld ans = 1e18;

	vector<ld> dp(n + 1);
	dp.back() = 0;

	for(int i = n - 1; i; --i){
		for(int j = n - 1; j; --j){
			ld su = 0, maxx = 0;
			for(auto ng: adj[j]){
				su += dp[ng];
				maxx = max(maxx, dp[ng]);
			}

			bool block = (i == j) and adj[j].size() > 1;

			dp[j] = 1 + (su - (block ? maxx : 0))
			            / (adj[j].size() - block);
		}

		ans = min(ans, dp[1]);
	}

	cout << ans << "\n";
}

