double dfs(int s, VVI &es, vector<bool> &seen, vector<double> &finished, vector<int> &finished2, vector<double> &memo, const PII &ban, vector<double> &bnb, int cnt, double p) {
    if (s == es.size() - 1) return 0;
    if (es[s].size() == 0) return 0;
    if (memo[s] > -1) return memo[s];
    if (seen[s]) {
        bnb[s] *= (1 - p / finished[s]);
        if (memo[s] == -1) memo[s] = 0;
        memo[s] += (cnt - finished2[s]) / p;
        return 0;
    }
    //seen[s] = true;
    double sum = 0;
    bool isDel = false;
    seen[s] = true;
    finished[s] = p;
    finished2[s] = cnt;

    for (const int &dst: es[s]) {
        if (s == ban.first && dst == ban.second) {
            isDel = true;
            break;
        }
    }
    for (const int &dst: es[s]) {
        if (s == ban.first && dst == ban.second) continue;
        sum += dfs(dst, es, seen, finished, finished2, memo, ban, bnb, cnt + 1, p / (es[s].size() - isDel));
    }
    if (memo[s] == -1) memo[s] = 0;
    memo[s] = sum / (es[s].size() - isDel) + 1;
    memo[s] /= bnb[s];
    return memo[s];
}

