	int n, m; std::cin >> n >> m;
	std::vector<std::vector<int>> rooms(n), inv(n);
	for (auto i = 0; i < m; ++i) {
		int s, t; std::cin >> s >> t;
		rooms[s - 1].push_back(t - 1);
		inv[t - 1].push_back(s - 1);
	}
	std::vector<double> default_est(n, 0.0), changed_est(n); default_est[n - 1] = 0;
	for (int i = n - 2; i >= 0; --i) {
		for (const auto next : rooms[i]) {
			default_est[i] += default_est[next];
		}
		default_est[i] /= rooms[i].size();
		default_est[i] += 1;
	}
	double result = default_est[0];
	for (int remove = 0; remove < n - 1; ++remove) if (rooms[remove].size() > 1) {
		std::copy(default_est.begin(), std::next(default_est.begin(), remove), changed_est.begin());
		double sum = 0;
		double max = 0;
		for (const auto next : rooms[remove]) {
			sum += default_est[next];
			max = std::max(max, default_est[next]);
		}
		changed_est[remove] = (sum - max) / (rooms[remove].size() - 1) + 1;
		for (int current = remove; current >= 0; --current) if (changed_est[current] != default_est[current]) {
			for (const auto prev : inv[current]) {
				changed_est[prev] += (changed_est[current] - default_est[current]) / rooms[prev].size();
			}
		}
		result = std::min(result, changed_est[0]);
	}
	std::cout << std::setprecision(15) << std::fixed << result << '\n';
}

