long double dp(int s, int t) {
	for (int n = N - 1; n >= 1; n--) {
		int rn = G[n].size();
		if (s == n)rn--;
		if (rn == 0) {
			DP[n] = LLONG_MAX;
			continue;
		}
		DP[n] = 0;
		for (int next : G[n]) {
			if (n == s && next == t)continue;
			if (DP[next] == LLONG_MAX) {
				DP[n] = LLONG_MAX;
				continue;
			}
			DP[n] += (1 + DP[next]) / rn;
		}
	}
	return DP[1];
}

long double dpp(int s, int t) {
	vector<long double> D(N+1,0);
	for (int n = N - 1; n >= 1; n--) {
		int rn = G[n].size();
		if (s == n)rn--;
		if (rn == 0) {
			D[n] = LLONG_MAX;
			continue;
		}
		for (int next : G[n]) {
			if (n == s && next == t)continue;
			if (D[next] == LLONG_MAX) {
				D[n] = LLONG_MAX;
				continue;
			}
			D[n] += (1 + D[next]) / rn;
		}
	}
	return D[1];
}


