ll N,M;
double dp[650];
vector<ll> paths[650];
double ans;
void input()
{

	cin>>N>>M;
	for(ll i=1;i<=M;i++)
	{
		ll s,t;
		cin>>s>>t;
		paths[s].pb(t);
	}
}
void f(ll block)
{
	dp[N]=0;
	for(ll i=N-1;i>=1;i--)
	{
		double sum=0;
		double mx=0;
		ll num=paths[i].size();
		for(auto to:paths[i])
		{
			sum+=dp[to];
			if(dp[to]>mx)
			{
				mx=dp[to];
			}
		}
		if(block==i&&num>=2)
		{
			sum-=mx;
			num--;
		}
		dp[i]=sum/num+1;
	}
	if(dp[1]<ans)
	{
		ans=dp[1];
	}
	return ;
}
void solve()
{
	input();
	ans=1e18;
	for(ll i=0;i<=N-1;i++)
	{
		f(i);
	}
	cout<<setprecision(10)<<ans<<"\n";
	return ;
}
int main()
{
	solve();
	return 0;
}

