	}
	P[1]=1;assert(q.empty());q.push(1);
	for(int i=1;i<=n;++i)ind[i]=G2[i].size();assert(ind[1]==0);
	while(!q.empty()){
		int u=q.front();q.pop();
		for(int i=0;i<(int)G1[u].size();++i){
			int v=G1[u][i];
			P[v]+=P[u]/G1[u].size();
			ind[v]--;
			if(!ind[v])q.push(v);
		}
	}
	double ans=E[1];
	for(int i=1;i<n;++i){
		if((int)G1[i].size()==1)continue;
		double EE=0;
		for(int j=0;j<(int)G1[i].size();++j)EE+=E[G1[i][j]];
		for(int j=0;j<(int)G1[i].size();++j){
			ans=min(ans,E[1]-P[i]*(E[i]-((EE-E[G1[i][j]])/((double)G1[i].size()-1)+1)));
		}
	}
	cout<<setiosflags(ios::fixed)<<setprecision(10)<<ans<<endl;
	return 0;
}

