    in(N, M);
    digraph<> g(2 * k5);;
    g.ing(N, M);
    vd dp(N);
    dp[N - 1] = 0;
    rer(i, N - 2) {
        dou sum = 0;
        rep(j,sz(g[i])){
            sum+=dp[g[i][j].t];
        }
        sum /= sz(g[i]);
        dp[i] = sum + 1;
    }
    dou res = linf + 100;
    rep(10)
        //kesu
    {
        rer(d, N - 2) {
            vd tdp = dp;
            {
                dou sum = 0;
                dou mu = g[d][0].t;
                rep(j,sz(g[d])){
                    int t= g[d][j].t;
                    sum += dp[t];
                    if (dp[mu] < dp[t])mu = t;
                }
                sum -= dp[mu];
                if (sz(g[d]) == 1)con;
                sum /= sz(g[d]) - 1;
                tdp[d] = sum + 1;

            }
            rer(i, d - 1) {
                dou sum = 0;
                rep(j,sz(g[d])){
                    int t = g[i][j].t;
                    sum += tdp[t];
                }
                sum /= sz(g[i]);
                tdp[i] = sum + 1;
