int N, M;
vector<vector<int>> graph;
vector<double> dp, dp2;

double rec(int cur) {
    if (dp[cur] != -1) return dp[cur];
    if (cur == N - 1) return dp[cur] = 0.0;
    double ret = 0.0;
    int cnt = 0;
    for (auto& nxt: graph[cur]) {
        ++cnt;
        ret += rec(nxt);
    }
    ret /= cnt;
    return dp[cur] = ret + 1.0;
}

double rec2(int cur, int idx) {
    if (dp2[cur] != -1) return dp2[cur];
    if (cur == N - 1) return dp2[cur] = 0.0;
    if (cur != idx) {
        double ret = 0.0;
        int cnt = 0;
        for (auto& nxt: graph[cur]) {
            ++cnt;
            ret += rec2(nxt, idx);
        }
        ret /= cnt;
        return dp2[cur] = ret + 1.0;
    } else {
        int idx = 0;
        double mx = 0.0, ret = 0.0;
        int cnt = 0;
        for (auto& nxt: graph[cur]) {
            ++cnt;
            double tmp = rec2(nxt, idx);
            if (mx < tmp) {
                mx = tmp;
                idx = nxt;
            }
            ret += tmp;
        }
        ret -= mx;
        ret /= cnt - 1;
        return dp2[cur] = ret + 1.0;
    }
}

