    cin >> N >> M;

    graph.assign(N, vector<int>());
    REP(i, M) {
        int S, T;
        cin >> S >> T;
        --S, --T;
        graph[S].emplace_back(T);
    }

    dp.assign(N, -1);
    rec(0);

    double ret = dp[0];

    REP(i, N) {
        if (graph[i].size() == 1) continue;
        dp2.assign(N, -1);
        rec2(0, i);
        ret = min(ret, dp2[0]);
    }

    cout << setprecision(15) << ret << endl;

}

