void solve() {
    in(N, M);;
    digraph<> g(2 * k5);;
    g.ing(N, M);
    vd per(N), cou(N);
    per[0] = 1;
    cou[N - 1] = 0;
    rer(i, N - 2) {
        forg(gi, g[i]) {
            cou[i] += cou[t];
        }
        cou[i] /= sz(g[i]);
        cou[i]++;
    }
    rep(i, N) {
        forg(gi, g[i]) {
            per[t] += per[i] / sz(g[i]);
        }
    }
    deb(cou);
    deb(per);
    dou base = cou[0];
    dou best = linf;
    rep(i, N - 1) {
        if (sz(g[i]) == 1)con;
        dou sum = 0;
        int mu = g[i][0].t;
        forg(gi, g[i]) {
            sum += cou[t];
            if (cou[mu] < cou[t])mu = t;
        }
        deb(i, sum);
        sum -= cou[mu];
        sum /= sz(g[i]) - 1;
        sum++;
        dou dec = cou[i] - sum;
        deb(i, mu, sum, dec);
        chmi(best, base - dec * per[i]);
    }
    if (best == linf) {
        best = base;
    }
    cout << best << endl;
}

