vector<int> d;
vector<double> E, C;

double expectation(int u) {
  if (E[u] != -1) return E[u];

  double res = 0;
  rep(v, N) if (G[u][v]) res += expectation(v);
  res /= d[u];
  res += 1;
  return E[u] = res;
}

double coefficient(int v) {
  if (C[v] >= 0.0) return C[v];

  double res = 0.0;
  rep(u, N) if (G[u][v]) res += coefficient(u) / d[u];
  return C[v] = res;
}

int main() {
