#include <bits/stdc++.h>
#define N 605

using namespace std;

int n, m;
int deg[N], ideg[N], Indeg[N], Outdeg[N];
bool G[N][N], iG[N][N];
double f[N], p[N], outp[N];

inline void cmin(double &u, double v) { if(u > v) u = v; }
inline void cmax(double &u, double v) { if(u < v) u = v; }

void build() {
	int u, v;
	cin >> n >> m;
	for(int i = 1; i <= m; ++i) {
		cin >> u >> v;
		G[u][v] = true, ++deg[v];
		iG[v][u] = true, ++ideg[u];
	}
	for(int i = 1; i <= n; ++i) {
		Indeg[i] = deg[i];
		Outdeg[i] = ideg[i];
		if(Outdeg[i]) outp[i] = 1.0 / Outdeg[i];
	}
	return;
}

void topo_1() {
	queue<int> que;
	que.push(n);
	while(!que.empty()) {
		int u = que.front(); que.pop();
		for(int v = 1; v <= n; ++v) {
			if(!iG[u][v]) continue;
			f[v] += (1.0 + f[u]) * outp[v];
			if((--ideg[v]) == 0) que.push(v);
		}
	}
	return;
}
void topo_2() {
	queue<int> que;
	que.push(1), p[1] = 1.0;
	while(!que.empty()) {
		int u = que.front(); que.pop();
		for(int v = 1; v <= n; ++v) {
			if(!G[u][v]) continue;
			p[v] += p[u] * outp[u];
			if((--deg[v]) == 0) que.push(v);
		}
	}
	return;
}

int main() {
	ios :: sync_with_stdio(false);
	build();
	topo_1(), topo_2();
	double ans = f[1], res;
	double p_1, p_2, maxf;
	for(int i = 1; i <= n; ++i) {
		if(Outdeg[i] <= 1) continue;
		res = maxf = 0;
		p_1 = outp[i], p_2 = 1.0 / (Outdeg[i] - 1);
		for(int j = 1; j <= n; ++j) {
			if(!G[i][j] && Indeg[j] <= 1) continue;
			res += 1.0 + f[j];
			cmax(maxf, 1.0 + f[j]);
		}
		cmin(ans, f[1] + p[i] * ((res - maxf) * p_2 - res * p_1));
	}
	cout << fixed << setprecision(7) << ans << endl;
	return 0;
}

