void func(Int n, vector<double> &ex, vector<vector<Int>> &g, Int f, Int t){
	ex.assign(n, 0.0);
	for(Int i=n-2; i>=0; --i){
		Int cnt = 0;
		for(Int j=i+1; j<n; ++j)
			if(g[i][j] == 1 && (i != f || j != t))
				++cnt;
		for(Int j=i+1; j<n; ++j)
			if(g[i][j] == 1 && (f != i || t != j))
				ex[i] += (ex[j] + 1) / cnt;
		if(cnt == 0) ex[i] = 1e10;
	}
}

