ll N, M;
std::vector<ll> G[610];

double f( ll block ) {
  std::vector<double> dp( N );

  repd( i, N-1 ) {
    double sum = 0;
    double ma = 0;
    ll num = 0;

    for( auto u : G[i] ) {
      sum += dp[u];
      chmax( ma, dp[u] );
      ++num;
    }

    if( i == block && num > 1 ) {
      sum -= ma;
      --num;
    }

    dp[i] = sum / num + 1;
  }

  return dp[0];
}

int main() {
  std::cin >> N >> M;

  rep( i, M ) {
    ll s, t;
    std::cin >> s >> t;
    --s; --t;

    G[s].emplace_back( t );
  }

  double ans = 1e18;

  rep( i, N-1 ) {
    chmin( ans, f(i) );
  }

  printf( "%.12f\n", ans );

  return 0;
}

