void solve(){
  std::cout << std::fixed << std::setprecision(20);
  int n, m; cin >> n >> m;
  vector<pair<int,int>> edge(m); vector<int> /*vi(n+5,0),*/ from(n+5,0), to(n+5,0);
  vector<vector<int>> eg(n+1);
  FOR(i,0,m) {
    cin >> edge[i].first >> edge[i].second;
    --edge[i].first;
    --edge[i].second;
    ++from[edge[i].first];
    ++to[edge[i].second];
    //vi[edge[i].first]++;
    //vi[edge[i].second+1]--;
    eg[edge[i].second].push_back(edge[i].first);
  }
  auto check = [&](){
    int cnt = 0;
    FOR(i,0,n-1){
      //cnt += vi[i];
      cnt += from[i];
      cnt -= to[i];
      if(to[i]>0 && from[i] == 0) return false;
      if(cnt==0) return false;
    }
    return true;
  };
  auto e_cal = [&](int x){
    ld ret=0; int a = -1, b = -1;
    if(x!=m) {a=edge[x].first; b=edge[x].second;}
    vector<ld> p(n,0); p[0] = 1;
    FOR(i,0,n){
      for(auto y: eg[i]){
        if(y==a && i==b) continue;
        if(from[y])p[i] += p[y]/from[y];
      }
      if(from[i]) ret += p[i];
    }
    //for(auto y: p) cout << y << ' '; 
    return ret;
  };
  ld ans = 1e10;
  FOR(i,0,m+1){
    bool ok = true;
    if(i<m){
      //vi[edge[i].first]--;
      //vi[edge[i].second+1]++;
      --from[edge[i].first];
      --to[edge[i].second];
      ok = check();
    }
    if(ok){
      ld ans_ = e_cal(i);
      ans = min(ans, ans_ );
      //cout << ans_ << endl;
    }
    if(i<m){
      //vi[edge[i].first]++;
      //vi[edge[i].second+1]--;
      ++from[edge[i].first];
      ++to[edge[i].second];
    }
  }
  cout << ans << '\n';
  //for(auto x: vi) cout << x << ' ';
}

int main(){
  solve();
  return 0;
}

