	for(int i = 0; i < m; i++) {
		int s, t;
		scanf("%d %d", &s, &t);
		g[s].push_back(t);
		gt[t].push_back(s);
	}

	fac[1] = 1;

	for(int i = 1; i < n; i++) {
		for(int j : g[i]) {
			fac[j] += fac[i] / g[i].size();
		}
	}

	dp[n] = 0;
	for(int i = n - 1; i >= 1; i--) {
		for(int j : g[i]) {
			dp[i] += (dp[j] + 1) / g[i].size();
		}
	}

	ld ans = dp[1];
	for(int i = 1; i < n; i++) {
		if(g[i].size() <= 1) continue;
		for(int j : g[i]) {
			ld tmp = dp[i] - (dp[j] + 1) / g[i].size();
			tmp *= g[i].size();
			tmp /= g[i].size() - 1;
			ans = min(ans, dp[1] + fac[i] * (tmp - dp[i]));
		}
	}

	printf("%.20Lf\n", ans);

