const double eps = 1e-10;

int n, m;
int deg[N], ideg[N], Outdeg[N];
bool G[N][N], iG[N][N];
double f[N], p[N];

inline void cmin(double &u, double v) { if(u > v) u = v; }

void build() {
	int u, v;
	cin >> n >> m;
	for(int i = 1; i <= m; ++i) {
		cin >> u >> v;
		G[u][v] = true, ++deg[v];
		iG[v][u] = true, ++ideg[u];
	}
	for(int i = 1; i <= n; ++i) Outdeg[i] = ideg[i];
	return;
}

void topo_1() {
	queue<int> que;
	int u;
	que.push(n);
	while(!que.empty()) {
		u = que.front(), que.pop();
		for(int v = 1; v <= n; ++v) {
			if(!iG[u][v]) continue;
			f[v] += (1.0 + f[u]) / (1.0 * Outdeg[v]);
			if((--ideg[v]) == 0) que.push(v);
		}
	}
	return;
}
void topo_2() {
	queue<int> que;
	int u;
	que.push(1), p[1] = 1.0;
	while(!que.empty()) {
		u = que.front(), que.pop();
		for(int v = 1; v <= n; ++v) {
			if(!G[u][v]) continue;
			p[v] += p[u] * (1.0 / Outdeg[u]);
			if((--deg[v]) == 0) que.push(v);
		}
	}
	return;
}

int main() {
	ios :: sync_with_stdio(false);
	build();
	topo_1();
	topo_2();
	double ans = f[1], res;
	for(int i = 1; i <= n; ++i) {
		if(Outdeg[i] <= 1 || p[i] < eps) continue;
		res = 0;
		double p_1 = 1.0 / Outdeg[i], p_2 = 1.0 / (Outdeg[i] - 1);
		for(int j = 1; j <= n; ++j) {
			if(!G[i][j]) continue;
			res += 1.0 + f[j];
		}
		for(int j = 1; j <= n; ++j) {
			if(!G[i][j]) continue;
			cmin(ans, f[1] + p[i] * ((res - (1.0 + f[j])) * p_2 - res * p_1));
		}
	}
	cout << fixed << setprecision(10) << ans << endl;
	return 0;
}

