{
	using vd = std::vector<long double>;
	int N, M;
	std::vector<std::vector<int>> edges;
	scanf("%d%d", &N, &M);
	edges.resize(N);
	for (int i{}; i < M; i++)
	{
		int s, t;
		scanf("%d%d", &s, &t);
		s--; t--;
		edges[s].push_back(t);
	}
	vd E(N);
	for (int i{N - 2}; i >= 0; i--)
		for (auto& e: edges[i])
			E[i] += (E[e] + 1) / edges[i].size();
	long double ans{E[0]};
	for (int i{N - 2}; i >= 0; i--)
	{
		if (edges[i].size() == 1) continue;
		long double max{};
		for (auto& e: edges[i])
			max = std::max(max, E[e] + 1);
		vd ignoreE(N);
		for (int j{N - 2}; j >= 0; j--)
		{
			for (auto& e: edges[j])
				ignoreE[j] += ignoreE[e] + 1;
			if (j == i)
				ignoreE[j] -= max;
			int size{(int)edges[j].size()};
			if (j == i) size--;
			ignoreE[j] /= size;
		}
		ans = std::min(ans, ignoreE[0]);
	}
	printf("%.9Lf\n", ans);

	return 0;
}

