  ll n, m;
  cin >> n >> m;
  vector<vector<ll>> g(n);
  rep(i, m) {
    int s, t;
    cin >> s >> t;
    --s; --t; // 0-indexed
    g[s].push_back(t);
  }

  vector<double> dp(n); // dp[i] .. expected valud from i.
  // dp[n-1] = 0;
  for (int v = n-2; v >= 0; --v) {
    double now = 0;
    for (int u : g[v]) {
      now += dp[u];
    }
    now /= g[v].size();
    now += 1; // one-hop
    dp[v] = now;
  }

  double ans = dp[0];
  for (int nv = 0; nv < n-1; ++nv) {
    if (g[nv].size() == 1) { continue; } // skip 1-degree
    int nu = g[nv][0];
    for (int u : g[nv]) {
      if (dp[u] > dp[nu]) { nu = u; }
    }
    // Here, nu is the maximum dp[nu]

    double nowAns;
    {
      for (int v = n-2; v >= 0; --v) {
        double now = 0;
        for (int u : g[v]) {
          if (v == nv && u == nu) { continue; } // skip removed edge
          now += dp[u];
        }
        int deg = g[v].size();
        if (v == nv) { --deg; }
        now /= deg;
        now += 1; // one-hop
        dp[v] = now;
      }
      nowAns = dp[0];
    }
    ans = min(ans, nowAns);
  }
  cout << ans << endl;
}

