        cin >> s >> t;--s;--t;
        G[s].pb(t);
        revG[t].pb(s);
        Edges.pb({s,t});
    }
    P[0]=1;
    Visited[0]=true;
    dfsP(N-1);
    fill(ALL(Visited),false);
    Visited[N-1]=true;
    E[N-1]=0;
    dfsE(0);
    ld ansE=E[0];
    for(Edge e:Edges) {
        if (G[e.fi].size()==1)continue;
        ld n=G[e.fi].size();
        ld nE=E[0]-P[e.fi]*(1+E[e.se])/n+P[e.fi]*(E[e.fi]*n-(1+E[e.se]))/n/(n-1);
        ansE=min(nE,ansE);
    }
    cout<<ansE<<endl;


    return 0;
}

