typedef long double ld;

const int N = 601;
const ld INF = 1e9 + 239;

int con[N][N];
int deg[N];
ld dp[2][N];

int n;

void calc(int u) {
	//0
	for (int v = u + 1; v < n; v++) {
		if (con[u][v]) {
			dp[0][u] += dp[0][v];
		}
	}
	dp[0][u] /= deg[u];
	dp[0][u]++;
	//1
	dp[1][u] = INF;
	if (deg[u] > 1) {
		for (int bn = u + 1; bn < n; bn++) {
			if (!con[u][bn]) continue;
			ld c = 0;
			for (int v = u + 1; v < n; v++) {
				if (v != bn && con[u][v]) {
					c += dp[0][v];
				}
			}
			c /= (deg[u] - 1);
			c++;
			dp[1][u] = min(dp[1][u], c);
		}
	}
	for (int sel = u + 1; sel < n; sel++) {
		if (!con[u][sel]) continue;
		ld c = 0;
		for (int v = u + 1; v < n; v++) {
			if (con[u][v]) {
				if (v == sel) c += dp[1][v];
				else c += dp[0][v];
			}
		}
		c /= deg[u];
		c++;
		dp[1][u] = min(dp[1][u], c);
	}
}

signed main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);

	cout << fixed << setprecision(16);

	cin >> n;
	int m;
	cin >> m;
	while (m--) {
		int u, v;
		cin >> u >> v;
		u--;
		v--;
		deg[u]++;
		con[u][v] = 1;
	}
	dp[0][n - 1] = 0;
	for (int i = n - 2; i >= 0; i--) {
		calc(i);
	}
	cout << min(dp[0][0], dp[1][0]) << endl;
}

