double calc_init(int n) {
	if (dp_first[n] != 0)return dp_first[n];
	if (n == N - 1)return 0;
	double ret = 0;
	for (auto nxt : par[n]) {
		ret += (calc_init(nxt) + 1) / par[n].size();
	}
	dp_first[n] = ret;
	return ret;
}
double calc(int n) {
	if (dp[n] != 0)return dp[n];
	if (n == N - 1)return 0;
	double ret = 0;
	for (auto nxt : par[n]) {
		ret += (calc(nxt) + 1) / par[n].size();
	}
	dp[n] = ret;
	return ret;
}

