vector<double> memo;
double dfs(int s,int i,const vector<vector<int>> &g){
    if(memo[s]) return memo[s];
    if(s==N-1) return memo[s] = 0;
    if(g[s].empty()) return memo[s] = N+1;
    if(s==Edge[i].first && g[s].size()==1) return N+1;
    double ret = 1;
    for(int v:g[s]){
        if(s==Edge[i].first && v==Edge[i].second) continue;
        if(s!=Edge[i].first) ret += dfs(v,i,g)/g[s].size();
        else ret += dfs(v,i,g)/(g[s].size()-1);
    }
    return memo[s] = ret;
}

// 繋がってなかったらdfsの値が∞になるようにしてるから意味ない。
bool isok(int i,vector<vector<int>> g){
    queue<int> q;
    q.push(0);
    vector<bool> seen(N,false);
    seen[0] = true;
    while (!q.empty())
    {
        int u = q.front();
        q.pop();
        for(int v:g[u]){
            if(u==Edge[i].first && v==Edge[i].second) continue;
            if(seen[v]) continue;
            if(v==N-1) return true;
            seen[v] = true;
            q.push(v);
        }
    }
    return seen[N-1];
}

int TLEsolve(){
    double ans = N+1;
    for (int i = 0; i <= M; i++)
    {
        // if(isok(i,G)) 
        memo.assign(N,0);
        ans = min(ans,dfs(0,i,G));
    }
    cout << fixed << setprecision(10) << ans << endl;    
    return 0;
}   

double eps = 1e-9;
int solve(){
    vector<vector<double>> dp(N+1,vector<double>(N+1,0));
    dp[0][0] = 1;
    for (int i = 0; i < N; i++)
    {
        for (int X = 0; X < N; X++)
        {
            if(dp[i][X]==0) continue;
            for(int u:G[i]){
                dp[u][X+1] += dp[i][X]/G[i].size();
            }
        }        
    }
    double ans = 0;
    DBG(dp[N-1])
    double Pmod = 0;
    for (int x = 1; x < N; x++)
    {
        Pmod += dp[N-1][x];
    }

    for (int x = 1; x < N; x++)
    {
        dp[N-1][x]/= Pmod;
        ans += dp[N-1][x]*x;
    }

    for (int k = 0; k < M; k++)
    {
        int s = Edge[k].first;
        int t = Edge[k].second;
        if(G[s].size()==1) continue;
        vector<vector<double>> dp_diff(N+1,vector<double>(N+1,0));

        for (int X = 0; X < N; X++)
        {
            if(dp[s][X]==0) continue;
            for(int u:G[s]){
                if(u==t) dp_diff[u][X+1] -= dp[s][X]/G[s].size();
                else dp_diff[u][X+1] += dp[s][X]/(G[s].size()-1)-dp[s][X]/G[s].size();
            }
        }

        for (int i = 0; i < N; i++)
        {
            for (int X = 0; X < N; X++)
            {
                if(dp_diff[i][X]==0) continue;
                for(int u:G[i]){
                    dp_diff[u][X+1] += dp_diff[i][X]/G[i].size();
                }
            }        
        }

        double ans_tmp = 0;
        DBG(dp_diff[N-1])
        // assert(A==0);
        vector<double> A(N);
        double P = 0;
        for (int x = 0; x < N; x++)
        {
            A[x] = dp[N-1][x]+dp_diff[N-1][x];
            P += A[x];
        }

        for (int x = 1; x < N; x++)
        {
            ans_tmp += A[x]*x;
        }
        ans_tmp /= P;
        if(abs(ans_tmp)<=eps) continue;
        DBG(ans_tmp)
        ans = min(ans,ans_tmp);
    }
    cout << fixed << setprecision(10) << ans << endl;
    return 0;
}

int main()
{
    input();
    solve();
    return 0;
}

