LL N, unable;

LD dp(LL v)
{
	if (v == N) return 0;
	if (memo[v] != -1) return memo[v];
	LD sum = 0, max = 0, res;
	for (LL u : G[v])
	{
		sum += dp(u) + 1;
		max = std::max(max, dp(u) + 1);
	}
	if (v == unable && G[v].size() >= 2) res = (sum - max) / (G[v].size() - 1);
	else res = sum / G[v].size();
	return memo[v] = res;
}

