double solve(int n, vi adj[], int blk)
{
    int i, j;
    double e[n];
    F(i, 0, n)
        e[i] = 1e9;
    e[n - 1] = 0;
    for(i = n - 2; i >= 0; i--)
    {
        int num = adj[i].size();
        double sum = 0;
        double maxi = 0;
        for(auto j: adj[i])
        {
            sum += e[j];
            maxi = max(maxi, e[j]);
        }
        if(i == blk && num >= 2)
        {
            --num;
            sum -= maxi;
        }
        if(num == 0)
            continue;
        e[i] = (sum / num) + 1;
    }
    return e[0];
}


