  auto graph=make_vector<2,int>(n,0);
  loop(m){
    int u, v; std::cin >> u >> v;
    u--,v--;
    graph[u].emplace_back(v);
  }

  std::vector< double > dp(n, 0);
  for (int i = n - 2; i >= 0; i--) {
    for(int j:graph[i]) dp[i]+=dp[j];
    dp[i]/=graph[i].size();
    dp[i]++;
  }

  std::vector<double> ep(n);
  ep.front()=1;
  rep(i,0,n){
    for(int j:graph[i]){
      ep[j]+=ep[i]/graph[i].size();
    }
  }

  double full = dp.front();
