    double max = *std::max_element(all(v));
    double x = sum / sz;
    double y = (sum-max)/(sz-1);
    double dim=ep[i]*(x-y);
    cmn(ans,full-dim);
  }
  std::cout << std::setprecision(10) << ans << std::endl;
  return 0;
}

