double dfs(int i)
{
  if (ev[i] != -1)
    return ev[i];
  double s = g[i].size();
  for (int nxt : g[i])
    s += dfs(nxt);
  ev[i] = s / g[i].size();
  return ev[i];
}

double dfs2(int i, int cls)
{
  if (ev2[i] != -1)
    return ev2[i];
  if (i == cls)
  {
    int c;
    double emx = -1;
    for (int nxt : g[i])
      if (ev[nxt] > emx)
      {
        emx = ev[nxt];
        c = nxt;
      }
    double s = g[i].size() - 1;
    for (int nxt : g[i])
      if (nxt != c)
        s += ev[nxt];
    ev2[i] = s / (g[i].size() - 1);
    return ev2[i];
  }
  double s = g[i].size();
  for (int nxt : g[i])
    s += dfs2(nxt, cls);
  ev2[i] = s / g[i].size();
  return ev2[i];
}

