int main(){
  cout << fixed << setprecision(20);
  int N,M;
  cin >> N >> M;
  vector<int> s,t;
  int p,q;
  for (int i = 0; i < M; i++){
    cin >> p >> q;
    s.push_back(p-1);
    t.push_back(q-1);
  }
  //隣接リスト表現に変換
  vector<set<int>> L(N);
  //L[i] = 部屋iから行ける部屋
  for (int i = 0; i < M; i++){
    L[s[i]].insert(t[i]);
  }
  //道をふさがないで計算
  vector<double> Etime(N);
  for (int i = 0; i < N; i++){
    Etime[i] = 0;
  }
  for (int i = N - 2; i >= 0; i--){
    int count = 0;
    for (int j : L[i]){
      Etime[i] += Etime[j] + 1;
      count++;
    }
    Etime[i]/=count;
  }
  double Emin = Etime[0];
  //道をふさぐ
  for (int i = 0; i < M; i++){
    bool inv = false;
    int S = s[i];
    int T = t[i];
    if (L[S].size()==1) continue;
    //道i(S->T)をふさぐ
    //DP
    for (int i = 0; i <= S-1; i++){
      Etime[i] = 0;
    }
    for (int i = S-1; i >= 0; i--){
      int count = 0;
      if (i!=S){
       for (int j : L[i]){
          Etime[i] += Etime[j];
          count++;
       }
      } else {
        for (int j : L[i]){
          if (j != T){
            Etime[i] += Etime[j];
            count++;
          }
        }
      }
      Etime[i] = Etime[i]/count+1;
    }
    if (Etime[0]<Emin) Emin=Etime[0];
  }
  cout << Emin;
}

