ld DP() {
	for (int u = 0; u < n; ++ u) {
		for (int v = 0; v <= n; ++ v) dp[u][v] = 0x3f3f3f3f;
	}
	dp[n - 1][n] = 0;
	for (int u = n - 2; ~u; -- u) {
		for (int v = u; v <= n; ++ v) {
			if (v == u) {
				if (g[u].size() == 1) continue;
				ld full = 1, mx = 0;
				for (int i = 0; i < g[u].size(); ++ i) {
					int to = g[u][i];
					full += dp[to][n] / ((int) g[u].size() - 1);
					mx = max(mx, dp[to][n]);
				}
				dp[u][v] = full - mx / ((int) g[u].size() - 1);
			} else {
				dp[u][v] = 1;
				for (int i = 0; i < g[u].size(); ++ i) {
					int to = g[u][i];
					dp[u][v] += min(dp[to][v], dp[to][n]) / (int) g[u].size();
