const double inf = 1e9;

double dfs(int at) {
  if (at == n) {
    return 0.0;
  }
  if (dp[at] > 0) {
    return dp[at];
  }
  double N = 0;
  double tot = 0;
  for (int to: g[at]) {
    double cur = dfs(to);
    if (cur >= inf) {
      //cout<<at<<"->"<<to<<endl;
      //continue;
    }
    N++; tot += cur;
  }
  if (N == 0) {
    return dp[at] = inf;
  }
  return dp[at] = 1.0 + (tot / N);
}

