    vector<vector<P>> graph(N), rev(N);
    for(int i = 0; i < M; ++i){
        int s, t;
        cin >> s >> t;
        --s, --t;
        graph[s].emplace_back(t, i);
        rev[t].emplace_back(s, i);
    }

    double ans = 1e+300;
    for(int ban = 0; ban < M; ++ban){
        vector<bool> arrival_from_1(N), arrival_to_N(N);
        arrival_from_1[0] = arrival_to_N[N - 1] = true;
        auto calc = [&](auto&& self, vector<vector<P>>& g, vector<bool>& b, int from) -> void {
            b[from] = true;
            for(auto& e : g[from]){
                int to = e.first, edge_idx = e.second;
                if(b[to] || edge_idx == ban)    continue;
                self(self, g, b, to);
            }
        };
        calc(calc, graph, arrival_from_1, 0);
        calc(calc, rev, arrival_to_N, N - 1);
        bool ok = arrival_from_1[N - 1];
        for(int i = 0; i < N; ++i)  ok &= arrival_to_N[i];
