                int to = e.first, edge_idx = e.second;
                if(edge_idx == ban) continue;
                ++cnt;
                res += self(self, to);
            }
            return dp[from] = res / cnt + 1;
        };
        dfs(dfs);
        chmin(ans, dp[0]);
    }

    vector<double> dp(N, -1);
