int n, m;
vector<int> adj[666];

double cache[666][666];

double dp(int v, int b) {
  if(v == n) return 0;
  if(adj[v].size() == 0) return 1e18;
  if(cache[v][b] != 0) return cache[v][b];

  vector<double> e;
  int d = adj[v].size();
  for(int u : adj[v]) {
    e.push_back(dp(u, b));
  }

  if(v == b) {
    sort(e.begin(), e.end());
    e.pop_back();
    d--;
  }

  double res = 0;
  for(double t : e) res += t;
  res /= d;
  res += 1.0;

  return cache[v][b] = res;
}

