  vvi g(N) , h(N);
  rep(i , M){
    ini(s , t); s--; t--;
    g[s].pb(t); h[t].pb(s);
  }

  vector<double> arrive(N, 0.0) , prob(N , 0.0) , inv(N , 0.0);

  // 到着確率
  arrive[0] = 1.0;
  rep(i , N){
    each(x , g[i]){
      arrive[x] += arrive[i] / (g[i].size());
    }
  }

  // 到着回数の期待値
  rep(i , N){
    each(x , g[i]){
      prob[x] += (prob[i] + 1) * (arrive[i] / g[i].size() ) / arrive[x];
    }
  }

  // 逆辺
  repr(i , N){
    each(x , h[i]){
      inv[x] += (inv[i] + 1) / g[x].size();
    }
  }

  rep(i , N) trc(g[i]);

  trc(arrive);
  trc(prob);
  trc(inv);

  double ans = prob[N - 1];
  // ふさぐ辺の始点  
  rep(i , N){
    // 1本しか路が出ていないときは塞げない
    if(g[i].size() == 1) continue;

    each(x , g[i]){
      // 今の期待値はinv[i]
      double nxt_inv = ( inv[i] * sz(g[i]) - (1 + inv[x]) ) / (sz(g[i]) - 1);
      double cur = prob[N - 1] - (inv[i] - nxt_inv) * arrive[i];
      amin(ans , cur);
    }
  }
  out(ans);

}

