int sol(int x, int k) {
    if (x == 0 || k == 0) { return 0; }
    return x + sol(x / 2, k - 1);
}
vel pri(int n) {
    veb ans(n, true);
    vel prime;
    for (int j = 2; j < n; j++) {
        if (ans[j]) {
            prime.push_back(j);
            for (int k = 2; j * k < n; k++) {
                ans[j * k] = false;
            }
        }
    }
    return prime;
}
V<double> solve(vel a, vel b, int n, bool return_ex) {
    vvel way(n);
    int m = a.size();
    vel count(n, 0);
    rep(i, m) { way[a[i]].push_back(b[i]); count[b[i]]++; }
    V<double> dp(n, 0); dp[0] = 1;
    V<double> E(n, 0);
    rep(i, n - 1) {
        if (count[i] != 0) {
            E[i] /= dp[i];
            for (auto x : way[i]) {
                dp[x] += dp[i] / way[i].size();
                E[x] += (E[i] + 1) * (dp[i] / way[i].size());
            }
        }
    }
    E[n - 1] /= dp[n - 1];
    if (!return_ex) { return dp; }
    else { return E; }
}
signed main() {
    int n, m; cin >> n >> m;
    vel a(m); vel b(m);
    vvel way(n);
    rep(i, m) { cin >> a[i] >> b[i]; a[i]--; b[i]--; way[a[i]].push_back(b[i]); }
    V<double> E = solve(a, b, n, false);
    V<double> F = solve(a, b, n, true);
    double ans = F[n - 1];
    double ret = F[n - 1];
    rep(i, n) { F[i] = ans - F[i]; }
    rep(i, n) {
        V<double> next_score;
        if (way[i].size() > 1) {
            for (auto x : way[i]) {
                next_score.push_back(F[x]);
            }
            sor(next_score);
            int sum0 = 0;
            int sum1 = 0;
            int sz = next_score.size();
            rep(i, sz) {
                sum0 += next_score[i];
                if (i != 0) { sum1 += next_score[i]; }
            }
            double qans = ret - (sum0 / n) + (sum1 / (n - 1));
            mmax(ans, qans);
        }
    }
    fcout << ans << endl;
    return 0;
}

