double calc(int id){
    for(int u=n-1;u>=1;--u){
        double sum=0,Max=0;
        int cnt=0;
        for(int i=0;i<(int)g[u].size();++i){
            int v=g[u][i];
            sum+=dp[v]+1;
            Max=max(Max,dp[v]+1);
            ++cnt;
        }
        if(cnt>=2 && id==u){
            --cnt;
            sum-=Max;
        }
        dp[u]=sum/cnt;
    }
    return dp[1];
}

