using Graph = vector<set<int>>;

int main() {
  int N, M;
  cin >> N >> M;
  Graph E(N);
  int a, b;
  for (int i=0; i < M; i++) {
    cin >> a >> b; a--; b--;
    E.at(a).insert(b);
  }
  vector<double> ex(N, 0), ex2(N, 0); double ans;
  ex.at(N-1) = 0;
  for (int i=N-2; i >= 0; i--) {
    for (auto x : E.at(i)) {
      ex.at(i) += (ex.at(x) + 1) / E.at(i).size();
    }
  }
  ans = ex.at(0);
  vector<double> mx(N-1, 0);
  for (int i=N-2; i >= 0; i--) {
    int tmp = -1;
    for (auto x : E.at(i)) {
      if (ex.at(x) > tmp) {
        mx.at(i) = x;
        tmp = ex.at(x);
      }
    }
  }
  for (int i=N-2; i >= 0; i--) {
    for (int j=0; j < N; j++)  ex2.at(j) = (j > i ? ex.at(j) : 0);
    if (E.at(i).size() > 1) {
      E.at(i).erase(mx.at(i));
      for (int j=i; j >= 0; j--) {
        for (auto x : E.at(j)) {
          ex2.at(j) += (ex2.at(x) + 1) / E.at(j).size();
        }
      }
      ans = min(ans, ex2.at(0));
      E.at(i).insert(mx.at(i));
    }
  }
  printf("%.8lf\n", ans);
}

