    cin >> s >> t;
    edges[s - 1].push_back(t - 1);
  }

  double ans;
  dp[N - 1] = 0;
  for(int i = N - 2; i >= 0; i--){
    dp[i] = edges[i].size();
    for(int j = 0; j < edges[i].size(); j++){
      dp[i] += dp[edges[i][j]];
    }
    dp[i] /= edges[i].size();
  }
