            dp[j] += dp[edges[j][k]];
          }
          dp[j] /= edges[j].size();
        } else {
          dp[j] = edges[j].size() - 1;
          double max_dp = 0;
          for(int k = 0; k < edges[j].size(); k++){
            dp[j] += dp[edges[j][k]];
