        G[b].push_back(a);
        edge[i]={a,b};
        out[a]++;
    }

    double ans=INF;

    ans=min(ans,solve({-1,-1}));

    for(int i=0;i<N;i++){
        int num=-1;
        double maxi=INF;
        double cnt=0.0,sum=0.0;
        for(int from:G[i]){
            cnt+=preQ[from]/prechild[from];
            sum+=(preP[from]+1.0)*preQ[from]/prechild[from];
        }

        for(int j=0;j<M;j++){
            if(edge[j].second==i&&out[edge[j].first]!=1){
                int from=edge[j].first;
                if(cnt==preQ[from]/prechild[from]){
                    num=j;
                    break;
                }
                double X=(sum-(preP[from]+1.0)*preQ[from]/prechild[from])/(cnt-preQ[from]/prechild[from]);
                if(maxi>X){
                    num=j;
                    maxi=X;
                }
                //cout<<i<<" "<<X<<" "<<solve(edge[j])<<endl;
            }
        }
        //if(num!=-1)cout<<solve(edge[num])<<endl;
        if(num!=-1) ans=min(ans,solve(edge[num]));
    }

    cout<<setprecision(25)<<ans<<endl;
}

