Vertex V[605];
//! 頂点iにjかいで来る確率
double E[605][605];

int main()
{
    ll N, M;
    cin >> N >> M;
    REP(i, M)
    {
        ll s, t;
        cin >> s >> t;
        s--;
        t--;
        V[s].node.push_back(pll(t, i));
        V[t].child++;
    }

    double min = INF;
    REP(m, M + 1)
    {
        //! 辺mを禁止
        REP(i, N)
        {
            V[i].count = 0;
        }
        REP(i, N)
        {
            REP(j, N)
            {
                E[i][j] = 0;
            }
        }
        E[0][0] = 1;
        bool exsit = true;
        REP(i, N - 1)
        {
            //! 辺iを処理
            ll num = 0;
            REP(j, V[i].node.size())
            {
                auto next = V[i].node[j];
                if (next.second == m)
                    continue;
                num++;
            }
            if (num == 0)
            {
                exsit = false;
                break;
            }
            REP(j, V[i].node.size())
            {
                auto next = V[i].node[j];
                if (next.second == m)
                    continue;
                REP(k, i + 1)
                {
                    E[next.first][k + 1] += E[i][k] / (double)num;
                }
            }
        }
        if (!exsit)
            continue;
        double e = 0;
        REP(i, N)
        {
            e += E[N - 1][i] * (double)i;
        }
        // cout << "m" << m << endl;
        // REP(i, N)
        // {
        //     REP(j, N)
        //     {
        //         cout << OF64 << E[i][j] << " ";
        //     }
        //     cout << endl;
        // }
        min = std::min(min, e);
    }
    cout << OF64 << min << endl;
    return 0;
}

