const int N = 607;

vector <int> g[N];
double sum[N], from[N];

void solve() {
    int n, m;
    cin >> n >> m;
    loop(i, m) {
        int u, v;
        cin >> u >> v;
        g[u].pb(v);
    }
    loop1(cv, n) {
        loop(i, N)
            sum[i] = 0;
        sum[cv] = 1;
        for (int v = cv; v <= n; ++v) {
            for (int u : g[v]) {
                double pls = sum[v] / g[v].size();
                from[cv] += pls; sum[u] += pls;
            }
        }
    }
    double ans = from[1];
    loop1(i, n) {
        if (g[i].size() < 2)
            continue;
        loop(j, N)
            sum[j] = 0;
        sum[1] = 1;
        double cur = 0;
        loop1(v, n) {
            int bad = 0;
            if (v == i)
                for (int u : g[v])
                    if (from[u] > from[bad])
                        bad = u;
            for (int u : g[v]) {
                if (bad == u)
                    continue;
                double pls = sum[v] / (g[v].size() - (v == i));
                cur += pls; sum[u] += pls;
            }
        }
        ans = min(ans, cur);
    }
    cout << fixed << setprecision(7) << ans;
}

