void solve(){
    // generate_array(size, min, max);
    ll n, m; in2(n, m);
    Graph graph(n);
    vpl paths;
    rep(i, m){
        ll a, b; in2(a, b); a--, b--;
        graph[a].pb({b, 1});
    }

    vector<ld> dp(n, -1); dp[n - 1] = 0;
    auto dfs = [&](auto dfs, ll src, ll rm) -> ld{
        if (dp[src] > -EPS) return dp[src];
        ld ret = 0; ll a = -1, b = -1, deg = 0;
        if (rm != -1) tie(a, b) = paths[rm];
        for (auto& e: graph[src])
            if (a != src || b != e.to)
                ret += dfs(dfs, e.to, rm) + 1, deg++;

        return dp[src] = ret / ld(deg);
    };

    dfs(dfs, 0, -1); ld ans = dp[0];
    vector<ld> memo = dp;
    rep(i, n){
        ll idx = 0; ld v = 0;
        for (auto& e: graph[i])
            if (chmax(v, memo[e.to])) idx = e.to;
        paths.pb({i, idx});
    }

    rep(i, paths.size()){
        ll a, b; tie(a, b) = paths[i];
        if (graph[a].size() == 1) continue;
        fill(all(dp), -1); dp[n - 1] = 0;
        dfs(dfs, 0, i);
        chmin(ans, dp[0]);
    }
    prl_nd(ans, 12);

    // ### DEBUG PART ###
    auto naive_solver = [&](){
    };
    #ifdef _LOCAL
        naive_solver();
    #endif
}

