double cnt[606], disum[606];
int from_v[404040], to_v[404040];

double solve(int pass){
    REP(i, n)indeg[i] = id[i], cnt[i] = 0.0, disum[i] = 0.0;
    queue<int> q2;
    indeg[to_v[pass]]--;
    if(indeg[to_v[pass]] == 0)q2.push(to_v[pass]);

    while(!q2.empty()){
        int cur = q2.front();
        q2.pop();
        for(auto to : graph[cur]){
            indeg[to.first]--;
            if(indeg[to.first] == 0)q2.push(to.first);
        }
    }
    queue<int> q;
    q.push(0);
    cnt[0] = 1.0;
    while(!q.empty()){
        int cur = q.front();
        q.pop();
        for(auto to : graph[cur]){
            if(to.second == pass){
                if(graph[cur].size() == 1){
                    return HINF<LL>();
                }else{
                    continue;
                }
            }
            cnt[to.first] += cnt[cur];
            disum[to.first] += disum[cur] + cnt[cur];
            indeg[to.first]--;
            if(indeg[to.first] == 0){
                q.push(to.first);
            }
        }
    }
    return disum[n - 1] / cnt[n - 1];
}

