#include<bits/stdc++.h>
using namespace std;

const int N=600;

struct NODE{
    int to,id;NODE *nxt;
    NODE(){}
    NODE(int _t,int _i,NODE *_n):to(_t),id(_i),nxt(_n){}
};
struct GRAPH{
    NODE pol[N*N],*head[N+3],*ncnt;
    int du[N+3];
    void Init(){
        ncnt=pol;
    }
    void AddEdge(int u,int v,int id){
        NODE *p=++ncnt;
        *p=NODE(v,id,head[u]);head[u]=p;du[u]++;
    }
}G;

int n,m,del;
int frm[N*N];
int seid[N+3];
double Te[N+3],Se[N+3];
bool vis[N+3];
double mngx[N+3];

double FirDP(int u){
    if(vis[u]) return Te[u];
    vis[u]=true;
    if(u==n) return Te[u]=0;
    mngx[u]=1e9;
    for(NODE *it=G.head[u];it;it=it->nxt){
        int v=it->to;
        double resu=FirDP(v);
        if(mngx[u]>resu){
            mngx[u]=resu;
            seid[u]=it->id;
        }
        Te[u]+=(resu+1)/G.du[u];
    }
    return Te[u];
}
double DP(int u){
    if(vis[u]) return Te[u];
    vis[u]=true;
    if(u==n) return Te[u]=0;
    mngx[u]=1e9;
    if(u==del){
        for(NODE *it=G.head[u];it;it=it->nxt){
            int v=it->to;
            if(it->id==seid[u]) continue;
            double resu=DP(v);
            Te[u]+=(resu+1)/(G.du[u]-1);
        }
    }
