    int n, m;
    cin >> n >> m;
    unordered_map<int, unordered_set<int>> prev, next;


    for (int i = 0; i < m; i++) {
        int s, t;
        cin >> s >> t;
        prev[t].insert(s);
        next[s].insert(t);
    }

    vector<long double> dist(n + 1, -1);
    dist[n] = 0;
    for (int i = n - 1; i >= 1; i--) {
        long double total_dist = 0;
        int total_c = 0;
        for (auto t : next[i]) {
            if (dist[t] < 0) continue;
            total_dist += 1 + dist[t];
            total_c += 1;
        }
        if (total_c == 0)
            continue;
        dist[i] = total_dist / total_c;
    }

    long double res = dist[1];
    // cout << res << endl;
    for (auto p : next) {
        int s = p.first;
        for (auto t : p.second) {
            if (next[s].size() == 1) continue;
            vector<long double> new_dist = dist;

            for (int i = t - 1; i >= 1; i--) {
                long double total_dist = 0;
                int total_c = 0;
                for (auto nt : next[i]) {
                    if (new_dist[nt] < 0) continue;
                    if (t == nt && s == i) continue;
                    total_dist += new_dist[nt];
                    total_c += 1;
                }
                if (total_c == 0)
                    continue;
                new_dist[i] = total_dist / total_c + 1;
            }
