double dp[605];
double coef[605];
vector<int> e[606];
vector<int> re[606];
double dfs1(int u, pair<int, int> dame = make_pair(-1, -1))
{
  double &ret = dp[u];
  if (ret >= 0)
    return ret;
  ret = 0.0;
  double p = 1.0 / (e[u].size() - (dame.first == u));
  for (auto s : e[u])
  {
    if ((make_pair(u, s) != dame))
      ret += p * (dfs1(s, dame) + 1.0);
  }
  return ret;
}

void solve(long long N, long long M, std::vector<long long> s,
           std::vector<long long> t)
{
  rep(i, N) dp[i] = -1;
  dp[N - 1] = 0.0;
  vadd(s, -1);
  vadd(t, -1);
  map<int, map<int, int>> id;
  rep(i, M) e[s[i]].push_back(t[i]), re[t[i]].push_back(s[i]);
  rep(i, M) id[s[i]][t[i]] = i;

  coef[0] = 1.0;
  rep(i, N)
  {
    double p = 1.0 / e[i].size();
    for (auto s : e[i])
      coef[s] += p * (coef[i] + 1);
  }
  rep(i, N) dfs1(i);
  double ret = dp[0];
  vector<int> cand;
  rep(i, N)
  {
    double ma = -1;
    int idx = -1;
    for (auto s : e[i])
    {
      if (chmax(ma, dp[s]))
        idx = s;
    }
    if (idx >= 0 && e[i].size() > 1)
      cand.push_back(id[i][idx]);
  }
  for (auto j : cand)
  {
    rep(i, N - 1) dp[i] = -1.0;

    double tp = dfs1(0, make_pair(s[j], t[j]));
    if (tp > 0)
      chmin(ret, tp);
  }
  printf("%.10f\n", ret);
}
signed main()
{
  long long N;
  scanf("%lld", &N);
  long long M;
  scanf("%lld", &M);
  std::vector<long long> s(M);
  std::vector<long long> t(M);
  for (int i = 0; i < M; i++)
  {
    scanf("%lld", &s[i]);
    scanf("%lld", &t[i]);
  }
  solve(N, M, std::move(s), std::move(t));
  return 0;
}

