#include <bits/stdc++.h>
using namespace std;
typedef long double ld;

const int N = 600 + 5;

int n, m, G[N][N], slowest[N];
ld dp[N];

ld DP(int u) {
  if(u == n) return 0;
  if(dp[u] >= 0) return dp[u];
  dp[u] = 0;
  int cc = 0;
  for(int i = 1 ; i <= n ; ++i) if(G[u][i]) {
    cc++;
    dp[u] += DP(i) + 1;
  }
  assert(cc > 0);
  dp[u] /= cc;
  return dp[u];
}

void init() {
  cin >> n >> m;
  for(int i = 0 ; i < m ; ++i) {
    int s, t; cin >> s >> t; G[s][t] = 1;
  }
}
void solve() {
  for(int i = 1 ; i < n ; ++i) dp[i] = -1;
  ld ans = DP(1);
  for(int i = 1 ; i <= n ; ++i) {
    int cc = 0, t = 0; ld mx = 0;
    for(int j = 1 ; j <= n ; ++j) if(G[i][j]) {
      cc++;
      if(dp[j] > mx) {
        mx = dp[j];
        t = j;
      }
    }
    if(cc > 1) slowest[i] = t;
  }
  for(int i = 1 ; i <= n ; ++i) if(slowest[i] != 0) {
    G[i][slowest[i]] = 0;
    for(int j = 1 ; j < n ; ++j) dp[j] = -1;
    ans = min(ans, DP(1));
    G[i][slowest[i]] = 1;
  }
  cout << fixed << setprecision(10) << ans << '\n';
}

int main() {
  ios_base::sync_with_stdio(0), cin.tie(0);
  init();
  solve();
}

