int main() {
	int N, M, s, t, sz;
	cin >> N >> M;
	for (int i = 0;i < M;i++) {
		cin >> s >> t;
		G[s].push_back(t);
		E[i] = { s,t };
	}
	for (int i = N;i > 0;i--) {
		cost[i] = 1.0;
		//(接続先の期待値+1)*(そこに進む確率)
		for (int j = i - 1;j > 0;j--) {
			sz = G[j].size();
			for (int k : G[j]) {
				cost[j] += cost[k] / sz;
			}
		}
		les[i] = cost[1];
		for (int j = 1;j <= N;j++)cost[j] = 0.0;
	}

	for (int i = N;i > 0;i--) {
		sz = G[i].size();
		for (int k : G[i]) {
			cost[i] += (cost[k] + 1) / sz;
		}
	}

	double ans = 0, tp;
	for (int i = 0;i < M;i++) {
		tie(s, t) = E[i];
		sz = G[s].size();
		if (sz == 1)continue;
		tp = cost[s] - (cost[t] + 1.0) / sz;
		tp *= (double)sz / (sz - 1);
		tp = (cost[s] - tp) * les[s];
		ans = max(tp, ans);
	}
	printf("%.10f", cost[1] - ans);
}

