ld dfs(li v) {
    if(r[v] > -1) return(r[v]);
    r[v] = 0;
    if(!g[v].size()) return(0);
    for(auto i : g[v]) r[v] += dfs(i);
    r[v] = r[v] / g[v].size() + ld(1);

    return(r[v]);
}

