double rcost[600];
vector<int> e[600], re[600];

double tmp[600];

int main() {
	int n, m; reader(n, m);
	FOR(i, m) {
		int s, t; reader(s, t);
		s--; t--;
		e[s].push_back(t);
		re[t].push_back(s);
	}

	for (int i = n - 1; i >= 0; i--) {
		if (sz(e[i])) rcost[i] /= sz(e[i]);
		for (auto from : re[i]) {
			rcost[from] += rcost[i] + 1;
		}
	}
	double ans = rcost[0];

	for (int x = 0; x < n - 1; x++) {
		int delTo = -1; double delCost = 0;
		if (sz(e[x]) == 1) continue;
		for (auto to : e[x]) {
			if (delCost < rcost[to]) {
				delCost = rcost[to];
				delTo = to;
			}
		}
		FOR(i, n) tmp[i] = 0;
		for (int i = n - 1; i >= 0; i--) {
			int ne = sz(e[i]);
			if (x == i) ne--;
			if (ne) tmp[i] /= ne;
			for (auto from : re[i]) {
				if (i == delTo && from == x) {
					continue;
				}
				tmp[from] += tmp[i] + 1;
			}
		}
		ans = min(ans, tmp[0]);
	}
	printf("%.15lf\n", ans);


	return 0;
}

