using namespace std;
const int MAXN=605;
const int MAXM=MAXN*MAXN;
const int INF=0X3F3F3F3F;
int N,M,Cnt[MAXN],cnt[MAXN],Mx[MAXN];
double f[MAXN],s[MAXN],Ans=MAXM;
double Mval[MAXN];
vector<int>P[MAXN];
queue<int>Q;
void Init_BFS(int u){
	while(!Q.empty())Q.pop();
	Q.push(u);f[u]=0;s[u]=1;
	while(!Q.empty()){
		u=Q.front();Q.pop();
		f[u]=f[u]/s[u];
		int size=P[u].size();
		for(int i=0;i<size;i++){
			int v=P[u][i];
			f[v]+=(f[u]+1)*s[u]/size;
			s[v]+=s[u]/size;
			if((f[u]+1)/s[u]/size>=Mval[v]){
				Mval[v]=(f[u]+1)*s[u]/size;
				Mx[v]=u;
			}
			if(--cnt[v]==0)Q.push(v);
		}
	}
}
void DBFS(int u){
	while(!Q.empty())Q.pop();
	Q.push(u);
	while(!Q.empty()){
		u=Q.front();Q.pop();
		int size=P[u].size();
		for(int i=0;i<size;i++){
			int v=P[u][i];
			if(--cnt[v]==0)Q.push(v);
		}
	}
}
void BFS(int u,int x,int y){
	Cnt[y]--;
	for(int i=1;i<=N;i++)
		cnt[i]=Cnt[i],f[i]=s[i]=0;
	for(int i=2;i<=N;i++)
		if(cnt[i]==0)DBFS(i);
	while(!Q.empty())Q.pop();
	Q.push(u);f[u]=0;s[u]=1;
	while(!Q.empty()){
		u=Q.front();Q.pop();
		f[u]=f[u]/s[u];
		int size=P[u].size();
		int ssize=size-(x==u);
		for(int i=0;i<size;i++){
			int v=P[u][i];
			if(u==x&&v==y)continue;
			f[v]+=(f[u]+1)*s[u]/ssize;
			s[v]+=s[u]/ssize;
			if(--cnt[v]==0)Q.push(v);
		}
	}Cnt[y]++;
}
int main(){
	scanf("%d%d",&N,&M);
	for(int i=1,x,y;i<=M;i++){
		scanf("%d%d",&x,&y);
		P[x].push_back(y);
		Cnt[y]++;cnt[y]++;
	}
	Init_BFS(1);Ans=min(Ans,f[N]);
	for(int i=1;i<=N;i++){
		if(Mx[i]&&P[Mx[i]].size()!=1){
			BFS(1,Mx[i],i);
			if(f[N])Ans=min(Ans,f[N]);
		}
	}
	printf("%.10f\n",Ans);
}

