int N, M;

vector<vector<int>> graph;

bool visited[666][2];
double dp[666][2];

double rec(int cur, int f) {
    if (visited[cur][f]) return dp[cur][f];
    if (cur == N - 1) return 0.0;
    visited[cur][f] = true;

    // まだ塞げる
    if (f == 0) {

        vector<double> cand1, cand2;
        EACH(nxt, graph[cur]) {
            cand1.emplace_back(rec(nxt, 0));    // 塞がない
            cand2.emplace_back(rec(nxt, 1));    // 塞ぐ
        }

        int sz = cand1.size();
        if (sz == 1) {
            return dp[cur][f] = cand1[0] + 1.0;
        }

        SORT(cand1);
        SORT(cand2);

        double ret1 = 0.0, ret2 = 0.0;
        REP(i, sz) ret1 += cand1[i] / sz;
        REP(i, sz - 1) ret2 += cand2[i] / (sz - 1);

        return dp[cur][f] = min(ret1, ret2) + 1.0;
    }

    // もう塞げない
    vector<double> cand;
    EACH(nxt, graph[cur]) {
        cand.emplace_back(rec(nxt, 1));
    }
    double ret = 0.0;
    int sz = cand.size();
    REP(i, sz) ret += cand[i] / sz;
    return dp[cur][f] = ret + 1.0;
}

