int main() {
    int N, M;
    cin >> N >> M;

    vector<vector<int>> G(N);
    for(int i=0;i<M;i++){
        int s, t;
        cin >> s >> t;
        G[s - 1].push_back(t - 1);
    }

    double ans = N;
    for(int k=0;k<N;k++){
        vector<double> dp(N, 0);
        for(int i=N - 2;i>=0;i--){
            int m = G[i].size();
            double expect_sum = 0, expect_max = 0;
            for(int to : G[i]){
                expect_sum += dp[to];
                expect_max = max(expect_max, dp[to]);
            }
            if(i == k && m > 1){
                dp[i] = (expect_sum - expect_max) / (m - 1) + 1;
            }else{
                dp[i] = expect_sum / m + 1;
            }
        }
        ans = min(ans, dp[0]);
    }
    printf("%.8f\n", ans);

