const double inf = 1e100;

int n, m;
vector<int> G[600];
double P[600];
double E[600];
int main() {
  scanf("%d %d", &n, &m);
  for (int j = 0; j < m; ++j) {
    int a, b;
    scanf("%d %d", &a, &b);
    --a; --b;
    G[a].push_back(b);
  }

  P[0] = 1;
  for (int i = 0; i < n; ++i) {
    for (int j : G[i]) {
      P[j] += P[i] / G[i].size();
    }
  }

  for (int i = n - 2; i >= 0; --i) {
    double sum = 0;
    for (int j : G[i]) {
      sum += E[j];
    }
    E[i] = sum / G[i].size() + 1;
  }

  double mn = 0;
  for (int i = 0; i < n; ++i) {
    int d = G[i].size();
    if (d <= 1) continue;
    for (int j : G[i]) {
      double ans = P[i] * (E[i] - E[j] - 1) / (d - 1);
      mn = min(mn, ans);
    }
  }
  printf("%.16f", E[0] + mn);
}

