db f[606];
int d[606];

void dp(int k) {
	rep(i, 1, n) f[i] = 1e300;
	queue <int> que;
	que.push(n);
	memcpy(d, cd, sizeof d);
	while(que.size()) {
		int now = que.front(); que.pop();
		db ans = 0;
		int cnt = 0;
		for(int i = head[now]; i; i = nxt[i]) {
			-- d[to[i]];
			if(d[to[i]] == 0) que.push(to[i]);
		}
		db mxx = 0;
		for(int i = head1[now]; i; i = nxt1[i]) {
			if(now == k) mxx = max(mxx, f[to1[i]]);
			ans += f[to1[i]];
			++ cnt;
		}
		if(cnt == 0) f[now] = 0;
		else {
			if(cnt >= 2 && now == k) f[now] = (ans - mxx) / (cnt - 1) + 1;
			else f[now] = ans / cnt + 1;
		}
	}
}

