#define REP(k,m,n) for(int (k)=(m);(k)<(n);(k)++)
#define rep(i,n) REP((i),0,(n))
using ll = long long;
using ld = long double;



int main()
{
    int N, M;
    cin >> N >> M;
    vector<vector<int>> edges(N), revs(N);
    vector<pair<int, int>> edgep;
    rep(i, M) {
        int s, t;
        cin >> s >> t;
        s--; t--;
        edges[s].push_back(t);
        revs[t].push_back(s);
        edgep.push_back({ s,t });
    }

    vector<ld> prob(N, 0);
    prob[0] = 1;
    REP(i, 1, N) {
        for (int bef : revs[i]) {
            prob[i] += prob[bef] / edges[bef].size();
        }
    }

    vector<ld> esti(N, 1);
    esti[N - 1] = 0;
    for (int i = N - 1; i >= 0; i--) {
        for (int next : edges[i]) {
            esti[i] += esti[next] / edges[i].size();
        }
    }

    ld bestscore = 0;
    pair<int, int> bestedge = { -1,-1 };

    for (auto edge : edgep) {
        int s, t;
        tie(s, t) = edge;
        if (edges[s].size() <= 1)continue;
        ld befscore = esti[s];
        ld siz = edges[s].size();
        ld aftscore = (befscore - 1 - esti[t] / siz)*siz / (siz - 1) + 1;
        ld diff = befscore - aftscore;
        ld score = prob[s] * diff;
        if (score > bestscore) {
            bestscore = score;
            bestedge = edge;
        }
        //cout << s << "->" << t << ": " << befscore << "->" << aftscore << ":" << score << endl;
    }

    if (bestedge.first != -1) {
        int s, t;
        tie(s, t) = bestedge;
        edges[s].erase(find(edges[s].begin(), edges[s].end(), t));
    }
    esti = vector<ld>(N, 1);
    esti[N - 1] = 0;
    for (int i = N - 1; i >= 0; i--) {
        for (int next : edges[i]) {
            esti[i] += esti[next] / edges[i].size();
        }
    }
    cout << fixed << setprecision(12) << esti.front() << endl;
    return 0;
}

