    for(int i=v-1; i>=0; i--){
        double sum = 0, num = 0;
        path[i] = {};
        for(int v : graph[i]){
            path[i].insert(expect[v] + 1);
            sum += expect[v] + 1;
            num += 1;
        }
        expect[i] = sum / num;
    }
