/*
f[i] = 1 + \frac 1{deg_i} \sum_{i \rightarrow j} f[j]

设 $f_1 = a_if_i + b_i$。这里 $b_i$ 为 $i + 1 \leq j \leq n$ 的贡献。 

$O(NM)$ 枚举解 $a_i, b_i$，暴力枚举断边随便算一下即可。

时间复杂度：$O(NM)$。 
*/

#include <cstdio>
#include <cstring>
#include <algorithm>

const int MAXN = 600 + 10;

int to[MAXN][MAXN], deg[MAXN];
double f[MAXN];
double fa[MAXN], fb[MAXN];
double pa[MAXN], pb[MAXN];

int main() {
	int i, j;
	int n, m;
	int u, v, t;
	double fx;
	double ans;

	scanf("%d %d", &n, &m);
	for(i=1; i<=m; i++) {
		scanf("%d %d", &u, &v);
		deg[u]++;
		to[u][deg[u]] = v;
	}

	for(u=n - 1; u; u--) {
		for(i=1; i<=deg[u]; i++) 
			f[u] += f[to[u][i]];
		f[u] = 1 + f[u] / deg[u];
	}

	ans = f[1];
	for(t=1; t<n; t++) {
		memset(pa, 0, sizeof(pa));
		memset(pb, 0, sizeof(pb));
		for(u=n-1; u; u--) {
			if(u == t) {
				pa[u] = 1;
				pb[u] = 0;
				continue;
			}
			pa[u] = 0;
			pb[u] = 1;
			for(i=1; i<=deg[u]; i++) {
				if(to[u][i] > t) 
					pb[u] += f[to[u][i]] / deg[u];
				else {
					pa[u] += pa[to[u][i]] / deg[u];
					pb[u] += pb[to[u][i]] / deg[u];
				}
			}
		}
		fa[t] = pa[1];
		fb[t] = pb[1];
	}

//	printf("f = ");
//	for(u=1; u<=n; u++)
//		printf("%lf ", f[u]);
//	putchar('\n');

//	for(u=1; u<n; u++)
//		printf("# %d %lf %lf\n", u, fa[u], fb[u]);

	for(u=1; u<n; u++){
		if(deg[u] > 1) {
			for(i=1; i<=deg[u]; i++) {
				fx = 0;
				for(j=1; j<=deg[u]; j++) 
					if(i^j) 
						fx += f[to[u][j]];
				fx = 1 + fx / (deg[u] - 1);
//				printf("# %d->%d %lf\n", u, to[u][i], fx);
				ans = std::min(ans, fa[u] * fx + fb[u]);
			}
		}
	}
	printf("%.12lf\n", ans);
	return 0;
}

