long double solve(int f, int s) {
  vector<long double> dp(n - 1, 0.0);
  repr(u, n - 2) {
    long double exp = (long double)G[u].size();
    if (u == f) exp -= 1.0;
    for (int v: G[u]) {
      if (u == f && v == s) continue;
      if (dp[v] > 0) exp += dp[v];
    }
    if (u == f) dp[u] = exp / ((long double)G[u].size() - 1.0);
    else dp[u] = exp / (long double)G[u].size();
  }

  return dp[0];
}

