template<class Type>
Type solve(Type res = Type()){
    int N,M; cin >> N >> M;
    vector<vector<int>> G(N);
    for(int i = 0; i < M;i++){
        int s,t; cin >> s >> t;
        s--; t--;
        G[s].emplace_back(t);
    }

    res = LINF;
    for(int i = 0; i < N-1;i++){
        vector<double> dp(N,LINF);
        dp[N-1] = 0;
        for(int j = N-2; j>= 0; j--){
            double sump = 0;
            double maxp = 0;
            for(auto v:G[j]){
                sump += dp[v];
                maxp = max(maxp,dp[v]);
            }

            if(j == i && G[j].size() > 1){
                dp[j] = (sump-maxp)/(G[j].size()-1) + 1;
            }else{
                dp[j] = sump/G[j].size() + 1;
            }
        }
        res = min(res,dp[0]);
    }
    return res;
}
