double solve(int pos)
{
  if(dp[pos] != -1) {
    return dp[pos];
  }

  if(pos == N) {
    return 0.0;
  }

  double ret = 0.0;
  int counter = 0;

  for(int next : edge[pos]) {
    if(D.first == pos && D.second == next) {
      continue;
    }
    counter++;
    double tmp = solve(next);
    if(tmp == INF_LL) {
      return INF_LL;
    }
    ret += tmp + 1;
  }

  if(counter == 0) {
    return INF_LL;
  }

  return dp[pos] = ret / counter;
}

