  int n, m; // n:頂点数 m:辺数
  cin >> n >> m;

  vector<int> G[n]; // G:頂点数がnのグラフを表す隣接リスト

  for (int i = 0; i < m; i++) {
    int u, v;
    cin >> u >> v;
    u--;
    v--;
    G[u].emplace_back(v);
    // G[v].emplace_back(u); // 有向グラフではこの行をコメントアウト
  }

  vector<double> origin(n);

  for (int i = n - 2; i >= 0; i--) {
    double sum = 0;
    for (int j = 0; j < G[i].size(); j++) sum += origin[G[i][j]];
    origin[i] = sum / G[i].size() + 1;
  }

  double ans = origin[0];
  for (int i = n - 2; i >= 0; i--) {
    if (G[i].size() == 1) continue;
    vector<double> update = origin;
    for (int j = i; j >= 0; j--) {
      double sum = 0;
      if (j == i) {
        double maximum = 0;
        for (int k = 0; k < G[j].size(); k++) {
          sum += update[G[j][k]];
          maximum = max(maximum, update[G[j][k]]);
        }
        update[j] = (sum - maximum) / (G[j].size() - 1) + 1;
      }
      else {
        for (int k = 0; k < G[j].size(); k++) sum += update[G[j][k]];
        update[j] = sum / G[j].size() + 1;
      }
      ans = min(ans, update[0]);
    }
  }

  cout << fixed << setprecision(10) << ans << '\n';
}

