int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(NULL);
  ll N, M;
  cin >> N >> M;
  vvl G(N);
  vvl G2(N);
  REP(i, M) {
    ll s, t;
    cin >> s >> t;
    G[s - 1].push_back(t - 1);
    G2[t - 1].push_back(s - 1);
  }
  //閉路はない！！！！！
  long double ans = 10000;

  vector<long double> DP(N + 1, 0);
  FOR(_, 0, 1) {
    queue<pair<ll, pair<long double, long double>>> que;
    que.push(make_pair(N - 1, make_pair(0, 1)));
    while (!que.empty()) {
      auto pos = que.front();
      que.pop();
      ll count = G2[pos.first].size();

      AUTO(g, G2[pos.first]) {
        DP[g] += (pos.second.first + 1) * pos.second.second *
                 ((long double)1 / count);
        que.push(make_pair(
            g, make_pair(pos.second.first + 1,
                         pos.second.second * ((long double)1 / count))));
      }
    }
  }
  // n=N-1の時は道を塞がない
  REP(n, N) {
    // mを塞ぐ
    queue<pair<ll, pair<long double, long double>>> que;
    que.push(make_pair(0, make_pair(0, 1)));
    long double score = 0;
    while (!que.empty()) {
      auto pos = que.front();
      que.pop();
      if (pos.first == N - 1) {
        score += pos.second.first * pos.second.second;
        continue;
      }
      ll count = G[pos.first].size();
      ll m = -1;
      if (pos.first == n) {
        count--;
        long double ma = -1;
        AUTO(g, G[pos.first]) {
          if (DP[g] > ma) {
            m = g;
            ma = DP[g];
          }
        }
      }
      if (count == 0) {
        score = 1000000;
        break;
      }

      AUTO(g, G[pos.first]) {
        if (g != m)
          que.push(make_pair(
              g, make_pair(pos.second.first + 1,
                           pos.second.second * ((long double)1 / count))));
      }
    }
    ans = min(ans, score);
  }

  cout << SP(20) << ans << endl;

  return 0;
}

