bool fail = false;

long double solve(int node) {
    if(node == n)
        return 0;
    if(vis[node])
        return dp[node];
    vis[node] = true;
    long double ans = 0;
    int sz = adjList[node].size();
    int cnt = 0;
    for(int i = 0;i<sz;i++)
        if(!blocked[node][i])
            ans += solve(adjList[node][i]), cnt++;
    if(cnt)
        ans /= cnt;
    else
        fail= true;
    return dp[node] = 1+ans;
}

