    }
    long double ans = solve(1);
    for(int i = 1;i<=n;i++) {
        for(int j =0;j<adjList[i].size();j++) {
            blocked[i][j] = true;
            fail = false;
            memset(vis, false, sizeof vis);
            long double currAns = solve(1);
            blocked[i][j] = false;
            if(fail)
                continue;
            ans = min(ans, currAns);
        }
    }
