int N,M;
vector<vector<int> > G;
vector<pair<int, int> > P;
vector<vector<double> > dp;

double sol( int im, int inum  )
{
  if( dp[im][inum] > -0.00000001 )
    {
      return dp[im][inum];
    }

  int num = 0;
  double sm = 0.0;
  double mx = 0.0;

  for( const auto& elem : G[inum] )
    {
      double temp = sol(0,elem) + 1.0;
      sm += temp;
      mx = max(temp,mx);
      ++ num;
    }

  double res = 2e18;
  if( num  > 0 )
    {
      res = min(res,sm/num);
    }

  if( im == 1 and 1 < num )
    {
      res = min(res,(sm-mx)/(num-1));
    }

  return dp[im][inum] = res;

}




signed main()
{
  IOS; /* making cin faster */
  SCAND2(N,M);
  G.resize(N);
  P.resize(M+1);
  dp.assign(M+1,vector<double>(N,-1.0));

  REP(i,M)
    {
      int s,t;
      SCAND2(s,t);
      -- s;
      -- t;
      G[s].push_back(t);
      P[i] = make_pair(s,t);
    }

  REP(i,M+1)
    {
      dp[i][N-1] = 0.0;
    }

  double mn = 1e18;
  REP(i,2)
    {
      mn = min(mn,sol(i,0));
    }

  printf("%.15lf\n",mn);


}

