double solve(int n, vii &G, pii kin) {
  vector<double> dp(n);
  dp[n - 1] = 0;
  rrep (i, n - 1) {
    rep (j, G[i].size()) {
      int v = G[i][j];
      if (i == kin.first and v == kin.second) continue;
      dp[i] += dp[v] + 1;
    }
    if (i != kin.first) {
      dp[i] /= (int)(G[i].size());
    }
