double cal_min_estimate(const std::vector<std::vector<int>> rooms, const int current_room, const int remove, std::vector<std::vector<double>>& memo) {
	if (current_room + 1 == rooms.size()) 
		return 0;
	if (remove < current_room && memo[current_room][0] >= 0) 
		return memo[current_room][0];
	if (current_room <= remove && memo[current_room][remove - current_room + 1] >= 0) 
		return memo[current_room][remove - current_room + 1];
	if (current_room == remove && rooms[current_room].size() > 1) {
		double sum = 0;
		double max = 0;
		for (const auto next : rooms[current_room]) {
			const auto res = cal_min_estimate(rooms, next, rooms.size() - 1, memo);
			sum += res;
			max = std::max(max, res);
		}
		return memo[current_room][remove - current_room + 1] = std::min((sum - max) / (rooms[current_room].size() - 1), sum / rooms[current_room].size()) + 1;
	}
	else {
		double sum = 0;
		for (const auto next : rooms[current_room]) {
			sum += cal_min_estimate(rooms, next, remove, memo);
		}
		if (remove < current_room) return memo[current_room][0] = sum / rooms[current_room].size() + 1;
		else return memo[current_room][remove - current_room + 1] = sum / rooms[current_room].size() + 1;
	}
}
int main() {
	std::cin.tie(0); std::cin.sync_with_stdio(false);
	int n, m; std::cin >> n >> m;
	std::vector<std::vector<int>> rooms(n);
	for (auto i = 0; i < m; ++i) {
		int s, t; std::cin >> s >> t;
		rooms[s - 1].push_back(t - 1);
	}
	std::vector<std::vector<double>> memo(n);
	for (auto i = 0; i < n; ++i) memo[i] = std::move(std::vector<double>(n - i + 1, -1.0));
	double min = n;
	for (auto i = 0; i < n - 1; ++i) if (i == 0 || rooms[i].size() > 1) {
		min = std::min(min, cal_min_estimate(rooms, 0, i, memo));
	}
	std::cout << std::setprecision(15) << std::fixed << min << '\n';
}

