	for (int skip : cand) {
		if (skip == -1) continue;
		a = v[skip].first;
		b = v[skip].second;
		if (cnt[a] == 1) continue;
		gr[a].erase(b);
		cnt[a]--;
		FOR(i, a + 1, n) es2[i] = es[i];
		RFOR(i, a, -1) {
			es2[i] = 0;
			for (auto j : gr[i]) es2[i] += 1 + es2[j];
			es2[i] /= cnt[i];
		}
		res = min(res, es2[0]);
		gr[a].insert(b);
		cnt[a]++;
	}
	cout << fixed << setprecision(10) << res;
	return 0;
}

