        revG[s].insert(t);
    }
    auto calc = [&](vector<set<int>> graph) {
        vector<double> dp(N + 1, 0);
        vector<int> count(N + 1, 0);
        for (auto now : graph) for (auto temp : now) count[temp]++;
        vector<int> check(N + 1, 0);
        queue<int> explore;
        explore.push(N);
        while (!explore.empty()) {
            int now = explore.front();
            explore.pop();
            for (auto next : G[now]) {
                double power = 1 / (double)count[next];
                dp[next] += dp[now] * power;
                check[next]++;
                if (count[next] == check[next]) {
                    dp[next]++;
                    explore.push(next);
                }
            }
        }
        return dp;
    };
    auto base = calc(G);
