// curからN-1に到達するまでに必要な回数の期待値
double normal(vector<vector<int>> &src, int cur) {
    static double dp[600] = {};
    static bool used[600] = {};
    if (used[cur]) {
        return dp[cur];
    }
    int N = src.size();
    if (cur == N - 1) {
        return 0.0;
    }
    double sz = src[cur].size();
    double ret = 0;
    for (int i = 0; i < src[cur].size(); i++) {
        ret += 1 + normal(src, src[cur][i]);
    }
    used[cur] = true;
    return dp[cur] = ret / sz;
}
// 0からcurに到達するまでに必要な回数の期待値
double backward(vector<vector<int>> &dst, int cur) {
    static double dp[600] = {};
    static bool used[600] = {};
    if (used[cur]) {
        return dp[cur];
    }
    if (cur == 0) {
        return 0.0;
    }
    double sz = dst[cur].size();
    double ret = 0;
    for (int i = 0; i < dst[cur].size(); i++) {
        ret += 1 + backward(dst, dst[cur][i]);
    }
    used[cur] = true;
    return dp[cur] = ret / sz;
}

