            for (int k = 0; k < src[i].size(); k++) {
                if (k == j) {
                    continue;
                }
                ret3 += 1 + normal(src, src[i][k]);
            }
            ret3 /= src[i].size() - 1;
            ret2 = min(ret2, backward(dst, i) + ret3);
        }
        answer = min(answer, ret + p[i] * ret2);
    }
    std::cout << std::fixed <<  std::setprecision(12)  << answer << std::endl;
}

