    --s;
    --t;
    edges[s].push_back(t);
  }

  constexpr auto none = numeric_limits<double>::max();
  vector<double> costs_removed(N, none);
  vector<double> costs(N);
  for (int i = N - 2; i >= 0; --i) {
    auto num_edges = edges[i].size();
    for (auto next : edges[i]) {
      costs[i] += (1. + costs[next]) / num_edges;
    }
    if (num_edges == 1) {
      costs_removed[i] = costs_removed[edges[i][0]];
    } else {
      for (size_t j = 0; j < num_edges; ++j) {
        double cost = 0.;
        for (size_t k = 0; k < num_edges; ++k) {
          if (j != k) {
            cost += (1. + costs[edges[i][k]]) / (num_edges - 1.);
          }
        }
        costs_removed[i] = min(costs_removed[i], cost);
        if (costs_removed[edges[i][j]] != none) {
          cost = 0.;
          for (size_t k = 0; k < num_edges; ++k) {
            if (j != k) {
              cost += (1. + costs[edges[i][k]]) / num_edges;
            } else {
              cost += (1. + costs_removed[edges[i][k]]) / num_edges;
            }
          }
          costs_removed[i] = min(costs_removed[i], cost);
        }
      }
    }
  }

  auto result = costs_removed[0];
  if (result == none) {
    result = costs[0];
  }
  cout << setprecision(15) << result << endl;
}

