void solve(std::istream &in, std::ostream &out) {
  out << fixed << setprecision(9);
  int n, m;
  in >> n >> m;
  vector<vector<int>> g(n + 1);
  for (int i = 0, u, v; i < m; ++i) {
    in >> u >> v;
    g[u].push_back(v);
  }
  vector<double> dp(n + 1, numeric_limits<double>::infinity());
  dp[n] = 0;
  for (int u = n - 1; u >= 1; --u) {
    dp[u] = 0;
    for (int v : g[u]) {
      dp[u] += dp[v] + 1;
    }
    dp[u] /= g[u].size();
  }
  double res = dp[1];
  for (int i = 1; i < n; ++i) {
    int num = g[i].size();
    if (num < 2) continue;
    vector<double> d = dp;
    double mx = 0, sum = 0;
    for (int u : g[i]) {
      sum += d[u];
      mx = max(d[u], mx);
    }
    d[i] = (sum - mx) / (num - 1) + 1;
    for (int j = i - 1; j >= 1; --j) {
      sum = 0;
      for (int u : g[j]) {
        sum += d[u] + 1;
      }
      d[j] = sum / g[j].size();
    }
    res = min(res, d[1]);
  }
  out << res << '\n';
}

