int main() {
    ll N, M;
    cin >> N >> M;

    vector<vector<double>> edge(N);
    for (ll i = 0; i < M; i++) {
        ll s, t;
        cin >> s >> t;
        s--; t--;
        edge[s].push_back(t);
    }

    vector<double> dp(N);
    dp[N - 1] = 0;

    vector<pair<double, ll>> max_diff(N, { 0.0, -1 });
    for (ll i = N - 2; i >= 0; i--) {
        if (edge[i].size() == 1) {
            dp[i] = dp[edge[i].front()] + 1;
            continue;
        }

        for (ll j : edge[i]) {
            dp[i] += 1.0 / edge[i].size() * (1 + dp[j]);
            double diff = (1 + dp[j]);
            if (max_diff[i].first < diff) {
                max_diff[i] = { diff, j };
            }
        }
    }

    //各iで実際に寄与の大きいものを切るとどうなるか
    double ans = N - 1;
    for (ll i = 0; i < N - 1; i++) {
        if (edge[i].size() == 1) {
            continue;
        }
        vector<double> dp2(N);
        dp2[N - 1] = 0;
        for (ll j = N - 2; j >= 0; j--) {
            for (ll k : edge[j]) {
                if (j == i && k == max_diff[j].second) {
                    continue;
                }
                dp2[j] += 1.0 / (edge[j].size() - (j == i)) * (1 + dp2[k]);
            }
        }
        ans = min(ans, dp2[0]);
    }

    cout << setprecision(10) << ans << endl;
}

