namespace adaptor = boost::adaptors;
using index_t = std::size_t;

void Main()
{
	int N, M;
	std::cin >> N >> M;
	std::vector<std::pair<std::set<int>, std::vector<std::pair<int, int>>>> edge(N);
	for (auto i : boost::irange(0, M))
	{
		int s, t;
		std::cin >> s >> t;
		--s; --t;
		edge[s].first.emplace(i);
		edge[s].second.emplace_back(i, t);
	}
	double min = std::numeric_limits<double>::max();
	for (auto s : boost::irange(-1, M))
	{
		bool flag = false;
		boost::multi_array<double, 2> dp(boost::extents[N][N]);
		dp[0][0] = 1;
		for (auto i : boost::irange(0, N - 1))
		{
			auto size = edge[i].first.size() - edge[i].first.count(s);
			if (size == 0)
			{
				flag = true;
				break;
			}
			auto d = 1.0 / size;
			for (auto p : edge[i].second)
			{
				if (p.first == s)
				{
					continue;
				}
				for (auto j : boost::irange(0, N - 1))
				{
					dp[p.second][j + 1] += d * dp[i][j];
				}
			}
		}
		if (!flag)
		{
			double E = 0;
			for (auto i : boost::irange(1, N))
			{
				E += i * dp[N - 1][i];
			}
			min = std::min(min, E);
		}
	}
	std::cout << min << std::endl;
}

int main()
{
	std::cin.tie(nullptr);
	std::ios_base::sync_with_stdio(false);
	std::cout << std::fixed << std::setprecision(15);
	Main();
}

