int main(int argc, char *argv[]) {
    int n, m;
    long double res = 0;
    cin >> n >> m;
    unordered_map<int, unordered_set<int>> prev, next;


    for (int i = 0; i < m; i++) {
        int s, t;
        cin >> s >> t;
        prev[t].insert(s);
        next[s].insert(t);
    }

    unordered_map<int, unordered_map<int, long double>> dist;
    vector<long double>prob(n + 1, 0);

    prob[1] = 1;
    for (int i = 1; i < n; i++) {
        for (auto t : next[i]) {
            prob[t] += prob[i] / next[i].size();
        }
    }
    for (int i = n; i >= 1; i--) {
        dist[i][i] = 0;
        for (int j = i - 1; j >= 1; j--) {
            long double d = 0;
            int c = 0;
            for (auto t : next[j]) {
                if (dist[t].find(i) == dist[t].end())
                    continue;
                d += dist[t][i];
                c++;
            }
            if (c > 0)
                dist[j][i] = d / c + 1;
        }
    }

    res = dist[1][n];
    // cout << res << endl;
    for (auto pa : next) {
        int s = pa.first;
        for (auto t : pa.second) {
            if (next[s].size() == 1 || dist[1].find(s) == dist[1].end() || dist[t].find(n) == dist[t].end()) continue;
            long double p = prob[s] / next[s].size();
            long double d = dist[1][s] + 1 + dist[t][n];
            // cout << p << " " << d << " ";
            // cout << (dist[1][n] - d * p) / (1 - p) << endl;
            res = min(res, (dist[1][n] - d * p) / (1 - p));
        }
    }
    cout << setprecision(12) << res << endl;
}

