int can() {
    fore(u,1,N) ok[u] = 0;

    for(int u = N-1; u >= 1; u--) {
        if(isconnect(u,N)) 
            ok[u] = 1;
        fore(v,u+1,N) {
            if(isconnect(u,v)) {
                ok[u] |= ok[v];
            }
        }
    }

    return ok[1];
}

double f(int u) {
    if(u == N) return 0;

    if(B[u]) return dp[u];
    B[u] = 1;
    dp[u] = 0;

    int k = 0;
    fore(v,u+1,N) {
        if(isconnect(u,v)) {
            dp[u] += 1+f(v);
            k++;
        } 
    }

    dp[u] /= k;
    return dp[u];
}

