void solve() {
  int N, M;
  cin >> N >> M;
  vector<int> s(M);
  vector<int> t(M);
  rep(i, M) cin >> s[i] >> t[i];

  unordered_map<int, vector<int>> con;
  rep(i, M) con[s[i] - 1].push_back(t[i] - 1);

  function<double(vector<double>&, int, pair<int, int>*)> solve;
  solve = [&](vector<double>& dp, int i, pair<int, int>* exclude) {
    if (dp[i] >= 0) return dp[i];
    if (i == N - 1) return dp[i] = 0.0;
    double sum = 0.0;
    int n = 0;
    for (auto j : con[i]) {
      if (exclude != nullptr && *exclude == make_pair(i, j)) continue;
      sum += 1.0 + solve(dp, j, exclude);
      n++;
    }
    return dp[i] = sum / n;
  };

  vector<double> base_dp(N, -1);

  double ans = solve(base_dp, 0, nullptr);
  rep(i, N - 1) {
    if (con[i].size() < 2) continue;
    int x = -1;
    double p = 0.0;
    for (auto j : con[i]) {
      double q = solve(base_dp, j, nullptr);
      if (p < q) {
        p = q;
        x = j;
      }
    }
    vector<double> dp(N, -1);
    auto ex = make_pair(i, x);
    ans = min(ans, solve(dp, 0, &ex));
  }
  cout << ans << endl;
}

