void startupcpp(){
  cin.tie(0);
  ios::sync_with_stdio(false);
  cout<<fixed<<setprecision(15);
}

int N;
vector<vector<int>> g;
vector<double> dis;
double dfs(int now){
  if(dis[now])return dis[now];
  double res=0,f=0;
  for(int next:g[now]){
    if(next==-1){
      f=1;
      continue;
    }
    res+=dfs(next);
  }
  res/=g[now].size()-f;
  return dis[now]=res+1;
}
int main(){
  startupcpp();
  int i,j,M,f=-1;
  double ans;
  cin>>N>>M;
  g.resize(N);
  dis.resize(N,0);
  dis[N-1]=1;
  while(M--){
    cin>>i>>j;
    g[--i].eb(--j);
  }
  ans=dfs(0);
  rep(i,N)if(g[i].size()>1){
    sort(all(g[i]),[](int l,int r){return dis[l]>dis[r];});
    swap(g[i][0],f);
    rep(j,i+1)dis[j]=0;
    chmin(ans,dfs(0));
    swap(g[i][0],f);
  }
  print(ans-1);
}

