int main()
{
    scanf("%d%d",&n,&m);
    int s,t;
    for(int i=0;i<m;++i)
    {
        scanf("%d%d",&s,&t);
        rad[s].push_back(t);
    }

    gl(1);
    bf[1] = 1;

    for(int i=1;i<n;++i)
    {
        long double tv = bf[i]/rad[i].size();
        for(int j=0;j<rad[i].size();++j)
            bf[rad[i][j]]+=tv;
    }

    long double ans = 0;
    for(int i=0;i<rad[1].size();++i){
        ans += (1+rl[rad[1][i]]);
    }
    ans/=rad[1].size();


    long double df = 0;
    for(int i=1;i<=n;++i){
        if(rad[i].size()==1) continue;
        long double tsm = rl[i]*rad[i].size();
        for(int j=0;j<rad[i].size();++j){
            long double sdf = ((tsm-rl[rad[i][j]]-1)/(rad[i].size()-1)-tsm/rad[i].size())*bf[i];
            if(sdf<df) df = sdf;
        }
    }
    cout << setprecision(25) <<std::fixed<<ans+df<< endl;
