long double gl(int now)
{
    //bf[now]+=g;
    if(rl[now]) return rl[now];
    long double trl = 0;
    for(int i=0;i<rad[now].size();++i)
    {
        trl+=gl(rad[now][i])+1;
    }
//    if(rad[now].size()==0) {
//        if(now==n) return rl[now] = 0;
//        return rl[now] = 1000;
//    }
    if(rad[now].size()==0) return 0;
    return rl[now] = trl/rad[now].size();
}

void ggl(int now,long double g)
{
    bf[now]+=g;
    if(--tcnt[now]>0) return;
    for(int i=0;i<rad[now].size();++i)
        ggl(rad[now][i],bf[now]/rad[now].size());
}


