inline double bfs(int ban){
	for(int i=1; i<=n; ++i)sum[i]=cnt[i]=0,gu[i]=dgr[i];
	if(ban)gu[g[ban].v]--;
	queue <int> q; q.push(n); sum[n]=0; cnt[n]=1;
	while(!q.empty()){
