		for(int i=head[u]; i; i=g[i].nxt){
			int v=g[i].v; if(i==ban)continue;
			sum[v]+=ans[u]+1; cnt[v]++;
			gu[v]--; if(gu[v]==0)q.push(v);
		}
	}
	return cnt[1]?ans[1]:inf;
}
