int dx[4] = {0, 1, 0, 1};

int n, m;
vi adj[600];
double dp[600];

double cal(int block) {
	per(i,0,n) {
		if(i == n-1) {
			dp[i] = 0;
			continue;
		}
		double maxi = -1;
		double sum = 0;
		rep(j,0,sz(adj[i])) {
			sum += dp[adj[i][j]];
			if(maxi < dp[adj[i][j]]) {
				maxi = dp[adj[i][j]];
			}
		}

		int cnt = sz(adj[i]);
		if(block == i && sz(adj[i]) > 1) {
			sum -= maxi;
			cnt--;
		}

		dp[i] = (sum/cnt)+1;
	}
	return dp[0];
}

