#define FOR_LT(i, beg, end) for (int i = beg; i < end; i++)
#define FOR_LE(i, beg, end) for (int i = beg; i <= end; i++)
#define FOR_DW(i, beg, end) for (int i = beg; end <= i; i--)

using namespace std;

double calc(int n, vector<vector<int>>& edges, vector<double>& dp)
{
	dp[n] = 0.0;

	FOR_DW(i, n - 1, 1) {
		int s = edges[i].size();
		if (s == 0) return numeric_limits<double>::max();

		for (int t : edges[i]) {
			dp[i] += (dp[t] + 1.0) / s;
		}
	}

	return dp[1];
}

int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);

	int n, m; cin >> n >> m;

	vector<vector<int>> edges(n + 1);
	FOR_LT(i, 0, m) {
		int s, t; cin >> s >> t;
		edges[s].push_back(t);
	}

	vector<double> dp(n + 1);
	double ans = calc(n, edges, dp);


	FOR_LE(i, 1, n - 1) {
		vector<double> cdp(n + 1);

		double val = 0.0;
		int idx = -1;
		vector<vector<int>> ces = edges;
		FOR_LT(j, 0, edges[i].size()) {
			if (val <= dp[edges[i][j]]) {
				val = dp[edges[i][j]];
				idx = j;
			}

		}

		ces[i].erase(ces[i].begin() + idx);

		double curans = calc(n, ces, cdp);
		ans = min(ans, curans);
	}

	cout << setprecision(20) << ans << endl;


	return 0;
}

