Int dfs(Int pos){
  static Int used[601], mem[601];
  if(pos == N-1) return 1;
  if(used[pos]++) return mem[pos];
  Int res = 0;
  for(Int to:G[pos]) res |= dfs(to);
  return mem[pos] = res;
}

Double mem[600][2];
int used[600][2];
Double dfs(Int pos, Int f){
  if(pos == N-1) return 0;
  if(used[pos][f]++) return mem[pos][f];
  if(G[pos].size() == 0) return INF;
  Double a = 0, b = INF;
  Int k = G[pos].size();
  if(k == 0) return INF;
  {
    for(Int to:G[pos]){
      Double score = dfs(to, f);
      a += score;
    }
  }

  if(k > 1 && f){
    b = 0;
    Double mx = -INF;
    vector<Double> scores;
    for(Int to:G[pos]){
      Double score = dfs(to, 0);
      b += score;
      Max(mx, score);
    }
    b -= mx;
  }
  //pr(pos, f, 1 + a/k, 1 + b/(k-1));
  Double res = 1 + min(a/k, b/(k - 1));
  return mem[pos][f] = res;
}

