namespace Problem {
using namespace std;

class Solver2 {
 public:
  int n, m;
  vector<vector<int>> g;
  vector<vector<double>> dp, prob;
  Solver2(LL n, LL m) : n(n), m(m), g(n), dp(n, vector<double>(n)), prob(n, vector<double>(n)){};

  void solve() {
    for (int i = 0; i < m; ++i) {
      int s, t;
      cin >> s >> t;
      g[--s].push_back(--t);
    }

    for (int s = 0; s < n; ++s) {
      prob[s][s] = 1.0;
      for (int i = 0; i < n; ++i) {
        int sz = g[i].size();
        for (int j = 0; j < sz; ++j) {
          prob[s][g[i][j]] += (prob[s][i]) / sz;
        }
      }
      for (int i = 0; i < n; ++i) {
        int sz = g[i].size();
        for (int j = 0; j < sz; ++j) {
          dp[s][g[i][j]] += (dp[s][i] + prob[s][i]) / sz;
        }
      }
    }

    double ans = dp[0][n - 1];
    for (int i = 0; i < n; ++i) {
      int s = g[i].size();
      if (s == 1) continue;
      for (int j = 0; j < s; ++j) {
        double tmp = dp[0][n - 1];
        for (int k = 0; k < s; ++k) {
          tmp -= (dp[0][i] / prob[0][i] + 1.0 + dp[g[i][k]][n - 1]) * (prob[0][i] / s);
          if (k != j) {
            tmp += (dp[0][i] / prob[0][i] + 1.0 + dp[g[i][k]][n - 1]) * (prob[0][i] / (s - 1));
          }
        }
        ans = min(ans, tmp);
      }
    }
    cout << ans << endl;
  }
};
}  // namespace Problem

