ll answer = 0;
ll n, m;
Graph graph[605];
ld dp[605][605], dp2[605];

void solve(){
    rep(i, m){
        ll a, b; in2(a, b); a--, b--;
        graph[a].pb({b, 1});
    }

    dp2[n - 1] = 0;
    revrep(i, n - 1){
        dp2[i] = 0;
        ll num = graph[i].size();
        rep(j, num){
            ll target = graph[i][j].to;
            dp2[i] += dp2[target] + 1;
        }
        dp2[i] /= num;
    }

    ld ans = dp2[0];
    rep(i1, n - 2){
        ll num = graph[i1].size();
        ll idx = 0; ld val = 0;
        rep(j, num){
            ll target = graph[i1][j].to;
            if (dp2[target] > val) idx = j, val = dp2[target];
        }
        graph[i1][idx].cost = 0;

        dp[i1][n - 1] = 0;
        revrep(i2, n - 1){
            dp[i1][i2] = 0;
            ll num = graph[i2].size();
            rep(j, num){
                if (graph[i2][j].cost == 0) continue;
                ll target = graph[i2][j].to;
                dp[i1][i2] += dp[i1][target] + 1;
            }
            if (i1 == i2) num--;
            if (num == 0) dp[i1][i2] = MOD;
            else dp[i1][i2] /= num;
        }

        chmin(ans, dp[i1][0]);
        graph[i1][idx].cost = 1;
    }

    prl_nd(ans, 12);
}

int main(void){
    in2(n, m);
    // assert(k <= 100000);
    solve();
    return 0;
}

