template<typename T>
void fin(T const& t){ std::cout << t << std::endl; exit(0); }

int const MAXN = 600;
double const INF = 1e30;

std::vector<int> G[MAXN];
double ex[MAXN];
int h;

double calc(int v) {
  if(ex[v] < INF) return ex[v];
  double res = 1;
  double num = 0, mx = 0, sum = 0;
  for(auto c: G[v]) {
    ++num;
    double e = calc(c);
    sum += e;
    mx = std::max(mx, e);
  }
  if(v == h) {
    sum -= mx;
    --num;
  }
  res += sum/num;
  return ex[v] = res;
}

int main() {
  std::cout << std::setprecision(10) << std::fixed;
  int N, M; std::cin >> N >> M;
  for(int i = 0; i < M; ++i) {
    int s, t; std::cin >> s >> t; --s; --t;
    G[s].push_back(t);
  }
  h = -1;
  std::fill_n(ex, N, INF);
  ex[N-1] = 0e0;
  double ans = calc(0);
  for(h = 0; h < N-1; ++h) if(G[h].size() > 1) {
    std::fill_n(ex, N, INF);
    ex[N-1] = 0e0;
    ans = std::min(ans, calc(0));
  }
  fin(ans);
  return 0;
}

