typedef long long ll;
const ll inf = 1e9;
const ll maxn = 610;
int a[maxn*maxn], b[maxn*maxn];
double f[maxn], ans;
vector <int> vec[maxn];
ll n, m;
double DP(double p) {
	for(int i = 1; i <= n; ++i) {
		f[i] = 0;
	}
	f[n] = 0;
	for(int i = n - 1; i >= 1; --i){
		ll len = vec[i].size();
		if(p == i && len == 1) {
			f[i] = inf;
			continue;
		}
		double t = 1.0 / (len - (p == i));
		double mx = 0;
		for(int j = 0; j < len; ++j) {
			int v = vec[i][j];
			mx = max(mx, (f[v]+1)*t);
			f[i] += (f[v] + 1) * t;
		}
		if(p == i)	f[i] -= mx;
	}
	return f[1];
}
