#define per(i,n) for(int i = (n)-1; i >= 0; --i)

int N, M;
vvl edges, dp;
vl cnts;
ld ans;

ld dfs(int v) {
    ld sum = 0, cnt = 0;
    rep(to,N) {
        if (edges[v][to] != 1) continue;
        sum += dfs(to);
        cnt += 1;
    }
    if (cnt == 0) return 0;
    sum = (sum + cnt) / cnt;
    return sum;
}

int main() {
    cin >> N >> M;
    edges.assign(N, vl(N, 0));
    dp.assign(N, vl(2, 0));
    cnts.assign(N, 0);
    rep(i,M) {
        int a, b; cin >> a >> b; a--; b--;
        cnts[a]++;
        edges[a][b] =  1;
        edges[b][a] = -1;
    }
    rep(i,N) rep(j,N) {
        if (edges[i][j] == 1)  dp[j][0] += dp[i][0] + 1;
    }
    per(i,N) rep(j,N) {
        if (edges[i][j] == -1) dp[j][1] += dp[i][1] + 1;
    }
    int mx = 0, from = -1, to = -1;
    rep(i,N-1) rng(j,i+1,N) {
        int sum = dp[i][0] + dp[j][1];
        if (sum > mx and cnts[i] >= 2) {
