#include <bits/stdc++.h>
using namespace std;
typedef long double LD;
LD Ef[605], Eb[605], Pf[605], Pb[605], E[605];
bool vis[605];
vector<int> g[605];
int n, m, a, b;
int main(){
    scanf("%d%d", &n, &m);
    for(int i=1;i<=m;i++){
        int a, b;
        scanf("%d%d", &a, &b);
        g[a].push_back(b);
    }   

    Pb[n] = 1;
    for(int i=n-1;i>=0;i--){
        for(int j=0;j<g[i].size();j++){
            int v = g[i][j];
            Ef[i] += (Ef[v]+1)/g[i].size();
            Pb[i] *= Pb[v]/g[i].size();
        }
    }

    for(int pos=n-1;pos>=1;pos--){
        memset(vis, 0, sizeof(vis));
        memset(E, 0, sizeof(E));
        vis[pos] = 1;
        E[pos] = 0;
        for(int i=pos-1;i>=0;i--){
            for(int j=0;j<g[i].size();j++){
                int v = g[i][j];
                if(!vis[v]) continue;
                E[i] += (E[i]+1)/g[i].size();
            }
        }
        Eb[pos] = E[1];
    }

    Pf[1] = 1;
    for(int i=1;i<=n;i++){
        for(int j=0;j<g[i].size();j++){
            int v = g[i][j];
            Pf[v] += Pf[i]/g[i].size();
        }
    }

    LD ans = Ef[1];
    for(int i=1;i<=n;i++){
        if(g[i].size() <= 1) continue;
        LD res = Ef[1];
        vector<LD> best;
        for(int j=0;j<g[i].size();j++){
            int v = g[i][j];
            LD Ex = (Ef[v]+1)*Pf[i]/g[i].size() + Eb[i]*Pb[i]/g[i].size();
            res -= Ex;
            Ex = (Ef[v]+1)*Pf[i]/(g[i].size()-1) + Eb[i]*Pb[i]/(g[i].size()-1);
            best.push_back(Ex);
        }
        sort(best.begin(), best.end());
        for(int i=0;i<best.size()-1;i++) res += best[i];
        ans = min(ans, res);
    }
    printf("%.10Lf\n", ans);
}

