const int mod = 1000000007;
struct mint {
  ll x; // typedef long long ll;
  mint(ll x=0):x(x%mod){}
  mint& operator+=(const mint a) {
    if ((x += a.x) >= mod) x -= mod;
    return *this;
  }
  mint& operator-=(const mint a) {
    if ((x += mod-a.x) >= mod) x -= mod;
    return *this;
  }
  mint& operator*=(const mint a) {
    (x *= a.x) %= mod;
    return *this;
  }
  mint operator+(const mint a) const {
    mint res(*this);
    return res+=a;
  }
  mint operator-(const mint a) const {
    mint res(*this);
    return res-=a;
  }
  mint operator*(const mint a) const {
    mint res(*this);
    return res*=a;
  }
  mint pow(ll t) const {
    if (!t) return 1;
    mint a = pow(t>>1);
    a *= a;
    if (t&1) a *= *this;
    return a;
  }

  // for prime mod
  mint inv() const {
    return pow(mod-2);
  }
  mint& operator/=(const mint a) {
    return (*this) *= a.inv();
  }
  mint operator/(const mint a) const {
    mint res(*this);
    return res/=a;
  }
};

const int MOD = 1000000007;
const int inf=1e9+7;
const ll longinf=1LL<<60 ;

void addM(ll &a, ll b) {
    a += b;
    if (a >= MOD) a -= MOD;
}

void mulM(ll &a, ll b) {
    a = ((a%MOD)*(b%MOD))%MOD ;
}

ll powM(ll a,ll b) {
    ll ret = 1;
    ll tmp = a;
    while(b>0) {
        if((b&1)==1) ret = (ret * tmp) % MOD;
        tmp = (tmp * tmp) % MOD;
        b = b >> 1;
    }
    return ret;
}

// mod. m での a の逆元 a^{-1} を計算する
ll modinv(ll a, ll m) {
    ll b = m, u = 1, v = 0;
    while (b) {
        ll t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= m;
    if (u < 0) u += m;
    return u;
}

int main(void) {
  cin.tie(0);
  ios::sync_with_stdio(false);  

  int N, M;
  cin >> N >> M;

  vector<int> g[600];
  REP(i, M){
    int s, t;
    cin >> s >> t;
    s--;t--;
    g[s].push_back(t);    
  }

  vector<double> dp1(N, 0);
  for(int i = N - 1; i >= 0; i--){
    if(g[i].size() == 0) continue;
    for(int v : g[i]){
      dp1[i] += dp1[v];
    }
    dp1[i] /= g[i].size();
    dp1[i] += 1;
  }

  vector<double> dp2(N, 0);
  dp2[0] = 1.0;
  for(int i = 0; i < N; i++){
    if(g[i].size() == 0) continue;
    double pr = dp2[i] / g[i].size();
    for(int v : g[i]){
      dp2[v] += pr;
    }
  }

  // 一つの道を塞いだ時の期待値を最小化するには、
  // ある部屋からの移動先における最大の期待値の部屋への道を塞げばよい
  // 期待値の変化量と部屋１からその部屋への移動確率の積だけ部屋１からの部屋Nへの移動距離期待値が変化する
  double ans = dp1[0];
  REP(i, N){
    if(g[i].size() <= 1) continue;    
    double tmp1 = 0, tmp2 = 0;
    for(int v : g[i]){
      tmp1 += dp1[v];
      chmax(tmp2, dp1[v]);
    }
    tmp1 = (tmp1 - tmp2) / (g[i].size() - 1) + 1;
    chmin(ans, dp1[0] - (dp1[i] - tmp1) * dp2[i]);    
  }
  cout << fixed << setprecision(10) << ans << endl;

  return 0;
}

