        --u, --v;
        graph[u].emplace_back(u, v);
    }

    std::vector<Real> effect(n);
    for (int r = 0; r < n; ++r) {
        std::vector<Real> dp(n, 0);
        for (int v = n - 2; v >= 0; --v) {
            for (auto e : graph[v]) {
                dp[v] += dp[e.dst];
            }
            dp[v] /= graph[v].size();
            if (v == r) dp[v] += 1;
        }
        effect[r] = dp[0];
    }

    std::vector<Real> dp(n, 0);
    for (int v = n - 2; v >= 0; --v) {
        int sz = graph[v].size();
        for (auto e : graph[v]) {
            dp[v] += dp[e.dst];
        }
        dp[v] /= sz;
        dp[v] += 1;
    }

    Real maxeffect = 0;
    for (int v = 0; v < n - 1; ++v) {
        int sz = graph[v].size();
        if (sz == 1) continue;

        for (int k = 0; k < graph[v].size(); ++k) {
            // k番目を塞いだ場合
            Real sum = 0;
            for (int i = 0; i < sz; ++i) {
                int u = graph[v][i].dst;
                sum += (i == k ? 0 : dp[u]);
            }
            Real diff = dp[v] - (sum / (sz - 1) + 1);
            maxeffect = std::max(maxeffect, diff * effect[v]);
        }
    }

