namespace mp = boost::multiprecision;
using Bint = mp::cpp_int;
using Real = mp::number<mp::cpp_dec_float<256>>;

int ri() {
	int n;
	scanf("%d", &n);
	return n;
}

int main() {
	int n = ri();
	int m = ri();
	int s[m], t[m];
	std::vector<int> hen[n];
	std::vector<int> rev[n];
	for (int i = 0; i < m; i++) {
		s[i] = ri() - 1;
		t[i] = ri() - 1;
		hen[s[i]].push_back(t[i]);
		rev[t[i]].push_back(s[i]);
	}
	std::vector<Bint> sum_0(n, 0);
	std::vector<Bint> num_0(n, 0);
	std::vector<Bint> sum_1(n, 0);
	std::vector<Bint> num_1(n, 0);
	num_0[0] = 1;
	num_1[n - 1] = 1;
	for (int i = 0; i < n; i++)
		for (auto j : hen[i]) num_0[j] += num_0[i], sum_0[j] += sum_0[i], sum_0[j] += num_0[i];
	for (int i = n - 1; i >= 0; i--)
		for (auto j : rev[i]) num_1[j] += num_1[i], sum_0[j] += sum_0[i], sum_0[j] += num_1[i];

	Real res = 1000000000000;
	for (int i = 0; i < m; i++) {
		Bint sum = sum_0[n - 1] - sum_0[s[i]] - sum_1[t[i]];
		Bint num = num_0[n - 1] - num_0[s[i]] - num_1[t[i]];
		res = std::min(res, (Real) sum / (Real) num);
	}
	std::cout << res << std::endl;
	return 0;
}

