const int MAXN = (int)1e3+7;
const double INF = (double)1e18+7;

int N,M;
int deg[MAXN];
vector<int> in[MAXN],out[MAXN];
double dp[MAXN][2],prob[MAXN];
queue<int> qu;

int main()
{
    scanf("%d %d",&N,&M);
    rep(i,1,M) {
        int u,v;
        scanf("%d %d",&u, &v);
        out[u].pb(v);
        in[v].pb(u);
        deg[u] ++;
    }
    rep(i,0,N) rep(j,0,N) dp[i][j]=INF;
    dp[N][0] = dp[N][1] = 0;
    rep(i,1,N) if (deg[i] == 0) qu.push(i);

    while (!qu.empty()) {
        int k = qu.front();qu.pop();
        for(int v:in[k]) if(--deg[v]==0) qu.push(v);
        int num = 0;
        double pro = 0.0;
        for(int v:out[k]) num ++,pro += dp[v][0];
        if (num == 0) {
            continue ;
        }else if (num == 1) {
            for (int v:out[k]) dp[k][0] = dp[v][0]+1,dp[k][1] = dp[k][0];
        }else {
            dp[k][0] = pro/num+1;
            for (int v:out[k]) dp[k][1] = min(dp[k][1],(pro-dp[v][0])/(num-1)+1);
        }
    }
    prob[1] = 1.0;
    double ans = INF;
    rep(i,1,N-1) {
        double probb = prob[i]/out[i].size();
        for(int v:out[i]) prob[v]+=probb;
        //cout << dp[1][1] << " " << prob[i] << " " << dp[i][0] << " " << dp[i][1] << endl;
        ans = min(ans,dp[1][0]-prob[i]*(dp[i][0]-dp[i][1]));
    }


    printf("%.15f\n",ans);
}

