int main() {
  int n, m; cin >> n >> m;
  vector<vector<int>> to(n);
  for(int i = 0; i < m; i++) {
    int s, t; cin >> s >> t;
    s--;
    t--;
    to[s].push_back(t);
  }
  vector<double> dp(n);
  // dp[n - 1] = 0;
  for(int v = n - 2; v >= 0; v--) {
    double now = 0;
    for(int u : to[v]) {
      now += dp[u];
    }
    now /= to[v].size();
    now += 1;
    dp[v] = now;
  }
  double ans = dp[0];

  for(int nv = 0; nv < n - 1; nv++) {
    if(to[nv].size() == 1) continue;
    int nu = to[nv][0];
    // 行き先の dp の値が最も大きい頂点をさがす
    for(int u : to[nv]) {
      if(dp[nu] < dp[u]) nu = u;
    }
    double now = [&]{
      vector<double> dp(n);
      // dp[n - 1] = 0;
      for(int v = n - 2; v >= 0; v--) {
        double now = 0;
        for(int u : to[v]) {
          if(v == nv and u == nu) continue;
          now += dp[u];
        }
        int deg = to[v].size();
        if(v == nv) deg--;
        now /= deg;
        now += 1;
        dp[v] = now;
      }
      return dp[0];
    }();
    ans = min(ans, now);
  }

  printf("%.10f\n", ans);
  return 0;
}

