int main() {
  cin >> n >> m;
  for (int j = 0; j < m; ++j) {
    int a, b;
    cin >> a >> b;
    --a;
    --b;
    G[a].push_back(b);
  }

  PS[0] = 1;
  for (int i = 0; i < n; ++i) {
    for (int j : G[i]) {
      PS[j] += PS[i] / G[i].size();
    }
  }

  for (int i = n - 2; i >= 0; --i) {
    double sum = 0;
    int cnt = 0;
    for (int j : G[i]) {
      sum += ET[j];
      ++cnt;
    }
    ET[i] = sum / cnt + 1;
  }

  for (int i = 0; i < n; ++i) {
    if (i != 0) FS[i] += PS[i];
    for (int j : G[i]) {
      FS[j] += FS[i] / G[i].size();
    }
  }

  double mn = ET[0];
  const int t = n - 1;
  for (int u = 0; u < n; ++u) {
    for (int v : G[u]) {
      double pe = PS[u] / G[u].size();
      double Est = FS[t] / PS[t];
      double Esu = FS[u] / PS[u];
      double Este = Esu + ET[v] + 1;
      double Gut = (ET[u] * G[u].size() - (ET[v] + 1)) / (G[u].size() - 1);
      double ans = Est + (-Este + Esu + Gut) * pe;
      mn = min(mn, ans);
    }
  }
  cout << fixed << setprecision(16) << mn << endl;
}

