vector<double> dp;

double solve_dp() {
    dp.assign(N, 1e9);
    dp[N - 1] = 0;

    for (int i = N - 2; i >= 0; i--) {
        double sum = 0;
        int count = 0;

        for (int j = i + 1; j < N; j++)
            if (adj[i][j]) {
                sum += dp[j] + 1;
                count++;
            }

        dp[i] = sum / count;
    }

    return dp[0];
}

