    for(removed = 0; removed < M; removed++) {
        if(can()) {
            fore(u,1,N) {
                B[u] = 0;
                dp[u] = 0;
            }
            mn = min(mn, f(1));
        }
    }

    cout << std::fixed << setprecision(8);
    cout << mn << endl;
    return 0;
}

