/*
      x: 1001 1010  1100 1011 1101  1111
x & ~ x: 0001 0010  0100 0001 0001  0001
    sum: 1010 1100 10000 1100 1100 10000

####### Attention #######
S | (1 << i) -> S union {i}
S & ~(1 << i) -> S - {i}

# inclusion-exclusion principle
|U[i = 1 to n] Ai| = sum[i = 1 to n] |Ai| - sum[i < j]|Ai ^ Aj| + ... + (-1)^(n - 1) |^[i = 1 to n]Ai|
*/

const ll MAX_N = 200005;
const size_t MAX_BIT = 160 * 160 + 10;
typedef bitset<MAX_BIT> bts;
typedef vector<bts> vbt;
typedef vector<vbt> vbt2;
typedef vector<vbt2> vbt3;
const bool multiple_queries = false;

void solve(){
    // generate_array(size, min, max);
    ll n, m; in2(n, m);
    Graph graph(n);
    rep(i, m){
        ll a, b; in2(a, b); a--, b--;
        graph[a].pb({b, 1});
    }

    vector<ld> dp(n, -1), memo; dp[n - 1] = 0;
    auto dfs = [&](auto dfs, ll src, pl path) -> ld{
        if (src > path.e1) return memo[src];
        else if (dp[src] > -EPS) return dp[src];
        ld ret = 0, deg = 0;
        for (auto& e: graph[src])
            if (mp(src, e.to) != path)
                ret += dfs(dfs, e.to, path) + 1, deg += 1;
        return dp[src] = ret / deg;
    };

    dfs(dfs, 0, {n, n}); ld ans = dp[0]; memo = dp;
    rep(s, n - 1){
        if (graph[s].size() == 1) continue;
        ll t = 0; ld v = 0;
        for (auto& e: graph[s])
            if (chmax(v, memo[e.to])) t = e.to;
        fill(all(dp), -1);
        chmin(ans, dfs(dfs, 0, {s, t}));
    }

    prl_nd(ans, 12);

    // ### DEBUG PART ###
    auto naive_solver = [&](){
    };
    #ifdef _LOCAL
        naive_solver();
    #endif
}

