using namespace std;

long long N, M;
vector<long long> tree[3600];

double memo[605];


double dfs(long long cur) {
	if(cur == N - 1) {
		return 1;
	}

	if(memo[cur] > 0) {
		return memo[cur] + 1;
	}

	double sumi = 0;
	long long num = tree[cur].size();

	for(auto next: tree[cur]) {
		sumi += dfs(next);
	}

	memo[cur] = sumi/num;

	return memo[cur] + 1;
}

long long ngfrom, ngto;

double memo2[605];

double dfs2(long long cur) {
	if(cur == N - 1) {
		return 1;
	}

	if(memo2[cur] > 0) {
		return memo2[cur] + 1;
	}

	double sumi = 0;
	long long num = tree[cur].size();

	for(auto next: tree[cur]) {
		if(cur == ngfrom && next == ngto) {
			num--;
			continue;
		}
		sumi += dfs2(next);
	}

	memo2[cur] = sumi/num;

	return memo2[cur] + 1;
}

int main(){
	cin >> N >> M;

	rep(i, M) {
		long long s, t;
		cin >> s >> t;
		s--;t--;
		tree[s].push_back(t);
	}

	dfs(0);
	double ans = memo[0];

	for(long long i = 0; i < N - 1; i++) {
		if(tree[i].size() == 1) continue;
		long long maxi = memo[tree[i][0]];
		long long maxito = tree[i][0];

		for(auto next: tree[i]) {
			if(memo[next] > maxi) {
				maxi = memo[next];
				maxito = next;
			}
		}

		ngfrom = i;
		ngto = maxito;
		dfs2(0);

		ans = min(ans, memo2[0]);


		rep(i, N + 2) {
			memo2[i] = 0;
		}
	}

	printf("%.10f\n", ans);

}

