int main() {
    int n, m; cin >> n >> m;
    vector<int> adj[n];
    while (m--) {
        int s, t; cin >> s >> t;
        adj[s-1].push_back(t-1);
    }
    for (int i = 0; i < n; i++) sort(adj[i].begin(), adj[i].end());
    double dp1[n];
    dp1[n-1] = 0;
    for (int k = n-2; k >= 0; k--) {
        double tmp = 0;
        for (int x : adj[k]) tmp += dp1[x];
        tmp /= adj[k].size();
        dp1[k] = tmp + 1;
    }
    double ans = dp1[0];
    for (int i = 0; i < n; i++) {
        if (adj[i].size() <= 1) continue;
        int j = adj[i][0];
        for (int k : adj[i]) if (dp1[k] > dp1[j]) j = k;
        double dp[n];
        dp[n-1] = 0;
        for (int k = n-2; k >= 0; k--) {
            double tmp = 0;
            for (int x : adj[k])
                if (k != i || x != j) tmp += dp[x];
            tmp /= adj[k].size() - (k == i);
            dp[k] = tmp + 1;
        }
        ans = min(dp[0], ans);
    }
    cout << setprecision(16) << ans << endl;
}

