void calc(const Graph &G, vector<double> &dp, int cnt) {
  rrep(i,cnt) {
    double sum = 0;
    for (auto &v : G[i]) {
      sum += dp[v] + 1;
    }
    dp[i] = sum / G[i].size();
  }
}

void solve() {
  int n, m; cin >> n >> m;
  Graph G(n);
  rep(i,m) {
    int s, t; cin >> s >> t; --s; --t;
    G[s].push_back(t);
  }

  vector<double> dp(n);
  dp.back() = 0;
  calc(G, dp, n-1);

  double ans = dp.front();
  rep(i,n-1) {
    auto ndp = dp;
    double tmp = 0;
    for (auto &v : G[i]) {
      tmp = max(tmp, dp[v] + 1);
    }
    ndp[i] = (dp[i] * G[i].size() - tmp) / (G[i].size() - 1);
    calc(G, ndp, i);
    ans = min(ans, ndp.front());
  }

  cout << ans << endl;
}


