int N, M;
vector<vector<int>> G;

vector<double> calc(int fr, int to){
    vector<double> dp(N, 1e16);
    dp[N-1] = 0.0;
    for(int i=N-2; i>=0; i--){
        int M = G[i].size();
        if(fr == i) M--;
        if(M==0) continue;
        dp[i] = 0.0;
        for(int j : G[i]){
            if(i!=fr || j!=to) dp[i] += 1+dp[j];
        }
        dp[i] /= M;
    }
    return dp;
}

int main(){
    cin >> N >> M;
    G.resize(N);
    REP(i, M){
        int s, t;
        cin >> s >> t;
        s--; t--;
        G[s].push_back(t);
    }
    vector<double> dp = calc(-1, -1);
    vector<int> cands(N);
    for(int i=0; i<N-1; i++){
        double mx = -1.0;
        int j = -1;
        for(int to : G[i]){
            if(dp[to] > mx){
                j = to;
                mx = dp[to];
            }
        }
        cands[i] = j;
    }
    double ans = 1e16;
    for(int i=0; i<N-1; i++){
        ans = min(ans, calc(i, cands[i])[0]);
    }
    ans = min(ans, calc(-1, -1)[0]);
    cout << fixed << setprecision(12) << ans << endl;
    return 0;
}

