// https://atcoder.jp/contests/abc144/submissions/15138762
void solve() {
  int n, m;
  cin >> n >> m;
  vector<vector<int> > to(n), ot(n);
  rep(i, m) {
    int a, b;
    cin >> a >> b;
    a--; b--;
    to[a].eb(b);
    ot[b].eb(a);
  }

  vector<double> en(n), pn(n); // v to n の長さの期待値
  pn[n - 1] = 1;
  for (int v = n - 2; v >= 0; --v) {
    int deg = sz(to[v]);
    for (int u : to[v]) {
      en[v] += en[u];
      pn[v] += pn[u];
    }
    en[v] /= deg; en[v] += 1;
    pn[v] /= deg;
  }
  // cerr << pn << endl << en << endl;

  vector<double> e1(n), p1(n); // 1 to v の長さの期待値
  // 1 をゴールとする
  p1[0] = 1;
  for (int v = 1; v < n; ++v) {
    for (int u : ot[v]) {
      int deg = sz(to[u]); // v to u, 元々は u to v
      e1[v] += (e1[u] + 1) / deg;
      p1[v] += p1[u] / deg;
    }
  }
  // cerr << p1 << endl << e1 << endl;

  double ans = en[0];
  for (int v = n - 2; v >= 0; --v) { // v始点の辺
    // まず, v始点の辺すべて 1/deg to 1/(deg-1) にする
    int deg = sz(to[v]);
    if (deg == 1) continue;
    /*
    3 3
    1 2
    1 3
    2 3
    のケースでは deg = 1 の2からの辺を切れるが, もっと前を切るべき
    */

    double tmp = 0;
    vector<double> x;
    for (int u : to[v]) {
      // 期待値_{1 to v} = ∑_{1 to v のパス}確率*長さ
      // ∑_{1 to v}∑_{u to n}確率*長さ, 確率 = p_{1 to v} * 1/deg * p_{u to n}, 長さ = l_{1 to v} + 1 + l_{u to n}
      // 1/deg ∑_{1 to v}∑_{u to n}p1 * p2 * (l1 + 1 + l2)
      // 中身 = (p1l1)p2 + p1p2 + p1(p2l2) = E1p2 + p1p2 + p1E2
      x.eb(e1[v] * pn[u] + p1[v] * pn[u] + p1[v] * en[u]);
    }
    double sum = accumulate(all(x), 0.0);
    tmp = en[0] - sum * 1.0 / deg + sum * 1.0 / (deg - 1);

    // 1つだけ 1/(deg-1) to 0
    rep(i, sz(x)) {
      chmin(ans, tmp - x[i] / (deg - 1));
    }
  }
  cout << ans << endl;
}
