typedef double db;
int n, m; db dp[610];
vector<int> G[610];
db ddp(int b) {
	for(int i = n - 1; i >= 1; i --) {
		dp[i] = 0; int s = 0; db sum = 0, mx = 0;
		for(int j = 0; j < (int) G[i].size(); j ++) {
			int v = G[i][j];
			sum += dp[v]; mx = max(mx, dp[v]); s ++;
		}
		if(b != i) { dp[i] = sum / s + 1; }
		else {
			if(s == 1) return 1e18;
			dp[i] = (sum - mx) / (s - 1) + 1;
		}
	}
	return dp[1];
}
int main() {
	scanf("%d%d", &n, &m);
	for(int i = 1; i <= m; i ++) {
