inline void calc (int id) {
	static double dp[N];
	dp[n] = 0;
	per (i, n - 1, 1) {
		dp[i] = 0;
		double mx = -1;
		rep (j, 1, mp[i][0]) {
			int v = mp[i][j];
			if (dp[v] < 0) { dp[i] = -1; break; }
			dp[i] += dp[v];
			mx = max (mx, dp[v]);
		}
		if (dp[i] < 0) continue;
		if (mp[i][0] - (i == id) == 0) dp[i] = -1;
		else {
			if (i == id) dp[i] -= mx;
			dp[i] = (dp[i] / (mp[i][0] * 1.0 - (i == id))) + 1;
		}
	}
	if (dp[1] > 0) ans = min (ans, dp[1]);
}

