namespace {
    ll mul(ll a, ll b) {
        ll val = a * b - (ll) ((ld) a * b / mod) * mod;
        if (val < 0) val += mod;
        if (val >= mod) val -= mod;
        return val;
    }

    ll poww(ll a, ll b) {
        ll val = 1;
        a %= mod;
        while (b > 0) {
            if (b % 2) val = mul(a, val);
            a = mul(a, a);
            b >>= 1;
        }
        return val % mod;
    }

    ll inv(ll a) {
        return poww(a, mod - 2);
    }
}
ll const maxn = 3e5 + 5;

unordered_set<int> g[maxn];
ld sum[maxn];
ll cnt[maxn];
ld rzn[maxn];

signed main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);
    ll n, m;
    cin >> n >> m;
    vector<ld> dp(maxn);
    vector<pair<int, int>> edges;
    for (ll i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        edges.emplace_back(u, v);
        g[u].insert(v);
    }
    dp[n] = 0;
    for (ll i = n - 1; i >= 1; i--) {
        cnt[i] = g[i].size();
        ld sm = 0;
        for (ll v : g[i]) {
            sm += dp[v];
        }
        sum[i] = sm;
        dp[i] = 1 + (1.0 / cnt[i]) * (sm);
    }
    ld ans = dp[1];
    for (ll u = n - 1; u >= 1; u--) {
        auto dpp = dp;
        dpp[u] -= 1;
        for (ll i = u - 1; i >= 1; i--) {
            ld sm = 0;
            for (ll v : g[i]) {
                sm += dpp[v];
            }
            dpp[i] = 1 + (1.0 / cnt[i]) * sm;
        }
        rzn[u] = dp[1] - dpp[1];
    }
    for (auto p : edges) {
        int u = p.X, v = p.Y;
        if (dp[u] == 1 + dp[v]) continue;
        ld new_sum = sum[u] - dp[v];
        ld new_dp = 1 + (1.0 / (cnt[u] - 1)) * new_sum;
        ld razn = dp[u] - new_dp;
        ans = min(ans, dp[1] - rzn[u] * razn);
    }
    cout << fixed << setprecision(10) << ans << endl;
    return 0;
}
