void solve(int N, int M, vi s, vi t) {
  vvi to(N);
  rep(i, M)to[s[i]].push_back(t[i]);
  vd p(N), e(N);
  p[0] = 1;
  rep(i, N - 1) {
    ld l = sz(to[i]);
    each(x, to[i]) p[x] += p[i] / l;
  }
  e[N - 1] = 0;
  rrep(i, N - 1) {
    ld sum = 0;
    each(x, to[i]) sum += e[x];
    e[i] = sum / sz(to[i]) + 1;
  };
  ld d = 0;
  rep(i, M) {
    int l = sz(to[s[i]]) - 1;
    if(l) amax(d, (e[t[i]] - e[s[i]] + 1) / l * p[s[i]]);
  }
  COUT(e[0] - d);
}


