    if(exp[x] >= 0)return exp[x];
    int es = edg[x].size();
    double res = 0;
    double mx = 0;
    for(int i=0;i<es;i++){
        int z = edg[x][i];
        res += f(z, y) + 1;
        mx = max(mx, f(z, y)+1);
    }
    if(x == y && es > 1){
        res -= mx;
        es--;
    }
    return exp[x] = res / es;
}
