        edg[--s].push_back(--t);
    }
    double ans = f(0, -1);
    for(int i=0;i<n;i++){
        exp.assign(n, -1);
        ans = min(ans, f(0, i));
    }


    cout << fixed << setprecision(16) << ans << endl;

}

