using namespace std;

// そのノードを通る確率
map<long, double> existance;

// そのノードを起点としたときのゴールまでの期待値
map<long, double> to_goal;

// 接続
map<long, set<long>> joint;

void solve() {
  long N, M;
  cin >> N >> M;
  rep (i, M) {
    long s, t;
    cin >> s >> t;
    joint[s].insert(t);
  }

  // そのノードを通る確率
  existance[1] = 1;
  for (long i = 1; i < N; i++) {
    double tmp = existance[i];
    tmp /= joint[i].size();
    for (long it: joint[i]) existance[it] += tmp;
  }

  // そのノードを起点としたときのゴールまでの期待値
  to_goal[N] = 0;
  for (long i = N - 1; i >= 1; i--) {
    double sum = 0;
    for (long it: joint[i]) sum += to_goal[it] + 1;
    sum /= joint[i].size();
    to_goal[i] = sum;
  }

  double ans_without_aoki = to_goal[1];
  double aoki = 0;
  for (long node = 1; node < N; node++) {
    // 枝の本数
    long edge_count = joint[node].size();

    // 塞げないケースで早期return
    if (joint[node].size() < 2) continue;

    double tmp_max = 0;
    for (auto it: joint[node]) tmp_max = max(tmp_max, to_goal[it]);
    tmp_max++;

    double current_to_goal = to_goal[node];
    double enhanced_to_goal = (current_to_goal * edge_count - tmp_max) / (edge_count - 1);
    double diff = current_to_goal - enhanced_to_goal;
    double tmp_result = diff * existance[node];
    aoki = max(aoki, tmp_result);

/*
    cout << "----------" << endl;
    cout << "node: " << node << endl;
    cout << "tmp_max: " << tmp_max << endl;
    cout << "edge_count: " << edge_count << endl;
    cout << "current_to_goal: " << current_to_goal << endl;
    cout << "enhanced_to_goal: " << enhanced_to_goal << endl;
    cout << "diff: " << diff << endl;
    cout << "tmp_result: " << tmp_result << endl;
*/
  }

//  cout << "aoki: " << aoki << endl;

  double ans = ans_without_aoki - aoki;
  cout << ans << endl;
}

int main(void) {
  cin.tie(0);
  ios::sync_with_stdio(false);
  cout.precision(12);
  solve();
  return 0;
}

