  for (RI i = 1; i <= m; ++i)
    addedge(G[i].x, G[i].y), ++d[G[i].x];
  f[1] = 0, g[1] = 1;
  for (RI i = 1; i < n; ++i) {
    double t = 1.0 / d[i];
    for (RI j = head[i]; j; j = e[j].next) {
      f[e[j].to] += f[i] * t + g[i] * t;
      g[e[j].to] += g[i] * t;
    }
  }
  double ans = f[n];
  memset(head, 0, sizeof(head)), tot = 0;
  memset(d, 0, sizeof(d));
  for (RI i = 1; i <= m; ++i)
    addedge(G[i].y, G[i].x), ++d[G[i].y];
  ff[n] = 0; gg[n] = 1;
  for (RI i = n; i > 1; --i) {
    double t = 1.0 / d[i];
    for (RI j = head[i]; j; j = e[j].next) {
      ff[e[j].to] += ff[i] * t + gg[i] * t;
      gg[e[j].to] += gg[i] * t;
    }
  }
  for (RI i = 1; i <= m; ++i)
