void dfs(int u){
	if(u==n){
		f[u]=0;
		return;
	}
	int tmp=0;double tp=0.00;double mx=0.00;
	for(int i=head[u];i!=-1;i=e[i].nxt){
		int v=e[i].to;
		tmp++;
		dfs(v);
		double x=f[v];
		if(x>mx){
			mx=x;
			valm[u]=i;
		}
		tp+=x+1.00;
	}
	f[u]=tp/tmp;
	if(tmp==1) valm[u]=-1;
	return;
}
void dfs1(int u,int lim){
	if(u==n){
		f[u]=0;
		return;
	}
	int tmp=0;double tp=0.00;
	for(int i=head[u];i!=-1;i=e[i].nxt){
		if(u==lim)  if(i==valm[u]) continue;
		int v=e[i].to;
		tmp++;
		dfs1(v,lim);
		tp+=f[v]+1.00;
	}
	f[u]=tp/tmp;
	return;
}
