  P[0] = 1;
  for(int i = 0; i < N; ++i){
    for(auto v : G[i]){
      P[v] += P[i]/G[i].size();
    }
  }
  vector<double> E(N,-1);
  dfs(G,0,E);
  double ans = E[0];
  for(int i = 0; i < N; ++i){
    int d = G[i].size();
    if(d == 1) continue;
    for(auto v : G[i]){
      double t = E[0] - (E[i] - (E[i]*d-(E[v]+1))/(d-1))*P[i];
      //cerr << i << " " << v << " " << t << endl;
      ans = min(ans,t);
    }
  }
  printf("%.12f\n",ans);
}

