class Task{
public:
    void solve(istream& in, ostream& out){
        int N, M;
        in>>N>>M;
        vc<double> P(N);
        vvc<int> G(N);
        REP(i, M){
            int s, t;
            in>>s>>t;
            s--, t--;
            G[s].pb(t);
        }
        P[0] = 1;
        REP(i, N){
            for(auto& v : G[i]) P[v] += P[i] / LEN(G[i]);
        }
        vc<double> dp(N, 0);
        for(int i=N-2;0<=i;--i){
            for(auto& v : G[i]) dp[i] += dp[v];
            dp[i] = dp[i] / LEN(G[i]) + 1;
        }
        double ans = dp[0];
        for(int i=N-2;0<=i;--i){
            if(LEN(G[i])==1) continue;
            int sz = LEN(G[i]) - 1;
            double now = 0;
            for(auto& v : G[i]) now += dp[v];
            now = now / sz + 1;
            for(auto& v : G[i]){
                now -= dp[v] / sz;
                chmin(ans, dp[0]+P[i]*(now-dp[i]));
                now += dp[v] / sz;
            }
        }
        out<<fixed<<setprecision(12)<<ans<<'\n';
    }
};

