	REP(i, 0, n - 1) {
		if (deg[i] == 1) continue;

		int mxpos; double mx = -1;
		REP(j, i + 1, n) {
			if (adj[i][j] && mx < E[j][0]) {
				mxpos = j;
				mx = E[j][0];
			}
		}

		--deg[i]; adj[i][mxpos] = 0;
		solve(1);
		++deg[i]; adj[i][mxpos] = 1;

		ans = min(ans, E[0][1]);
	}

	cout << fixed << setprecision(10) << ans;
}

