    vector<double> exp(n, 0);
    for(int ng = -1; ng < n - 1; ++ng){
        if(ng != -1 && net.at(ng).size() == 1){
            continue;
        }
        vector<double> exp2(n, 0);
        for(int x = n - 2; x >= 0; x--){
            if(ng != -1 && ng < x){
                exp2.at(x) = exp.at(x);
            }

            double tmp = 0;
            double count = 0;
            double maxval = 0;
            for(int nxt : net.at(x)){
                tmp += exp2.at(nxt) + 1.0;
