                count++;
            }
            if(ng != x){
                exp2.at(x) = tmp / count;
                exp.at(x) = exp2.at(x);
            }else{
                exp2.at(x) = (tmp - maxval) / (count - 1);
            }
        }
        ans = min(ans, exp2.at(0));
