double f(const vector<vector<int>>& g, int k) {
    int n = g.size();

    vector<double> dp(n);

    for (int i = n - 1; i >= 0; i--) {

        vector<double> a;
        a.reserve(g[i].size());

        for (int to : g[i]) {
            a.push_back(dp[to]);
        }

        sort(a.begin(), a.end());

        if (i == k && a.size() > 1) {
            a.pop_back();
        }

        for (double x : a) {
            dp[i] += (x + 1.0) / a.size();
        }
    }

    return dp[0];
}

