                dp[n][x] += solve(e[n][i], x) + 1;
                M = max(M, solve(e[n][i], x) + 1);
            }
            dp[n][x] -= M;
            dp[n][x] /= e[n].size()-1;
        }
    }
    return dp[n][x];
}

signed main(){
    cin >> N >> M;
    rep(i, M){
        cin >> s[i] >> t[i];
        s[i]--; t[i]--;
        e[s[i]].pb(t[i]);
    }

    double ans = LLONG_MAX;
    rep(i, N){
        ans = min(ans, solve(0, i));
    }
    cout << fixed << setprecision(16) << ans << endl;
}

#include <iostream>
