using namespace std;
#define N 605

double dp[N][2];
vector<int> adj[N];
int main(void) {
	//solve 
	int n, m; scanf("%d %d", &n, &m);
	for (int i = 0; i < m; ++i) {
		int s, t; scanf("%d %d", &s, &t);
		adj[s].push_back(t);
	}
	dp[n][0] = 0, dp[n][1] = 1e18;
	for (int i = n - 1; i ; --i) {
		dp[i][1] = 1e18;
		double sum = 0, minZero = 1e18, minDiff = 1e18;
		int sz = adj[i].size();
		for (int j = 0; j < sz; ++j) {
			int id = adj[i][j];
			double zero = dp[id][0], one = dp[id][1];
			minDiff = min(minDiff, one - zero);
			minZero = min(minZero, -zero);
			sum += zero;
		}
		dp[i][0] = 1 + sum / sz;
		if (sz == 1) {
			dp[i][1] = 1 + (sum + minDiff) / sz;
		}
		else {
			dp[i][1] = 1 + (sum + minDiff) / sz;
			dp[i][1] = 1 + (sum + minZero) / (sz - 1);
		}
	}
	printf("%0.9lf\n",min(dp[1][0],dp[1][1]));
	return 0;
}

