        edge[s-1].push_back(t-1);
    }

    double opt = N+M;
    for (int i=0; i<N-1; ++i) { // 削除する部屋でループ
        std::vector<double> v(N);
        v[N-1] = 0.0;
        for (int j=N-2; j>=0; --j) { // DP計算
            double sum = 0.0;
            double maxv = 0.0;
            for (int t : edge[j]) { // 部屋内通路ループ
                sum += v[t];
                maxv = std::max(maxv, v[t]);
            }
            int nLink = edge[j].size();
            if (nLink > 1 && i == j) {
                sum -= maxv;
                nLink -= 1;
            }
            v[j] = (sum + nLink) / nLink;
        }
        opt = std::min(opt, v[0]);
    }

    std::cout << opt << std::endl;
    return 0;
}

