double dfs(int s, VVI &es, vector<bool> &seen, vector<bool> &finished, vector<double> &memo, const PII &ban) {
    if (s == es.size() - 1) return 0;
    if (es[s].size() == 0) return 0;
    if (memo[s] > -1) return memo[s];
    //seen[s] = true;
    double sum = 0;
    bool isDel = false;

    for (const int &dst: es[s]) {
        if (s == ban.first && dst == ban.second) {
            isDel = true;
            continue;
        }
        sum += dfs(dst, es, seen, finished, memo, ban);
    }
    return memo[s] = sum / (es[s].size() - isDel) + 1;
}

