#define MAXN 666

struct Edge {
	int to;
	bool can;
	Edge(int _to = -1, bool _can = false) : to(_to), can(_can) {}
};

vector<Edge> g[MAXN];

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);

	int n, m;
	cin >> n >> m;
	for(int i = 0; i < m; i++) {
		int u, v;
		cin >> u >> v;
		u--, v--;
		g[u].emplace_back(v, true);
	}

	vector<double> dp(n);
	for(int i = n-2; i >= 0; i--) {
		dp[i] = 1;
		double tot = 0;
		for(Edge e : g[i]) {
			tot += dp[e.to];
		}

		dp[i] += tot / g[i].size();
	}

	double ans = dp[0];

	for(int i = 0; i < n-1; i++) {
		if((int) g[i].size() == 1) continue;
		int best = -1;
		double mx = -1;
		for(Edge e : g[i]) {
			if(dp[e.to] > mx) {
				best = e.to, mx = dp[e.to];
			}
		}

		for(Edge& e : g[i]) {
			if(e.to == best) {
				e.can = false;
			}
		}

		vector<double> new_dp(n);
		for(int u = n-2; u >= 0; u--) {
			new_dp[u] = 1;
			double tot = 0;
			int sz = 0;
			for(Edge e : g[u]) {
				if(!e.can) continue;
				sz++;
				tot += new_dp[e.to];
			}

			new_dp[u] += tot / sz;
		}

		ans = min(ans, new_dp[0]);

		for(Edge& e : g[i]) {
			if(e.to == best) {
				e.can = true;
			}
		}
	}

	cout << fixed << setprecision(10) << ans << endl;
}

