        vector<double> e(N, 0);
        for ( int v = N-2; v >= 0; v-- ) {
            double m = -1;
            int j;
            for ( int u : G[v] ) {
                e[v] += (1 + e[u])/G[v].size();
                if ( m < e[u] ) {
                    m = e[u];
                    j = u;
                }
            }
            if ( nd == v && G[v].size() > 1 ) {
                double edc = 0;
                for ( int u : G[v] ) {
                    if ( u == j ) continue;
                    edc += (1 + e[u])/(G[v].size()-1);
                }
                e[v] = min(e[v], edc);
            }
        }
        return e[0];
    };

