double cal_min_estimate(const std::vector<std::vector<int>> rooms, const int current_room, std::vector<double>& memo) {
	if (current_room + 1 == rooms.size()) 
		return 0;
	if (memo[current_room] >= 0)
		return memo[current_room];
	double sum = 0;
	for (const auto next : rooms[current_room]) {
		sum += cal_min_estimate(rooms, next, memo);
	}
	return memo[current_room] = sum / rooms[current_room].size() + 1;
}
int main() {
	std::cin.tie(0); std::cin.sync_with_stdio(false);
	int n, m; std::cin >> n >> m;
	std::vector<std::vector<int>> rooms(n);
	for (auto i = 0; i < m; ++i) {
		int s, t; std::cin >> s >> t;
		rooms[s - 1].push_back(t - 1);
	}
	std::vector<double> default_est(n, 0.0); default_est[n - 1] = 0;
	for (int i = n - 2; i >= 0; --i) {
		for (const auto next : rooms[i]) {
			default_est[i] += default_est[next];
		}
		default_est[i] /= rooms[i].size();
		default_est[i] += 1;
	}
	auto changed_est(default_est);
	double result = default_est[0];
	for (int remove = 0; remove < n - 1; ++remove) if (rooms[remove].size() > 1) {
		std::fill(changed_est.begin(), std::next(changed_est.begin(), remove), -1);
		double sum = 0;
		double max = 0;
		for (const auto next : rooms[remove]) {
			sum += default_est[next];
			max = std::max(max, default_est[next]);
		}
		changed_est[remove] = (sum - max) / (rooms[remove].size() - 1) + 1;
		result = std::min(result, cal_min_estimate(rooms, 0, changed_est));
	}
	std::cout << std::setprecision(15) << std::fixed << result << '\n';
}

