struct UnionFind{
    vector<int> tree;

    UnionFind(int n): tree(n+1, -1) {};

    int root(int i){ return tree[i] < 0 ? i : tree[i] = root(tree[i]); }

    bool unite(int i, int j){
        i = root(i), j = root(j);
        if(i == j) return false;
        tree[i] += tree[j], tree[j] = i;
        return true;
    }

    bool same(int i, int j){ return root(i) == root(j); }

    int size(int i){ return -tree[root(i)]; }
};

double dfs(int i){
    if(used[i] == 1){
        return dp[i];
    }

    if(i == n-1) return 0;

    used[i] = 1;

    double k = 0;


    for(auto e : graph[i]){
        k += (dfs(e)+1);
    }

    return dp[i] = k / graph[i].size();
}

