double func(int place){
	if(place==n)return 0;
	double res = 0;
	rep(i, roads[place].size()){
		double d = 1 + func(roads[place][i]);
		dp[place][i] = d;
		res += d;
	}
	sum[place] = res;
	res /= roads[place].size();
	return res;
}

double func2(int place){
	if(place==n)return 0;
	double res = 0;
	if(roads[place].size()==1){
		return func2(roads[place][0]);
	}
	rep(i, roads[place].size()){
		chmin(res, func2(roads[place][i]));
		chmin(res, ((sum[place]-dp[place][i])/(roads[place].size()-1) - sum[place] / roads[place].size())*selecter[place]);
	}
	return res;
}

void add(){
	for(int i=1;i<n;++i){
		foreach(j, roads[i]){
			selecter[j] += selecter[i] / roads[i].size();
		}
	}
}


