using namespace std;
typedef long double LD;
#define N 600 + 5

int n, m, Go[N][N];
LD ans, PreP[N], Pre[N], Suf[N];

void DP()
{
	PreP[1] = 1, Pre[1] = 0;
	for (int i = 1; i < n; i ++)
	{
		LD tp = PreP[i] / Go[i][0], tpl = (Pre[i] + PreP[i]) / Go[i][0];
		for (int j = 1; j <= Go[i][0]; j ++)
		{
			int d = Go[i][j];
			PreP[d] += tp;
			Pre[d] += tpl;
		}
	}
	Suf[n] = 0;
	for (int i = n - 1; i; i --)
	{
		for (int j = 1; j <= Go[i][0]; j ++)
			Suf[i] += Suf[Go[i][j]] + 1;
		Suf[i] /= Go[i][0];
	}
	ans = Suf[1];
}

int main()
{
	scanf("%d%d", &n, &m);
	for (int i = 1, u, v; i <= m; i ++)
	{
		scanf("%d%d", &u, &v);
		Go[u][++ Go[u][0]] = v;
	}
	DP();
	for (int i = 1; i <= n; i ++)
		if (Go[i][0] > 1)
		{
			LD retpl = Pre[n] - PreP[i] * Suf[i];
			for (int j = 1; j <= Go[i][0]; j ++)
			{
				LD npl = retpl + PreP[i] * (Suf[i] * Go[i][0] - (Suf[Go[i][j]] + 1)) / (Go[i][0] - 1);
				ans = min(ans, npl);
			}
		}
	printf("%.9Lf\n", ans);
	return 0;
}

