template<class T>
T next(istream& in) {
    T ret;
    in >> ret;
    return ret;
}


void solve(istream& in, ostream& out) {
    int n = next<int>(in);
    int m = next<int>(in);
    vector<vector<int>> edges(n);
    forn (int, i, m) {
        int u = next<int>(in) - 1;
        int v = next<int>(in) - 1;
        edges[u].push_back(v);
    }
    vector<double> p(n), e(n);
    p[0] = 1.0;
    forn (int, i, n) {
        double add = p[i] / edges[i].size();
        for (int j : edges[i]) {
            p[j] += add;
        }
    }
    rforn (int, i, n - 1) {
        for (int j : edges[i]) {
            e[i] += e[j];
        }
        e[i] = e[i] / edges[i].size() + 1;
    }
    double ans = e[0];
    forn (int, i, n) {
        int cnt = edges[i].size();
        if (cnt > 1) {
            for (int j : edges[i]) {
                rmn(ans, e[0] + p[i] * ((e[i] - 1 - e[j]) / (cnt - 1)));
            }
        }
    }
    out << setprecision(11) << ans << "\n";
}


