void dfs(ll u)
{
	vis[u] = 1;
	ld mn = 0;
	for(auto v:adj[u])
	{
		if(vis[v] == 0)
			dfs(v);
		deg[v]++;
		dp[u] += dp[v]+1;
		mn = max(mn,dp[v]+1.0);
	}
	if(adj[u].empty())
		return;
	ll sz = adj[u].size();
	dp[u] /= (ld)(sz);
	dp2[u] = dp[u];
	if (sz > 1) {
		for (int v: adj[u]) {
			dp2[u] = min(dp2[u], (dp[u]*sz - dp[v] - 1) / (sz - 1));
		}
	}
	return;
}

