const int MAX_N=600+1;
int N,M;

VI G[MAX_N];
double dp[MAX_N];
void solve() {
  ZERO(dp);
  for(int u=N-2; u>=0; --u) {
    double sum=0;
    FORR(v,G[u]) sum+=dp[v];
    dp[u]=1+sum/SZ(G[u]);
  }
  double res=dp[0];
  REP(u,N-1) {
    double maxe=dp[G[u][0]];
    FORR(v,G[u]) SMAX(maxe,dp[v]);
    double temp=dp[u];
    double sum=SZ(G[u])*(temp-1);
    dp[u]=1+(sum-maxe)/(SZ(G[u])-1);
    for(int i=u-1; i>=0; --i) {
      double sum=0;
      FORR(j,G[i]) sum+=dp[j];
      dp[i]=1+sum/SZ(G[i]);
    }
    SMIN(res,dp[0]);
  }
  cout<<res<<endl;
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);
  cout<<setprecision(12)<<fixed;

  cin>>N>>M;
  REP(i,M) {
    int u,v; cin>>u>>v;
    --u,--v;
    G[u].push_back(v);
  }
  solve();

