int main(){
    int n, m;
    cin >> n >> m;

    vector<vector<int>> graph(n);
    for(int i=0; i<m; i++){
        int s, t;
        cin >> s >> t;
        s -= 1;
        t -= 1;
        graph[s].push_back(t);
    }

    vector<double> dp(n);
    for(int i=n-2; i>=0; i--){
        double sum = 0;
        for(int v : graph[i]) sum += dp[v];
        sum /= (double)graph[i].size();
        dp[i] = sum + 1;
    }

    double ans = dp[0];
    for(int i=n-2; i>=0; i--){
        if(graph[i].size() == 1) continue;

        int block = graph[i][0];
        for(int v : graph[i]){
            if(dp[v] > dp[block]) block = v;
        }

        vector<double> dp(n);
        for(int j=n-2; j>=0; j--){
            double sum = 0;
            for(int v : graph[j]){
                if(j == i && v == block) continue;
                sum += dp[v];
            }
            if(j == i) sum /= (double)(graph[j].size() - 1);
            if(j != i) sum /= (double)graph[j].size();
            dp[j] = sum + 1;
        }
        ans = min(ans, dp[0]);
    }
    cout << fixed << setprecision(10) << ans << endl;
    return 0;
}

