    int s, t;
    cin >> s >> t;
    --s; --t;
    to[s].push_back(t);
    ot[t].push_back(s);
  }

  vector<double> en(n), pn(n);
  pn[n-1] = 1;
  for (int v = n-2; v >= 0; --v) {
    int deg = to[v].size();
    for (int u : to[v]) {
      en[v] += en[u];
      pn[v] += pn[u];
    }
    en[v] /= deg; en[v] += 1;
    pn[v] /= deg;
  }

  vector<double> e1(n), p1(n);
  p1[0] = 1;
  for (int v = 1; v < n; ++v) {
    for (int u : ot[v]) {
      e1[v] += (e1[u]+1)/to[u].size();
      p1[v] += p1[u]/to[u].size();
    }
  }
  // rep(i,n) printf("%d %.2f %.2f\n", i, en[i], pn[i]);
  // rep(i,n) printf("%d %.2f %.2f\n", i, e1[i], p1[i]);

  double ans = en[0];
  for (int v = 0; v <= n-2; ++v) {
    int deg = to[v].size();
    if (deg == 1) continue;
    double now = en[0];
    { // 1/deg -> 0
      double p = 1.0/deg;
      for (int u : to[v]) {
        double s = e1[v]*pn[u];
        s += p1[v]*en[u];
        s += p1[v]*pn[u];
        s *= p;
        now -= s;
      }
    }
    { // 0 -> 1/(deg-1)
      double p = 1.0/(deg-1);
      for (int u : to[v]) {
        double s = e1[v]*pn[u];
        s += p1[v]*en[u];
        s += p1[v]*pn[u];
        s *= p;
        now += s;
      }
    }
    for (int u : to[v]) {
      // 1/(deg-1) -> 0
      double p = 1.0/(deg-1);
      double s = e1[v]*pn[u];
      s += p1[v]*en[u];
      s += p1[v]*pn[u];
      s *= p;
      ans = min(ans, now-s);
    }
  }

  printf("%.10f\n", ans);
  return 0;
}

