			if ((u==ban) && (len>1))
			{
				len--;sum-=mx;
			}
			f[u]=sum/len+1;
		}
		//rep(i,1,n) cout << f[i] << " ";cout << endl;
		ans=min(ans,f[1]);
	}
	printf("%0.8lf",ans);
	return 0;
}

