void make_link(const V<t2> &srclist,
               V<ll> linklist[603], V<ll> rlinklist[603],
               ll refers[603], ll referred[603])
{
    memset(refers, 0, sizeof(ll) * 603LL);
    memset(referred, 0, sizeof(ll) * 603LL);

    for (auto src : srclist) {
        ll a = get<0>(src);
        ll b = get<1>(src);
        linklist[a].pb(b);
        rlinklist[b].pb(a);
        refers[a]++;
        referred[b]++;
    }
}

void trim(V<ll> linklist[603], V<ll> rlinklist[603],
          ll refers[603], ll referred[603], ll n, ll m)
{
    queue<ll> q;
    rep (i, n+1) if (i != 1LL && referred[i] == 0LL) q.push(i);

    while (!q.empty()) {
        ll v = q.front(); q.pop();
        debug_printf("---- trim v = %lld\n", v);
        for (auto nv : linklist[v]) {
            rlinklist[nv].erase(lower_bound(ALL(rlinklist[nv]), v));
            refers[v]--;
            referred[nv]--;
            debug_printf("---- nv=%lld referred[nv]=%lld\n", nv, referred[nv]);
            if (nv != 1LL && referred[nv] == 0LL) q.push(nv);
        }
        linklist[v].clear();
    }
}

void calc_expectation(double expects[603], double probs[603],
                      const V<ll> linklist[603], const ll referred[603],
                      ll n, ll m)
{
    memset(expects, 0, sizeof(double) * 603);
    memset(probs, 0, sizeof(double) * 603);
    queue<ll> q;
    static ll refcnts[603];
    memset(refcnts, 0, sizeof(refcnts));
    static double lexpects[603][603];
    static double lprobs[603][603];
    memset(lexpects, 0, sizeof(lexpects));
    memset(lprobs, 0, sizeof(lprobs));

    q.push(1LL);
    expects[1] = 0.;
    probs[1] = 1.;

    while (!q.empty()) {
        ll v = q.front(); q.pop();
        if (linklist[v].empty()) continue;

        ll refs = linklist[v].size();
        double uprobe = 1. / (double)refs;

        for (auto nv : linklist[v]) {
            ll cnt = refcnts[nv];
            lexpects[nv][cnt] = expects[v] + 1.0;
            lprobs[nv][cnt] = probs[v] * uprobe;
            cnt = ++refcnts[nv];
            assert(refcnts[nv] <= referred[nv]);
            if (refcnts[nv] == referred[nv]) {
                probs[nv] = 0.;
                expects[nv] = 0.;
                rep (i, cnt) {
                    probs[nv] += lprobs[nv][i];
                    expects[nv] += lprobs[nv][i] * lexpects[nv][i];
                }
                expects[nv] *= (1. / probs[nv]);
                q.push(nv);
            }
        }
    }

    srep (i, 1, 5) {
        debug_printf("---- probs[%lld] = %lf expects[%lld] = %lf\n",
                     i, probs[i], i, expects[i]);
    }
}

void calc_remain_expects(V<double> remain_expects[603],
                         const V<ll> rlinklist[603],
                         const ll refers[603], ll n, ll m)
{
    queue<ll> q;
    double lexpects[603];
    memset(lexpects, 0, sizeof(lexpects));

    q.push(n);
    lexpects[n] = 0.;

    while (!q.empty()) {
        ll v = q.front(); q.pop();
        for (auto nv : rlinklist[v]) {
            remain_expects[nv].pb(lexpects[v] + 1.);
            assert(remain_expects[nv].size() <= refers[nv]);
            if (remain_expects[nv].size() == refers[nv]) {
                q.push(nv);
                lexpects[nv] = 0.;
                rep (i, refers[nv]) lexpects[nv] += remain_expects[nv][i];
                lexpects[nv] /= (double)refers[nv];
            }
        }
    }

    rep (v, n+1) sort_reverse(remain_expects[v]);

    debug_printf("---- remain_expects[4]\n"); debug_print(remain_expects[4]);
    debug_printf("---- remain_expects[3]\n"); debug_print(remain_expects[3]);
    debug_printf("---- remain_expects[2]\n"); debug_print(remain_expects[2]);
    debug_printf("---- remain_expects[1]\n"); debug_print(remain_expects[1]);
    debug_printf("---- remain_expects[0]\n"); debug_print(remain_expects[0]);
}

double solve(const double expects[603], const double probs[603],
             const V<double> remain_expects[603], ll n, ll m, ll v)
{
    ll cnt = remain_expects[v].size();
    if (cnt <= 1LL) return expects[n];

    double orig_remain_expect = 0.;
    for (auto e : remain_expects[v]) orig_remain_expect += e;
    orig_remain_expect /= (double)cnt;

    double new_remain_expect = 0.;
    for (auto e : remain_expects[v]) new_remain_expect += e;
    new_remain_expect -= remain_expects[v][0];
    new_remain_expect /= (double)(cnt - 1LL);

    assert(new_remain_expect <= orig_remain_expect);
    double decr = (orig_remain_expect - new_remain_expect) * probs[v];
    debug_printf("--- solve v=%lld decr = %lf\n", v, decr);
    return expects[n] - decr;
}

int _main()
{
    ll n; llin(n);
    ll m; llin(m);
    V<t2> stlist; llinl2(stlist, m);

    static V<ll> linklist[603];
    static V<ll> rlinklist[603];
    static ll refers[603];
    static ll referred[603];
    make_link(stlist, linklist, rlinklist, refers, referred);
    trim(linklist, rlinklist, refers, referred, n, m);

    static double expects[603];
    static double probs[603];
    calc_expectation(expects, probs, linklist, referred, n, m);

    static V<double> remain_expects[603];
    calc_remain_expects(remain_expects, rlinklist, refers, n, m);

    double ans = expects[n];
    srep (v, 1, n) {
        ans = min(ans, solve(expects, probs, remain_expects, n, m, v));
    }

    cout << ans << endl;

    return 0;
}

