inline void calc () {
	static double dp[N];
	rep (i, 1, n) dp[i] = INT_MAX;
	dp[n] = 0;
	per (i, n - 1, 1) {
		double cnt = 0;
		double tmp = 0;
		rep (j, i + 1, n) {
			if (mp[i][j] && fabs (dp[j] - INT_MAX) > 1e-9) {
				tmp += dp[j];
				cnt += 1;
			}
		}
		if (fabs(cnt) < 1e-9) continue;
		dp[i] = tmp;
		dp[i] /= cnt;
		dp[i] += 1.0;
	}
	if (dp[1] != INT_MAX) ans = min (ans, dp[1]);
}

