void solve(long long N, long long M, std::vector<long long> s, std::vector<long long> t){
  long double ans=M+1;
  vector<vector<ll>> graph(N);
  REP(M){
    --s[i];--t[i];
    graph[s[i]].push_back(t[i]);
  }
  dump(graph);
  REP(M+1){
    if(i<M&&graph[s[i]].size()==1)continue;
    vector<pair<long double,long double>> e(N,pdd(0.0,0.0));
    e[0]=pdd(1.0,0);
    For(j,N-1){
      long double prob;
      if(i!=M && graph[j].size()>1)
        prob = (long double)1/(graph[j].size()-(s[i]==j?1:0));
      else
      {
        prob = (long double)1/graph[j].size();
      }
      long double tmp=e[j].first*prob;
      for (auto &&k : graph[j])
      {
        if(i!=M&&graph[j].size()>1&&j==s[i]&&k==t[i])continue;
        e[k].first+=tmp;
        e[k].second+=e[j].second*prob+tmp;
      }
    }
    dump(e);
    ans=min(ans,e[N-1].second);
  }
  cout<<setprecision(100) << ans<<endl;
}

