int main() {
  scanf("%lld%lld", &n, &m);
  for (ll i = 0; i < m; i++) {
    scanf("%lld%lld", &s, &t);
    s--; t--;
    e[s].push_back(t);
  }
  for (ll i = n-2; i >= 0; i--) {
    for (ll j : e[i]) dp[i] += dp[j];
    dp[i] = dp[i] / e[i].size() + 1;
  }
  ans = dp[0];
  for (ll i = 0; i < n; i++) {
    if (e[i].size() <= 1) continue;
    double mx = -INF, sum = 0;
    for (ll j : e[i]) mx = max(mx, dp[j]), sum += dp[j];
    dp[i] = (sum - mx) / (e[i].size() - 1) + 1;
    for (ll k = i-1; k >= 0; k--) {
      dp[k] = 0;
      for (ll j : e[k]) dp[k] += dp[j];
      dp[k] = dp[k] / e[k].size() + 1;
    }
    ans = min(ans, dp[0]);
  }
  printf("%.10lf\n", ans);
}

