using namespace std;
typedef long long ll;
const ll MOD = 1e9 + 7;
const ll INF = 1LL << 60;
double dp[600];
double A[600], B[600];
vector<int> G[600];
int main() {
	int N, M;
	cin >> N >> M;
	for (int i = 0; i < M; i++) {
		int s, t;
		cin >> s >> t;
		s--; t--;
		G[s].push_back(t);
	}
	dp[N - 1] = 0;
	for (int v = N - 2; v >= 0; v--) {
		for (int to : G[v]) {
			dp[v] += (dp[to] + 1);
		}
		dp[v] /= G[v].size();
	}
	double ans = dp[0];
	for (int s = 0; s < N; s++) {
		if (G[s].size() == 1) continue;
		A[s] = 1;
		B[s] = 0;
		for (int i = s + 1; i < N; i++) {
			A[i] = 0;
			B[i] = dp[i];
		}
		for (int i = s - 1; i >= 0; i--) {
			A[i] = B[i] = 0;
			for (int to : G[i]) {
				A[i] += A[to] / G[i].size();
				B[i] += (B[to] + 1) / G[i].size();
			}
		}
		for (int to : G[s]) {
			double x = (dp[s] * G[s].size() - (dp[to] + 1)) / (G[s].size() - 1);
			ans = min(ans, A[0] * x + B[0]);
		}
	}
	printf("%.15lf\n", ans);
}

