using namespace std;
typedef pair<int, int> PII;
const int N = 610;
int g[N][N];
double ex[N];
double p[N];
double backup[N];
vector<PII> edges;
int n,m;

void add(int a, int b){
    g[a][b] = 1;
    p[a] += 1.0;
    PII temp = {a, b};
    edges.push_back(temp);
}

double cal(int s, int t){
    if (s != 0){
        g[s][t] = 0;
        p[s] -= 1;
    } else{
        s = n - 1 ;
    }
    ex[n] = 0;
    for (int j = s; j >=1 ; j --){
        ex[j] = 0;
        for (int k = j + 1; k <= n; k ++){
            if(g[j][k]) {
                ex[j] += (1 + ex[k]) * (1/p[j]);
            }
        }
    }
    double res = ex[1];
    if (s != n - 1){
        g[s][t] = 1;
        p[s] += 1;
    }
    return res;
}

int main(){
    cin >> n >> m;
    while(m --){
        int a,b;
        cin >> a >> b;
        add(a, b);
    }
    double res = cal(0,0);
    memcpy(backup, ex, sizeof ex);

    for (auto edge:edges){
        int i = edge.first;
        int j = edge.second;
        if((g[i][j] == 1) && p[i] != 1){
            double temp = cal(i,j);
            memcpy(ex, backup, sizeof ex);
            res = min(res, temp);
        }
    }
    cout << setprecision(14) <<res << endl;
    return 0;
}

