struct Vertex
{
    vector<pll> node;
    double E;
    double E2;
    ll size = 0;
    ll count = 0;
};
struct Node
{
    ll index;
    double E;
    ll cost;
};

Vertex V[605];
//! 頂点iまでkかいで来る時の確率
double C[605][605];

int main()
{
    ll N, M;
    cin >> N >> M;
    REP(i, M)
    {
        ll s, t;
        cin >> s >> t;
        s--;
        t--;
        V[s].node.push_back(pll(t, i));
        V[t].size++;
    }

    double min = 100000.0;
    REP(m, M + 1)
    {
        // cout << m << endl;
        //! 通路iを禁止する
        queue<Node> q;
        q.push(Node{0LL, 1.0, 0LL});
        REP(i, N)
        {
            V[i].count = 0;
            V[i].E = 0;
            V[i].E2 = 0;
        }

        REP(i, N)
        {
            REP(j, N)
            {
                C[i][j] = 0;
            }
        }
        C[0][0] = 1.0;
        bool exist = true;
        while (!q.empty())
        {
            auto t = q.front();
            q.pop();
            if (t.index == N - 1)
            {
                break;
            }
            ll num = 0;
            REP(i, V[t.index].node.size())
            {
                auto node = V[t.index].node[i];
                if (m == node.second)
                    continue;
                num++;
            }
            if (num == 0)
            {
                exist = false;
                break;
            }
            REP(i, V[t.index].node.size())
            {
                auto node = V[t.index].node[i];
                V[node.first].count++;
                if (m != node.second)
                {
                    C[node.first][t.cost] += t.E / (double)num;
                }

                if (V[node.first].count == V[node.first].size)
                {
                    double ex = 0;
                    REP(j, N)
                    {
                        if (C[node.first][j] == 0)
                            continue;
                        Node newNode;
                        newNode.index = node.first;
                        newNode.E = C[node.first][j];
                        newNode.cost = j + 1;
                        q.push(newNode);
                    }
                }
            }
        }

        if (!exist)
            continue;
        double e = 0;
        REP(i, N)
        {
            e += C[N - 1][i] * (double)i;
        }
        min = std::min(min, e);
    }
    cout << OF64 << min << endl;
    return 0;
}

