void dynamic_programming(
    const vector<vector<int>> &edge, 
    vector<double>& dis, int cfrom, int cto)
{
    int n = edge.size();
    dis[0] = 0;
    for (int i=1; i<n; ++i)
    {
        double without = 0;
        double num = edge[i].size();
        for (auto to: edge[i])
        {
            if (cfrom == i and cto == to) continue;
            without += 1+dis[to];
        }

        if (i == cfrom)
            without /= num-1;
        else
            without /= num;
        dis[i] = without;
        // cout << without << endl;
    }
}

int main()
{
