        cin >> s >> t;
        s = n-s;
        t = n-t;
        edge[s].push_back(t);
    }

    vector<double> dis(n);
    dynamic_programming(edge, dis, -1, -1);
    double ans = dis[n-1];
    // cout << "****** " << ans << endl;

    for (int i=1; i<=n-1;++i)
    {
        if (edge[i].size() <= 1) continue;
        int to = edge[i][0];
        for (auto t: edge[i])
            if (dis[t] > dis[to]) to = t;

        vector<double> now(n);
        dynamic_programming(edge, now, i, to);
        ans = min(ans, now[n-1]);
        // cout << "****** " << ans << endl;
    }
    printf("%.10f\n", ans);
