struct Graph {

    int n;

    vector<vector<int>> edges;
    vector<double> exp;
    vector<P> candidate;

    Graph(int n): n(n), edges(n){}

    void add_edge(int u, int v){
        edges[u].emplace_back(v);
    }

    double calc(){

        exp.assign(n, INF);
        exp[n-1] = 0;


        REP_REV(v, n-1){
            exp[v] = 0;
            int tmp = -1;
            double mx = 0;
            for (auto e: edges[v]){
                exp[v] += exp[e];
                if (exp[e] > mx){
                    tmp = e;
                    mx = exp[e];
                }
            }
            candidate.emplace_back(v, tmp);
            exp[v] /= edges[v].size();
            exp[v] += 1;
        }
        return exp[0];
    }

    double calc2(){

        double ans = INF;
        for (auto p: candidate){
            int u = p.first;
            int t = p.second;

            REP_REV(v, n-1){
                exp[v] = 0;
                int num = 0;
                for (auto e: edges[v]){
                    if (v == u && e == t) continue;
                    exp[v] += exp[e];
                    num++;
                }
                exp[v] /= num;
                exp[v] += 1;
            }
            ans = min(ans, exp[0]);
        }

        return ans;
    }
};


