const bool multiple_queries = false;

void solve(){
    // generate_array(size, min, max);
    ll n, m; in2(n, m);
    Graph graph(n);
    rep(i, m){
        ll a, b; in2(a, b); a--, b--;
        graph[a].pb({b, 1});
    }

    vector<ld> dp(n, -1); dp[n - 1] = 0;
    auto dfs = [&](auto dfs, ll src, pl path) -> ld{
        if (dp[src] > -EPS) return dp[src];
        ld ret = 0, deg = 0;
        for (auto& e: graph[src])
            if (mp(src, e.to) != path)
                ret += dfs(dfs, e.to, path) + 1, deg += 1;
        return dp[src] = ret / deg;
    };

    dfs(dfs, 0, {-1, -1});
    vector<ld> memo = dp; ld ans = dp[0];
    rep(s, n){
        if (graph[s].size() == 1) continue;
        ll t = 0; ld v = 0;
        for (auto& e: graph[s])
            if (chmax(v, memo[e.to])) t = e.to;
        fill(all(dp), -1); dp[n - 1] = 0; chmin(ans, dfs(dfs, 0, {s, t}));
    }

    prl_nd(ans, 12);

    // ### DEBUG PART ###
    auto naive_solver = [&](){
    };
    #ifdef _LOCAL
        naive_solver();
    #endif
}

