double solve(const vector<vector<int> > &graph, int ver) {
  int n = graph.size();
  if (graph[ver].size() == 1) return LINF;
  vector<double> dp(n, LINF);
  dp[n - 1] = 0;
  for (int i = n - 2; i >= 0; --i) {
    double sum = 0, mx = 0;
    for (int e : graph[i]) {
      sum += dp[e] + 1;
      mx = max(mx, dp[e] + 1);
    }
    if (i == ver) {
      dp[i] = (sum - mx) / (graph[i].size() - 1);
    } else {
      dp[i] = sum / graph[i].size();
    }
  }
  return dp[0];
}

int main() {
  int n, m; cin >> n >> m;
  vector<vector<int> > graph(n);
  while (m--) {
    int s, t; cin >> s >> t; --s; --t;
    graph[s].emplace_back(t);
  }
  double ans = n - 1;
  REP(i, n - 1) ans = min(ans, solve(graph, i));
  cout << ans << '\n';
  return 0;
}

