	REP(i, m) {
		cin >> a >> b; a--;	b--;
		v.push_back(P(a, b));
		gr[a].insert(b);
		cnt[a]++;
	}
	vector<double> es(n);
	es[n - 1] = 0;
	RREP(i, n - 1) {
		double e = 0;
		for (auto j : gr[i]) e += 1 + es[j];
		es[i] = e / cnt[i];
	}
	vector<double> maxval(n);
	vector<int> cand(n);
	REP(i, n) {
		maxval[i] = 0;
		cand[i] = -1;
	}
	REP(i, m) {
		a = v[i].first;
		b = v[i].second;
		if (maxval[a] < es[b]) {
			maxval[a] = es[b];
			cand[a] = i;
		}
	}
