using namespace std;

int N, M, A[1 << 18], B[1 << 18];
double dp[1 << 18];
double dp2[1 << 18], prob2[1 << 18];
vector<int> X[1 << 18];

void init() {
	dp[N] = 0.0;
	for (int i = N - 1; i >= 1; i--) {
		double mul = 1.0 / (double)X[i].size();
		for (int j = 0; j < X[i].size(); j++) {
			dp[i] += (dp[X[i][j]] + 1.0) * mul;
		}
	}
}

int main() {
	cin >> N >> M;
	for (int i = 1; i <= M; i++) {
		cin >> A[i] >> B[i];
		X[A[i]].push_back(B[i]);
	}

	init();

	double ans = dp[1]; prob2[1] = 1.0;
	for (int i = 1; i <= N; i++) {
		// Step #1: 計算を行う
		double dp3[609], prob3[609];

		if (X[i].size() >= 2) {
			double mul = 1.0 / (1.0 * X[i].size() - 1.0);
			for (int j = 0; j < X[i].size(); j++) {
				for (int k = 1; k <= N; k++) dp3[k] = dp2[k];
				for (int k = 1; k <= N; k++) prob3[k] = prob2[k];

				for (int k = 0; k < X[i].size(); k++) {
					if (j == k) continue;
					dp3[X[i][k]] += (dp3[i] + prob3[i]) * mul;
					prob3[X[i][k]] += prob3[i] * mul;
				}

				double rem = 0;
				for (int k = i + 1; k <= N; k++) {
					if (prob3[k] < 1e-10) continue;
					rem += prob3[k] * (dp3[k] / prob3[k] + dp[k]);
				}
				ans = min(ans, rem);
			}
		}

		// Step #2: 次への遷移
		double mul = 1.0 / X[i].size();
		for (int j = 0; j < X[i].size(); j++) {
			dp2[X[i][j]] += (dp2[i] + prob2[i]) * mul;
			prob2[X[i][j]] += prob2[i] * mul;
		}
	}
	printf("%.12lf\n", ans);
	return 0;
}

