double dfs(int from) {
	if(dp[from] != -1) {
		return dp[from];
	}
	double ret = 0;
	for(int to : edge[from]) {
		ret += dfs(to) + 1;
	}
	double sz = edge[from].size();
	if(sz != 0) ret /= sz;
	return dp[from] = ret;
}
double dfsp(int from) {
	if(dpp[from] != -1) {
		return dpp[from];
	}
	double ret = 0;
	for(int to : edge[from]) {
		ret += dfsp(to) + 1;
	}
	double sz = edge[from].size();
	if(sz != 0) ret /= sz;
	return dpp[from] = ret;
}
