long double exp_root(int x, int n, std::vector<std::pair<int, int>> r, int m) {
	long double exp = 0;
	if (x == n)
		return 0;

	std::vector<int> v;
	for (int i = 0; i < m; ++i)
		if (r[i].first == x)
			v.push_back(r[i].second);

	if (!v.size()) return -1;

	int tmp;
	for (int i = 0; i < v.size(); ++i)
		if ((tmp = exp_root(v[i], n, r, m)) == -1)
			return -1;
		else
			exp += tmp;
	return exp / v.size() + 1;
}

long double erase_root(int x, int n, std::vector<std::pair<int, int>> r, int m, int erase) {
	std::vector<std::pair<int, int>> tmp(r);
	tmp.erase(tmp.begin() + erase);
	return exp_root(1, n, tmp, m - 1);
}

