    for (RI i = 1; i <= m; ++i)
      if (i != tmp)
        addedge(G[i].x, G[i].y), ++d[G[i].x];
    memset(f, 0, sizeof(f));
    memset(g, 0, sizeof(g));
    f[1] = 0, g[1] = 1;
    for (RI i = 1; i < n; ++i) {
