int N;

ld dfs(int now){
    if(now == N-1) return 0;
    ld E = 0, n = es[now].size();
    for(auto &e: es[now]){
        if(memo[e] >= 0) E += memo[e];
        else E += dfs(e);
    }
    E = 1+(E/n);
    memo[now] = E;
    return E;
}

ld dfs2(int now, int s, int t){
    if(now == N-1) return 0;
    ld E = 0, n = es[now].size();
    for(auto &e: es[now]){
        if(now == s && e == t) n--;
      	elif(memo[e] >= 0) E += memo[e];
        else E += dfs2(e, s, t);
    }
    E = 1+(E/n);
  	memo[now] = E;
    return E;
}

