void dfs_expected(int node, vector<double> &expected) {
    if(node == n-1) {
        expected[n-1] = 0.0;
        return;
    }
    expected[node] = 0.0;
    int cnt = 0;
    for(int child: graph[node]) {
        if(node == cut_from && child == cut_to) continue;
        if(expected[child] < 0.0-EPS) dfs_expected(child, expected);
        expected[node] += expected[child] + 1.0;
        ++cnt;
    }
    expected[node] /= double(cnt);
}

