    for(int i=0;i<n;++i) {
        if(graph[i].size() <= 1) continue;
        cut_from = i;
        cut_expected = -1.0;
        for(int child: graph[i]) {
            if(cut_expected < expected[child]) {
                cut_to = child;
                cut_expected = expected[child];
            }
        }
        vector<double> dp(n, -1.0);
        dfs_expected(0, dp);
