#define rep(i, n)   for(ll i=0, i##_length=(n); i< i##_length; ++i)

ll N, M;
ll dels=-1, delt=-1;

double updatedp(vector<vector<ll>> &g,vector<double> &dp,ll v){
	if(v==N-1)return 0.;
	if(dp[v]>-0.1)return dp[v];
	double ans=0.;
	ll gvsize=g[v].size();
	for(ll nextv:g[v]){	
		if(v==dels && nextv==delt){
			gvsize--;
			continue;
		}
		ans+=updatedp(g,dp,nextv);
	}
	return dp[v]=1.+ans/gvsize;
}

signed main() {
  	scanf("%lld%lld", &N, &M);
	vector<vector<ll>> g(N);
	for(ll i=0;i<M;i++){
		ll s,t;
		scanf("%lld%lld", &s, &t);
		s--;t--;
		g[s].push_back(t);
	}

	vector<double> dptmp(N,-1.);
	double ans=updatedp(g,dptmp,0);

	vector<pair<ll,ll>> delpath;
	for(ll v=0;v<N;v++){
		if(g[v].size()==1)continue;
		double maxval=0.;
		ll tmps=-1,tmpt=-1;
		for(ll nextv:g[v]){
			if(maxval<dptmp[nextv]){
				maxval=dptmp[nextv];
				tmps=v;
				tmpt=nextv;
			}
		}
		delpath.push_back({tmps,tmpt});
	}

	for(pair<ll,ll> path:delpath){
		dels=path.first,delt=path.second;
		vector<double> dp(N,-1.);
		double tmp=updatedp(g,dp,0);
		ans=min(ans,tmp);
	}

	printf("%.20f\n", ans);
	return 0;
}

