    }
};

int main()
{
  int nnode, nedge;
  cin >> nnode >> nedge;
  vector<Node> node(nnode);
  for (int i = 0; i < nedge; i++) {
    int from, to;
    cin >> from >> to;
    from--;
    to--;
    node.at(from).edge.push_back(to);
  }

  node.at(nnode-1).del = 0;
  node.at(nnode-1).nodel = 0;
  for (int i = nnode-2; 0 <= i; i--) {
    if (node.at(i).edge.size() == 1) {
      node.at(i).del = node.at(node.at(i).edge.front()).del + 1;
      node.at(i).nodel = node.at(node.at(i).edge.front()).nodel + 1;
      continue;
    }
    double e = node.at(i).edge.size();
    double sum = 0;
    double max_nodel = 0;
    for (int to : node.at(i).edge) {
      sum += node.at(to).nodel;
      max_nodel = max(max_nodel, node.at(to).nodel);
    }
    node.at(i).nodel = sum / e + 1;
    double removed_sum = sum;
    for (int to : node.at(i).edge) {
      removed_sum = min(removed_sum, sum + node.at(to).del - node.at(to).nodel);
    }
    double already_removed = removed_sum / e + 1;
    double remove_now = (sum - max_nodel) / (e - 1) + 1;
    node.at(i).del = min(already_removed, remove_now);
  }
  printf("%.10lf\n", min(node.front().del, node.front().nodel));
  return 0;
}

