void dfs2(int u){
  if(memo[u]) return;
  memo[u] = true;
  for(auto x : T[u]) dfs2(x);
  for(auto x : T[u]){
    dp[u][0] += dp[x][0];
  }
  ld m = (ld)T[u].size();
