        for(auto x : T[u]){
          R.push_back(dp[x][0]);
        }
        sort(R.begin(), R.end());
        R.pop_back();
        for(auto x : R) dp[u][y] += x;
        dp[u][y] = (dp[u][y] / (m - 1.0)) + 1.0;
      }
