        if (v != u) {
          dp2[v] += (dp2[edge.to] + 1) / graph[v].size();
        } else if (mxi[v] != edge.to) {
          dp2[v] += (dp2[edge.to] + 1) / (graph[v].size() - 1);
        }
      }
    }
