                            sv2.at(j)=dp.at(to.at(i).at(j));
                        } else{ // dpが最大の行き先への通路を塞ぎ、それ以外を計算する
                            if (to.at(i).at(j)!=mx2.at(i)) {
                                sv2.at(j)=dp.at(to.at(i).at(j))/(num-1);
                            }
                        }
                    }
                    dp2.at(i)=accumulate(sv2.begin(), sv2.end(), 0.0)+1;
                }
            }
        ans=min(ans,dp2.at(1));
        //cout<<"k="<<k<<" ";
    }
        printf("%10.10f\n",ans);
    return 0;
}

