void solve() {
  ll N, M;
  cin >> N >> M;

  VVL edges(N);
  rep(i, M) {
    ll s, t;
    cin >> s >> t;
    s--, t--;
    edges[s].push_back(t);
  }

  // その頂点から点 N までの辺の数の期待値
  auto calc_dp = [&](ll rm_from, ll rm_to) {
    V<double> dp(N);
    for (ll u = N - 2; u >= 0; u--) {
      double e = 0;

      for (auto v : edges[u]) {
        if (u == rm_from && v == rm_to) continue;
        e += dp[v];
      }

      ll deg = edges[u].size();
      if (u == rm_from) deg--;

      e /= deg;
      e++;
      dp[u] = e;
    }

    return dp;
  };

  V<double> dp = calc_dp(-1, -1);
  double res = dp[0];

  // 各頂点について、期待値の大きい点への辺を消す
  rep(rm_from, N - 1) {
    if (edges[rm_from].size() == 1) continue;

    ll rm_to;
    {
      double max_e = -1;
      for (auto rv : edges[rm_from]) {
        if (chmax(max_e, dp[rv])) rm_to = rv;
      }
    }

    auto rdp = calc_dp(rm_from, rm_to);
    chmin(res, rdp[0]);
  }

  cout << fixed << setprecision(10) << res << endl;
}

