    room_info[n-1]=0; // 初期化

    int count = 0;
    long double total = 0;
    int next = 0;
    long double max = 0;

    long double step[n];

    for(int j=n; j>0; j--){// 部屋N~1まで

        for(int i=m-1; i>-1; i--){

            int s = route[i][0];// 部屋s
            int t = route[i][1];// 部屋t

            if(s==j){
                if(room_info[t-1]+1 > max){
                    max = room_info[t-1]+1;
                }
            }

            total += room_info[t-1]+1;
            count++;

            if(i>0){
                next = route[i-1][0];
            }
            if((s!=next)||i==0){

                if((count>1)&&j==s){
                    total-=max;
                    count--;
                }
                room_info[s-1]=(total)/count;
                total = 0;
                count = 0;
                max = 0;
            }
        }
        step[j-1] = room_info[0];
    }
    sort(step, step+n);
    //std::cout <<  step[0] << "\n";
    cout << fixed << setprecision(10) << step[0] << endl;
    return 0;
}

