  const usize n = scan<usize>();
  const usize m = scan<usize>();
  auto g = md_vec(n, 0, usize()), rg = g;
  for (const usize i : rep(0, m)) {
    const usize s = scan<usize>() - 1;
    const usize t = scan<usize>() - 1;
    g[s].push_back(t);
    rg[t].push_back(s);
  }
  std::vector<double> ex(n, 0);
  ex[n - 1] = 0;
  for (const usize i : revrep(0, n - 1)) {
    for (const auto e : g[i]) {
      ex[i] += ex[e];
    }
    ex[i] = ex[i] / g[i].size() + 1;
  }
  const auto calc = [&](const usize s, const usize t) {
    std::vector<double> ex2(n, 0);
    ex2[n - 1] = 0;
    for (const usize i : revrep(0, n - 1)) {
      usize deg = 0;
      for (const auto e : g[i]) {
        if (i != s || e != t) {
          ++deg;
          ex2[i] += ex2[e];
        }
      }
      ex2[i] = ex2[i] / deg + 1;
    }
    return ex2[0];
  };
