	for(int i=0;i<=M;i++){
		int a,b;
		if(i!=M){
			a = P[i].first;
			b = P[i].second;
			E[a].erase(b);
			revE[b].erase(a);
		}

		ans = min(ans,get_E(E,revE));
		if(i!=M){
			E[a].insert(b);
			revE[b].insert(a);
		}


	}

	cout<<fixed<<setprecision(15)<<ans<<endl;

    return 0;
}

