#include<bits/stdc++.h>
using namespace std;

const int N=600;

struct NODE{
    int to,id;NODE *nxt;
    NODE(){}
    NODE(int _t,int _i,NODE *_n):to(_t),id(_i),nxt(_n){}
};
struct GRAPH{
    NODE pol[N*N],*head[N+3],*ncnt;
    int du[N+3];
    void Init(){
        ncnt=pol;
    }
    void AddEdge(int u,int v,int id){
        NODE *p=++ncnt;
        *p=NODE(v,id,head[u]);head[u]=p;du[u]++;
    }
}G;

int n,m,del;
int frm[N*N];
int seid[N+3];
double Te[N+3],Se[N+3];

double DP(int u){
    if(Te[u]) return Te[u];
    if(u==n) return Te[u]=0;
    if(u==del){
        for(NODE *it=G.head[u];it;it=it->nxt){
            int v=it->to;
            if(it->id==seid[u]) continue;
            Te[u]+=(DP(v)+1)/(G.du[u]-1);
        }
    }
    else{
        for(NODE *it=G.head[u];it;it=it->nxt){
            int v=it->to;
            Te[u]+=(DP(v)+1)/G.du[u];
        }
    }
    return Te[u];
}
int main(){
    G.Init();
    scanf("%d%d",&n,&m);
    for(int i=1;i<=m;i++){
        int u,v;scanf("%d%d",&u,&v);
        G.AddEdge(u,v,i);
        frm[i]=u;
    }
    double ans=DP(1);
    for(int i=1;i<=n;i++) Se[i]=Te[i];
    for(int i=1;i<=m;i++){
        int u=frm[i];
        if(G.du[u]==1) continue;
        double resu=0;
        for(NODE *it=G.head[u];it;it=it->nxt){
            int v=it->to;
            if(it->id==i) continue;
            resu+=Te[v]/(G.du[u]-1);
        }
        if(Se[u]>resu){
            Se[u]=resu;
            seid[u]=i;
        }
    }
    for(int i=1;i<=n;i++){
        if(!seid[i]) continue;
        for(int j=1;j<=n;j++) Te[j]=0;
        del=i;
        ans=min(ans,DP(1));
    }
    printf("%.7f\n",ans);
    return 0;
}

