double updatedp(vector<vector<ll>> &g,vector<double> &dp,ll v){
	//debug(v);
	if(v==N-1)return 0.;
	double ans=0.;
	ll gvsize=g[v].size();
	for(ll nextv:g[v]){	
		if(v==dels && nextv==delt){
			gvsize--;
			continue;
		}
		ans+=updatedp(g,dp,nextv);
	}
	if(gvsize==0)return INF;
	return dp[v]=1.+ans/gvsize;
}

void solve() {

	//map<pair<ll,ll>,ll> depth;

  	scanf("%lld%lld", &N, &M);
	rep(i, M) {
		scanf("%lld%lld", s + i, t + i);
		s[i]--;t[i]--;
		//depth[{s[i],t[i]}]=0;
	}

	vector<vector<ll>> g(N);//,revg(N);
	rep(i,M){
		g[s[i]].push_back(t[i]);
	}

	vector<double> dptmp(N,0.);
	double ans=updatedp(g,dptmp,0);

	vector<pair<ll,ll>> delpath;
	rep(v,N){
		if(g[v].size()==1)continue;
		double maxval=0.;
		ll tmps=-1,tmpt=-1;
		for(ll nextv:g[v]){
			if(chmax(maxval,dptmp[nextv])){
				tmps=v;
				tmpt=nextv;
			}
		}
		delpath.push_back({tmps,tmpt});
	}

	for(pair<ll,ll> path : delpath){
		dels=path.first,delt=path.second;
		vector<double> dp(N,0.);
		double tmp=updatedp(g,dp,0);
		if(chmin(ans,tmp)){debug(s[i],t[i]);}
	}

	printf("%.20f\n", ans);
}

signed main() {
	solve();
	return 0;
}

