            bool skip = 0;
            trav (k, adj[i])
                if (skip || k != j) adj_fin += (1 + fin[k]) / (sz(adj[i]) - 1);
                else skip = 1;

            double adj_ans = enoi + visit[i] * (get[i] + adj_fin);
            ckmin(ans, adj_ans);
        }
