    if(u==n) {
        en[u]=1;
        ep[u]=0;
    }
    else {
        ep[u]=(en[u]*ep[u]+num)/(en[u]+1);
        ++en[u];
    }
    for(int i=0;i<ev[u].size();i++){
        dfss(ev[u][i],num+1);
    }
}

