            for(int dst : path[i]){
                if(i==a[k] && dst==b[k]){
                    continue;
                }

                if(dst >= a[k]+1){
                    E[dst] = compE[dst];
                }

                E[i] += (E[dst]+1)/num;
            }
            if(E[i]==0){
                ok=0;
                break;
            }
        }

        if(ok==1){
            ans = min(ans, E[0]);
        }
    }



    cout<<fixed<<setprecision(10)<<ans<<endl;
    return 0;
}

