double get_E(vector<vector<int>> &E,vector<vector<int>> &revE){
	int N = E.size();


	vector<double> P(E.size(),0.0);
	P[0]=1.0;
	for(int i=0;i<N-1;i++){
		for(int j=0;j<E[i].size();j++){
			int ind = E[i][j];
			P[ind] += P[i]/E[i].size();
		}
	}
	if(abs(P[N-1]-1.0)>0.000001)return Inf;

	vector<double> e(E.size(),0.0);

	for(int i=1;i<N;i++){
		for(int j=0;j<revE[i].size();j++){
			int to = revE[i][j];
			e[i] += (P[to]/E[to].size())*(1.0+e[to]);
		}
		if(P[i]!=0.0)e[i] /= P[i];
	}

	return e[N-1];
}

