        double cur = 0;
        loop(j, N)
            sum[j] = 0;
        sum[1] = 1;
        loop1(v, n) {
            for (int u : g[v]) {
                if (v == ed[i].F && u == ed[i].S)
                    continue;
                double pls = sum[v] / (g[v].size() - (v == ed[i].F));
                cur += pls; sum[u] += pls;
            }
        }
