vector<double> E,Pr;
// ダイクストラっぽいのでO(MlogN)
// ダイクストラはlogNが重かったのでO(M)になるよう、forで実装
// O(M)
double solveG(int es,int et, vector<vector<int>> g){
    vector<double> dp(N+1,0);
    vector<double> pr(N+1,0);
    dp[0] = 0;
    pr[0] = 1;
    for (int u = 0; u < N; u++)
    {
        for(int v:g[u]){
            if(u==es && v==et) continue;
            if(u==es) {
                pr[v] += pr[u]/(g[u].size()-1);
                dp[v] += (dp[u]+pr[u])/(g[u].size()-1);
            }
            else {
                pr[v] += pr[u]/g[u].size();
                dp[v] += (dp[u]+pr[u])/g[u].size();
            }
        }
    }
    if(es==N+1) {
        E = dp;
        Pr = pr;
    }
    return dp[N-1];
}

int solve(){
    double ans = solveG(N+1,N+1,G);
    // 実は全部Mを試す必要ない説。
    // 消す辺をO(N)ぐらいまで下げる。
    DBG(E)
    DBG(Pr)
    const double eps = 1e-12;
    for (int t = 0; t < N; t++)
    {
        vector<pair<double,int>> cmp;
        double cmpC = 0;
        for(int s:revG[t]){
            if(G[s].size()==1) continue;
            if(cmpC<=(E[s]+Pr[s])/G[s].size()+eps){
                cmpC = (E[s]+Pr[s])/G[s].size();
                cmp.emplace_back(cmpC,s);
            }
        }
        if(cmp.empty()) continue;
        sort(cmp.begin(),cmp.end(),[](pair<double,int> a, pair<double,int> b){return a.first < b.first;});
        int s = cmp.back().second;
        double tmp = solveG(s,t,G);
        ans = min(ans,tmp);

    }
    cout << fixed << setprecision(10) << ans << endl;
    return 0;
}

