      std::sort(all(b));
      if (i == skip) b.pop_back();
      dp.at(i) = std::accumulate(all(b), 0.0) / b.size();
    }
    return dp.at(0);
  };

  double ans = inf;
  rep(i, -1, n - 1) {
    cmn(ans, cal(i));
  }
  std::cout << std::setprecision(10) << ans << std::endl;
  return 0;
}

