void dfs(ll u)
{
	vis[u] = 1;
	ld mn = 0;
	for(auto v:adj[u])
	{
		if(vis[v] == 0)
			dfs(v);
		dp[u] += dp[v]+1;
		mn = max(mn,dp[v]+1.0);
	}
	if(adj[u].empty())
		return;
	ll sz = adj[u].size();
	if(sz > 1)
	{
		dp2[u] = (dp[u]-mn);
		dp2[u] /= (ld)(sz-1);
	}
	dp[u] /= (ld)(sz);
	dp2[u] = min(dp[u],dp2[u]);
	return;
}

