            for(int pre : rv[j]){
                if(pre == i){
                    if(j == arg) continue;
                    e[pre] += (e[j] + 1) * 1.0 / ((int)v[pre].size() - 1);
                }
                else e[pre] += (e[j] + 1) * 1.0 / (int)v[pre].size();
            }
        }
        ans = min(ans, e[0]);
    }
    cout << fixed << setprecision(15) << ans << endl;
}

