const int N = 600+5;
//dp[u]: expected number need to be done, but not have been done
//for every edge from u->v, it is garantee that v>u
struct Edge{
    int v;
    int next;
};
int head[N]; Edge e[N*N]; int id = 0;
//f[i][j]: E[i] block edge start from j
double f[N][N];

double min(double a,double b){ return a>b?b:a; }

double max(double a,double b){ return a>b?a:b; }

void addEdge(int u,int v){
    id++;
    e[id].v = v; e[id].next = head[u];
    head[u] = id;
}

int main(){
    int n,m;
    scanf("%d%d",&n,&m);
    for(int i = 0; i < m; i++){
        int u,v;
        scanf("%d%d",&u,&v);
        addEdge(u,v);
    }
    f[n][0] = 0;
    for(int u = n-1; u >= 1; u--){
        int cnt = 0;
        double maxf = 0;
        double sum = 0;
        for(int i = head[u]; i; i = e[i].next){
            cnt++;
            int v = e[i].v;
            sum += f[v][0];
            maxf = max(maxf,f[v][0]);
            for(int j = u+1; j <= n; j++){
                if(j>=v) f[u][j] += f[v][j];
                else f[u][j] += f[v][0];
            }
        }
        f[u][0] = sum/(double)cnt + 1.0;
        f[u][u] = f[u][0];
        if(cnt>1) f[u][u] = min(f[u][u],(sum-maxf)/(double)(cnt-1)+1.0);
        for(int i = u+1; i <= n; i++) f[u][i] = f[u][i]/(double)cnt + 1.0;
    }
    double ans = f[1][0];
    for(int i = 1; i <= n; i++) ans = min(ans,f[1][i]);
    printf("%.9f\n",ans);
    return 0;
}

