R calc(int n, int skip){
	dp[n - 1] = 0.0;

	rrep(v, n - 1){
		int d = tree[v].size();
		R total = 0.0, cmax = 0.0;

		for(auto &u: tree[v]){
			chmax(cmax, dp[u]);
			total += dp[u];
		}

		if (skip == v and d > 1) {
			total -= cmax;
			d--;
		}

		dp[v] = 1.0 * total / d + 1.0;
	}

	return dp[0];
}

