double solve(const V<ll> edgelist[606], const double elist[606],
             ll n, ll m, ll v)
{
    double emax = -1;
    ll nvmax = -1;

    for (auto nv : edgelist[v]) {
        if (elist[nv] > emax) {
            emax = elist[nv];
            nvmax = nv;
        }
    }

    assert(nvmax > 0);

    double flist[606];
    memcpy(flist, elist, sizeof(flist));

    ll cnt = 0;
    double fsum = 0.;
    for (auto nv : edgelist[v]) {
        if (nv == nvmax) continue;
        cnt++;
        fsum += flist[nv] + 1.;
    }
    flist[v] = fsum / (double)cnt;

    rrep (vv, v) {
        if (!vv) break;
        ll lcnt = 0;
        double lfsum = 0.;
        for (auto nvv : edgelist[vv]) {
            lcnt++;
            lfsum += flist[nvv] + 1.;
        }
        flist[vv] = lfsum / (double)lcnt;
    }

    return flist[1];
}


