using namespace std;

typedef long long ll;
typedef long double ld;

double perform(vector<vector<int>> &g, int block_beg, int block_end) {
    int n = (int)g.size() - 1;
    vector<double> dp(n + 1);
    for (int i = n - 1; i >= 1; --i) {
        double sum = 0;
        for (auto &j:g[i]) {
            if (i == block_beg && j == block_end) {
                continue;
            }
            sum += dp[j];
        }
        if (i == block_beg) {
            dp[i] = 1 + sum / ((int)g[i].size() - 1);
        } else {
            dp[i] = 1 + sum / ((int)g[i].size());
        }
    }
    return dp[1];
}

int main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0), cout.tie(0);
    int n, m;
    cin >> n >> m;
    vector<vector<int>> g(n + 1);
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        g[min(u, v)].push_back(max(u, v));
    }
    vector<double> dp(n + 1);
    vector<double> max_exp(n + 1);
    for (int i = n - 1; i >= 1; --i) {
        double sum = 0;
        double exp = 0;
        for (auto &j:g[i]) {
            sum += dp[j];
            if (dp[j] > exp) {
                max_exp[i] = j;
                exp = dp[j];
            }
        }
        dp[i] = 1 + sum / g[i].size();
    }
    double ans = dp[1];
    for (int i = n - 1; i >= 1; --i) {
        ans = min(ans, perform(g, i, max_exp[i]));
    }
    cout << fixed << setprecision(10) << ans;
}

