vector<double> expect(const pair<int, int>& ignore) {
  vector<double> dp(n);
  for (int u = n - 2; u >= 0; u--) {
    double cur = 0;
    int cnt = 0;
    for (auto v : g[u]) {
      if (u == ignore.x && v == ignore.y) {
        continue;
      }
      cnt++;
      cur += dp[v];
    }
    dp[u] = cur / cnt + 1;
  }
  return dp;
}

