    --s, --t;
    G[s][t] = 1;
    ++d[s];
  }

  E.resize(N, -1);
  E[N - 1] = 0.0;
  expectation(0);

  C[0] = 1.0;
  coefficient(N - 1);

  double m = 0.0;
  rep(u, N) {
    if (d[u] == 1 && (C[u] - 1.0) < 1e-9) continue;
    rep(v, N) if (G[u][v]) {
      double deltaE =
          (G[u].size() == 1 ? 1.0 : (E[u] - E[v] - 1) / (d[u] - 1.0));
