double cal(int s, int t){
    if (s != 0){
        g[s][t] = 0;
        p[s] -= 1;
    } else{
        s = n - 1 ;
    }
    ex[n] = 0;
    for (int j = s; j >=1 ; j --){
        ex[j] = 0;
        for (int k = j + 1; k <= n; k ++){
            if(g[j][k]) {
                ex[j] += (1 + ex[k]) * (1/p[j]);
            }
        }
    }
    double res = ex[1];
    if (s != n - 1){
        g[s][t] = 1;
        p[s] += 1;
    }
    return res;
}

