    }

    double ans = dp[0];

    rep(s,n){
        int t=s;
        double x=0;
        if(to[s].size()==1)continue;
        Each(y,to[s]){
            if(dp[t]>x){
                t = y;
                x = dp[t];
            }
        }
        vector<double> e(n,0);

        per(i,n-1){
            ll cntedge = to[i].size();
            for(auto j :to[i]){
                if(i==s&&j==t)cntedge--;
            }
            for(auto j :to[i]){
                if(i==s&&j==t)continue;
                e[i] += (e[j]+1)/cntedge;
            }
        }
        ans = min(e[0],ans);
    }

    cout<<ans<<endl;
    return  0;
}

