namespace adaptor = boost::adaptors;
using index_t = std::size_t;

std::vector<double> base_expected(int N, std::vector<std::set<index_t>>const& edge)
{
	std::vector<double> ret(N);
	for (auto i : boost::irange(0, N - 1) | adaptor::reversed)
	{
		auto d = 1.0 / edge[i].size();
		for (auto j : edge[i])
		{
			ret[i] += d * (1 + ret[j]);
		}
	}
	return ret;
}

void Main()
{
	int N, M;
	std::cin >> N >> M;
	std::vector<std::set<index_t>>edge(N);
	for (auto i : boost::irange(0, M))
	{
		int s, t;
		std::cin >> s >> t;
		--s; --t;
		edge[s].emplace(t);
	}
	auto expected = base_expected(N, edge);
	auto min = expected[0];
	for (auto i : boost::irange(0, N - 1))
	{
		if (edge[i].size() == 1)
		{
			continue;
		}
		for (auto j : boost::irange(0, N - 1) | adaptor::reversed)
		{
			expected[j] = 0;
			auto max = 0.0;
			auto d = 1.0 / (edge[j].size() - (i == j));
			for (auto n : edge[j])
			{
				expected[j] += d * (expected[n] + 1);
				max = std::max(max, d * (expected[n] + 1));
			}
			expected[j] -= (i == j) * max;
		}
		min = std::min(min, expected[0]);
	}
	std::cout << min << std::endl;
}

int main()
{
	std::cin.tie(nullptr);
	std::ios_base::sync_with_stdio(false);
	std::cout << std::fixed << std::setprecision(15);
	Main();
}

