    for(int i = n-1; i > 0; i--){
        double tmp = dp[i];
        if(edge[i].size() > 1){
            double mindp = (double)dp[i];
            for(const auto x: edge[i]){
                double chdp = dp[i];
                chdp *= (double)edge[i].size();
                chdp -= (dp[x] + 1.0);
                chdp /= (double)(edge[i].size() - 1);
                mindp = min(mindp,chdp);
            }
            dp[i] = mindp;
            ans = min(execDpNonChange(dp,i,edge),ans);
        }
        dp[i] = tmp;
    }

    cout << setprecision(17) << fixed;
    cout << ans << endl;

    return 0;
}

