int removed = -1;
int ok[MAXN];
double dp[MAXN];
int B[MAXN];

int isconnect(int u, int v) {
    return adj[u][v] && (removed == -1 || edge[removed] != mp(u,v)); 
}

int can() {
    ok[N] = 1;
    fore(u,1,N) ok[u] = 0;

    for(int u = N-1; u >= 1; u--) {
        fore(v,u+1,N) {
            if(isconnect(u,v)) {
                ok[u] |= ok[v];
            }
        }
    }

    return ok[1];
}

double f(int u) {
    if(u == N) return 0;

    if(B[u]) return dp[u];
    B[u] = 1;
    dp[u] = 0;

    int k = 0;
    fore(v,u+1,N) {
        if(isconnect(u,v)) {
            dp[u] += 1+f(v);
            k++;
        } 
    }

    assert(k);
    dp[u] /= k;
    return dp[u];
}

