    for(int i = 0; i < m; i++)
    {
        int s, t;
        cin >> s >> t;
        s--;t--;
        d[s].push_back(t);
    }

    vector<double> dp(n);
    dp[n-1] = 0;
    for(int i = n-2; i >= 0; i--)
    {
        int size = d[i].size();
        double sum = 0;
        for(int cand : d[i])
        {
            sum += dp[cand] + 1;
        }
        dp[i] = sum / size;
    }
    vector<double> tdp(n);
    tdp[n-1] = 0;
    double ans = dp[0];
    for(int i = n-2; i >= 0; i--)
    {
        for(int j = n-2; j >= 0; j--)
        {
            double sum = 0;
            if(d[j].size() == 1)
            {
                tdp[j] = tdp[d[j][0]]+1;
            }
            else
            {
                double ma = 0;
                for(int cand : d[j])
                {
                    sum += tdp[cand]+1;
                    if(tdp[cand]+1 > ma) ma = tdp[cand]+1;
                }
                if(i == j)
                {
                    sum -= ma;
                    tdp[j] = sum / (d[j].size()-1);
                }
                else
                {
                    tdp[j] = sum / d[j].size();
                }
            }
        }
        ans = min(ans, tdp[0]);
    }
    printf("%.10f", ans);;
}

