void add(int a,int b){
	cnt++;
	e[cnt].to=b;
	e[cnt].nxt=head[a];
	head[a]=cnt;
}
double dfs(int u){
	if(u==n){
		f[u]=0;
		return f[u];
	}
	int tmp=0;double tp=0.00;double mx=0.00;
	for(int i=head[u];i!=-1;i=e[i].nxt){
		int v=e[i].to;
		tmp++;
		double x=dfs(v);
		if(x>mx){
			mx=x;
			valm[u]=i;
		}
		tp+=x+1.00;
	}
	f[u]=tp/tmp;
	if(tmp==1) valm[u]=-1;
	return f[u];
}
double dfs1(int u,int lim){
	if(u==n){
		return 0;
	}
	int tmp=0;double tp=0.00;
	for(int i=head[u];i!=-1;i=e[i].nxt){
		if(i==lim)continue;
		int v=e[i].to;
		tmp++;
		double x=dfs1(v,lim);
		tp+=x+1.00;
	}
	return tp/tmp;
}
