        a[u].emplace_back(II(v, i));
    }

    ld res = 1000000000;
    FOR(i,1,m) {
        FOR(j,1,n) dp[j] = -1;
        dp[n] = 0;
        ld x = solve(1, i);
        if (cmp(x, 0) <= 0) continue;
        res = min(res, x);
    }

    if (cmp(res, 1000000000) == 0) {
        FOR(i,1,n) dp[i] = -1;
        dp[n] = 0;
        res = min(res, solve(1, 0));
    }

    cout << fixed << setprecision(9) << res;
    return 0;
}

