		int A, B; cin >> A >> B; A--; B--;
		adj[A][B] = true;
	}

	ld E[N], P[N]; F0R(i, N) E[i] = 0, P[i] = 0;

	E[N-1] = 0; P[0] = 1;
	int deg[N]; F0R(i, N) {
		deg[i] = 0;
		F0R(j, N) if (adj[i][j]) deg[i]++;
	}

