#define RFOR(i,a,b) for(int i=(a);i>(b);i--)
#define REP(i,n) FOR(i,0,n)
#define RREP(i,n) RFOR(i,n-1,-1)

int main(void) {
	cin.tie(0);
	ios::sync_with_stdio(false);
	int n, m, a, b;
	cin >> n >> m;
	vector<P> v;
	vector<int> cnt(n);
	vector<set<int>> gr(n);
	REP(i, m) {
		cin >> a >> b;
		a--;
		b--;
		v.push_back(P(a, b));
		gr[a].insert(b);
		cnt[a]++;
	}
	vector<double> es(n);
	RREP(i, n - 1) {
		for (auto j : gr[i]) es[i] += 1 + es[j];
		es[i] /= cnt[i];
	}
	vector<double> maxval(n);
	vector<int> cand(n);
	REP(i, n) cand[i] = -1;
	REP(i, m) {
		a = v[i].first;
		b = v[i].second;
		if (maxval[a] < es[b]) {
			maxval[a] = es[b];
			cand[a] = i;
		}
	}
	double res = es[0];
	vector<double> es2(n);
	for (int skip : cand) {
		if (skip == -1) continue;
		a = v[skip].first;
		b = v[skip].second;
		if (cnt[a] == 1) continue;
		gr[a].erase(b);
		cnt[a]--;
		FOR(i, a + 1, n) es2[i] = es[i];
		RFOR(i, a, -1) {
			es2[i] = 0;
			for (auto j : gr[i]) es2[i] += 1 + es2[j];
			es2[i] /= cnt[i];
		}
		res = min(res, es2[0]);
		gr[a].insert(b);
		cnt[a]++;
