vector<int> path[1000];
long double dp[1005];

int main(){
	int n,m;
	int i,j,k;
	int a,b,c;
	long double da,db,dc,s;
	cin>>n>>m;
	for(i=0;i<m;i++){
		cin>>a>>b;
		a--,b--;
		path[a].push_back(b);
	}
	s=INF;
	for(k=0;k<n;k++){
		for(i=0;i<n-1;i++)dp[i]=INF;
		for(i=n-1;i>=0;i--){
			da=0,a=0;
			for(auto to:path[i]){
				if(dp[to]==INF)continue;
				da+=dp[to];
				a++;
			}
			if(a==0)continue;
			dp[i]=da/a+1;
			if(a==1 || i!=k)continue;
			for(auto to:path[i]){
				if(dp[to]==INF)continue;
				dp[i]=min(dp[i],(da-dp[to])/(a-1)+1.0);
			}
		}
		s=min(s,dp[0]);
	}
	cout<<fixed<<setprecision(10)<<s<<endl;
}

