const int MX = 605;
int n, m, s, t, sz[MX];
vector<int> G[MX], rG[MX];
double p[MX], d[MX], ans;
int main(){
	scanf("%d%d", &n, &m);
	rep(i,m){
		scanf("%d%d", &s, &t);
		s--; t--;
		sz[s]++;
		G[s].push_back(t);
		rG[t].push_back(s);
	}
	for(int i = n-1; i >= 0; i--){
		if(i != n-1) p[i] += 1;
		for(int pr: rG[i]) p[pr] += p[i] / sz[pr];
	}
	for(int i = n-2; i >= 0; i--){
		double dd[MX] = {};
		dd[i] = 1;
		for(int j = i; j >= 0; j--){
			for(int pr: rG[j]) dd[pr] += dd[j] / sz[pr];
		}
		d[i] = dd[0];
	}
	ans = p[0];
	rep(i,n) if(sz[i] > 1){
		for(int nx: G[i]){
			double np = ((p[i] - 1) * sz[i] - p[nx]) / (sz[i]-1) + 1;
			ans = min(ans, p[0] + (np - p[i]) * d[i]);
		}
	}
	printf("%.9f\n", ans);
}

