int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  cout << fixed << setprecision(10);
  int n, m; cin >> n >> m;
  vector<vector<P>> g(n);
  vector<int> d(n);
  map<int, int> mp;
  for(int i=0;i<m;++i) {
    int s, t; cin >> s >> t;
    s--; t--;
    g[s].push_back({t, i});
    d[s]++;
    mp[i] = s;
  }
  double mi = INF;
  mp[m] = -1;
  for(int i=0;i<=m;++i) {
    if(i != m && d[mp[i]] == 1) continue;
    vector<double> dp(n);
    dp[n-1] = 0;
    for(int j=n-2;j>=0;--j) {
      int deg = d[j];
      if(j == mp[i]) deg--;
      for(auto &e: g[j]) {
        int next = e.first, num = e.second;
        if(num == i) continue;
        dp[j] += (dp[next] + 1) / deg;
      }
    }
    mi = min(mi, dp[0]);
  }
  cout << mi << endl;
}

