i64 n, m;
vector<vector<int>> g, ig;
double sp[601][601], sep[601][601];

int main() {
  cin >> n >> m;
  g.resize(n + 1);
  ig.resize(n + 1);
  for (int i = 0; i < m; ++i) {
    int s, t;
    cin >> s >> t;
    g[s].push_back(t);
    ig[t].push_back(s);
  }

  for (int a = 1; a <= n; ++a) {
    sp[a][a] = 1.0;
    for (int u = 1; u <= n; ++u) {
      double deg = g[u].size();
      for (int v : g[u]) {
        sp[a][v] += sp[a][u] / deg;
      }
    }
    for (int u = 1; u <= n; ++u) {
      double deg = g[u].size();
      for (int v : g[u]) {
        sep[a][v] += (sep[a][u] + sp[a][u]) / deg;
      }
    }
  }

  double ans = sep[1][n];
  for (int u = 1; u <= n; ++u) {
    if (g[u].size() <= 1) continue;
    double deg = g[u].size();
    for (int v : g[u]) {
      double f = -sp[1][u] / deg * sep[v][n];
      for (int w : g[u]) {
        if (w != v) {
          f += sp[1][u] * (1.0 / (deg - 1) - 1.0 / deg) * sep[w][n];
        }
      }
      ans = min(ans, sep[1][n] + f);
    }
  }
  printf("%.10f\n", ans);
  return 0;
}

