class Solve
{
  int N, M;
  vector<ld> E, P;
  vector<vector<int>> V;

public:
  Solve(int N, int M) : N{N}, M{M}, E(N, -1), P(N, 0), V(N)
  {
    for (auto i{0}; i < M; ++i)
    {
      int s, t;
      cin >> s >> t;
      --s;
      --t;
      V[s].push_back(t);
    }
    E[N - 1] = 0;
    calc_E(0);
    P[0] = 1;
    for (auto i{0}; i < N; ++i)
    {
      spread_P(i);
    }
  }

  void flush()
  {
    ld ans{E[0]};
    for (auto i{0}; i < N - 1; ++i)
    {
      ch_min(ans, del_path(i));
    }
    cout << fixed << setprecision(10) << ans << endl;
  }

private:
  ld calc_E(int v)
  {
    if (E[v] >= 0)
    {
      return E[v];
    }
    ld ans{0};
    for (auto e : V[v])
    {
      ans += calc_E(e) + 1;
    }
    ans /= V[v].size();
    return E[v] = ans;
  }

  void spread_P(int v)
  {
    ld p{P[v] / V[v].size()};
    for (auto e : V[v])
    {
      P[e] += p;
    }
  }

  ld difference(int v)
  {
    if (V[v].size() == size_t{1})
    {
      return 0;
    }
    ld sum{0}, maxi{0};
    for (auto e : V[v])
    {
      sum += E[e] + 1;
      ch_max(maxi, E[e] + 1);
    }
    return (sum - maxi) / (V[v].size() - 1) - E[v];
  }

  ld del_path(int v)
  {
    return E[0] + difference(v) * P[v];
  }
};

int main()
{
  int N, M;
  cin >> N >> M;
  Solve solve(N, M);
  solve.flush();
}

