        edge[s-1].push_back(t-1);
    }

    double opt = N+M;
    for (int i=0; i<N-1; ++i) { // 削除する部屋でループ
        std::vector<double> v(N);
        v[N-1] = 0.0;
        for (int j=N-2; j>=0; --j) { // DP計算
