                sum += v[t];
                maxv = std::max(maxv, v[t]);
            }
            int nLink = edge[j].size();
            if (nLink > 1 && i == j) {
                sum -= maxv;
                nLink -= 1;
            }
            v[j] = (sum + nLink) / nLink;
        }
        opt = std::min(opt, v[0]);
    }

    std::cout << opt << std::endl;
    return 0;
}

