int main() {
    int n, m;
    cin >> n >> m;
    vl s(m), t(m);
    vvl edges(n);
    for (int i = 0; i < m; ++i) {
        cin >> s[i] >> t[i];
        s[i]--, t[i]--;
        edges[s[i]].push_back(t[i]);
    }
    s.push_back(-1);
    t.push_back(-1);
    double ret = 100000000;
    for (int i = 0; i < m + 1; ++i) {
        // s[i] -> t[i] is blocked
        vector<vector<pair<double, int>>> dist(n);
        deque<int> bfs;
        bfs.push_back(0);
        dist[0].emplace_back(1.0, 0);
        while (!bfs.empty()) {
            auto c = bfs.front();
            bfs.pop_front();
            double nsize = edges[c].size();
            if (c == s[i])
                nsize--;

            for (auto &ne : edges[c]) {
                if (s[i] == c && ne == t[i])
                    continue;
                bfs.emplace_back(ne);
                for (auto &pro : dist[c]) {
                    dist[ne].emplace_back(pro.first / nsize, pro.second + 1);
                }
            }
        }
        if (dist[n - 1].empty())
            continue;
        double temp = 0;
        double prob = 0.0;
        for (auto &pro : dist[n - 1]) {
            temp += pro.first * pro.second;
            prob += pro.first;
        }
        if (abs(prob - 1.0) > 1.0e-5)
            continue;
        chmin(ret, temp);
    }
    cout << fixed << setprecision(10) << ret << "\n";
    return 0;
}

