//------------------------------- Solver ------------------------------------//

void solve()
{
    int n, m;
    cin >> n >> m;
    yukari<pair<int, int>> g(n);
    for (int i = 0; i < m; i++)
    {
        int s, t;
        cin >> s >> t;
        s--, t--;
        g[s].push_back(make_pair(t, 1));
    }
    akari<double> dp(n, -1);
    akari<int> heavy(n);
    auto calc = [&](auto &&calc, akari<double> &dp, int s) -> double {
        if (dp[s] > -0.5)
        {
            return dp[s];
        }
        double res = 0, maxi = 0;
        int cnt = 0;
        for (auto np : g[s])
        {
            if (!np.second)
            {
                continue;
            }
            cnt++;
            double w = calc(calc, dp, np.first) + 1;
            if (maxi < w)
            {
                maxi = w;
                heavy[s] = np.first;
            }
            res += w;
        }
        if (cnt)
        {
            res /= cnt;
        }
        else if (s != n - 1)
        {
            res = -10;
        }
        return dp[s] = res;
    };
    double ans = calc(calc, dp, 0);
    for (int s = 0; s < n - 1; s++)
    {
        akari<double> dp2(n, -1);
        for (auto &p : g[s])
        {
            if (p.first == heavy[s])
            {
                p.second = 0;
                calc(calc, dp2, 0);
                if (dp2[0] > -0.5)
                {
                    ans = min(ans, dp2[0]);
                }
                p.second = 1;
                break;
            }
        }
    }
    cout << setprecision(15) << ans << endl;
}

int main()
{
    solve();
    return 0;
}

