void calcDP(int skip = n+1) {
    for (int i = 0; i < ord.size(); i++) {
        if (ord[i] == skip) continue;
        if (i == 0) dp[ord[i]] = 0;
        else {
            dp[ord[i]] = 1;
            int sz = adj[ord[i]].size();
            for (int j: adj[ord[i]]) {
                dp[ord[i]] += (ld)1/sz*dp[j];
            }
        }
        //cout << i << ": " << dp[ord[i]] << '\n';
    }
    ans = min(ans,dp[1]);
}

