#include <bits/stdc++.h>

using namespace std;

const int MAX_N = 660;

int head[MAX_N], current, n, m;
double dp[MAX_N];
bool vis[MAX_N];

struct edge
{
    int to, nxt;
    bool tag;
} edges[MAX_N * MAX_N << 1];

void addpath(int src, int dst)
{
    edges[current].to = dst, edges[current].nxt = head[src];
    head[src] = current++;
}

void dfs(int u)
{
    if (u == n || vis[u])
        return;
    int deg = 0;
    vis[u] = true;
    double sum = 0;
    for (int i = head[u]; i != -1; i = edges[i].nxt)
        if (edges[i].tag != true)
            dfs(edges[i].to), deg++, sum += dp[edges[i].to];
    dp[u] = sum / deg + 1;
}

int main()
{
    memset(head, -1, sizeof(head));
    scanf("%d%d", &n, &m);
    for (int i = 1, u, v; i <= m; i++)
        scanf("%d%d", &u, &v), addpath(u, v);
    double ans = 0x3fffffffffffffff;
    for (int i = 0; i <= current; i++)
    {
        if (current == i && ans != 0x3fffffffffffffff)
            continue;
        memset(dp, 0, sizeof(dp)), memset(vis, 0, sizeof(vis));
        edges[i].tag = true, dfs(1);
        if (dp[1] != 0)
            ans = min(ans, dp[1]);
        edges[i].tag = false;
    }
    printf("%.6lf", ans);
    return 0;
}

