        graph[a].pb({b, 1});
    }

    sort(all(paths));
    vector<ld> dp(N, 0.0);
    dp[N - 1] = 0;
    revrep(i, N - 1){
        ld sz = graph[i].size();
        for (auto& e: graph[i]){
            ll nxt = e.to;
            dp[i] += (dp[nxt] + 1) / sz;
        }
    }

    queue<pl> q;
    rep(i, N){
        if (graph[i].size() == 1) continue;
        pair<ld, ll> vmax = {0.0, -1};        
        for (auto& e: graph[i])
            if (vmax.e1 < dp[e.to]) vmax = {dp[e.to], e.to};
        q.push({i, vmax.e2});
    }

    ld ans = dp[0];
    while (!q.empty()){
        ll a, b; tie(a, b) = q.front(); q.pop();
        vector<ld> dp2 = dp;
        revrep(i, b){
            dp2[i] = 0;
            ld sz = graph[i].size() - (i == a);
            for (auto& e: graph[i]){
                ll nxt = e.to;
                if (i == a && e.to == b) continue;
                dp2[i] += (dp2[nxt] + 1) / sz;                
            }
        }
        chmin(ans, dp2[0]);
    }

    prl_nd(ans, 12);

    // ### DEBUG PART ###
    auto naive_solver = [&](){
    };
    #ifdef _LOCAL
        naive_solver();
    #endif
}

