constexpr int DEBUG = 0;

struct Edge {
  const int from, to;
  Edge(int from, int to) : from(from), to(to) {}
};

vector<vector<Edge>> ReadDirectedGraph(
    int n, int m, bool is_one_indexed=false) {
  vector<vector<Edge>> graph(n);
  for (int i = 0; i < m; i++) {
    int v1, v2;
    cin >> v1 >> v2;
    if (is_one_indexed) {
      v1--;
      v2--;
    }
    graph[v1].push_back(Edge({v1, v2}));
  }
  return graph;
}

vector<double> Solve(const vector<vector<Edge>>& graph) {
  int n = graph.size();
  vector<double> dp(n, DBL_MAX);
  dp[n - 1] = 0.0;
  for (int i = n - 2; i >= 0; i--) {
    double sum = 0.0;
    for (const auto& e : graph[i]) {
      sum += dp[e.to];
    }
    dp[i] = sum / graph[i].size() + 1.0;
  }
  return dp;
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  cout << fixed << setprecision(10);

  int n, m;
  cin >> n >> m;

  auto graph = ReadDirectedGraph(n, m, true);
  auto dp = Solve(graph);

  double ans = dp[0];
  for (int i = n - 2; i >= 0; i--) {
    if (graph[i].size() <= 1) continue;

    int max_to = -1;
    double max = 0.0;
    for (const auto& e : graph[i]) {
      if (dp[e.to] > max) {
        max_to = e.to;
        max = dp[e.to];
      }
    }

    vector<vector<Edge>> new_graph(n);
    for (int v = 0; v < n; v++) {
      for (const auto& e : graph[v]) {
        if (v != i || e.to != max_to) {
          new_graph[v].push_back(e);
        }
      }
    }
    auto new_dp = Solve(new_graph);
    if (new_dp[0] < ans) {
      ans = new_dp[0];
