void f(int block){
    dp[n] = 0;
    RREP(i,1,n){
        long double sum = 0.0;
        long double maxi = 0.0;
        int num = g[i].size();
        for(auto to : g[i]){
            sum += dp[to];
            maxi = max(maxi, dp[to]);
        }
        if(i == block && num >= 2){
            num--;
            sum -= maxi;
        }
        dp[i] = sum / num + 1;
    }
}

