static const ll INF = 1e15;

const ll mod = 1000000007;
ll n, m;
vector<vector<int>> g;
vector<P> dp;
vector<bool> visit;

P dfs(int current, int block) {
	if (visit[current]) {
		return dp[current];
	}
	vector<P> path;
	const int c = g[current].size();
	for (int next : g[current]) {
		path.push_back(dfs(next, block));
	}
	double zero = 0;
	double one = 0;
	for (auto p : path) {
		zero += p.first;
		one += p.second;
	}
	double all = zero;
	zero /= c;
	zero += 1;
	one /= c;
	one += 1;
	double cut = INF;
	if (c > 1 && current == block) {
		for (auto p : path) {
			cut = min(cut, all - (p.first));
		}
		cut /= (c - 1);
		cut += 1;
	}
	dp[current] = { zero, min(cut, one) };
	visit[current] = true;
	return dp[current];
}

int main() {
	cin >> n >> m;
	g.resize(n);
	rep(i, m) {
		int s, t;
		cin >> s >> t;
		s--; t--;
		g[s].push_back(t);
	}
	double ans = INF;
	for (int block = 0; block < n - 1; block++) {
		dp.assign(n, P(INF, INF));
		visit.assign(n, false);
		dp[n - 1] = { 0,0 };
		visit[n - 1] = true;
		for (int i = n - 2; i >= 0; i--) {
			dfs(i, block);
		}
		ans = min(ans, min(dp[0].first, dp[0].second));
	}
	cout << setprecision(10) << ans << endl;
	return 0;
}

