using Graph = vector<vector<int>>;

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  int n, m;
  cin >> n >> m;
  vector<int> s(m), t(m);
  Graph g0(n);
  for (int i = 0; i < m; i++) {
    cin >> s[i] >> t[i];
    s[i]--;
    t[i]--;
    // s->t
    g0[s[i]].push_back(t[i]);
  }
  auto calc = [&](const Graph &g) {
    vector<ld> ret(n, inf);
    ret[n - 1] = 0;
    for (int i = n - 2; i >= 0; i--) {
      int sz = g[i].size();
      if (sz == 0) continue;
      ld sum = 0;
      for (auto nxt : g[i]) {
        sum += ret[nxt];
        if(ret[nxt]==inf) return inf;
      }
      ret[i] = 1 + sum / sz;
    }
    return ret[0];
  };
  ld ret = calc(g0);
  for (int i = 0; i < m; i++) {
    Graph g(n);
    for (int j = 0; j < m; j++) {
      if (i == j) continue;
      g[s[j]].push_back(t[j]);
    }
    ret = min(ret, calc(g));
  }
  cout << fixed << setprecision(10) << ret << endl;
}

