bool memo[N];

void dfs1(int u){
  if(memo[u]) return;
  memo[u] = true;
  can[u].insert(u);
  for(auto x : T[u]){
    dfs1(x);
    for(auto y : can[x]) can[u].insert(y);
  }
}

void dfs2(int u){
  if(memo[u]) return;
  memo[u] = true;
  for(auto x : T[u]) dfs2(x);
  for(auto x : T[u]){
    dp[u][0] += dp[x][0];
  }
  ld m = (ld)T[u].size();
  dp[u][0] = (dp[u][0] / m) + 1.0;
  for(auto y : can[u]){
    if(y == u){
      if(T[u].size() <= 1) dp[u][y] = inf;
      else{
        vector<ld> R;
        for(auto x : T[u]){
          R.push_back(dp[x][0]);
        }
        sort(R.begin(), R.end());
        R.pop_back();
        for(auto x : R) dp[u][y] += x;
        dp[u][y] = (dp[u][y] / (m - 1.0)) + 1.0;
      }
    }
    else{
      for(auto x : T[u]){
        if(can[x].count(y)) dp[u][y] += dp[x][y];
        else dp[u][y] += dp[x][0];
      }
      dp[u][y] = (dp[u][y] / m) + 1.0;
    }
  }
}

