using Graph = vector<vector<int>>;

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  int n, m;
  cin >> n >> m;
  vector<int> s(m), t(m);
  Graph g0(n);
  for (int i = 0; i < m; i++) {
    cin >> s[i] >> t[i];
    s[i]--;
    t[i]--;
    // s->t
    g0[s[i]].push_back(t[i]);
  }
  vector<ld> dist(n, inf);
  auto calc = [&](const Graph &g) {
    for (int i = 0; i < n; i++) dist[i] = inf;
    dist[n - 1] = 0;
    for (int i = n - 2; i >= 0; i--) {
      int sz = g[i].size();
      if (sz == 0) continue;
      ld sum = 0;
      for (auto nxt : g[i]) {
        sum += dist[nxt];
        if (dist[nxt] == inf) return inf;
      }
      dist[i] = 1 + sum / sz;
    }
    return dist[0];
  };
  ld ret = calc(g0);
  for (int i = n - 2; i >= 0; i--) {
    if (g0[i].size() == 1) continue;
    calc(g0);
    ld ma = 0, sum = 0;
    for (auto nxt : g0[i]) {
      sum += dist[nxt];
      ma = max(ma, dist[nxt]);
    }
    sum -= ma;
    dist[i] = 1 + sum / (g0[i].size() - 1);
    bool f = true;
    for (int j = i - 1; j >= 0; j--) {
      int sz = g0[j].size();
      assert(sz);
      ld stmp = 0;
      for (auto nxt : g0[j]) {
        stmp += dist[nxt];
        assert(dist[nxt] != inf);
      }
      dist[j] = 1 + stmp / sz;
    }
    if (!f) continue;
    ret = min(ret, dist[0]);
  }
  cout << fixed << setprecision(10) << ret << endl;
}

