ll pwr(ll a,ll n,ll m)
{
	ll p=1;
	while(n>0)
	{
		if(n%2==1)
			p=(p*a)%m;
		a=(a*a)%m;
		n=n/2;
	}
	return p;
}

queue<ll> q;
ll vis[M],deg[M];
ld pr[M],dp[M],dp2[M],out[M];
vector<ll> adj[M];

void dfs(ll u)
{
	vis[u] = 1;
	ld mn = 0;
	for(auto v:adj[u])
	{
		if(vis[v] == 0)
			dfs(v);
		dp[u] += dp[v]+1;
		mn = max(mn,dp[v]+1.0);
	}
	if(adj[u].empty())
		return;
	ll sz = adj[u].size();
	dp[u] /= (ld)(sz);
	dp2[u] = dp[u];
	if (sz > 1) {
		for (int v: adj[u]) {
			dp2[u] = min(dp2[u], (dp[u]*sz - dp[v] - 1) / (sz - 1));
		}
	}
	return;
}

