using namespace std;

const int N = 600 + 5;
int mp[N][N], n, m;
pair<int, int> node[N * N];
double ans = INT_MAX;
inline void calc (int id) {
	static double dp[N];
	int x = node[id].first, y = node[id].second;
	dp[n] = 0;
	per (i, n - 1, 1) {
		dp[i] = 0;
		rep (j, 1, mp[i][0]) {
			int v = mp[i][j];
			if (i == x && v == y) continue;
			if (dp[v] < 0) { dp[i] = -1; break; }
			dp[i] += dp[v];
		}
		if (dp[i] < 0) continue;
		if (mp[i][0] - (i == x) == 0) dp[i] = -1;
		else dp[i] = (dp[i] / (mp[i][0] * 1.0 - (i == x))) + 1;
	}
	if (dp[1] > 0) ans = min (ans, dp[1]);
}

