int N,M;
vector<vector<int>> G;
vector<pii> Edge;
void input(){
    fast_io();
    cin >> N >> M;
    G.resize(N);
    for (int i = 0; i < M; i++)
    {
        int s,t; cin >> s >> t;
        s--,t--;
        Edge.emplace_back(s,t);
    }

}

double dfs(int s, vector<vector<int>> g){
    if(s==N-1) return 0;
    if(g[s].empty()) return N+1;
    double ret = 1;
    for(auto u:g[s]){
        ret += dfs(u,g)/g[s].size();
    }
    return ret;
}

bool isok(vector<vector<int>> g){
    queue<int> q;
    q.push(0);
    vector<bool> seen(N,false);
    seen[0] = true;
    while (!q.empty())
    {
        int u = q.front();
        q.pop();
        for(int v:g[u]){
            if(seen[v]) continue;
            seen[v] = true;
            q.push(v);
        }
    }
    return seen[N-1];
}

int solve(){
    double ans = N+1;
    for (int i = 0; i <= M; i++)
    {
        vector<vector<int>> g(N);
        for (int j = 0; j < M; j++)
        {
            if(i==j) continue;
            g[Edge[j].first].push_back(Edge[j].second);
        }
        if(isok(g)) ans = min(ans,dfs(0,g));
    }
    cout << fixed << setprecision(10) << ans << endl;    
    return 0;
}   

int main()
{
    input();
    solve();
    return 0;
}

