double calc(int pos) {
    rep(i, 1, n) f[i] = 0;
    for (int x = n - 1; x >= 1; x--) {
        int num = nxt[x].size();
        if (pos == x && num == 1) { f[x] = inf; continue; }
        double t = 1.0 / (num - (pos == x)), mx = 0;
        for (int i = 0; i < num; i++) {
            int y = nxt[x][i];
            f[x] += (f[y] + 1) * t;
            // printf("%d %d %.2lf %.2lf\n", x, y, f[x], f[y]);
            mx = max(mx, (f[y] + 1) * t);
        }
        if (pos == x) f[x] -= mx;
    }
    // rep(i, 1, n) printf("%.2lf ", f[i]); puts("");
    return f[1];
}

