void process(int pos, double res[]){
    for(int i = pos; i; --i){
        double cnt = 0;
        for(auto x : g[i]) cnt += res[x]; // Bug 2 is here. Change dp[] to res[]
        int sz = g[i].size();
        res[i] = cnt / sz + 1;
    }
}

