int main()
{
    int n,m;scanf("%d%d",&n,&m);
    for (int i=0;i<m;++i)
    {
        int t1,t2;scanf("%d%d",&t1,&t2);
        e[t1].push_back(t2);
    }
    for (int i=0;i<m;++i) dis0[i]=dis1[i]=0;

    for (int i=n-1;i>0;--i){
        for (int j=0;j<e[i].size();++j){
            dis0[i]+=dis0[e[i][j]];
        }
        dis0[i]/=(1.0*e[i].size());dis0[i]+=1.0;
        dis1[i]=dis0[i];
    }
    double ans=dis0[1];
    for (int i=1;i<n;++i){
        double tmp_max=0;
        if (e[i].size()==1) continue;
        dis1[i]=0;
        for (int j=0;j<e[i].size();++j){
            if (dis1[e[i][j]]>tmp_max)
                tmp_max=dis1[e[i][j]];
            dis1[i]+=dis1[e[i][j]];
        }
        dis1[i]-=tmp_max;
        dis1[i]/=(e[i].size()-1.0);
