#define rep(i,a,b) for(int i=(a);i<=(b);++i)
#define per(i,a,b) for(int i=(a);i>=(b);--i)
using namespace std;

const int N = 600 + 5;
int mp[N][N], n, m;
double ans = INT_MAX;
pair<int, int> info[N * N];

inline void calc () {
	static double dp[N];
	rep (i, 1, n) dp[i] = INT_MAX;
	dp[n] = 0;
	per (i, n - 1, 1) {
		double cnt = 0;
		double tmp = 0;
		rep (j, i + 1, n) {
			if (mp[i][j]) {
				tmp += dp[j];
				cnt += 1;
			}
		}
		if (tmp >= INT_MAX - 0.000001) return ;
		if (fabs(cnt) < 1e-9) continue;
		dp[i] = tmp;
		dp[i] /= cnt;
		dp[i] += 1.0;
	}
	if (dp[1] != INT_MAX) ans = min (ans, dp[1]);
}

int main () {
	scanf ("%d%d", &n, &m);
	rep (i, 1, m) {
		int x, y;
		scanf ("%d%d", &x, &y);
		info[i] = {x, y};
		mp[x][y] = 1;
	}
	calc ();
	rep (i, 1, m) {
		int tmpx = info[i].first, tmpy = info[i].second;
		mp[tmpx][tmpy] = 0;
		calc ();
		mp[tmpx][tmpy] = 1;
	}
	printf ("%.7lf\n", ans);
	return 0;
}

