const int M = 600 * 599 / 2;

int n, m, s[M + 1], t[M + 1];
vector<int> g[601];
double p[600], e[600];

double f(int w) {
	if(SI(g[s[w]]) == 1) { return m + 1; }

	inc(i, n) { p[i] = e[i] = 0; }

	p[0] = 1;
	e[0] = 0;
	inc(i, n - 1) {
		double q = SI(g[i]) - (i == s[w] ? 1 : 0);
		RF(j, g[i]) {
			if(i == s[w] && j == t[w]) { continue; }
			p[j] += p[i] / q;
			e[j] += (e[i] + p[i]) / q;
		}
	}
	if(p[n - 1] > 0.999) { return e[n - 1]; } else { return m + 1; }
	// return e[n - 1];
}

