int n, m;
vector<int> g[605];
ld dp[605];
ld f(int idx) {
    dp[n - 1] = 0;
    repd(v, n - 1) {
        ld sum = 0.0L;
        ld ma = 0.0L;
        auto cnt = sz(g[v]);
        each(nv, g[v]) {
            sum += dp[nv];
            maxs(ma, dp[nv]);
        }
        if (v == idx && cnt > 1) {
            --cnt;
            sum -= ma;
        }
        dp[v] = sum / ld(cnt) + 1;
    }
    return dp[0];
}
