    p[0] = 1.0, e[0] = -1.0;
    for(i = 0; i < n - 1; ++i) for(j = 0; j < vec[i].size(); ++j) if(j != now || i != k) p[vec[i][j]] += p[i] / (i == k ? vec[i].size() - 1 : vec[i].size());
    for(i = 0; i < n - 1; ++i) {
      e[i] += 1.0;
