void preprocess(){
	dp[n] = 0;
	for(int i = n - 1; i >= 1; i--){
		for(int j = 0; j < Adj[i].size(); j++) dp[i] += dp[Adj[i][j]];
		dp[i] /= (long double)(Adj[i].size());
		dp[i] += 1.0;
		//cout << dp[i] << "\n";
	}
}

long double cal(int banx, int bany){
	dp1[n] = 0;
	for(int i = n - 1; i >= 1; i--){
		dp1[i] = 0;
		if(i == banx){
			bool minus = 0;
			for(int j = 0; j < Adj[i].size(); j++){
				if(Adj[i][j] == bany){
					minus = 1;
					continue;
				}
				dp1[i] += dp1[Adj[i][j]];
			}
			dp1[i] /= (long double)(Adj[i].size() - minus);
			dp1[i] += 1.0;
		}
		else{
			for(int j = 0; j < Adj[i].size(); j++) dp1[i] += dp1[Adj[i][j]];
			dp1[i] /= (long double)(Adj[i].size());
			dp1[i] += 1.0;
		}
		//if(banx == 1) cout << dp1[i] << "\n";
	}
	return dp1[1];
}

