		for(int j = 0; j < Adj[i].size(); j++){
			if(dp[Adj[i][j]] > mx){
				mx = dp[Adj[i][j]];
				ind = Adj[i][j];
			}
		}
		//cout << cal(i, ind) << "\n";
		answ = min(answ, cal(i, ind));
	}
	cout << fixed << setprecision(6) << answ;
}

