double dfs(long long cur) {
	if(cur == N - 1) {
		return 0;
	}

	if(memo[cur] > 0) {
		return memo[cur];
	}

	double sumi = 0;
	long long num = tree[cur].size();

	for(auto next: tree[cur]) {
		sumi += dfs(next);
	}

	memo[cur] = sumi/num + 1;

	return memo[cur];
}

long long ngfrom, ngto;

double memo2[605];

double dfs2(long long cur) {
	if(cur == N - 1) {
		return 0;
	}

	if(memo2[cur] > 0) {
		return memo2[cur];
	}

	double sumi = 0;
	long long num = tree[cur].size();

	for(auto next: tree[cur]) {
		if(cur == ngfrom && next == ngto) {
			num--;
			continue;
		}
		sumi += dfs2(next);
	}

	memo2[cur] = sumi/num + 1;

	return memo2[cur];
}

