double dp(int x){
	if(x == n) return 0.0;
	double &ret = memo[x];
	if(ret>=0.0) return ret;
	ret = 0;
	for(int i=0;i<adj[x].size();i++){
		int cur = adj[x][i];
		ret += dp(cur);
	}
	ret = ret/(double)adj[x].size();
	if(x == dis && adj[x].size() > 1){
		double lol2;
		double lala = 0.0;
		for(int i=0;i<adj[x].size();i++){
