			lala += dp(cur);
		}
		lol2 = lala;
		for(int i=0;i<adj[x].size();i++){
			int cur = adj[x][i];
			double now = lala - dp(cur);
			lol2 = min(lol2,now);
		}
		lol2/=(double)(adj[x].size()-1);
		ret = min(ret,lol2);
	}
	ret = ret+1.0;
	return ret;
}

