double recurse(int node, vector<vector<double>> &dp, vector<vector<int> > &g, int blocked){
	if(dp[node][blocked] + 0.001 < 1e10){
		return dp[node][blocked];
	}
	if (blocked == 1){
		double prob = 1/double(g[node].size());
		double ans = 0;
		for(auto it:g[node]){
			ans += prob*(1.0+recurse(it, dp, g, 1));
		}
		dp[node][blocked] = ans;
		return dp[node][blocked];
	}
	else{
		double prob = 1/double(g[node].size());
		double ans = 0;
		for(auto it:g[node]){
			ans += prob*(1.0+recurse(it, dp, g, 0));
		}
		dp[node][0] = ans;

		if (g[node].size() != 1){
			double max_e = -1;
			double max_node =-1;
			for(auto it:g[node]){
				double val = recurse(it, dp, g, 1);
				if (val > max_e){
					max_e = val;
					max_node = it;
				}
			}

			prob = 1/double(g[node].size() - 1);
			ans = 0;
			for(auto it:g[node]){
				if (it == max_node)
					continue;
				ans += prob*(1.0+recurse(it, dp, g, 1));
			}
			dp[node][0] = min(ans, dp[node][0]);
		}
		return dp[node][0];
	}
}

