    for(int v: G[cur]) {
        if(DD[v] < 0) dfs(v, DD);
        ret += DD[v];
        if(depth[v] == -1) depth[v] = depth[cur] + 1;
        else depth[v] = min(depth[v], depth[cur] + 1);
    }
    ret /= G[cur].size();
    DD[cur] = ret + 1;
}

