const int INF = numeric_limits<int>::max() - (int)1e8;
const ll INFLL = numeric_limits<ll>::max() - (ll)1e17;

int main() {
    int N, M;
    cin >> N >> M;
    vector<set<int>> G(N + 1), revG(N + 1);
    vector<int> count(N + 1, 0);
    for (int i = 0; i < M; i++) {
        int s, t;
        cin >> s >> t;
        G[s].insert(t);
        revG[t].insert(s);
        count[s]++;
    }
    vector<double> dp(N + 1, 0);
    vector<int> check(N + 1, 0);
    auto calc = [&]() {
        queue<int> explore;
        explore.push(N);
        while (!explore.empty()) {
            int now = explore.front();
            explore.pop();
            for (int next : revG[now]) {
                double power = 1 / (double) count[next];
                dp[next] += dp[now] * power;
                check[next]++;
                if (count[next] == check[next]) {
                    dp[next]++;
                    explore.push(next);
                }
            }
        }
    };
    calc();
    vector<int> maxIdx(N + 1, -1);
    for (int i = 1; i < N; i++) {
        set<pair<double, int>> temp;
        for (int next : G[i]) temp.emplace(dp[next], next);
        if (temp.size() > 1) maxIdx[i] = temp.rbegin()->second;
    }
    auto graphUpdate = [&](int now, bool isAdd) {
        if (isAdd) {
            revG[maxIdx[now]].insert(now);
            count[now]++;
        } else {
            revG[maxIdx[now]].erase(now);
            count[now]--;
        }
    };
    double ans = dp[1];
    for (int i = 1; i < N; i++) {
        if (maxIdx[i] == -1) continue;
        dp = vector<double>(N + 1, 0);
        check = vector<int>(N + 1, 0);
        graphUpdate(i, false);
        calc();
        if (dp[1] != 0) ans = min(ans, dp[1]);
        graphUpdate(i, true);
    }
    cout << fixed << setprecision(10) << ans << endl;
}

