int main() {
	int n, m; cin >> n >> m;
	vector<vector<int>> edg(n), eid(n);
	for (int i = 0; i < m; i++) {
		int u, v; cin >> u >> v;
		u--; v--;
		edg[u].push_back(v);
		eid[u].push_back(i);
	}
	double ans = 1e18;
	vector<double> dp(n);
	for (int i = -1; i < n; i++) {
		for (int j = 0; j < n; j++) dp[j] = 0.;
		for (int j = n - 2; j >= 0; j--) {
			int c = edg[j].size();
			double ma = 0.;
			for (int t = 0; t < c; t++) {
				dp[j] += dp[edg[j][t]];
				if (edg[j][t] != n - 1) {
					ma = max(ma, dp[edg[j][t]]);
				}
			}
			if (j == i && c > 1) {
				dp[j] -= ma;
				dp[j] /= (c - 1);
			}
			else {
				dp[j] /= c;
			}
			dp[j]++;
		}
		ans = min(ans, dp[0]);
	}
	printf("%.15f\n", ans);
	return 0;
}

