                mx_next = next;
                mx = dp[next];
            }
        }

        edge delete_edge = edge(i, mx_next);
        bool ok = true;
        fill(dp2, dp2 + N, 0);
        for (int j = N-2; j >= 0; j--) {
            double sum = 0;
            int cnt = 0;
            for (int next : table[j]) {
                if (edge(j, next) == delete_edge) continue;
                cnt++;
                sum += dp2[next];
            }
            if (cnt == 0) {
                ok = false;
                break;
            }

            sum /= cnt;
            dp2[j] = sum + 1;
        }

        if (!ok) continue;
        ret = min(ret, dp2[0]);
    }

