                for (auto &&u : out[v]) {
                    if(v == i and u == j) continue;
                    es.push_back(dp[u]+1);
                } // end u
                if(es.empty()) continue;
                dp[v] = 0;
                sort(ALL(es));
                for (int t = 0; t < es.size(); ++t) {
                    dp[v] += (es[t]);
                } // end t
                dp[v] /= es.size();
            } // end v

            up_min(ans, dp[0]);
        } // end j
    } // end i

    os << ans << endl;
}

