bool done[666][666],g[666][666];

long double solve(int v, int s){
	int i,c=0;
	long double m=-INF;
	if(done[v][s]){
		return memo[v][s];
	}
	done[v][s] = true;
	if(v==(n-1)){
		return memo[v][s] = 0.0;
	}
	memo[v][s] = 0.0;
	for(i=0; i<n; ++i){
		if(!g[v][i]){
			continue;
		}
		memo[v][s] += solve(i,s);
		++c;
	}
	if(v!=s || c<2){
		memo[v][s] /= c;
		memo[v][s] += 1.0;
		return memo[v][s];
	}
	for(i=0; i<n; ++i){
		if(!g[v][i]){
