#define FOR(i, n, m) for (ll(i) = (m); (i) < (n); ++(i))
#define REP(i, n) FOR(i, n, 0)
#define OF64 std::setprecision(10)

const ll MOD = 1000000007;
const ll INF = (ll)1e15;

struct Vertex
{
    vector<pll> node;
};
struct Node
{
    ll index;
    double E;
    ll cost;
};

Vertex V[605];

int main()
{
    ll N, M;
    cin >> N >> M;
    REP(i, M)
    {
        ll s, t;
        cin >> s >> t;
        s--;
        t--;
        V[s].node.push_back(pll(t, i));
    }

    double min = 100000.0;
    REP(m, M + 1)
    {
        // cout << m << endl;
        //! 通路iを禁止する
        queue<Node> q;
        q.push(Node{0LL, 1.0, 0LL});

        double e = 0;
        bool exist = true;
        ll limit = 200000;
        while (!q.empty())
        {
            auto t = q.front();
            q.pop();
            //cout << t.index << t.cost << endl;
            //cout << OF64 << t.E << endl;
            if (t.index == N - 1)
            {
                e += t.E * t.cost;
            }
            else
            {
                ll num = 0;
                REP(i, V[t.index].node.size())
                {
                    auto node = V[t.index].node[i];
                    if (m == node.second)
                        continue;
                    num++;
                }
                if (num == 0)
                {
                    exist = false;
                    break;
                }
                REP(i, V[t.index].node.size())
                {
                    auto node = V[t.index].node[i];
                    if (m == node.second)
                        continue;

                    ll cost = t.cost + 1;
                    double ex = t.E / (double)(num);
                    q.push(Node{node.first, ex, cost});
                }
            }
            limit--;
            if (limit < 0)
                break;
            if (!exist)
                break;
        }
        if (e == 0.0 || !exist)
            continue;
        //cout << OF64 << e << endl;
        min = std::min(min, e);
    }
    cout << OF64 << min << endl;
    return 0;
}

