#include "bits/stdc++.h"
using namespace std;

long long N, M;
double ANS = 100000000;
static pair<long long, long long> P[200000];
static vector<long long> VS[600];
double COUNT[600] = {};
bool visited[600] = {};

double DFS(long long S, long long T, long long NOW) {
	if (visited[NOW]) return COUNT[NOW];
	double SUM = 0, SIZE = 0;
	for (long long To : VS[NOW]) {
		if (NOW == S && T == To) continue;
		SUM += DFS(S, T, To) + 1;
		SIZE += 1;
	}
	COUNT[NOW] = SUM / SIZE;
	visited[NOW] = true;
	return COUNT[NOW];
}

int main() {
	cin >> N >> M;
	for (int i = 0; i < M; i++) {
		long long S, T;
		cin >> S >> T;
		S--, T--;
		VS[S].push_back(T);
		P[i] = { S, T };
	}
	COUNT[N - 1] = 0, visited[N - 1] = true;
	ANS = DFS(-1, -1, 0);
	for (int i = 0; i < M; i++) {
		long long S = P[i].first, T = P[i].second;
		if (VS[S].size() == 1) continue;
		for (int i = 0; i < N; i++) COUNT[i] = 0, visited[i] = false;
		COUNT[N - 1] = 0, visited[N - 1] = true;
		ANS = min(ANS, DFS(S, T, 0));
	}
	printf("%.12lf\n", ANS);
}

