        for (int i = s+1; i < N; i++)
        {
            for (int X = 0; X < N; X++)
            {
                if(dp_diff[i][X]==0) continue;
                for(int u:G[i]){
                    dp_diff[u][X+1] += dp_diff[i][X]/G[i].size();
                }
            }        
        }

        double ans_tmp = 0;
        DBG(dp_diff[N-1])

        for (int x = 1; x < N; x++)
        {
            ans_tmp += (dp[N-1][x]+dp_diff[N-1][x])*x;
        }
        if(abs(ans_tmp)<=eps) continue;
        DBG(ans_tmp)
        ans = min(ans,ans_tmp);
    }
    cout << fixed << setprecision(10) << ans << endl;
    return 0;
}

