vector<int> graph[610];
vector<double> ev[610];

double dfs(int v, int dist, double probability, const pair<int, int>& stop,
           vector<pair<int, int>>& remove_edges, bool save) {
  int count = 0;
  for (auto& u : graph[v]) {
    if (v == stop.first && u == stop.second) continue;
    count++;
  }
  if (count == 0) return probability * dist;

  double max_ev = 0.0;
  double ev_sum = 0.0;
  pair<int, int> remove_edge;
  for (auto& u : graph[v]) {
    if (v == stop.first && u == stop.second) continue;
    double ev = dfs(u, dist + 1, probability/count, stop, remove_edges, save);
    if (save && ev > max_ev) {
      remove_edge = {v, u};
      max_ev = ev;
    } 
    ev_sum += ev;
  }
  if (save && graph[v].size() > 1) remove_edges.push_back(remove_edge);
  return ev_sum;
}

int main() {
  cin.tie(nullptr);
  ios::sync_with_stdio(false);
  cout << setprecision(20);

  int n, m;
  cin >> n >> m;
  rep(i, m) {
    int s, t;
    cin >> s >> t;
    --s; --t;
    graph[s].push_back(t);
  }

  vector<pair<int, int>> remove_edges; 
  double ans = dfs(0, 0, 1.0, {-1, -1}, remove_edges, true);

  for (auto& edge : remove_edges) {
    double temp = dfs(0, 0, 1.0, edge, remove_edges, false);  
    ans = min(ans, (double)temp);
  }
  cout << ans << endl;
  return 0;
}

#include <cstdio>
#include <vector>
#include <cstring>
#include <algorithm>
using namespace std;
int n,m;
vector<int> al[605];
vector<int> f[605];
double _exp[605];
int num[605];
double exp_i[605];
double test(int i){
    memset(exp_i,0,sizeof(exp_i));
    memset(_exp,0,sizeof(_exp));
    memset(num,0,sizeof(num));

    num[n]=1;

    for (int x=n;x>0;x--){
        _exp[x]=exp_i[x]/num[x];
        for (vector<int>::iterator it=al[x].begin();it!=al[x].end();it++){
            if (*it==i && x==f[i][0]) continue;
            exp_i[*it]+=_exp[x]+1;
            num[*it]++;
        }
    }

    return _exp[1];
}

int main(){
    scanf("%d%d",&n,&m);
    int a,b;
    for (int x=0;x<m;x++){
        scanf("%d%d",&a,&b);
        al[b].push_back(a);
        f[a].push_back(b);
    }
    num[n]=1;

    for (int x=n;x>0;x--){
        _exp[x]=exp_i[x]/num[x];
        for (vector<int>::iterator it=al[x].begin();it!=al[x].end();it++){
            exp_i[*it]+=_exp[x]+1;
            num[*it]++;
        }
    }

    for (int x=1;x<=n;x++){
        sort(f[x].begin(),f[x].end(),[](int i,int j){
            return _exp[i]>_exp[j];
        });
    }

    double ans=_exp[1];
    for (int x=1;x<n;x++){
        ans=min(ans,test(x));
    }

    printf("%.8f\n",ans);
}

