double simulate(const int N, const vector<vector<int>> &G, const int T) {
  vector<double> P(N, 0);
  for (int i = N - 2; i >= 0; i--) {
    double sum = 0.0;
    double mx = 0.0;
    int d = G[i].size();
    for (int j : G[i]) {
      sum += P[j];
      mx = max(mx, P[j]);
    }
    if (i == T) {
      if (d > 1) {
        P[i] = (sum - mx) / (d - 1) + 1;
      } else {
        P[i] = sum + 1;
      }
    } else {
      P[i] = sum / d + 1;
    }
  }
  return P[0];
}
