			for (int j = 0; j < adj[i].size(); j++)
				if (j != remove) dp[i] += (1 + dp[adj[i][j]]) / (adj[i].size() - 1);
			for (int j = i - 1; j > 0; j--) {
				dp[j] = 0;
				for (int k = 0; k < adj[j].size(); k++)
					dp[j] += (1 + dp[adj[j][k]]) / adj[j].size();
			}
			best = min(best, dp[1]);

			dp[i] = 0;
			for (int j = 0; j < adj[i].size(); j++)
				dp[i] += (1 + dp[adj[i][j]]) / adj[i].size();
		}
	}
