double dfs(int v, int dist, double probability, const pair<int, int>& stop) {
  int count = 0;
  for (auto& u : graph[v]) {
    if (v == stop.first && u == stop.second) continue;
    count++;
  }
  if (count == 0) return probability * dist;
  double ev = 0.0;
  for (auto& u : graph[v]) {
    if (v == stop.first && u == stop.second) continue;
    ev += dfs(u, dist + 1, probability/count, stop);
  }
  return ev;
}

