using namespace std;

char buf[1000000], *p1 = buf, *p2 = buf;
inline char gc() {
  if (p1 == p2) p2 = (p1 = buf) + fread(buf, 1, 1000000, stdin);
  return p1 == p2 ? EOF : *(p1++);
}
template <class T> inline void read(T &n) {
  n = 0; RI ch = gc(), f;
  while ((ch < '0' || ch > '9') && ch != '-') ch = gc();
  f = (ch == '-' ? ch = gc(), -1 : 1);
  while (ch >= '0' && ch <= '9') n = n * 10 + (ch ^ 48), ch = gc();
  n *= f;
}

int const MAXN = 605;
struct Edge { int x, y; } G[MAXN * MAXN];
double f[MAXN], g[MAXN], ff[MAXN], gg[MAXN];
struct Edges { int to, next; } e[MAXN * MAXN];
int head[MAXN], tot, d[MAXN], dd[MAXN];
struct Node {
  int id; double sum;
  bool operator < (const Node &A) const {
    return sum < A.sum;
  }
};
priority_queue <Node> q;

inline void addedge(int from, int to) {
  e[++tot] = (Edges){to, head[from]};
  head[from] = tot;
}

int main() {

#ifdef LOCAL
  FILEIO("a");
#endif

  int n, m; read(n), read(m);
  for (RI i = 1; i <= m; ++i)
    read(G[i].x), read(G[i].y), ++dd[G[i].x];
  for (RI i = 1; i <= m; ++i)
    addedge(G[i].x, G[i].y), ++d[G[i].x];
  f[1] = 0, g[1] = 1;
  for (RI i = 1; i < n; ++i) {
    double t = 1.0 / d[i];
    for (RI j = head[i]; j; j = e[j].next) {
      f[e[j].to] += f[i] * t + g[i] * t;
      g[e[j].to] += g[i] * t;
    }
  }
  double ans = f[n];
  memset(head, 0, sizeof(head)), tot = 0;
  memset(d, 0, sizeof(d));
  for (RI i = 1; i <= m; ++i)
    addedge(G[i].y, G[i].x), ++d[G[i].y];
  ff[n] = 0; gg[n] = 1;
  for (RI i = n; i > 1; --i) {
    double t = 1.0 / d[i];
    for (RI j = head[i]; j; j = e[j].next) {
      ff[e[j].to] += ff[i] * t + gg[i] * t;
      gg[e[j].to] += gg[i] * t;
    }
  }
  for (RI i = 1; i <= m; ++i)
    q.push((Node){i, f[G[i].x] + ff[G[i].y]});
  for (RI i = 1; i <= min(1000, m); ++i) {
    int tmp = q.top().id; q.pop();
    if (dd[G[tmp].x] == 1) continue;
    memset(head, 0, sizeof(head)), tot = 0;
    memset(d, 0, sizeof(d));
    for (RI i = 1; i <= m; ++i)
      if (i != tmp)
        addedge(G[i].x, G[i].y), ++d[G[i].x];
    memset(f, 0, sizeof(f));
    memset(g, 0, sizeof(g));
    f[1] = 0, g[1] = 1;
    for (RI i = 1; i < n; ++i) {
      double t = 1.0 / d[i];
      for (RI j = head[i]; j; j = e[j].next) {
        f[e[j].to] += f[i] * t + g[i] * t;
        g[e[j].to] += g[i] * t;
      }
    }
    ans = min(ans, f[n]);
  }
  printf("%.10lf\n", ans);


  return 0;
}

