void update(vector<double>& E,int a,const vector<vector<int>>& adj){
  double temp=0;
  for(int i: adj.at(a)){
    temp+=E.at(i);
  }
  temp/=adj.at(a).size();
  temp+=1;
  E.at(a)=temp;
}

double calc(vector<double>& E,int a,int b,const vector<vector<int>>& adj){
  int n=E.size();
  vector<double> E2(n);
  vector<int> f(n,0);
  f.at(a)=1;
  for(int i=n-2;i>=a+1;i--){
    E2.at(i)=E.at(i);
  }
  double temp=0;
  for(int j: adj.at(a)){
    if(j==b)continue;
    temp+=E2.at(j);
  }
  temp/=adj.at(a).size()-1;
  temp+=1;
  E2.at(a)=temp;

  for(int i=a-1;i>=0;i--){
    int flag=0;
    for(int x:adj.at(i)){
      if(f.at(x)==0)
	continue;
      flag=1;break;
    }
    if(flag==0){
      E2.at(i)=E.at(i);
      continue;
    }
    f.at(i)=1;
    double temp=0;
    for(int j: adj.at(i)){
      temp+=E2.at(j);
    }
    temp/=adj.at(i).size();
    temp+=1;
    E2.at(i)=temp;

  }
  return E2.at(0);
}

