namespace adaptor = boost::adaptors;
using index_t = std::size_t;

std::vector<double> base_expected(int N, std::vector<std::vector<int>>const& edge)
{
	std::vector<double> ret(N);
	for (auto i : boost::irange(0, N - 1) | adaptor::reversed)
	{
		for (auto j : edge[i])
		{
			ret[i] += 1 + ret[j];
		}
		ret[i] /= edge[i].size();
	}
	return ret;
}

void Main()
{
	int N, M;
	std::cin >> N >> M;
	std::vector<std::vector<int>>edge(N);
	for (auto i : boost::irange(0, M))
	{
		int s, t;
		std::cin >> s >> t;
		--s; --t;
		edge[s].emplace_back(t);
	}
	auto expected = base_expected(N, edge);
	auto min = expected[0];
	for (auto i : boost::irange(0, N - 1))
	{

		if (edge[i].size() == 1)
		{
			continue;
		}
		for (auto j : boost::irange(0, N - 1) | adaptor::reversed)
		{
			expected[j] = 0;
			auto max = 0.0;
			for (auto n : edge[j])
			{
				expected[j] += expected[n] + 1;
				max = std::max(max, expected[n] + 1);
			}
			expected[j] -= (i == j) * max;
			expected[j] /= (edge[j].size() - (i == j));
		}
		min = std::min(min, expected[0]);
	}
	std::cout << min << std::endl;
}

