int main() {
    int N, M;
    cin >> N >> M;
    vector<set<int>> G(N + 1), revG(N + 1);
    vector<int> count(N + 1, 0);
    for (int i = 0; i < M; i++) {
        int s, t;
        cin >> s >> t;
        G[s].insert(t);
        revG[t].insert(s);
        count[s]++;
    }
    auto calc = [&](vector<set<int>> graph) {
        vector<double> dp(N + 1, 0);
        vector<int> check(N + 1, 0);
        queue<int> explore;
        explore.push(N);
        while (!explore.empty()) {
            int now = explore.front();
            explore.pop();
            for (int next : graph[now]) {
                double power = 1 / (double) count[next];
                dp[next] += dp[now] * power;
                check[next]++;
                if (count[next] == check[next]) {
                    dp[next]++;
                    explore.push(next);
                }
            }
        }
        return dp;
    };
    auto base = calc(revG);
    vector<int> maxIdx(N + 1, -1);
    for (int i = 1; i < N; i++) {
        set<pair<double, int>> temp;
        for (int next : G[i]) temp.emplace(base[next], next);
        maxIdx[i] = temp.rbegin()->second;
    }
    auto graphUpdate = [&](int now, bool isAdd) {
        if (isAdd) {
            revG[maxIdx[now]].insert(now);
            count[now]++;
        } else {
            revG[maxIdx[now]].erase(now);
            count[now]--;
        }
    };
    double ans = base[1];
    for (int i = 1; i < N; i++) {
        graphUpdate(i, false);
        auto temp = calc(revG);
        if (temp[1] != 0) ans = min(ans, temp[1]);
        graphUpdate(i, true);
    }
    cout << fixed << setprecision(10) << ans << endl;
}

