vector<ll> top_sort(const vector<vector<ll>> &edges) {
    ll N = edges.size();
	vector<ll> ret;
	vector<bool> road(N);
	vector<bool> used(N);
	function<bool(ll)> dfs = [&](ll now) {
		used[now] = true;
		road[now] = true;
		for(ll nxt : edges[now]) {
			if(road[nxt]) return false;
			if(used[nxt]) continue;
			if(!dfs(nxt)) return false;
		}
		ret.push_back(now);
		road[now] = false;
		return true;
	};
	for(ll i = 0; i < edges.size(); i++) {
		if(used[i]) continue;
		if(!dfs(i)) return vector<ll>(0);
	}
	reverse(ret.begin(), ret.end());
	return ret;
}

const double inf = 5e15;

V<double> memo;

double dfs(ll cur, const VV<ll> &edges, V<double> &memo, ll from, ll to) {
    if(memo[cur] != -inf) return memo[cur];
    memo[cur] = 0;
    ll cnt = edges[cur].size();
    for(ll nxt : edges[cur]) {
        if(cur == from && nxt == to) {
            cnt--;
            continue;
        }
        memo[cur] += 1 + dfs(nxt, edges, memo, from, to);
    }
    memo[cur] /= cnt;
    return memo[cur];
}

int main() {
    ll N, M;
    cin >> N >> M;
    VV<ll> edges(N), redges(N);
    for(ll i = 0; i < M; i++) {
        ll a, b;
        cin >> a >> b;
        a--; b--;
        edges[a].push_back(b);
        redges[b].push_back(a);
    }

    memo.resize(N, -inf);
    memo.back() = 0;
    dfs(0, edges, memo, -1, -1);

    double ans = memo[0];
    for(ll from = 0; from < N - 1; from++) {
        if(edges[from].size() <= 1) continue;
        double max_idx = 0;
        for(ll i = 1; i < edges[from].size(); i++) if(memo[max_idx] < memo[from]) max_idx = i;
        V<double> dp(N, -inf);
        dp.back() = 0;
        chmin(ans, dfs(0, edges, dp, from, edges[from][max_idx]));
    }

    cout << ans << endl;
    return 0;
}

