// Karn's algorithm
void Topological_sort(Vvec<int> &to, std::vector<int> &ans)
{
    const int V = to.size();
    // std::vector<int> ans; // 結果
    std::stack<int> st; // 入次数0の頂点
    ans.clear();

    // 入次数のカウント
    std::vector<int> in_deg(V, 0);
    for(auto& u_to: to){
        for(int& v: u_to) in_deg[v]++;
    }

    // 入次数0の頂点追加
    for(int i=0; i<V; i++){
        if(in_deg[i] == 0) st.push(i);
    }

    // 更新
    while(!st.empty()){
        int u = st.top(); st.pop();
        ans.push_back(u);
        for(int &v: to[u]){
            in_deg[v]--;
            if(in_deg[v] == 0) st.push(v);
        }
    }
}

