    // vector<int> ans;
    // Topological_sort(graph, ans);

    Vvec<double> dp(N, vector<double>(2, 0.0));
    for(int i=N-2; i>=0; i--){
        double m1=0.0, m2=0.0;
        for(int& to: graph[i]){
            dp[i][0] += dp[to][0];
            m1 = max(dp[to][0], m1);
            m2 = max(dp[to][0] - dp[to][1], m2);
        }
        dp[i][1] = (dp[i][0] - m2) / graph[i].size();
        if(graph[i].size() > 1)
            dp[i][1] = min((dp[i][0] - m1) / (graph[i].size()-1), dp[i][1]);
        dp[i][0] /= graph[i].size();
        dp[i][0]++;
        dp[i][1]++;
    }

    printf("%.8f\n", dp[0][1]);
}

