signed main() {
    LCIN(N, M);
    G.resize(N);
    REP(i, M) {
        LCIN(s, t);
        s--, t--;
        G[s].emplace_back(t);
    }
    dp[N - 1] = 0;
    REPR(i, N - 2) {
        FOREACH(to, G[i]) { dp[i] += 1 + dp[to]; }
        dp[i] /= G[i].size();
    }
    double ans = dp[0];
    REPR(i, N - 2) {
        if(G[i].size() < 2) {
            dp2[i] = dp[i];
            continue;
        }
        VD tmp;
        FOREACH(to, G[i]) { tmp.emplace_back(dp[to]); }
        sort(All(tmp));
        tmp.pop_back();
        FOREACH(to, tmp) { dp2[i] += to + 1; }
        dp2[i] /= tmp.size();
        REPR(j, i - 1) {
            dp2[j] = 0;
            FOREACH(to, G[j]) { dp2[j] += dp2[to] + 1; }
            dp2[j] /= G[j].size();
        }
        ans = min(ans, dp2[0]);
        dp2[i] = dp[i];
    }
    cout << ans << "\n";
}

