		gr[a].insert(b);
		cnt[a]++;
	}
	vector<double> es(n);
	es[n - 1] = 0;
	RREP(i, n - 1) {
		double e = 0;
		for (auto j : gr[i]) e += 1 + es[j];
		es[i] = e / (double)cnt[i];
	}
	vector<double> maxval(n);
	vector<int> cand(n);
	REP(i, n) {
