    rep3(i, N-1, 0){
        double n = edge[i].size();
        double sum = 0;
        rep(j, n){
            sum += E[0][edge[i][j]];
        }
        E[0][i] = sum/n + 1;
    }
    rep2(i, 1, N){
        rep3(j, N, i){
            E[i][j] = E[0][j];
