            rep(k, n){
                sum += E[i][edge[i][k]];
                maxi = max(maxi, E[i][edge[i][k]]);
            }
            E[i][i] = (sum-maxi)/(n-1) + 1; 
        }
        rep3(j, i-1, 0){
            double n = edge[j].size();
            double sum = 0;
            rep(k, n){
                sum += E[i][edge[j][k]];
            }
            E[i][j] = sum/n + 1;
        }
    }
