signed main() {
    int N, M;
    cin >> N >> M;
    vector<P> edges;
    for (int i = 0; i < M; i++) {
        int s, t;
        cin >> s >> t;
        s--; t--;
        table[s].push_back(t);
        edges.push_back(P(s, t));
    }

    dp[N-1] = 0;
    for (int i = N-2; i >= 0; i--) {
        double sum = 0;
        int num = 0;
        for (int next : table[i]) {
            sum += dp[next];
            ++num;
        }
        sum /= num;
        dp[i] = sum + 1;
    }

    pb[0] = 1;
    for (int i = 0; i < N; i++) {
        int sz =table[i].size();
        if (sz == 0) continue;
        double cof = 1.0 / sz;

        for (int next : table[i]) {
            pb[next] += pb[i] * cof;
        }
    }

    double ret = DBL_MAX;
    for (P edge : edges) {
        int i = edge.first;
        int j = edge.second;
        int n = table[i].size();
        if (n == 1) continue;
        double val = dp[0];
        val -= pb[i] * dp[i];
        val += pb[i] * ((n * dp[i] - n - dp[j]) / (n-1) +1);
        ret = min(ret, val);
    }

    cout << setprecision(10) << fixed << ret << endl;
    return 0;
