double solve(int n, vi adj[], ii edge)
{
    int i, j;
    double e[n];
    F(i, 0, n)
        e[i] = 1e9;
    e[n - 1] = 0;
    for(int i = n - 2; i >= 0; i--)
    {
        int x = (edge.first == i) ? (((int)adj[i].size()) - 1) : adj[i].size();
        if(x)
            e[i] = 0;
        else
            continue;
        for(auto j: adj[i])
        {
            if(i == edge.first && j == edge.second)
                continue;
            e[i] += ((double)(e[j] + 1)) / x;
        }
    }
    if(e[0] == INF)
        return LONG_LONG_MAX;
    return e[0];
}


