vector<int> et[600];
vector<int> rev_et[600];
int inV[600];	//inV[v] = 頂点vに入る辺の数
bool vis1[600];	//vis1[v] = 0-->vに行けるか
bool vis2[600];	//vis2[v] = v-->N-1に行けるか
double E1[600];	//E1[v] = 0-->vの期待値,   O(N + M)
double E2[600];	//E2[v] = v-->N-1の期待値, O(N + M)
double P[600];	//P[v] = 0-->vに至る確率,  O(N + M)
double E[600];	//E[v] = 0-->vを通らない-->N-1の期待値, O(N(N + M))

signed main() {
	int i, j, k;

	cin >> n >> m;
	rep(i, m) {
		cin >> s[i] >> t[i];
		s[i]--; t[i]--;
		et[s[i]].push_back(t[i]);
		rev_et[t[i]].push_back(s[i]);
		inV[t[i]]++;
	}

	vis1[0] = true;
	rep(i, n) {
		if (!vis1[i]) continue;
		rep(j, et[i].size()) {
			vis1[et[i][j]] = true;
		}
	}

	vis2[n - 1] = true;
	for (i = n - 1; i >= 0; i--) {
		rep(j, et[i].size()) {
			if (vis2[et[i][j]] == true) break;
		}
		if (j < et[i].size()) { vis2[i] = true; }
	}

	E1[0] = 0;
	for (i = 1; i < n; i++) {
		if (!vis1[i]) continue;
		rep(j, rev_et[i].size()) {
			int pv = rev_et[i][j];
			E1[i] += E1[pv];
		}
		E1[i] /= rev_et[i].size();
		E1[i] += 1;
	}

	E2[n - 1] = 0;
	for (i = n - 2; i >= 0; i--) {
		if (!vis2[i]) continue;
		E2[i] = 0;
		rep(j, et[i].size()) {
			int nv = et[i][j];
			E2[i] += E2[nv];
		}
		E2[i] /= et[i].size();
		E2[i] += 1;
	}

	P[0] = 1;
	rep(i, n) {
		rep(j, et[i].size()) {
			int nv = et[i][j];
			P[nv] += P[i] / (double)et[i].size();
		}
	}

	double E3[600];
	double INF = 1e+12;
	rep(i, n) {	//頂点iを通らず、0-->N-1と行く
		E3[n - 1] = 0;
		for (j = n - 2; j >= 0; j--) {
			if (j == i) { E3[j] = INF; continue; }
			E3[j] = 0;

			int cnt = 0;
			rep(k, et[j].size()) {
				int nv = et[j][k];
				if (nv == i) continue;
				E3[j] += E3[nv];
				if (E3[j] >= INF) {  break; }
				cnt++;
			}
			if (E3[j] >= INF || cnt == 0) { E3[j] = INF; continue; }
			E3[j] /= cnt;
			E3[j] += 1;
		}
		E[i] = E3[0];
		//cout << "E[" << i << "] = " << E[i] << endl;
	}
	E[n - 1] = INF;
	E[0] = INF;

	//あとは各辺についてやる
	double ans = E2[0];
	rep(i, m) {
		if (vis1[s[i]] == false) { continue; }
		if (et[s[i]].size() == 1) { continue; }

		/*double ssum = (E2[s[i]] - 1) * et[s[i]].size();
		ssum -= E2[t[i]];
		double e = ssum / (double)(et[s[i]].size() - 1) + 1;
		if (e >= INF) { continue; }*/

		double ssum = 0;
		rep(j, et[s[i]].size()) {
			int nv = et[s[i]][j];
			if (nv == t[i]) continue;
			ssum += E2[nv];
		}
		double e = ssum / (double)(et[s[i]].size() - 1) + 1;

		double score = P[s[i]] * (E1[s[i]] + e) + (1 - P[s[i]]) * E[s[i]];
		ans = min(ans, score);
	}
	printf("%.14f\n", ans);
	return 0;
}

