double dfs(int u)
{
	if(u==n) return 0.0;
	if(dp[u]>-0.5) return dp[u];
	int cnt=0;
	double &ans=dp[u];
	ans=0.0;
	for(int v:g[u])
	{
		if(u==st&&v==ed) continue;
		cnt++;
		ans+=dfs(v);
	}
	if(cnt)
	{
		ans/=cnt;
		ans+=1.0;
	}
	return ans;
}
