int can() {
    ok[N] = 1;
    fore(u,1,N) ok[u] = 0;

    for(int u = N-1; u >= 1; u--) {
        fore(v,u+1,N) {
            if(isconnect(u,v)) {
                ok[u] |= ok[v];
            }
        }
    }

