	int n, m; scanf("%d%d", &n, &m);
	for(int i=1;i<=m;i++) {
		int a, b; scanf("%d%d", &a, &b);
		A[a][b] = true, d[a]++;
	}
	for(int i=n;i>=1;i--) {
		f[i] = 0;
		for(int j=i+1;j<=n;j++)
			if( A[i][j] )
				f[i] += (f[j] + 1) / d[i];
	}
	double ans = f[1];
	for(int i=n;i>=1;i--) {
		if( d[i] > 1 ) {
			int mx = -1;
			for(int j=i+1;j<=n;j++)
				if( A[i][j] ) {
					if( mx == -1 || f[j] > f[mx] )
						mx = j;
				}
			g[i] = 0;
			for(int j=i+1;j<=n;j++)
				if( A[i][j] ) {
					if( j != mx ) {
						g[i] += (g[j] + 1) / (d[i] - 1);
					}
				}
			for(int j=i-1;j>=1;j--) {
				g[j] = 0;
				for(int k=j+1;k<=n;k++)
					if( A[j][k] )
						g[j] += (g[k] + 1) / d[j];
			}
			ans = min(ans, g[1]);
		}
		g[i] = f[i];
