void solver::run(){
    is >> N >> M;
    if(!is) return;
    out.resize(N);
    for (int ii = 0; ii < M; ++ii) {
        int s, t;
        is >> s >> t;
        s--; t--;
        out[s].push_back(t);
    } // end ii

    double ans = INF;
    for (int i = 0; i < N; ++i) {
        auto dp = make_mdvector(N,  1e+9);
        dp[N-1] = 0; dp[N-1] = 0;
        for (int v = N - 2; v >= 0; --v) {
            vector<double> es0;
            double mxe = 0;
            for (auto &&u : out[v]) {
                es0.push_back(dp[u]+1);
                up_max(mxe, dp[u]+1);
            } // end u
            if(es0.empty()) continue;
            dp[v] = 0;
            for (int t = 0; t < es0.size(); ++t) {
                dp[v] += (es0[t]);
            } // end t
            if(i == v and es0.size() > 1){
                dp[v] -= mxe;
                dp[v] /= es0.size() - 1;
            }
            else dp[v] /= es0.size();
        } // end v
        up_min(ans, dp[0]);
    } // end i

    os << ans << endl;
}

