struct Edge {
	int v;
	Edge *nxt;
}edge[2*M];
Edge *NIL=&edge[0];
Edge *ecnt=&edge[1];
Edge *head[N],*best[N];
Edge *ban;
int n,m;
double ans;
double p[N];
inline void AddEdge(int u,int v) {
	ecnt->v=v;
	ecnt->nxt=head[u];
	head[u]=ecnt++;
}
double Prework(int u) {
	if(p[u]!=-1) return p[u];
	p[u]=0;
	int cnt=0;
	for(Edge *e=head[u];e!=NIL;e=e->nxt)
		cnt++;
	for(Edge *e=head[u];e!=NIL;e=e->nxt) {
		p[u]+=Prework(e->v)+1;
		if(p[e->v]>p[best[u]->v])
			best[u]=e;
	}
	p[u]/=cnt;
	return p[u];
}
double Dfs(int u) {
	if(p[u]!=-1) return p[u];
	p[u]=0;
	int cnt=0;
	for(Edge *e=head[u];e!=NIL;e=e->nxt)
		if(e!=ban)
			cnt++;
	if(cnt==0) return INF;
	for(Edge *e=head[u];e!=NIL;e=e->nxt)
		if(e!=ban)
			p[u]+=Dfs(e->v)+1;
	p[u]/=cnt;
	return p[u];
}
