		best[i]=head[i]=NIL;
		p[i]=-1;
	}
	for(int i=1,s,t;i<=m;i++) {
		scanf("%d %d",&s,&t);
		AddEdge(s,t);
	}
	p[n]=0;
	ans=Prework(1);
	for(int j=1;j<n;j++) {
		p[n]=0;
		for(int i=1;i<n;i++)
			p[i]=-1;
		ban=best[j];
		ans=min(ans,Dfs(1));
	}
	printf("%.10lf\n",ans);
	return 0;
}

