#define per(i,n) for(int i = (n)-1; i >= 0; --i)

int N, M;
vvl edges, dp;
vl cnts;
vd ans;

void dfs(int v) {
    if (ans[v] != 0) return;
    ld sum = 0, cnt = 0;
    rep(to,N) {
        if (edges[v][to] != 1) continue;
        dfs(to);
        sum += ans[to];
        cnt += 1;
    }
    if (cnt) sum = (sum + cnt) / cnt;
    ans[v] = sum;
}

int main() {
    cin >> N >> M;
    edges.assign(N, vl(N, 0));
    dp.assign(N, vl(2, 0));
    cnts.assign(N, 0);
    ans.assign(N, 0);
    rep(i,M) {
        int a, b; cin >> a >> b; a--; b--;
        cnts[a]++;
        edges[a][b] =  1;
        edges[b][a] = -1;
    }
    rep(i,N) rep(j,N) {
        if (edges[i][j] == 1)  dp[j][0] += dp[i][0] + 1;
    }
    per(i,N) rep(j,N) {
        if (edges[i][j] == -1) dp[j][1] += dp[i][1] + 1;
    }
    int mx = 0, from = -1, to = -1;
    rep(i,N-1) rng(j,i+1,N) {
        int sum = dp[i][0] + dp[j][1];
        if (sum > mx and cnts[i] >= 2) {
            mx = sum;
            from = i;
            to = j;
        }
    }
    if (from != -1) edges[from][to] = 0;
    dfs(0);
    printf("%.10Lf\n", ans[0]);
    return 0;
}

