int N, M;
Vec< Vec< int > > arc;

double run(vector< double >& dp) {
	dp.assign(N, 0);
	dp[N-1] = 0;
	for (int v=N-2; v>=0; --v) {
		int c = 0;
		for (int u : arc[v]) {
			if (u >= 0) {
				dp[v] += dp[u] + 1;
				++c;
			}
		}
		dp[v] /= c;
	}
	return dp[0];
}

