		if (arc.size() == 1) continue;
		int tar_i = 0;
		for (int i=0, m=arc[v].size(); i<m; ++i) if (dp[arc[v][tar_i]] < dp[arc[v][i]]) tar_i = i;
		int p = arc[v][tar_i];
		arc[v][tar_i] = -1;
		vector< double > dp_;
		ans = min(ans, run(dp_));
		arc[v][tar_i] = p;
