    out.assign(N, 0);

    for (int i = 0; i < M; i++) {
        int s, t;
        cin >> s >> t;
        s--; t--;
        adj[s][t] = true;
        out[s]++;
    }

    double base = solve_dp();
    double best = base;
    solve_probability();

    for (int s = 0; s < N; s++) {
        if (out[s] <= 1)
            continue;

        double worst = 0;

        for (int t = s + 1; t < N; t++)
            if (adj[s][t])
                worst = max(worst, dp[t]);

        double save = (dp[s] - 1) - ((dp[s] - 1) * out[s] - worst) / (out[s] - 1);
        best = min(best, base - probability[s] * save);
    }

    cout << best << '\n';
}

