double Dfs(int u) {
	if(p[u]!=-1) return p[u];
	p[u]=0;
	int cnt=0;
	for(Edge *e=head[u];e!=NIL;e=e->nxt)
		if(e!=&edge[ban])
			cnt++;
	if(cnt==0) return INF;
	for(Edge *e=head[u];e!=NIL;e=e->nxt)
		if(e!=&edge[ban])
			p[u]+=Dfs(e->v)+1;
	p[u]/=cnt;
	return p[u];
}
