  if(start==target) return true;
  queue<ll> que;
  que.push(start);
  while(!que.empty()){
    auto q=que.front();
    que.pop();
    for( auto x:graph[q].children ){
      if( x==target ) return true;
      else{
        if(x<target){
          que.push(x);
        }
      }
    }

  }
  return false;
}



