void solve() {
	int n, m; cin >> n >> m;
    vector<vector<int>> G(n);
    rep(i, m) {
        int s, t; cin >> s >> t; --s; --t;
        G[s].push_back(t);
    }
    vector<double> dp(n, 0);
    //DAGなのでdp
    for(int i = n - 2; i >= 0; --i) {
        int cnt = (int)G[i].size();
        for(auto e: G[i]) {
            dp[i] += (dp[e] + 1.0) / (double)cnt;
        }
    }
    double ans = dp[0];
    //探索するもののを減らすべし
    rep(i, n - 1) {
        vector<double> dp2(n, 0);
        int k = 0;
        double d = -1;
        for(auto e: G[i]) {
            if(dp[e] > d) k = e, d = dp[e];
        }
        if(G[i].size() == 1) continue;
        for(int j = n - 2; j >= 0; --j) {
            if(j > i) dp2[j] = dp[j];
            else if(j == i) {
                int cnt = (int) G[j].size();
                for(auto e: G[j]) {
                    if(e != k) dp2[j] += (dp2[e] + 1.0) / (double)(cnt - 1);
                }
            }
            else {
                int cnt = (int)G[j].size();
                for(auto e: G[j]) {
                    dp2[j] += (dp2[e] + 1.0) / (double)cnt;
                }
            }
        }
        chmin(ans, dp2[0]);
    }
    cout << ans << endl;
}

