        A[i][i] = T;
        for(auto to : g[i]){
            A[i][to] -= 1.0;
        }
        b[i] = T;
    }
    A[n - 1][n - 1] = 1.0;
    b[n - 1] = 0.0;

    vec e = gauss_jordan(A, b);

    assert(!e.empty());

    vec p(n);
    p[0] = 1.0;
    rep(i, n){
        double T = g[i].size();
        for(auto to : g[i]){
            p[to] += p[i] / T;
        }
    }

    double ans = e[0];

    double D = 1e10;

    rep(i, n){
        if((int)g[i].size() <= 1){
            continue;
        }
        sort(g[i].begin(), g[i].end(), [&](int i, int j){ return e[i] > e[j]; });
        double T = g[i].size();
        double d = e[g[i][0]] / T;
        d = -d;
        REP(j, 1, g[i].size()){
            d += e[g[i][j]] / (T - 1.0) - e[g[i][j]] / T;
        }
        chmin(D, d * p[i]);
    }

    chmin(ans, ans + D);

    cout << ans << endl;

    cout << flush;

    return 0;
}

