        long double cmpC = 0;
        for(int s:revG[t]){
            if(G[s].size()==1) continue;
            if(cmpC<=(E[s]+Pr[s])/G[s].size()+eps){
                cmpC = (E[s]+Pr[s])/G[s].size();
                cmp.emplace_back(cmpC, s);
            }
        }
        if(cmp.empty()) continue;
        sort(cmp.begin(),cmp.end(),[](pair<long double,int> a, pair<long double,int> b){return a.first < b.first;});
        int s = cmp.back().second;
        long double tmp = solveG(s,t,G);
        ans = min(ans,tmp);
    }
    cout << fixed << setprecision(10) << ans << endl;
    return 0;
}

