bool reach(int u) {
	if(u == n) return true;
	bool ret = true;
	out[u] = 0;
	for(int v:G[u]) if(ok[u][v]){
		ret &= reach(v);
		out[u]++;
	}
	return ret && out[u];
}

void dfs(int u) {
	vis[u] = true;
	for(int v:rG[u]) if(ok[v][u]) {
		if(!vis[v]) dfs(v);
		ld pc = 1. / out[v];
		E[u] += pc * (E[v] + sp[v]);
		sp[u] += sp[v] * pc;
	}
}

ld go() {
	if(!reach(1)) return INF;		
	for(int i=1;i<=n;i++) E[i] = sp[i] = vis[i] = 0;
	E[1] = 0, sp[1] = 1;
	vis[1] = true;
	dfs(n);
	return E[n];
}

