double rec(int n){
    if(dp[n] != -1) return dp[n];
    if(n == N-1) return dp[n] = 1;

    int size = G.adj[n].size();
    if(id2e[unused].from == n) size--;
    double res = 0;
    for(Edge e : G.adj[n]){
        if(e.id == unused) continue;
        res += (rec(e.to)+1)/size;
    }
    return dp[n] = res;
}

