typedef long double ld;

const int Maxn = 606;

int n, m;
vector <int> neigh[Maxn];
ld a[Maxn], b[Maxn];
ld res = Maxn;

void Fill(int lef, int rig)
{
    for (int j = rig; j >= lef; j--) {
        a[j] = b[j] = 0;
        for (int z = 0; z < neigh[j].size(); z++) {
            int k = neigh[j][z];
            a[j] += a[k];
            b[j] += 1.0l + b[k];
        }
        a[j] /= ld(neigh[j].size());
        b[j] /= ld(neigh[j].size());
    }
}

int main()
{
    scanf("%d %d", &n, &m);
    for (int i = 0; i < m; i++) {
        int a, b; scanf("%d %d", &a, &b);
        neigh[a].push_back(b);
    }
    for (int x = 0; x < n; x++) {
        Fill(x + 1, n - 1);
        a[x] = 1; b[x] = 0;
        Fill(1, x - 1);
        if (x == 0) res = min(res, b[1]);
        else if (neigh[x].size() > 1) {
            ld sum = 0, mx = 0;
            for (int z = 0; z < neigh[x].size(); z++) {
                int k = neigh[x][z];
                sum += 1.0l + b[k];
                mx = max(mx, 1.0l + b[k]);
            }
            ld val = (sum - mx) / ld(int(neigh[x].size()) - 1);
            res = min(res, a[1] * val + b[1]);
        }
    }
    cout << fixed << setprecision(10) << res << endl;
    return 0;
}

