            rep(j, G[i].size()){
                if(G[i][j].first == s && i == t)continue;
                if(i == n-1 || dp[i] > 0){
                    dp[G[i][j].first] += (double)(dp[i] + 1);
                    cnt2[G[i][j].first]++;
                }
            }
        }
        cnt[s]++;
        /*
