        rep(i,n)cout << dp[i] << endl;
        cout << endl;
        */
        int flag = 0;
        rep(i,n-1){
            if(cnt3[i] > 0 && cnt2[i] == 0){
                flag = 1;
                break;
            }
        }
        if(dp[0] > 0 && flag == 0)ans = min(ans, dp[0]);
    }

    cout << fixed << setprecision(10) << ans << endl;
    return 0;
}

