constexpr ll M_MAX = 600;
ll N, M;
ll s[M_MAX];
ll t[M_MAX];
queue<pair<ll,ll>> que;
ll dels=-1,delt=-1;

void bfs(vector<vector<ll>> &g,map<pair<ll,ll>,ll> &depth){
	while (!que.empty()) {
		pair<ll,ll> v = que.front(); // キューから先頭頂点を取り出す
		que.pop();

		// v から辿れる頂点をすべて調べる
		for (auto nextv : g[v.first]) {
			chmax(depth[{nextv,v.first}],v.second+1);
			que.push({nextv,v.second+1});
		}
	}
}

void dfs(vector<vector<ll>> &g,vector<double> &dp,ll v){
	if(v==N-1){
		return;
	}else if(g[v].size()==1){
		dfs(g,dp,g[v][0]);
	}else{
		double maxval=0.;
		for(ll nextv:g[v]){
			if(chmax(maxval,dp[nextv])){
				dels=v;
				delt=nextv;
			}
		}
	}
}

double updatedp(vector<vector<ll>> &g,vector<double> &dp,ll v){
	//debug(v);
	if(v==N-1)return 0.;
	double ans=0.;
	ll gvsize=g[v].size();
	for(ll nextv:g[v]){	
		if(v==dels && nextv==delt){
			gvsize--;
			continue;
		}
		ans+=updatedp(g,dp,nextv);
	}
	if(gvsize==0)return INF;
	return dp[v]=1.+ans/gvsize;
}

void solve() {

	map<pair<ll,ll>,ll> depth;

  	scanf("%lld%lld", &N, &M);
	rep(i, M) {
		scanf("%lld%lld", s + i, t + i);
		s[i]--;t[i]--;
		depth[{s[i],t[i]}]=0;
	}

	vector<vector<ll>> g(N),revg(N);
	rep(i,M){
		g[s[i]].push_back(t[i]);
	}

	double ans=INF;
	vector<double> dp(N,0.);
	double tmp=updatedp(g,dp,0);
	chmin(ans,tmp);
	rep(i,M){
		dels=s[i],delt=t[i];
		vector<double> dp(N,0.);
		double tmp=updatedp(g,dp,0);
		chmin(ans,tmp);
	}

	printf("%.20f\n", ans);
}

signed main() {
	solve();
	return 0;
}

