using graph = vector<vector<int>>;

vector<int> topo(const graph &g) {
  const int n = g.size();
  vector<int> res;
  vector<bool> vis(n);
  auto dfs = [&](auto dfs, int u) -> void {
    if (vis[u]) return;
    vis[u] = true;
    for (int v : g[u]) {
      dfs(dfs, v);
    }
    res.push_back(u);
  };
  rep(i, n) dfs(dfs, i);
  return res;
}

int main() {
  cin.tie(nullptr);
  ios::sync_with_stdio(false);
  cout << fixed << setprecision(15);
  int N, M; cin >> N >> M;
  vector<vector<int>> G(N);
  vector<pair<int, int>> es;
  rep(i, M) {
    int a, b; cin >> a >> b; a--; b--;
    G[a].push_back(b);
    es.emplace_back(a, b);
  }
  vector<double> rev(N);
  vector<int> top = topo(G);
  rep(i, N) {
    vector<double> dp(N);
    dp[i] = 1;
    for (int u : top) {
      for (int v : G[u]) dp[u] += dp[v] / G[u].size();
    }
    rev[i] = dp[0];
  }
  vector<double> ep(N);
  ep[N - 1] = 0;
  for (int u : top) {
    for (int v : G[u]) {
      ep[u] += (ep[v] + 1) / G[u].size();
    }
  }
  double ans = ep[0];
  rep(i, M) {
    int a = es[i].first;
    int b = es[i].second;
    if (G[a].size() == 1) continue;
    double k = G[a].size();
    // sum(ep) / k -> (sum(ep) - ep[b]) / (k - 1)
    double sum = ep[a] * k;
    double diff = (sum - ep[b] - 1) / (k - 1) - sum / k;
    ans = min(ans, ep[0] + diff * rev[a]);
  }
  cout << ans << endl;
}

