typedef long long ll;

ll N, M;
vector<vector<ll>> Kids;
vector<double> Dp;
typedef pair<ll, ll> Pair;
vector<Pair> Cands;
typedef pair<double, ll> DPair;
double R;

int main() {
  cin >> N >> M;
  Kids.resize(N);
  for (ll i = 0; i < M; ++i) {
    ll s, t;
    cin >> s >> t;
    --s;
    --t;
    Kids[s].push_back(t);
  }
  Dp.resize(N);
  for (ll v = N - 2; v >= 0; --v) {
    Dp[v] = 1;
    for (ll w : Kids[v]) {
      Dp[v] += Dp[w] / Kids[v].size();
    }
  }
  R = Dp[0];
  for (ll v = 0; v < N; ++v) {
    if (Kids[v].size() == 1) continue;
    DPair best = DPair(-1, -1);
    for (ll w : Kids[v]) {
      best = max(best, DPair(Dp[w], w));
    }
    Cands.push_back(Pair(v, best.second));
  }
  for (Pair cand : Cands) {
    for (ll v = N - 2; v >= 0; --v) {
      Dp[v] = 1;
      ll s = Kids[v].size() - (cand.first == v ? 1 : 0);
      for (ll w : Kids[v]) {
        if (Pair(v, w) == cand) continue;
        Dp[v] += Dp[w] / s;
      }
    }
    R = min(R, Dp[0]);
  }
  cout << setprecision(10) << R << endl;
  return 0;
}

