int N,M;
vector<vector<int> > G;
vector<vector<double> > dp;

double sol( int block, int inum  )
{
  if( dp[block][inum] > -0.00000001 )
    {
      return dp[block][inum];
    }

  if( inum == N-1 )
    {
      return dp[block][inum] = 0.0;
    }



  int num = 0;
  double sm = 0.0;
  double mx = 0.0;

  for( const auto& elem : G[inum] )
    {
      double temp = sol(block,elem) + 1.0;
      sm += temp;
      mx = max(temp,mx);
      ++ num;
    }

  double res = 1e18;

  if( 0 < num )
    {
      res = min(res,sm/num);
    }
  if( block == inum and 1 < num)
    {
      res = min(res,(sm-mx)/(num-1));
    }

  return dp[block][inum] = res;

}




signed main()
{
  IOS; /* making cin faster */
  SCAND2(N,M);
  G.resize(N);
  dp.assign(N+1,vector<double>(N,-1.0));

  REP(_,M)
    {
      int s,t;
      SCAND2(s,t);
      -- s;
      -- t;
      G[s].push_back(t);
    }

  double mn = 1e18;
  REP(i,N+1)
    {
      mn = min(mn,sol(i,0));
    }

  printf("%.15lf\n",mn);


}

