auto solve_k(ll n, const V<list<ll>>& graph, V<float>& dp, ll k) {
	RREP(i, k + 1) {
		if (i >= n - 1) { continue; }
		ll s = graph[i].size();

		float val = 0.0;
		REPC(to, graph[i]) {
			val += dp[to];
		}

		float mx = 0.0;
		REPC(to, graph[i]) {
			mx = std::max(mx, dp[to]);
		}

		if (i == k) { val -= mx; --s; }
		dp[i] = (val + s) / s;
	}
	return dp[0];
}

auto solve(ll n, ll m, const V<list<ll>>& graph) {
	auto dp = V<float>(n);
	float ans = solve_k(n, graph, dp, n);
	REP(i, n - 1) {
		ans = std::min(ans, solve_k(n, graph, dp, i));
	}
	return ans;
}

