ll modinv(ll a, ll m) {
	ll b = m, u = 1, v = 0;
	while (b) {
		ll t = a / b;
		a -= t * b; std::swap(a, b);
		u -= t * v; std::swap(u, v);
	}
	u %= m;
	if (u < 0) u += m;
	return u;
}

double dfs(int n) {
	if (dp[n] != -1)
		return dp[n];
	std::vector<int> out_pathes = pathes[n];

	int num_candidate = out_pathes.size();

	double temp_max=0.0;
	int argmax;
	if (n == blocked && num_candidate > 1) {
		for (int i = 0; i < num_candidate; i++) {
			if (temp_max < dp[out_pathes[i]]) {
				temp_max = dp[out_pathes[i]];
				argmax = i;
			}
		}
		out_pathes.erase(out_pathes.begin()+argmax);
	}
	double temp = 0.0;
	for (int i = 0; i < out_pathes.size(); i++) {
		//printf("n:%d, caindidate:%d\n", n, out_pathes[i]);
		temp += (dfs(out_pathes[i]) + 1.0) / out_pathes.size();
	}
	dp[n] = temp;
	return dp[n];
}

