using namespace std;
#define REP(i,n) for (int i=0;i<(n);++i)
using ll = long long;
constexpr ll INF = 1LL << 60;
constexpr int MOD = 998244353;

int N, M, s, t;
double dp[606];

int main() {
  cin >> N >> M;
  vector<vector<int>> g(N);
  REP(i, M) {
    cin >> s >> t;
    --s, --t;
    g[s].push_back(t);
  }

  for(int i = N-2; i >= 0; --i) {
    double s = 0;
    for(int v : g[i]) s += dp[v];
    dp[i] = s / g[i].size() + 1;
  }

  double ans = dp[0];
  for(int i = 0; i < N-1; ++i) {
    if(g[i].size() == 1) continue;
    int cut = g[i][0];
    for(int nv : g[i]) if(dp[cut] < dp[nv]) cut = nv;

    // recalculate expectation value without cut
    vector<double> dp2(N);
    for(int j = N-2; j >= 0; --j) {
      double s = 0;
      for(int v : g[j]) {
        if(j == i && v == cut) continue;
        s += dp2[v];
      }
      dp2[j] = s / (g[j].size() - (j == i)) + 1;
    }
    ans = min(ans, dp2[0]);
  }
  cout << fixed << setprecision(10) << ans;
  return 0;
}

