double dfs(Graph& graph, ll v,P edge) {
	if (v == graph.size() - 1)return 0;
	if (dp[v] != 0)return dp[v];

	double temp = 1;


	double n = graph[v].size();
	REP(i, graph[v].size()) {
		ll to = graph[v][i].to;
		if (edge.first == v && edge.second == to) {
			if (n == 1)return 100000;
			n--;
			break;
		}
	}
	REP(i, graph[v].size()) {
		ll to = graph[v][i].to;
		if (edge.first == v && edge.second == to) {
			continue;
		}
		temp += 1.0 / n * dfs(graph, to, edge);
	}
	dp[v] = temp;
	return dp[v];
}



