typedef long double ld;

const int N = 601;

int deg[N];
int con[N][N];

ld dp[N];

int n;

ld calc() {
	fill(dp, dp + n, 0);
	for (int i = n - 2; i >= 0; i--) {
		for (int j = i + 1; j < n; j++) {
			if (con[i][j]) dp[i] += dp[j];
		}
		dp[i] /= deg[i];
		dp[i] += 1;
	}
	return dp[0];
}

