		u--;
		v--;
		deg[u]++;
		con[u][v] = 1;
	}
	ld ans = calc();
	vector<ld> sdp(n);
	for (int i = 0; i < n; i++) {
		sdp[i] = dp[i];
	}
	for (int i = 0; i < n; i++) {
		if (deg[i] < 2) continue;
		vector<pair<ld, int>> soski;
		for (int j = i + 1; j < n; j++) {
			if (con[i][j]) {
