    int tmp = q.top().id; q.pop();
    if (dd[G[tmp].x] == 1) {  en = min(en + 1, m); continue;}
    memset(head, 0, sizeof(head)), tot = 0;
    memset(d, 0, sizeof(d));
    for (RI i = 1; i <= m; ++i)
      if (i != tmp)
        addedge(G[i].x, G[i].y), ++d[G[i].x];
    memset(f, 0, sizeof(f));
