template<class C> constexpr auto RLE(C const& v) { // run length encoding
  using T = typename C::value_type; using U = typename C::size_type;
  vector<pair<T, U>> w; auto t=begin(v); U cnt=0;
  for(auto i=begin(v);i!=end(v);++i) { if(*t == *i) ++cnt; else { w.emplace_back(*t, cnt); t=i; cnt=1; } }
  w.emplace_back(*t, cnt); return w;
}

template<typename T> constexpr T gcd2(T a, T b) { while(b) { T t=b; b=a%b; a=t; } return a; }
