const int MAXN = 600;
vector<vector<int>> to(MAXN);

double ans(int block){
	int n = to.size();
	vector<double> dp(n);

	for(int v = n-1; v >= 0; v--){
		int deg = to[v].size();

		if(v==block && deg>1){
			double maxdp = 0;
			for(auto next : to[v]) maxdp = max(maxdp,dp[next]);
			for(auto next : to[v]) dp[v] += dp[next];
			dp[v] -= maxdp;
			dp[v] /= deg-1;
			dp[v]++;
		}
		else{
			if(deg==0) continue;
			for(auto next : to[v]) dp[v] += dp[next];
			dp[v] /= deg;
			dp[v]++;
		}
	}

	return dp[0];
}


