const int N = 607;

vector <int> g[N];
pi ed[N];
double sum[N];
bitset <N> used;

bool dfs(int v, int bad, int n) {
    used[v] = 1;
    if (g[v].size() == 1 && v == ed[bad].F && g[v][0] == ed[bad].S)
        return false;
    for (int u : g[v])
        if (!used[v] && !dfs(u, bad, n))
            return false;
    return true;
}

void solve() {
    int n, m;
    cin >> n >> m;
    loop(i, m) {
        int u, v;
        cin >> u >> v;
        g[u].pb(v);
        ed[i] = { u, v };
    }
    double ans = N;
    loop(i, m + 1) {
        used = 0;
        if (!dfs(1, i, n))
            continue;
        double cur = 0;
        loop(j, N)
            sum[j] = 0;
        sum[1] = 1;
        loop1(v, n) {
            for (int u : g[v]) {
                if (v == ed[i].F && u == ed[i].S)
                    continue;
                double pls = sum[v] / (g[v].size() - (v == ed[i].F));
                cur += pls; sum[u] += pls;
            }
        }
        ans = min(ans, cur);
    }
    cout << fixed << setprecision(7) << ans;
}

