double dp[600];
int n, m;
vector<int> edge[600];


double calc(int ngs, int ngt) {
	dp[n - 1] = 0;
	for (int s = n - 2; s >= 0; s--) {
		int e = 0;
		double sum = 0;
		for (int t : edge[s]) {
			if (s == ngs && t == ngt)continue;
			e++;
			sum += dp[t];
		}

		dp[s] = sum / e + 1;
	}
	return dp[0];
}


