int can() {
    fore(u,1,N) ok[u] = 0;

    for(int u = N-1; u >= 1; u--) {
        if(isconnect(u,N)) 
            ok[u] = 1;
        fore(v,u+1,N) {
            if(isconnect(u,v)) {
                ok[u] |= ok[v];
            }
        }
    }

