int N,M;
const double EPS = 1e-10;
vector<vector<int>> G;
double dp[600];
int ab[600];

double dfs1(int v) {
    if (v==N-1) return 0.0;
    if (dp[v] > EPS) return dp[v];
    double MAX = 0.0;
    for (auto nv : G[v]) {
        double val = dfs1(nv);
        dp[v] += val+1.0;
        if (chmax(MAX,val)) ab[v] = nv;
    }
    if (G[v].size()==1) ab[v] = -1;
    dp[v] /= G[v].size();
    return dp[v];
}

double dfs2(int v, int u) {
    if (v==N-1) return 0.0;
    if (dp[v] > EPS) return dp[v];
    int cnt = 0;
    for (auto nv : G[v]) {
        if (v==u&&nv==ab[v]) continue;
        dp[v] += dfs2(nv,u) + 1.0;
        cnt++;
    }
    dp[v] /= cnt;
    return dp[v];
}
