        sum_e += e;
        if (e > max_e) {
          max_e = e;
          max_t = t;
        }
      }

      int num = tos.size();
      if (num > 1) {
        sum_e -= max_e;
        --num;
      }
      double p = 1. / num;
      dp[i] = sum_e / num + 1;
    }
    ret = min(ret, dp[0]);
  }
  cout << fixed << setprecision(10) << ret << "\n";

  return 0;
}

