typedef long long ll;
#define REP(i,n) for (int i = 0; i < (n); ++i)

int main(){
    int n, m;
    cin >> n >> m;
    vector<vector<int>> net(n);
    vector<pair<int, int>> edges;
    REP(i, m){
        int si, ti;
        cin >> si >> ti;
        si--; ti--;
        net.at(si).push_back(ti);
        edges.emplace_back(si, ti);
    }

    double ans = n + 1;
    for(int ng = -1; ng < n - 1; ++ng){
        if(ng != -1 && net.at(ng).size() == 1){
            continue;
        }
        vector<double> exp(n, 0);
        for(int x = n - 2; x >= 0; x--){

            double tmp = 0;
            double count = 0;
