            for(int nxt : net.at(x)){
                tmp += exp.at(nxt) + 1.0;
                maxval = max(maxval, exp.at(nxt) + 1.0);
                count++;
            }
            if(ng != x){
                exp.at(x) = tmp / count;
            }else{
                exp.at(x) = (tmp - maxval) / (count - 1);
            }
        }
        ans = min(ans, exp.at(0));
    }
    printf("%.8f\n", ans);
