        //printf("visiting %d\n",u);
        if (u == n-1){
            en[u] = 0;
            continue;
        }
        double sum = 0;
        int ct = 0;
        int best = -1;
        for (auto v : adjlist[u]){
            em[v.second] = en[v.first]+1;
            if (best == -1 || em[v.second] >= em[best]){
                //printf("%d %f \n",v.second,em[v.second]);
                best = v.second;
            }
            sum += em[v.second];
            ct++;
        }
        en[u] = (double)sum/(ct);
        //printf("%f %d\n",sum,ct);
        //printf("%f %d\n",sum-em[best],ct-1);
        if (ct == 1){
            enk[u] = en[u];
        }
        else{
            enk[u] = (double)(sum-em[best])/(ct-1);
        }
    }
    for (int i = 0; i < n; i++){
        //printf("%f ",enk[i]);
    }
    double ans = 1000000000;

    for (int i = 0; i < n; i++){
        //printf("block off %d\n",i);
        double ene[n];
        for (auto u : preorder){
            //printf("visiting %d\n",u);
            if (u == n-1){
                ene[u] = 0;
                continue;
            }
            if (u == i){
                ene[u] = enk[u];
                continue;
            }
            double sum = 0;
            int ct = 0;
            for (auto v : adjlist[u]){
                //printf("considering %d %d\n",v.first,v.second);
                if (v.first == i){
                    sum += enk[v.first]+1;
                }
                else {sum += ene[v.first]+1;}
                ct++;
            }
            ene[u] = (double)sum/ct;
        }

        //printf("%f\n",ene[0]);
        ans = min(ans,ene[0]);
    }
    printf("%f",ans);
}

