auto solve_k(ll n, const V<list<ll>>& graph, ll k) {
	V<float> dp(n);
	RREP(i, n - 1) {
		float mx = 0.0;
		ll s = graph[i].size();
		float val = 0.0;
		REPC(to, graph[i]) {
			val += dp[to];
			chmax(mx, dp[to]);
		}
		if (i == k) { val -= mx; --s; }
		val += s;
		dp[i] = val / s;
	}
	return dp[0];
}

auto solve(ll n, ll m, const V<list<ll>>& graph) {
	float ans = 1e10;
	REP(i, n) {
		chmin(ans, solve_k(n, graph, i));
	}
	return ans;
}

