        G[s].push_back(t);
    }
    vector<double> dp(n, 0);
    //DAGなのでdp
    for(int i = n - 2; i >= 0; --i) {
        int cnt = (int)G[i].size();
        for(auto e: G[i]) {
            dp[i] += (dp[e] + 1.0) / (double)cnt;
        }
    }
    double ans = dp[0];
    //探索するもののを減らすべし
    rep(i, n - 2) {
        vector<double> dp2(n, 0);
        for(int j = n - 2; j >= 0; --j) {
            int cnt = (int)G[j].size();
            for(auto e: G[i]) {
                dp2[i] += (dp2[e] + 1.0) / (double)cnt;
            }
            if(j == i) {
                --cnt;
                priority_queue<double, vector<double>, greater<double>> pque;
                for(auto e: G[j]) {
                    pque.push(dp[e]);
                }
                rep(k, cnt) {
                    int next = pque.top(); pque.pop();
                    dp2[i] += (dp2[next] + 1.0) / (double)cnt;
                }
            }
        }
        chmin(ans, dp2[0]);
    }
    cout << ans << endl;
}

