	return (idx == V);
}

vector<double> expect(Graph &G, vector<ll> &dag){
	ll N = G.size();
	vector<double> res(N, 0);
	for(int i=N-1;i>=0;i--){
		double tmp = 0;
		ll now = dag[i];
		ll dig = G[now].size();
		if(dig==0) continue;
		REP(j, G[now].size()){
			ll next = G[now][j];
			tmp += (1.0+res[next])/dig;
		}
		res[now] = tmp;
	}
	return res;
}

