    	//flag = true;
    	ll idx;
    	double ma = -1.0;
    	REP(j, G[i].size()){
    		ll next = G[i][j];
    		if(kitai[next]>ma){
    			ma = kitai[next];
    			idx = j;
    		}
    	}

    	Graph H(N);
