double getExpection(vector<double> &expection, vector<vector<int>> &passages, int i) {
  for (int j = i; j >= 0; j--) {
    expection[j] = 0;
    int total = passages[j].size();
    for (int next : passages[j]) {;
      expection[j] += expection[next] / total;
    }
    expection[j]++;
  }
  return expection[0];
}
int main()
{
