  for (int i = 0; i < M; i++) {
    int si, ti;
    cin >> si >> ti;
    passages[si - 1].push_back(ti - 1);
  }
  vector<double> expection(N, 0);
  double min_expection = getExpection(expection, passages, N - 2);
  for (int i = 0; i < N; i++) {
    if (passages[i].size() <= 1) {
      continue;
    }
    int max_next = passages[i][0];
    for (int next : passages[i]) {
      if (expection[next] > expection[max_next]) {
        max_next = next;
      }
    }
    int total = passages[i].size() - 1;
    expection[i] = 0;
    for (int next : passages[i]) {
      if (next == max_next) {
        continue;
      }
      expection[i] += expection[next] / total;
    }
    expection[i]++;
    double cur_expection = getExpection(expection, passages, i - 1);
    min_expection = min(min_expection, cur_expection);
  }
  cout << setprecision(10) << min_expection << endl;
  return 0;
}

