typedef double db;
int main () {
  int N, M;
  cin >> N >> M;
  vector<db>E(N + 1);
  vector<db>P(N + 1, 0);
  vector<vector<int>>dag(N + 1);
  for (int i = 0; i < M; i ++) {
    int s, t;
    cin >> s >> t;
    dag[s].push_back(t);
  }
  P[1] = 1;
  for (int i = 1; i < N; i ++) {
    int s = (int)dag[i].size();
    for (int j = 0; j < s; j ++) {
      P[dag[i][j]] += (P[i] / s);
    }
  }
  E[N] = 0;
  for (int i = N - 1; i >= 1; i --) {
    int s = (int)dag[i].size();
    db kj = 0;
    for (int j = 0; j < s; j ++) {
      kj += E[dag[i][j]];
    }
    kj /= s;
    E[i] = kj + 1;
  }
  db ans = E[1];
  for (int i = 1; i < N; i ++) {
    int s = dag[i].size();
    if (s == 1) continue;
    for (int j = 0; j < s; j ++) {
      db moto = E[i] * s;
      db dis = ((moto - E[dag[i][j]]) / (s - 1)) - E[i];
      db kj = E[1] + (dis * P[i]);
      if (ans > kj) ans = kj;
    }
  }
  cout << setprecision(10) << ans << endl;
}

