            probs[start] = 1;
            REP(current,start,N) {
                for (const auto next : st[current]) {
                    if (current == shouldBeClosed.first && next == shouldBeClosed.second) continue;
                    probs[next] += probs[current] / st[current].size();
                }
            }
            means[start] = 0;
            REP(current,start+1,N+1) {
                double ratioSum = 0;
                for (const auto from : ts[current]) {
                    if (current == shouldBeClosed.second && from == shouldBeClosed.first) continue;
                    means[current] += (means[from] + 1) * (probs[from] / st[from].size());
                    ratioSum += probs[from] / st[from].size();
                }
