//------------------------------- Solver ------------------------------------//

void solve()
{
    int n, m;
    cin >> n >> m;
    yukari<pair<int, int>> g(n);
    for (int i = 0; i < m; i++)
    {
        int s, t;
        cin >> s >> t;
        s--, t--;
        g[s].push_back(make_pair(t, 1));
    }
    akari<double> dp(n);
    akari<int> heavy(n), vst(n);
    auto calc = [&](auto &&calc, akari<double> &dp, int s = 0) -> double {
        if (vst[s])
        {
            return dp[s];
        }
        double res = 0, maxi = 0;
        int cnt = 0;
        vst[s] = 1;
        for (auto np : g[s])
        {
            if (!np.second)
            {
                continue;
            }
            cnt++;
            double w = calc(calc, dp, np.first) + 1;
            if (maxi < w)
            {
                maxi = w;
                heavy[s] = np.first;
            }
            res += w;
        }
        if (cnt)
        {
            res /= cnt;
        }
        else if (s != n - 1)
        {
            res = n + 1;
        }
        return dp[s] = res;
    };
    double ans = calc(calc, dp);
    for (int s = 0; s < n - 1; s++)
    {
        akari<double> dp2(n);
        fill(vst.begin(), vst.end(), 0);
        for (auto &p : g[s])
        {
            if (p.first == heavy[s])
            {
                p.second = 0;
                ans = min(ans, calc(calc, dp2));
                p.second = 1;
                break;
            }
        }
    }
    cout << setprecision(15) << ans << endl;
}

