vertex ver[600];

void dfs(int x) {
    ver[x].cnt++;
    if (ver[x].cnt < ver[x].np) return;
    for (auto &i : ver[x].to) {
        ver[i].prob += ver[x].prob / ver[x].to.size();
        dfs(i);
    }
}

void dec(int x) {
    if (--ver[x].np != 0) return;
    for (auto &i : ver[x].to) dec(i);
}

void inc(int x) {
    if (ver[x].np++ != 0) return;
    for (auto &i : ver[x].to) inc(i);
}

