const int Maxn = 600;

int N, M;
vector<pair<int, int> > G[Maxn + 5];
int out_deg[Maxn + 5];
double f[Maxn + 5];
bool vis[Maxn + 5];
int best_edge[Maxn + 5];

double PreDFS(int u) {
	static double mx[Maxn + 5];
	if(vis[u]) return f[u];
	vis[u] = true;
	if(u == N) return f[u] = 0;
	mx[u] = 0;
	for(int i = 0; i < (int)G[u].size(); i++) {
		int v = G[u][i].first, id = G[u][i].second;
		double res = PreDFS(v);
		if(res > mx[u]) {
			mx[u] = res;
			best_edge[u] = id;
		}
		f[u] += 1.0 * (res + 1) / out_deg[u];
	}
	return f[u];
}

int del;
double DFS(int u) {
	if(vis[u]) return f[u];
	vis[u] = true;
	if(u == N) return f[u] = 0;
	for(int i = 0; i < (int)G[u].size(); i++) {
		int v = G[u][i].first, id = G[u][i].second;
		if(u == del && best_edge[u] == id) continue;
		f[u] += 1.0 * (DFS(v) + 1) / (out_deg[u] - (u == del));
	}
	return f[u];
}

