using namespace std;
typedef long long ll;
typedef long double ld;
const int MAXN = 610;

int N, M;
vector <int> nv[MAXN];
ld pv[MAXN]; // prob to reach i
ld dp[MAXN]; // time to finish from i

int main()
{
    ios_base::sync_with_stdio(0);

    cin >> N >> M;
    for (int i = 0; i < M; i++)
    {
        int x, y;
        cin >> x >> y;
        x--, y--;
        nv[x].push_back(y);
    }

    for (int i = 0; i < N; i++)
        pv[i] = dp[i] = 0;
    pv[0] = 1;

    for (int i = 0; i < N - 1; i++)
    {
        ld ng = nv[i].size();
        for (int x : nv[i])
            pv[x] += pv[i] * 1. / ng;
    }

    dp[N] = 0.0;
    for (int i = N - 2; i >= 0; i--)
    {
        ld ng = nv[i].size();
        dp[i] = 1.0;
        for (int x : nv[i])
            dp[i] += dp[x] * 1. / ng;
    }

    ld res = dp[0];
    for (int i = 0; i < N - 1; i++)
    {
        if (nv[i].size() <= 1) continue;

        for (int x : nv[i])
        {
            ld nl = ((dp[x]) - (dp[i] - 1)) / (nv[i].size() - 1.);
            res = min (res, dp[0] - pv[i] * nl);
        }
    }
    cout << fixed << setprecision(10);
    cout << res << "\n";
}

