#define N 605
#define INF 0x3f3f3f3f
using namespace std;
int n,m;
vector<int>v[N];
double dp[N]={0};
double process(int p)//对于p这个顶点删除其连着的最大的出边 
{
	int i,j;
	for(i=1;i<=n;i++)dp[i]=0.0;
	dp[n]=0.0;
	for(i=n-1;i>=1;i--)
	{
		if(v[i].size()==1&&p==i)//i出度为1且 要删它的边 
		{
			dp[i]=INF;
			continue;
		}
		double len=v[i].size()-(p==i);
		dp[i]=1.0;
		double mmax=0;
		for(j=0;j<v[i].size();j++)
		{
			double temp=dp[v[i][j]];
			mmax=max(mmax,temp);
			dp[i]+=temp*1.0/len;
		}
		if(i==p)dp[i]-=mmax*1.0/len;
	}
	//cout<<dp[1]<<endl;
	return dp[1]; 
}
