		scanf("%d%d",&s,&t);
		 v[s].push_back(t);//出边 
	}
	double ans=INF;
	for(i=n;i>=1;i--)
	{
		ans=min(ans,process(i));
	}
	printf("%.10lf",ans);
	return 0;
}

