using namespace std;
typedef long long ll;

typedef pair<int, int> P;

#define FOR(i,a,b) for(ll i=(a);i<(b);++i)
#define RFOR(i,a,b) for(ll i=(a);i>(b);i--)
#define REP(i,n) FOR(i,0,n)
#define RREP(i,n) RFOR(i,n,-1)

int main(void) {
	auto start = chrono::system_clock::now();
	int n, m, a, b;
	cin >> n >> m;
	vector<P> v;
	vector<int> cnt(n);
	vector<set<int>> gr(n);
	REP(i, m) {
		scanf("%d%d", &a, &b);
		a--;
		b--;
		v.push_back(P(a, b));
		gr[a].insert(b);
		cnt[a]++;
	}
	mt19937 get_rand_mt;
	shuffle(v.begin(), v.end(), get_rand_mt);
	vector<long double> es(n);
	REP(i, n) es[i] = 0;
	es[0] = 1;
	long double mine = 0;
	REP(i, n - 1) {
		mine += es[i];
		for(auto j : gr[i]){
			es[j] += es[i] / (long double)cnt[i];
		}
	}
	REP(skip, m) {
		if (chrono::duration_cast<chrono::milliseconds>(chrono::system_clock::now() - start).count() > 1980) break;
		REP(i, n) es[i] = 0;
		es[0] = 1;
		a = v[skip].first;
		b = v[skip].second;
		if (cnt[a]>1) {
			gr[a].erase(b);
			cnt[a]--;
			long double e = 0;
			REP(i, n - 1) {
				e += es[i];
				for (auto j : gr[i]) {
					es[j] += es[i] / (long double)cnt[i];
				}
			}
			mine = min(mine, e);
			gr[a].insert(b);
			cnt[a]++;
		}
	}
	cout << fixed << setprecision(10) << mine;
	return 0;
}

