void input(){
    fast_io();
    cin >> N >> M;
    G.resize(N);
    revG.resize(N);
    for (int i = 0; i < M; i++)
    {
        int s,t; cin >> s >> t;
        s--,t--;
        Edge.emplace_back(s,t);
        G[s].push_back(t);
        revG[t].push_back(s);
    }
    for (int i = 0; i < N; i++)
    {
        sort(G[i].begin(),G[i].end(),greater<int>());
    }

}

void chmin(double &a, double b){if(a>b) a=b;}

int solve(){
    vector<double> dp(N,0);
    dp[N-1] = 0;
    for (int i = N-1; i >= 0; i--)
    {
        for(auto t:G[i]){
            dp[i] += (dp[t]+1)/G[i].size();
        }
    }
    double ans = dp[0];

    for (int i = N-1; i >= 0; i--)
    {
        if(G[i].size()<=1) continue;
        double dp_max = 0;
        int idx = 0;
        for(auto t:G[i]){
            if(dp[t] > dp_max){
                idx = t;
                dp_max = dp[t];
            }
        }
        vector<double> dp_i(N, 0);
        for (int s = N-1; s >= 0; s--)
        {
            for(auto t:G[s]){
                if(s==i && t==idx) continue;
                if(s==i) dp_i[s] += (dp_i[t]+1)/(G[s].size()-1);
                else dp_i[s] += (dp_i[t]+1)/(G[s].size());
            }
        }
        chmin(ans, dp_i[0]);
    }
    cout << fixed << setprecision(10) << ans << endl;
    return 0;
}

int main()
{
    input();
    solve();
    return 0;
}

