vector<vector<int>> G;
vector<int> depth;

void dfs(int cur, vector<double> &DD) {
    if(cur == G.size() - 1) {
        DD[cur] = 0;
        return;
    }
    double ret = 0;
    for(int v: G[cur]) {
        if(DD[v] < 0) dfs(v, DD);
        ret += DD[v];
    }
    ret /= G[cur].size();
    DD[cur] = ret + 1;
}

void dfs2(int cur, vector<double> &DD, int from, int to) {
    if(cur == G.size() - 1) {
        DD[cur] = 0;
        return;
    }
    double ret = 0;
    int cnt = 0;
    for(int v: G[cur]) {
        if(cur == from && to == v) continue;
        if(DD[v] < 0) dfs2(v, DD, from, to);
        ret += DD[v];
        cnt++;
    }
    ret /= cnt;
    DD[cur] = ret + 1;
}

