	for (int i = 0; i < M; i++) {
		int s, t;
		scanf("%d %d", &s, &t);
		p[s - 1].push_back(t - 1);
	}
	double*P = new double[N];
	for (int i = 0; i < N; i++)P[i] = 0;
	P[0] = 1;
	for (int i = 0; i < N - 1; i++) {
		for (int j = 0; j < p[i].size(); j++) {
			P[p[i][j]] += P[i] / p[i].size();
		}
	}
	double*E = new double[N];
	E[N - 1] = 0;
	double best = N;
	for (int i = N - 2; i >= 0; i--) {
		double sum = 0;
		for (int j = 0; j < p[i].size(); j++) {
			sum += E[p[i][j]];
		}
		E[i] = sum / p[i].size() + 1;
		if (p[i].size() == 1)continue;
		for (int j = 0; j < p[i].size(); j++) {
			double d = (sum - E[p[i][j]]) / (p[i].size() - 1) + 1 - E[i];
			if (best > d*P[i])best = d * P[i];
		}
	}
	if (best < 0) {
		printf("%f", E[0] + best);
	}
	else {
		printf("%f", E[0]);
	}
	return 0;
}

