const int INF=0x3f3f3f3f;
const int M=200005;
const int N=603;
struct Edge {
	int v;
	Edge *nxt;
}edge[2*M];
Edge *NIL=&edge[0];
Edge *ecnt=&edge[1];
Edge *head[N],*best[N];
Edge *ban;
int n,m;
double ans;
double p[N];
inline void AddEdge(int u,int v) {
	ecnt->v=v;
	ecnt->nxt=head[u];
	head[u]=ecnt++;
}
double Prework(int u) {
	if(p[u]!=-1) return p[u];
	p[u]=0;
	int cnt=0;
	for(Edge *e=head[u];e!=NIL;e=e->nxt)
		cnt++;
	for(Edge *e=head[u];e!=NIL;e=e->nxt) {
		p[u]+=Prework(e->v)+1;
		if(best[u]==NIL||p[e->v]>p[best[u]->v])
			best[u]=e;
	}
	p[u]/=cnt;
	return p[u];
}
double Dfs(int u) {
	if(p[u]!=-1) return p[u];
	p[u]=0;
	int cnt=0;
	for(Edge *e=head[u];e!=NIL;e=e->nxt)
		if(e!=ban)
			cnt++;
	if(cnt==0) return INF;
	for(Edge *e=head[u];e!=NIL;e=e->nxt)
		if(e!=ban)
			p[u]+=Dfs(e->v)+1;
	p[u]/=cnt;
	return p[u];
}
int main() {
	NIL->v=0; NIL->nxt=NIL;
	scanf("%d %d",&n,&m);
	for(int i=0;i<=n;i++) {
		best[i]=head[i]=NIL;
		p[i]=-1;
	}
	for(int i=1,s,t;i<=m;i++) {
		scanf("%d %d",&s,&t);
		AddEdge(s,t);
	}
	p[n]=0;
	ans=Prework(1);
	for(int j=1;j<n;j++) {
		if(best[j]==NIL) continue;
		p[n]=0;
		for(int i=1;i<n;i++)
			p[i]=-1;
		ban=best[j];
		ans=min(ans,Dfs(1));
	}
	printf("%.10lf\n",ans);
	return 0;
}

