    dp[n] = 0;
    for (ll i = n - 1; i >= 1; i--) {
        cnt[i] = g[i].size();
        ld sm = 0;
        for (ll v : g[i]) {
            sm += dp[v];
        }
        sum[i] = sm;
        dp[i] = 1 + (1.0 / cnt[i]) * (sm);
    }
    ld ans = dp[1];
    for (ll u = n - 1; u >= 1; u--) {
        auto dpp = dp;
        dpp[u] -= 1;
        for (ll i = u - 1; i >= 1; i--) {
            ld sm = 0;
            for (ll v : g[i]) {
                sm += dpp[v];
            }
            dpp[i] = 1 + (1.0 / cnt[i]) * sm;
        }
        rzn[u] = dp[1] - dpp[1];
    }
    for (auto[u, v] : edges) {
        if (dp[u] == 1 + dp[v]) continue;
        ld new_sum = sum[u] - dp[v];
        ld new_dp = 1 + (1.0 / (cnt[u] - 1)) * new_sum;
        ld razn = dp[u] - new_dp;
        ans = min(ans, dp[1] - rzn[u] * razn);
    }
    cout << fixed << setprecision(10) << ans << endl;
    return 0;
}
