#include <algorithm>
#include <iostream>
#include <iomanip>
#include <utility>
#include <vector>
#include <limits>
#include <queue>

double estimate(const int n, const std::vector<std::pair<int,int>> edge_forward, const std::vector<int> edge_forward_index, const std::vector<double> cost_c, int node, int close)
{
    std::vector<double> cost(cost_c.size());
    std::copy(cost_c.begin(), cost_c.end(), cost.begin());
    double cost_min = std::numeric_limits<double>::max();

    for (int i = node; i >= 0; i--) {
        int len = edge_forward_index[i + 1] - edge_forward_index[i];
        if (len == 1) {
            // 1経路しかないのでそのまま
            cost[i] = cost[edge_forward[edge_forward_index[i]].second] + 1;
            continue;
        }
        // 2経路以上ある
        if (close == 0) { // もう閉められない
            for (int j = 0; j < len; j++) {
                int ptr = edge_forward_index[i] + j;
                cost[i] += cost[edge_forward[ptr].second] + 1;
            }
            cost[i] /= len;
        } else {
            // どの扉を閉めるか判定をする
            std::vector<double> expected(len);
            for (int j = 0; j < len; j++) {
                int ptr = edge_forward_index[i] + j;
                expected[j] = cost[edge_forward[ptr].second] + 1;
            }
            // 昇順ソート
            std::sort(expected.begin(), expected.end(), std::less<double>());

            // 一番期待値が悪い通路を塞ぐ場合の値を計算
            double sum = 0;
            for (int j = 0; j < len; j++) {
                sum += expected[j];
            }
            double cost_close = (sum - expected[len - 1]) / (len - 1);
            double cost_open  =  sum                      /  len     ;

            cost[i] = cost_close;
            double a = estimate(n, edge_forward, edge_forward_index, cost, i - 1, close - 1);
            cost_min = std::min(cost_min, a);

            cost[i] = cost_open;
        }
    }
    return std::min(cost_min, cost[0]);
}

int main(int argc, char *argv[])
{
    int n, m;
    std::vector<std::pair<int,int>> edge_forward;
    std::vector<double> cost;
    std::vector<int> edge_forward_index;
    double ans;

    std::cin >> n >> m;

    edge_forward.reserve(m);

    for (int i = 0; i < m; i++) {
        int s, t;
        std::cin >> s >> t;
        edge_forward.push_back(std::make_pair(s - 1, t - 1));
    }

    // 一つ目の要素で昇順ソート
    std::sort(edge_forward.begin(), edge_forward.end(),
      [](const std::pair<int,int>& x, const std::pair<int,int>& y){return x.first < y.first;});

    // インデックスの作成
    edge_forward_index.resize(n);
    edge_forward_index[0] = 0;
    for (int i = 1, ptr = 0; i < n; i++) {
        while(edge_forward[ptr].first < i) {ptr++;}
        edge_forward_index[i] = ptr;
    }
    edge_forward_index[n - 1] = m;

    // 初期化
    cost.resize(n);
    std::fill(cost.begin(), cost.end(), 0);

    ans = estimate(n, edge_forward, edge_forward_index, cost, n - 2, 1);

    std::cout << std::setprecision(16) << ans << std::endl;

    return 0;
}

