struct UnionFind{
    vector<int> tree;

    UnionFind(int n): tree(n+1, -1) {};

    int root(int i){ return tree[i] < 0 ? i : tree[i] = root(tree[i]); }

    bool unite(int i, int j){
        i = root(i), j = root(j);
        if(i == j) return false;
        tree[i] += tree[j], tree[j] = i;
        return true;
    }

    bool same(int i, int j){ return root(i) == root(j); }

    int size(int i){ return -tree[root(i)]; }
};

double dfs(int i, vector<vector<int>> &graph){
    if(used[i] == 1){
        return dp[i];
    }

    if(i == n-1) return 0;

    used[i] = 1;

    double k = 0;


    for(auto e : graph[i]){
        k += (dfs(e, graph)+1);
    }

    return dp[i] = k / graph[i].size();
}

int no = 0;

void isOK(int i, vector<vector<int>> &graph){
    if(used[i] == 1)
        return;

    if(i == n-1) return;

    used[i] = 1;


    if(graph[i].size() == 0){
        no = 1;
        return;
    }

    for(auto e : graph[i]){
        isOK(e, graph);
    }

    return;
}

double solve(int idx){
    vector<vector<int>> graph(n);
    UnionFind uf(n);

    memset(used, 0, sizeof(used));

    for(int i = 0;i < m;i++){
        if(i != idx){
            uf.unite(edge[i].first, edge[i].second);
            graph[edge[i].first].push_back(edge[i].second);
        }
    }

    isOK(0, graph);
    if(no){
        graph[edge[idx].first].push_back(edge[idx].second);
    }

    memset(used, 0, sizeof(used));

    return dfs(0, graph);
}


