    for(int i = 0;i < m;i++){
        cin >> edge[i].first >> edge[i].second;
        edge[i].first--;
        edge[i].second--;
    }

    double ans = INT_MAX;

    for(int i = 0;i < n;i++){
        ans = min(ans, solve(i));
    }

    printf("%.12lf\n", ans);

    return 0;
