#define REP(i,n) for (ll i = 0; i < n; ++i)
#define REPR(i,n) for (ll i = n-1; i >= 0; --i)
#define FOR(i,m,n) for (int i = m; i < n; ++i)
#define FORR(i,m,n) for (ll i = n-1; i >= m; --i)
#define FORE(x,xs) for (const auto& x : xs)
#define ALL(v) v.begin(), v.end()
#define rALL(v) v.rbegin(), v.rend()

const int MAX = 600;

int N, M;
ld prob[MAX];
vi edge[MAX];
ld dp[MAX];

ld solve() {
    prob[N-1] = 0;
    REPR (i, N-1) {
        FORE (e, edge[i]) prob[i] += (1 + prob[e]);
        prob[i] /= edge[i].size();
    }

    ld ans = prob[0];
    REP (block, N-1) {
        FOR (j, block+1, N) dp[j] = prob[j];
        int cut = -1;
        ld mx = -1;
        FORE (e, edge[block]) if (prob[e] > mx) {
            cut = e;
            mx = prob[e];
        }
        dp[block] = 0;
        FORE (to, edge[block]) if (cut != to) {
            dp[block] += (1 + dp[to]);
        }
        dp[block] /= (edge[block].size() - 1);
        REPR (j, block) {
            dp[j] = 0;
            FORE (to, edge[j]) dp[j] += (1 + dp[to]) / edge[j].size();
        }
        if (dp[0] > 0) ans = min(ans, dp[0]);
    }
    return ans;
}

