ld inv(int b) {
  for (int i = 1; i <= n; i++)
    dp[i] = 0, deg[i] = sz(adj[i]);
  deque<int> pq;
  pq.pb(n);
  while (sz(pq)) {
    int u = pq.front(); pq.pop_front();
    if (u != n) {
      ld d = sz(adj[u]);
      if (u == b && sz(adj[u]) > 1) {
        ld mx = 0;
        int i = -1;
        trav(v, adj[u]) {
          if (dp[v] > mx)
            i = v;
          mx = max(mx, dp[v]);
        }
        dp[u] -= mx;
        d--;
      }
      dp[u] /= d;
      dp[u] += 1;
    }
    trav(v, radj[u]) {
      deg[v]--;
      dp[v] += dp[u];
      if (!deg[v])
        pq.pb(v);
    }
  }
  return dp[1];
}

