#include <bits/stdc++.h>
using namespace std;
int s[200000], t[200000];
vector<int> g[601];
bool vis1[601][601], vis2[601][601];
double P1[601][601], P2[601][601];
int main(){
    int n, m;
    scanf("%d%d", &n, &m);
    for(int i=1;i<=m;i++){
        scanf("%d%d", &s[i], &t[i]);
        g[s[i]].push_back(t[i]);
    }

    vis1[1][0] = 1;
    P1[1][0] = 1;
    for(int u=1;u<=n;u++){
        for(int d=0;d<=n;d++){
            if(vis1[u][d]){
                int sz = g[u].size();
                for(int i=0;i<sz;i++){
                    int v = g[u][i];
                    P1[v][d+1] += P1[u][d]*1/sz;
                    vis1[v][d+1] = 1;
                }
            }
        }
    }

    vis2[n][0] = 1;
    P2[n][0] = 1;
    for(int u=n-1;u>=1;u--){
        for(int d=1;d<=n;d++){
            int sz = g[u].size();
            for(int i=0;i<sz;i++){
                int v = g[u][i];
                if(vis2[v][d-1]){
                    P2[u][d] += P2[v][d-1];
                    vis2[u][d] = 1;
                }
            }
            P2[u][d] /= sz;
        }
    }

    double ans = 0, tmp = 0;
    for(int i=0;i<=n;i++) ans += P1[n][i]*i;
    tmp = ans;

    int cnt = 0;
    for(int u=1;u<=n;u++){
        if(g[u].size() <= 1) continue;

        double res = tmp, mx = 0;
        int sz = g[u].size();
        for(int i=0;i<sz;i++){

            cnt++;
            int v = g[u][i];
            double sum = 0, sum2 = 0;
            for(int d1=0;d1<=n;d1++){
                if(!vis1[u][d1]) continue;
                for(int d2=0;d2<=n;d2++){
                    if(!vis2[v][d2]) continue;
                    double P = P1[u][d1]*P2[v][d2]*(d1+d2+1);
                    sum -= P/sz;
                    sum += P/(sz-1);
                    sum2 += P/(sz-1);
                }
            }

            res += sum;
            mx = max(mx, sum2);
        }
        ans = min(ans, res-mx);
    }
    printf("%.10f\n", ans);
}

