	for (int i = 0;i < M;i++) {
		tie(s, t) = E[i];
		sz = G[s].size();
		if (sz == 1)continue;
		tp = cost[s] - (cost[t] + 1.0) / sz;
		tp *= (double)sz / (sz - 1);
		tp = (cost[s] - tp) * les[s];
		ans = max(tp, ans);
	}
	printf("%.10f", cost[1] - ans);
}

