using namespace std;


void solve(long long N, long long M, std::vector<long long> s, std::vector<long long> t){
    vector<vector<int>> path(N);
    for(int i = 0; i < M; i++)
    {
        path[s[i] - 1].push_back(t[i] - 1);
    }

    vector<double> dp(N);
    dp[N-1] = 0;
    for(int i = N - 2; i >= 0; i--)
    {
        double sum = 0.0;
        for(auto k:path[i])
        {
            sum += dp[k];
        }

        dp[i] = sum / path[i].size() + 1.0;
    }

    double ans = dp[0];
// どの点から伸びた辺を着るか
    for(int i = 0; i < N - 1; i++)    
    {
        if(path[i].size() == 1) {continue;}

        int maxk = path[i][0];

        // つながった先の最大の期待値を除く
        for(auto k: path[i])
        {
            if(dp[maxk] < dp[k]) {maxk = k;}
        }

        double updated_e = [&] {
            vector<double> dp(N);
            dp[N - 1] = 0;
            for (int v = N - 2; v >= 0; v--)
            {
                double sum = 0.0;
                for (auto k : path[v])
                {
                    if(v == i && k == maxk) { continue; }
                    sum += dp[k];
                }
                int deg = path[v].size();
                if(v == i) deg -= 1;

                dp[v] = sum / deg + 1.0;
            }
            return dp[0];
        }();

        // 全頂点から切った結果得られた期待値のうち最小値
        ans = min(ans, updated_e);
    }
    printf("%.10f\n", ans);
}

