	for(int i = 0; i < m; ++i) {
		int v = fetch<int>() - 1;
		int u = fetch<int>() - 1;

		g[v].push_back(u);
	}

	dp[n - 1] = 0.;

	for(int v = n - 2; v >= 0; --v) {
		heavy[v] = g[v].front();

		for(auto& u: g[v]) {
			dp[v] += dp[u];

			if(dp[u] > dp[heavy[v]]) {
				heavy[v] = u;
			}
		}

		dp[v] /= len(g[v]);
		dp[v] += 1.;
	}

	DBG(dp[0]);
	double answ = dp[0];

	for(int v = 0; v < n; ++v) {
		if(len(g[v]) < 2) {
			continue;
		}

		for(int u = 0; u < n; ++u) {
			dp2[u] = 0.;
		}

		for(int u = n - 2; u >= 0; --u) {
			for(auto& w: g[u]) {
				if(w == heavy[u] && u == v) {
					continue;
				}

				dp2[u] += dp2[w];
			}

			dp2[u] /= len(g[u]) - (u == v);
			dp2[u] += 1.;
		}

		answ = min(answ, dp2[0]);
	}

	cout << fixed << setprecision(12) << answ << '\n';
}

