inline int cmp(ld a, ld b) {
    return (a < b - EPS) ? -1 : ((a > b + EPS) ? 1 : 0);
}

ld solve(int u, int ban) {
    if (dp[u] != -1) return dp[u];

    int num = 0;

    FOR(i,0,SZ(a[u])-1) {
        int idx = a[u][i].SE;
        if (idx == ban) continue;
        num++;
    }

    ld res = 0;
    FOR(i,0,SZ(a[u])-1) {
        int v = a[u][i].FI;
        int idx = a[u][i].SE;
        if (idx == ban) continue;
        res += 1.0 / num * (solve(v, ban) + 1);
    }

    if (cmp(res, 0) == 0) res = -1000000000;

    return dp[u] = res;
}

