        a[u].emplace_back(II(v, i));
        A[u][v] = i;
    }

    FOR(i,1,n) dp[i] = -1;
    dp[n] = 0;
    ld res = solve(1, 0);
    FOR(i,1,n) {
        int pos = 0;
        ld Max = 0;
        FOR(j,0,SZ(a[i])-1) {
            int v = a[i][j].FI;
            if (dp[v] > Max) {
                Max = dp[v];
                pos = v;
            }
        }
        if (pos > 0) check[i] = pos;
    }

    FOR(i,1,n) {
        if (!check[i]) continue;
        FOR(j,1,n) dp[j] = -1;
        dp[n] = 0;
        int edge = A[i][check[i]];
        ld x = solve(1, edge);
        if (cmp(x, 0) <= 0) continue;
        // cout << i << ' ' << x << endl;
        res = min(res, x);
    }

    cout << fixed << setprecision(9) << res;
    return 0;
}

