		RFOR(i, a, -1) {
			es2[i] = 0;
			for (auto j : gr[i]){
				if (i!=a or j!=b) es2[i] += 1 + es2[j];
			}
			es2[i] /= cnt[i];
		}
		res = min(res, es2[0]);
		cnt[a]++;
	}
	cout << fixed << setprecision(10) << res;
	return 0;
}

