vector<int> adj[605];

double memo[605][5];

double dp(int x, int done){
	if(x == n) return 0.0;
	double &ret = memo[x][done];
	if(ret>=0.0) return ret;
	ret = 0;
	for(int i=0;i<adj[x].size();i++){
		int cur = adj[x][i];
		ret += dp(cur,done)+1;
	}
	double lol = ret/adj[x].size();
	ret = lol;
	if(done!=1 && adj[x].size() > 1){
		double lol2;
		double lala = 0.0;
		for(int i=0;i<adj[x].size();i++){
			int cur = adj[x][i];
			lala += dp(cur,1)+1;
		}
		lol2 = lala;
		for(int i=0;i<adj[x].size();i++){
			int cur = adj[x][i];
			double now = lala - dp(cur,1) - 1;
			lol2 = min(lol2,now);
		}
		lol2/=(adj[x].size()-1);
		ret = min(ret,lol2);
	}
	return ret;
}

