using namespace std;
template <class T, class U> inline void chmin(T & a, U const & b) { a = min<T>(a, b); }

double solve(int n, int m, const vector<vector<int> > & g) {
    vector<double> e(n, INFINITY);
    e[n - 1] = 0;
    REP_R (i, n - 1) {
        double acc = 0;
        for (int j : g[i]) {
            acc += e[j];
        }
        e[i] = 1 + acc / g[i].size();
    }

    vector<double> cnt(n, 0.0);
    cnt[0] = 1;
    REP (i, n - 1) {
        for (int j : g[i]) {
            cnt[j] += cnt[i] / g[i].size();
        }
    }

    double answer = e[0];
    REP (i, n - 1) if (g[i].size() >= 2) {
        double acc = (e[i] - 1) * g[i].size();
        for (int j : g[i]) {
            double updated_e_i = 1 + (acc - e[j]) / (g[i].size() - 1);
            chmin(answer, e[0] - cnt[i] * e[i] + cnt[i] * updated_e_i);
        }
    }
    return answer;
}

