long double exp_root(int n, int max, std::vector<std::pair<int, int>> r, int m, std::vector<long double> *ans, bool change) {
	std::vector<long double> ans_tmp(*ans);
	for (int i = max; i >= 1; --i) {
		std::vector<int> v;
		for (int j = 0; j < m; ++j)
			if (r[j].first == i)
				v.push_back(r[j].second);
		if (v.size() == 0) {
			ans_tmp[i] = -1;
			continue;
		}

		long double exp = 0;
		for (int j = 0; (unsigned)j < v.size(); ++j)
			if (ans_tmp[v[j]] == -1) {
				ans_tmp[i] = -1;
				break;
			}
			else exp += ans_tmp[v[j]];

		if (ans_tmp[i] != -1) ans_tmp[i] = exp / v.size() + 1;
	}

	if (change)
		*ans = ans_tmp;

	return ans_tmp[1];
}

long double erase_root(int n, std::vector<std::pair<int, int>> r, int m, int erase, std::vector<long double> ans) {
	std::vector<std::pair<int, int>> tmp(r);
	tmp.erase(tmp.begin() + erase);
	return exp_root(n, r[erase].first, tmp, m - 1, &ans, 0);
}

