	int n, m;
	std::cin >> n;
	std::cin >> m;

	std::vector<std::pair<int, int>> r(m);
	for (int i = 0; i < m; ++i) {
		std::cin >> r[i].first;
		std::cin >> r[i].second;
	}

	std::vector<long double> ans(n + 1, 0);
	long double min = exp_root(n, n - 1, r, m, &ans, 1);
	long double tmp;
	for (int i = 0; i < m; i++) 
		if ((tmp = erase_root(n, r, m, i, ans)) != -1 && tmp < min)
			min = tmp;

	std::cout << std::setprecision(10) << std::fixed << min << std::endl;
}

