int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;
    vector<vector<int>> graph(N);
    for(int i = 0; i < M; ++i){
        int s, t;
        cin >> s >> t;
        --s, --t;
        graph[s].emplace_back(t);
    }

    vector<double> dp(N, -1);
    dp[N - 1] = 0;
    auto MemoRec = [&](auto&& self, int from = 0) -> double {
        if(dp[from] != -1)  return dp[from];
        double res = 0;
        int cnt = 0;
        for(int to : graph[from]){
            ++cnt;
            res += self(self, to);
        }
        return dp[from] = res / cnt + 1;
    };
    double ans = MemoRec(MemoRec);

    for(int u = 0; u < N - 1; ++u){
        if(graph[u].size() == 1)    continue;
        double max_val = 0;
        int ban = -1;
        for(int v : graph[u]){
            if(chmax(max_val, dp[v]))   ban = v;
        }
        vector<double> dp2(N, -1);
        dp2[N - 1] = 0;
        auto MemoRec2 = [&](auto&& self, int from = 0) -> double {
            if(dp2[from] != -1) return dp2[from];
            double res = 0;
            int cnt = 0;
            for(int to : graph[from]){
                if(from == u && to == ban)  continue;
                ++cnt;
                res += self(self, to);
            }
            return dp2[from] = res / cnt + 1;
        };
        chmin(ans, MemoRec2(MemoRec2));
    }

    cout << fixed << setprecision(15);
    cout << ans << endl;
}

