	}

	long double min = exp_root(n, r, m);
	long double tmp;
	for (int i = 0; i < m; i++) 
		if ((tmp = erase_root(n, r, m, i)) != -1 && tmp < min)
			min = tmp;

	std::cout << std::setprecision(10) << std::fixed << min << std::endl;
}

