struct custom_hash
{
	static uint64_t splitmix64(uint64_t x)
	{
		x += 0x9e3779b97f4a7c15;
		x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9;
		x = (x ^ (x >> 27)) * 0x94d049bb133111eb;
		return x ^ (x >> 31);
	}

	size_t operator()(uint64_t x) const
	{
		static const uint64_t FIXED_RANDOM = chrono::steady_clock::now().time_since_epoch().count();
		return splitmix64(x + FIXED_RANDOM);
	}
};
int blocked;
int n, m;
vector<vi> g;
vector<ld> d;
vector<char> used;
ld solve(int v)
{
	if (v == n - 1)
		return d[v] = 0;
	if (used[v])
		return d[v];
	used[v] = 1;
	int sz = g[v].size();
	ld sum = 0;
	ld mx = 0;
	for (auto to : g[v])
	{
		sum += solve(to);
		mx = max(mx, d[to]);
	}
	if (v == blocked && sz > 1)
		sz--, sum -= mx;
	return d[v] = sum / sz + 1;
}
signed main()
{
	//freopen(".in", "r", stdin);
