	ld ans = solve(0);
	for (int i = 0; i <n; i++)
	{
		d.assign(n, 0);
		used.assign(n, 0);
		blocked = i;
		ans = min(ans, solve(0));
	}
	cout << setprecision(9) << fixed << ans << '\n';
}

#include<bits/stdc++.h>
using namespace std;
const int maxn=610;
int n,m;
double f[maxn],a[maxn],b[maxn];
vector<int> G[maxn];
void solve(){
    scanf("%d%d",&n,&m);
    for(int i=1,u,v;i<=m;++i){
        scanf("%d%d",&u,&v);//confirm u is less than v
        G[u].push_back(v);
    }
    f[n]=0;
    for(int u=n-1;u;--u){
        for(auto v: G[u]){
            f[u]+=f[v]+1;
        }
        f[u]/=G[u].size();
    }
    double ans=f[1],Delta;
    //cout<<ans<<endl;//cerr<<ans<<endl;
    for(int s=1;s<n;++s){
        if(G[s].size()<=1)continue;
        a[s]=1;
        b[s]=0;
        for(int i=s+1;i<=n;++i){
            b[i]=f[i];
            a[i]=0;
        }
        for(int i=s-1;i;--i){
            a[i]=0;b[i]=0;
            if(G[i].size()<1)continue;
            for(auto v:G[i]){
                a[i]+=a[v];
                b[i]+=b[v]+1;
            }
            a[i]/=G[i].size();
            b[i]/=G[i].size();
        }
        for(auto v: G[s]){
            Delta=(f[s]*G[s].size()-f[v]-1)/(G[s].size()-1);
            ans=min(ans,a[1]*Delta+b[1]);
        }
    }
    printf("%lf\n",ans);
}
int main(){
    solve();
    return 0;
}

