using namespace std;

int N, M, EDGE_COUNT[600];

double ex(double prev_ex[], list<int> edges[], int index, bool set_edge_count) {
  list<int> e = edges[index];
  int edge_count = 0;
  double sum = 0;
  for (list<int>::iterator it = e.begin(); it != e.end(); it++) {
    edge_count++;
    sum += prev_ex[*it];
  }
  if (set_edge_count) EDGE_COUNT[index] = edge_count;
  return sum / edge_count + 1;
}

int main() {
  cin >> N >> M;
  list<int> edges[N];
  for (int i = 0; i < N; i++) edges[i] = list<int>();
  for (int i = 0; i < M; i++) {
    int s, t; cin >> s >> t;
    edges[s-1].push_back(t-1);
  }
  double ex_init[N]; ex_init[N-1] = 0;
  for (int i = N - 2; i >= 0; i--) ex_init[i] = ex(ex_init, edges, i, true);
  double min = ex_init[0];
  for (int s = N - 2; s >= 0; s--) {
    if (EDGE_COUNT[s] <= 1) continue;
    double ex_new[N];
    for (int i = N - 1; i > s; i--) ex_new[i] = ex_init[i];
    for (int i = 0; i < EDGE_COUNT[s]; i++) {
      int t = *(edges[s].begin());
      edges[s].pop_front();
      for (int j = s; j >= 0; j--) ex_new[j] = ex(ex_new, edges, j, false);
      if (ex_new[0] < min) min = ex_new[0];
      edges[s].push_back(t);
    }
  }
  cout << setprecision(10) << min << endl;
}

