const int N = 600;
vector<int> adj[N];
double dp[N], dpr[N], prob[N];

int main(){
    int n, m;
    scanf("%d %d", &n, &m);
    for(int i = 0; i < m; i++){
        int u, v;
        scanf("%d %d", &u, &v);
        adj[u - 1].push_back(v - 1);
    }
    dp[n - 1] = 0;
    for(int u = n - 2; u >= 0; u--){
        double curr = 0;
        int sz = adj[u].size();
        for(int v: adj[u]) curr += dp[v];
        dp[u] = 1 + curr / sz;
        dpr[u] = dp[u];
        if(sz > 1) for(int v: adj[u]) dpr[u] = min(dpr[u], 1 + (curr - dp[v]) / (sz - 1));
    }
    prob[0] = 1;
    for(int u = 0; u < n - 1; u++){
        double pj = prob[u] / adj[u].size();
        for(int v: adj[u]) prob[v] += pj;
    }
    double ans = dp[0];
    for(int u = 0; u < n - 1; u++) ans = min(ans, dp[0] - prob[u] * (dp[u] - dpr[u]));
    printf("%.10lf", ans);
    return 0;
}

