double sub_dp(int i, const std::vector<std::vector<int>> &from) {
  int N = from.size();
  std::vector<double> dp(N);

  for(int j = N - 2; j >= 0; --j) {
    if(from[j].size() == 1) {
      dp[j] = dp[from[j][0]] + 1;
    } else {
      dp[j] = 0;
      for(int t : from[j]) {
        dp[j] += dp[t];
      }

      if(i == j) {
        int argmax = from[j][0];
        double max = dp[argmax];
        for(int t : from[j]) {
          if(dp[t] > max) {
            max = dp[t];
            argmax = t;
          }
        }
        dp[j] -= max;
        dp[j] /= from[j].size() - 1;
        ++dp[j];
      } else {
        dp[j] /= from[j].size();
        ++dp[j];
      }
    }
  }

  return dp[0];
}

