inline void fast_io() { ios_base::sync_with_stdio(false); cin.tie(nullptr); cout.tie(nullptr); };
inline void chmin(double &a, double b){if(a > b) a = b;}

int N, M;
vector<vector<int> > G;
void input(){
    fast_io();
    cin >> N >> M;
    G.resize(N);
    for (int i = 0; i < M; i++)
    {
        int s,t; cin >> s >> t;
        s--, t--;
        G[s].push_back(t);
    }
    for (int i = 0; i < N; i++) sort(G[i].begin(),G[i].end(),greater<int>());
}

int solve(){
    vector<double> dp(N,0);
    dp[N-1] = 0;
    for (int i = N - 1; i >= 0; i--)
    {
        for(auto t:G[i]){
            dp[i] += (dp[t]+1)/G[i].size();
        }
    }
    double ans = dp[0];

    for (int i = N - 1; i >= 0; i--)
    {
        if(G[i].size()<=1) continue;
        // N-1に到達できないようなカットはしない.
        double dp_max = 0;
        int cut_idx = 0;
        for(auto t:G[i]){
            if(dp[t] > dp_max){
                cut_idx = t;
                dp_max = dp[t];
            }
        }
        // i->tのうちdp[t]が最大のものの辺をカットする
        // カットするindexをcut_idxとする
        vector<double> dp_i(N, 0);
        for (int s = N-1; s >= 0; s--)
        {
            for(auto t:G[s]){
                if(s==i && t==cut_idx) continue;
                if(s==i) dp_i[s] += (dp_i[t]+1)/(G[s].size()-1);
                else dp_i[s] += (dp_i[t]+1)/(G[s].size());
            }
        }
        chmin(ans, dp_i[0]);
    }
    cout << fixed << setprecision(10) << ans << endl;
    return 0;
}

int main()
{
    input();
    solve();
    return 0;
}

