int main() {

  ios::sync_with_stdio(false);
  cout.tie(nullptr);
  cin.tie(nullptr);

  int n, m;
  cin >> n >> m;

  vector<vector<int>> g(n + 5);
  for (int i = 0; i < m; ++i) {
    int u, v;
    cin >> u >> v;

    g[u].push_back(v);
  }

  auto calc = [&](vector<double> &d, int x) {
    for (auto to : g[x])
      d[x] += d[to];
    d[x] /= g[x].size();
    d[x]++;
  };

  vector<double> dp(n + 5, 0);
  for (int i = n - 1; i > 0; --i) {
    calc(dp, i);
  }

  double ans = dp[1];
  for (int i = n - 1; i > 0; --i) {
    if (g[i].size() == 1) continue;
    vector<double> cur(n + 5, 0);
    double mx = 0;
    for (auto to : g[i])  mx = max(mx, dp[to]);
    for (int j = n - 1; j > 0; --j) {
      if (j > i)  cur[j] = dp[j];
      else if (j == i)  {
        if (g[j].size() == 1) cur[j] = 0;
        else cur[j] = (dp[j] * g[j].size() - mx - 1) / (g[j].size() - 1);
      }
      else calc(cur, j);
    }
    ans = min(ans, cur[1]);
  }
  cout << ans << '\n';  
}

