void dfs(int x) {
    if (++ver[x].cnt < ver[x].from.size()) return;
    for (auto &i : ver[x].to) {
        ver[i].prob += ver[x].prob / ver[x].to.size();
        dfs(i);
    }
}

void bdfs(int x) {
    if (++ver[x].bcnt < ver[x].to.size()) return;
    if (x != n - 1) ver[x].weight /= ver[x].to.size();
    for (auto &i : ver[x].from) {
        ver[i].weight += ver[x].weight + 1.0; 
        bdfs(i);
    }
}

