    jdg[0] = true;
    for (int i = 0; i < m; i++) {
        if (jdg[p[i].first - 1]) {
            jdg[p[i].second - 1] = true;
            ver[p[i].first - 1].to.emplace(p[i].second - 1);
            ver[p[i].second - 1].from.emplace(p[i].first - 1);
        }
    }

    ver[0].prob = 1.0; 
