queue<ll> q;
ll vis[M],deg[M];
ld pr[M],dp[M],dp2[M],out[M];
vector<ll> adj[M];

void dfs(ll u)
{
	vis[u] = 1;
	ld mn = 0;
	for(auto v:adj[u])
	{
		if(vis[v] == 0)
			dfs(v);
		dp[u] += dp[v]+1;
		mn = max(mn,dp[v]+1.0);
	}
	if(adj[u].empty())
		return;
	ll sz = adj[u].size();
	if(sz > 1)
	{
		dp2[u] = (dp[u]-mn);
		dp2[u] /= (ld)(sz-1);
	}
	dp[u] /= (ld)(sz);
	// cout << u << " " << sz << " " << dp[u] << " " << dp2[u] << "\n";
	return;
}

