	ans = dp[1];
	// cout << ans << endl;

	while(!q.empty())
	{
		u = q.front();
		q.pop();
		ans = min(ans,dp[1]-pr[u]*dp[u]+pr[u]*dp2[u]);
		for(auto v:adj[u])
		{
			deg[v]--;
			pr[v] = pr[v] + (pr[u]/out[u]);
			if(deg[v] == 0)
				q.push(v);
		}
	}

	cout << setprecision(12) << ans << "\n";
