double cal_min_estimate(const std::vector<std::vector<int>> rooms, const int current_room, const int remove, std::vector<double>& memo) {
	if (current_room + 1 == rooms.size()) 
		return 0;
	if (memo[current_room] >= 0) return memo[current_room];
	if (current_room == remove) {
		double sum = 0;
		double max = 0;
		for (const auto next : rooms[current_room]) {
			const auto res = cal_min_estimate(rooms, next, remove, memo);
			sum += res;
			max = std::max(max, res);
		}
		return memo[current_room] = std::min((sum - max) / (rooms[current_room].size() - 1), sum / rooms[current_room].size()) + 1;
	}
	else {
		double sum = 0;
		for (const auto next : rooms[current_room]) {
			sum += cal_min_estimate(rooms, next, remove, memo);
		}
		return memo[current_room] = sum / rooms[current_room].size() + 1;
	}
}
int main() {
	std::cin.tie(0); std::cin.sync_with_stdio(false);
	int n, m; std::cin >> n >> m;
	std::vector<std::vector<int>> rooms(n);
	for (auto i = 0; i < m; ++i) {
		int s, t; std::cin >> s >> t;
		rooms[s - 1].push_back(t - 1);
	}
	std::vector<double> memo(n, -1);
	double min = cal_min_estimate(rooms, 0, -1, memo);
	for (auto i = 0; i < n - 1; ++i) if (rooms[i].size() > 1) {
		std::fill(memo.begin(), std::next(memo.begin(), i + 1), -1);
		min = std::min(min, cal_min_estimate(rooms, 0, i, memo));
	}
	std::cout << std::setprecision(15) << std::fixed << min << '\n';
}

