double dfs(int u, vector<double> &dp, vector<vector<LL>> &graph, pair<LL, LL> &ng) {
    double ans = 0;

    int N = LEN(graph);
    if (u == N - 1) {
        return 0;
    }

    int num = LEN(graph[u]);
    FOE(v, graph[u]) {
        if (num != 1 and u == ng.first and v == ng.second) {
            num--;
            continue;
        }
        ans += dfs(v, dp, graph, ng);
    }

    ans *= 1.0 / num;
    ans += 1;

    return dp[u] = ans;
}

