int main(){
  long long int N, M, tmp1, tmp2;
  scanf("%lld%lld", &N, &M);

  std::vector<std::vector<long long int> > G(N);
  for(long long int i = 0; i < M; i++){
    scanf("%lld%lld", &tmp1, &tmp2);
    G[tmp1-1].push_back(tmp2-1);
  }

  double E, tmpd1, tmpd2;

  // calculate the expectation value with no operation
  std::vector<double> exp_list(N);
  for(long long int i = 0; i < N; i++){
    exp_list[i] = 0.0;
  }
  for(long long int i = N-2; i >= 0; i--){
    tmp1 = G[i].size();
    for(long long int j = 0; j < tmp1; j++){
      exp_list[i] += exp_list[G[i][j]]/(tmp1*1.0);
    }
    exp_list[i] += 1.0;
  }
  E = exp_list[0];

  // operation on a edge starting from s-th vertex
  for(long long int s = 0; s < N-1; s++){
    // if it is impossible to remove a edge starting from i-th vertex
    if(G[s].size() == 1){
      continue;
    }
    // initialize exp_list
    for(long long int i = 0; i < N; i++){
      exp_list[i] = 0.0;
    }
    for(long long int i = N-2; i >= 0; i--){
      // if there is no operation
      if(i != s){
        tmp1 = G[i].size();
        for(long long int j = 0; j < tmp1; j++){
          exp_list[i] += exp_list[G[i][j]]/(tmp1*1.0);
        }
        exp_list[i] += 1.0;
      }
      // if there is operation
      else{// if(i == s)
        // determine the edge to operate: remove the edge to the vertex biggest expectation value
        tmp1 = G[i].size();
        tmpd1 = exp_list[G[i][0]];
        tmp2 = 0;
        for(long long int j = 0; j < tmp1; j++){
          if(exp_list[G[i][j]] > tmpd1){
            tmpd1 = tmpd2;
            tmp2 = j;
          }
        }
        // determine expectation value of the point
        for(long long int j = 0; j < tmp1; j++){
          if(j != tmp2){
            exp_list[i] += exp_list[G[i][j]]/((tmp1-1)*1.0);
          }
        }
        exp_list[i] += 1.0;
      }
    }

    if(E > exp_list[0]){
      E = exp_list[0];
    }
  }

  std::cerr << "Answer:" << std::endl;
  std::cout << std::setprecision(12) << E << std::endl;

  return 0;
}

