      }
      if(i == j && nn >= 2) {
	nn--;
	tt -= ma;
      }
      dp2[j] = tt / nn + 1;
    }
    if((i == 0 && g[i].size() == 1) || dp2[0] == 1) continue;
    ans = min(ans,dp2[0]);
