    {
        // cout << m << endl;
        //! 通路iを禁止する
        queue<Node> q;
        q.push(Node{0LL, 1.0, 0LL});
        REP(i, N)
        {
            V[i].count = 0;
            V[i].E = 0;
            V[i].E2 = 0;
        }

        REP(i, N)
        {
            REP(j, N)
            {
                C[i][j] = 0;
            }
        }
        C[0][0] = 1.0;
        bool exist = true;
        while (!q.empty())
        {
            auto t = q.front();
            q.pop();
            if (t.index == N - 1)
            {
                break;
            }
            ll num = 0;
            REP(i, V[t.index].node.size())
            {
                auto node = V[t.index].node[i];
                if (m == node.second)
                    continue;
                num++;
            }
            if (num == 0)
            {
                exist = false;
                break;
            }
            REP(i, V[t.index].node.size())
            {
                auto node = V[t.index].node[i];
                V[node.first].count++;
                if (m != node.second)
