                        newNode.E = C[node.first][j];
                        newNode.cost = j + 1;
                        q.push(newNode);
                    }
                }
            }
        }

        if (!exist)
            continue;
        double e = 0;
        REP(i, N)
        {
            e += C[N - 1][i] * i;
        }
