        }
        sort(tmp.begin(), tmp.end());
        for (int j = 0; j < len - 1; j++) {
          dp[i] += tmp[j] + 1;
        }
        dp[i] /= (len - 1);
        cout << "OK" << endl;
      } else {
        for (int j = 0; j < len; j++) {
          dp[i] += dp[st[i][j]] + 1;
        }
        dp[i] /= len;
      }
    }
    ret = min(ret, dp[1]);
  }

  cout.precision(10);
  cout << ret << endl;
}

