#define REP(i,s,n) for(int i=s;i<n;++i)
#define rep(i,n) REP(i,0,n)
#define ALL(x) x.begin(),x.end()
#define EPS (1e-9)
#define equals(a,b) (fabs((a)-(b))<EPS)

using namespace std;

typedef long long ll;

bool LT(double a,double b) { return !equals(a,b) && a < b; }
bool LTE(double a,double b) { return equals(a,b) || a < b; }

bool debug = 1;
#define MAX 800
int V,E;
vector<int> G[MAX];
double dp[MAX], dp2[MAX];

void compute() {
  for(int i=V-2;i>=0;--i) {
    rep(j,(int)G[i].size()) {
      int nex = G[i][j];
      dp[i] += (dp[nex] + 1.0);
    }
    dp[i] /= (double)G[i].size();
  }
  double answer = dp[0];
  for(int i=V-2;i>=0;--i) if( G[i].size() >= 2 ) {
    int pos = -1;
    double sum = 0;
    rep(j,(int)G[i].size()) {
      int nex = G[i][j];
      if( pos == -1 ) pos = nex;
      else if( LT(dp[pos],dp[nex]) ) pos = nex;
      sum += ( dp[nex] + 1.0 );
    }
    assert( pos != -1 );
    sum -= ( dp[pos] + 1.0 );
    dp2[i] = sum / (double)( (int)G[i].size() - 1 );

    for(int j=i-1;j>=0;--j) {
      dp2[j] = 0;
      rep(k,(int)G[j].size()) {
	int nex = G[j][k];
	if( nex <= i ) dp2[j] += ( dp2[nex] + 1.0 );
	else           dp2[j] += ( dp[nex]  + 1.0 );
      }
      dp2[j] /= (double)G[j].size();
    }
    if( LT(dp2[0],answer) ) answer = dp2[0];
  }
  printf("%.10f\n",answer);
}

int main() {
  cin >> V >> E;
  int s,t;
  rep(_,E) {
    cin >> s >> t;
    --s, --t;
    G[s].push_back(t);
  }
  compute();
  return 0;
}

