//posからNまでいく期待値
Int used[610][610];
Double mem[610][610];
Double dfs(Int pos, Int ng){
  if(pos == N-1) return 0;
  if(used[pos][ng]++) return mem[pos][ng];
  Double sum = 0;
  Int n = 0;
  for(auto p:G[pos]){
    Int to, id; tie(to, id) = p;
    if(id == ng) continue;
    sum += 1 + dfs(to, ng);
    n++;
  }
  Double E = sum / n;
  return mem[pos][ng] = E;
}

