  }
  //隣接リスト表現に変換
  vector<set<int>> L(N);
  //L[i] = 部屋iから行ける部屋
  for (int i = 0; i < M; i++){
    L[s[i]].insert(t[i]);
  }
  //道をふさがないで計算
  vector<double> Etime(N);
  for (int i = 0; i < N; i++){
    Etime[i] = 0;
  }
  for (int i = N - 2; i >= 0; i--){
    int count = 0;
    for (int j : L[i]){
      Etime[i] += Etime[j] + 1;
      count++;
    }
    Etime[i]/=count;
  }
  double Emin = Etime[0];
  //道をふさぐ
  for (int i = 0; i < M; i++){
    bool inv = false;
    int S = s[i];
