// binary search.
i64 bin(const std::function<bool(i64)> &pred, i64 ok, i64 ng)
{
    while(std::abs(ok - ng) > 1)
    {
        i64 mid = (ok + ng) / 2;
        (pred(mid) ? ok : ng) = mid;
    }
    return ok;
}
double bin(const std::function<bool(double)> &pred, double ok, double ng, const double eps)
{
    while(std::abs(ok - ng) > eps)
    {
        double mid = (ok + ng) / 2;
        (pred(mid) ? ok : ng) = mid;
    }
    return ok;
}
