void __solve()
{
    i32 n,m; cin>>n>>m;
    bool to[666][666]={};
    i32 in[666]={},out[666]={};
    vector<pii> e(m);
    for(i32 i=0; i<m; ++i)
    {
        i32 s,t; cin>>s>>t; --s,--t;
        e[i]={s,t};
        to[s][t]=1;
        in[t]++;
        out[s]++;
    }   

    vector<double> dp(n);
    dp[n-1]=0;
    for(i32 i=n-2; i>=0; --i)
    {
        for(i32 j=i+1; j<n; ++j)
        {
            if(to[i][j])
            {
                dp[i]+=dp[j];
            }
        }
        dp[i]/=double(out[i]);
        dp[i]+=1.0;
    }

    double ans=dp[0];

    for(i32 i=0; i<n-1; ++i)
    {
        if((in[i]>0 || !i) and out[i]>1)
        {
            i32 t=-1;
            double maxe=-1;
            for(i32 j=i+1; j<n; ++j)
            {
                if(to[i][j] and sbmax(maxe,dp[j]))
                {
                    t=j;
                }
            }
            assert(t!=-1);
            to[i][t]=0;
            out[i]--;
            vector<double> dp2(n);
            dp2[n-1]=0;
            for(i32 i=n-2; i>=0; --i)
            {
                for(i32 j=i+1; j<n; ++j)
                {
                    if(to[i][j])
                    {
                        dp2[i]+=dp2[j];
                    }
                }
                dp2[i]/=double(out[i]);
                dp2[i]+=1.0;
            }
            sbmin(ans,dp2[0]);
            to[i][t]=1;
            out[i]++;
        }
    }

    cout << ans << "\n";
}

