	REP(i, m) {
		cin >> a >> b;
		a--;
		b--;
		v.push_back(P(a, b));
		gr[a].insert(b);
		cnt[a]++;
	}
	vector<double> es(n);
	RREP(i, n - 1) {
		for (auto j : gr[i]) es[i] += 1 + es[j];
		es[i] /= cnt[i];
	}
	vector<double> maxval(n);
	vector<int> cand(n);
	REP(i, n) cand[i] = -1;
	REP(i, m) {
		a = v[i].first;
		b = v[i].second;
		if (maxval[a] < es[b]) {
			maxval[a] = es[b];
