double ch(vector<vector<int>> &da,int n,int x,int y){
	vector<double> dp(n,0);
	for(int i=n-1;i>-1;i--){
		int si = da[i].size();
		if(i == x){
			si--;
		}
		rip(j,da[i].size(),0){
			if(i==x && j==y){
				continue;
			}
			dp[i]+=(double)(dp[da[i][j]]+1)/si;
		}
	}
	return dp[0];
}

