      if (pr[i] == 0) continue;
      cnt[i] /= pr[i];
      if (p == i) c--;
      for(auto& e: graph[i]) {
        if (p == i && q == e) continue;
        pr[e] += pr[i]/c;
        cnt[e] += (cnt[i]+1)*pr[i]/c;
      }
    }
    debug(p, q, cnt[n-1]);
    chmin(ans, cnt[n-1]);
  }

  cout << setprecision(10) << fixed << ans << endl;
}

