	}
	vector<double>dp(N);
	dp[N - 1] = 0;
	for (int i = N - 2; i >= 0; --i) {
		double  now = 0;
		for (auto j : to[i]) {
			now += dp[j];
		}
		now /= to[i].size();
		now += 1;
		dp[i] = now;
	}
	double ans = dp[0];

	for (int i = 0;i<N-1;++i) {
		if (1 == to[i].size()) {
			continue;
		}
		int nu = to[i][0];
		for (auto j : to[i]) {
			if (dp[nu] < dp[j]) {
				nu = j;
			}
		}
		vector<double>dp0(N);
		dp0[N - 1] = 0;
		for (int j = N - 2; j >= 0; --j) {
