const int N = 600 + 5;
double E[N];
vector<int> g[N];

int main(){
	cin.tie(0);
	cout.tie(0);
	ios_base::sync_with_stdio(0);
	cout.precision(13);
	int n,m;
	cin >> n >> m;
	for(int i = 0;i < m; ++i){
		int x,y;
		cin >> x >> y;
		g[x].push_back(y);
	}
	// rememeber base case
	E[n] = 0;
	for(int i = n-1; i >= 1; --i){
		// not takeys	
		int cnt = g[i].size();
		double esum = cnt; // add trans, keep image
		for(int to: g[i]){
			esum += E[to];
		}
		E[i] = esum/cnt;
	}
	double D[N] = {};
	double ans = E[1];
	const double inf = 1e18;
	for(int u = 1; u <= n; ++u){
		if(g[u].size() > 1){
			int cnt = g[u].size();
			fill(D,D + sizeof(D)/sizeof(double), 0);
			D[u] = inf;
			for(int v: g[u]){
				D[u] = min(D[u], (E[u]*cnt - E[v] - 1)/(cnt-1));
			}
			for(int i = u-1; i >= 1; --i){
				int cnt = g[i].size();
				double esum = cnt;
				for(int to: g[i]){
					esum += (to <= u? D[to] : E[to]);
				}
				D[i] = esum/cnt;
			}
			ans = min(ans, D[1]);
		}
	}
	cout << ans << '\n';
}

