    double x = dp[v]*deg/(deg-1);
    for (int u : to[v]) {
      double nx = x - (dp[u]+1)/(deg-1);
      ans = min(ans, dp[0] + p1[v]*(nx-dp[v]));
    }
  }

  printf("%.10f\n", ans);
