		for (int j = 0; j < N; j++) {
			count += matrix[i][j];
		}
		if (count > 0) {
			for (int j = 0; j < N; j++) {
				matrix[i][j] = matrix[i][j] / (double)count;
			}
		}
	}

	double* E = new double[N];
	int* ans = new int[N];
	for (int i = 0; i < N; i++) {
		E[i] = 0;
		ans[i] = -1;
	}

	int j = M - 1;
	for (int i = N - 2; i >= 0; i--) {
		double e = 0;// 最も悪い行き先
		double sum = 0;// 合計
		double count = 0;// 行き先の数
		while (j >= 0 && input[j].first == i) {
			if (E[input[j].second] > e) {
				ans[i] = input[j].second;
				e = E[input[j].second];
			}
			sum += E[input[j].second];
			count++;
			j--;
		}
		E[i] = 1 + sum / count;
	}
	/*
	for (int i = 0; i < N; i++) {
		cout << ans[i] << endl;
	}
	cout << endl;*/

	sort(input.begin(), input.end(), compare_by_b);

	double* dp = new double[N];
	for (int i = 0; i < N; i++) {
		dp[i] = 0;
	}
	double m = E[0];

	for (int k = 0; k < N - 1; k++) {
		int count = 0;
		for (int i = 0; i < N; i++) { if (matrix[k][i] != 0) { count++; } }

		if (count == 1) { continue; }
		double rate = 1.0 / (1.0 - 1.0 / (double)count);
		for (int i = 0; i < N; i++) { matrix[k][i] *= rate; }

		for (int i = 0; i < N; i++) {
			dp[i] = 0;
		}
		matrix[k][ans[k]] = 0;
		/*
		for (int i = 0; i < N; i++) {
			for (int j = 0; j < N; j++) {
				cout << matrix[i][j] << " ";
			}
			cout << endl;
		}
		cout << endl;*/

		for (auto itr = input.begin(); itr != input.end(); itr++) {
			dp[itr->first] += (dp[itr->second] + 1.0) * matrix[itr->first][itr->second];
		}

		matrix[k][ans[k]] = 1;
		for (int i = 0; i < N; i++) { if (matrix[k][i] != 0) { matrix[k][i] = 1.0 / count; } }

		//for (int i = 0; i < N; i++) { cout << dp[i] << endl; }cout << endl;

		if (m == -1) {
			m = dp[0];
		}
		else { m = min(m, dp[0]); }
	}

	delete[] dp;

	cout << setprecision(15) << m << endl;

	return 0;
}

