ll mpow(ll a, ll b) {
  if (b == 0)
    return 1;
  else if (b % 2 == 0) {
    ll memo = mpow(a, b / 2);
    return memo * memo % MOD;
  } else
    return mpow(a, b - 1) * a % MOD;
}
ll lpow(ll a, ll b) {
  if (b == 0)
    return 1;
  else if (b % 2 == 0) {
    ll memo = lpow(a, b / 2);
    return memo * memo;
  } else
    return lpow(a, b - 1) * a;
}
ll gcd(ll a, ll b) {
  if (b == 0)
    return a;
  else
    return gcd(b, a % b);
}
vector<ll> kaijo_memo;
ll kaijo(ll n) {
  if (kaijo_memo.size() > n)
    return kaijo_memo[n];
  if (kaijo_memo.size() == 0)
    kaijo_memo.push_back(1);
  while (kaijo_memo.size() <= n)
    kaijo_memo.push_back(kaijo_memo[kaijo_memo.size() - 1] * kaijo_memo.size() %
                         MOD);
  return kaijo_memo[n];
}
vector<ll> gyaku_kaijo_memo;
ll gyaku_kaijo(ll n) {
  if (gyaku_kaijo_memo.size() > n)
    return gyaku_kaijo_memo[n];
  if (gyaku_kaijo_memo.size() == 0)
    gyaku_kaijo_memo.push_back(1);
  while (gyaku_kaijo_memo.size() <= n)
    gyaku_kaijo_memo.push_back(gyaku_kaijo_memo[gyaku_kaijo_memo.size() - 1] *
                               mpow(gyaku_kaijo_memo.size(), MOD - 2) % MOD);
  return gyaku_kaijo_memo[n];
}

ll nCr(ll n, ll r) {
  if (n == r)
    return 1; // 0個の丸と-1個の棒みたいな時に時に効く？不安.
  if (n < r || r < 0)
    return 0;
  ll ret = 1;
  ret *= kaijo(n);
  ret %= MOD;
  ret *= gyaku_kaijo(r);
  ret %= MOD;
  ret *= gyaku_kaijo(n - r);
  ret %= MOD;
  return ret;
}

int n, m;
list<int> G[1000];
double dp[1000], p[1000], dp2[1000];
void func(int now) {
  if (now == n - 1) {
    rep(i, n) {
      dp[i] = 0.0;
      p[i] = 0.0;
    }
    p[0] = 1.0;
  }

  int size = G[now].size();
  for (int to : G[now]) {
    dp[now] += (dp[to] + 1.0) / size;
  }
  if (now != 0)
    func(now - 1);
}

void func2(int now, double dp_val, bool init) {
  if (init) {
    rep(i, n) { dp2[i] = dp[i]; }
    dp2[now] = dp_val;
    func2(now - 1, 0, false);
    return;
  }

  if (now == -1)
    return;

  dp2[now] = 0.0;
  int size = G[now].size();
  for (int to : G[now]) {
    dp2[now] += (dp2[to] + 1.0) / size;
  }
  func2(now - 1, 0, false);
}

