    for (auto v : anss) {
        sum += v;
    }

    sort(all(anss));

    if (r == 1 and siz(anss) > 1) {
        sum -= anss[siz(anss) - 1];
        sum += siz(anss) - 1;
        sum /= (siz(anss) - 1);
    }
    else {
        sum += siz(anss);
        sum /= siz(anss);
    }

    return dp[r] = sum;
}

