        if(abs(ans_tmp)<=eps) continue;
        DBG(ans_tmp)
        ans = min(ans,ans_tmp);
    }
    cout << fixed << setprecision(10) << ans << endl;
    return 0;
}

double solveG(int es,int et, vector<vector<int>> g){
    vector<double> dp(N+1,0);
    vector<double> pr(N+1,0);
    dp[0] = 0;
    pr[0] = 1;
    for (int u = 0; u < N; u++)
    {
        if(pr[u]==0) continue;
        for(int v:g[u]){
            if(u==es && v==et) continue;
            if(u==es) pr[v] += pr[u]/(g[u].size()-1);
            else pr[v] += pr[u]/g[u].size();
        }
    }

    for (int u = 0; u < N; u++)
    {
        for(auto v:g[u]){
            if(u==es && v==et) continue;
            if(u==es) dp[v] += dp[u]/(g[u].size()-1)+pr[u]/(g[u].size()-1);
            else dp[v] += dp[u]/g[u].size()+pr[u]/g[u].size();
        }
    }
    return dp[N-1];
}

int solve(){
    double ans = solveG(N+1,N+1,G);
    for (int i = 0; i < M; i++)
    {
        int es = Edge[i].first;
        int et = Edge[i].second;
        if(G[es].size()==1) continue;
        double tmp = solveG(es,et,G);
        ans = min(ans,tmp);
    }
    cout << fixed << setprecision(10) << ans << endl;
    return 0;
}

