void BFS(int u,int x,int y){
	Cnt[y]--;
	for(int i=1;i<=N;i++)
		cnt[i]=Cnt[i],f[i]=s[i]=0;
	for(int i=2;i<=N;i++)
		if(cnt[i]==0)DBFS(i);
