	Q.push(u);f[u]=0;s[u]=1;
	while(!Q.empty()){
		u=Q.front();Q.pop();
		f[u]=f[u]/s[u];
		int size=P[u].size();
		int ssize=size-(x==u);
		for(int i=0;i<size;i++){
			int v=P[u][i];
			if(u==x&&v==y)continue;
			f[v]+=(f[u]+1)*s[u]/ssize;
			s[v]+=s[u]/ssize;
			if(--cnt[v]==0)Q.push(v);
		}
	}Cnt[y]++;
}
