double solve(int cur, const Graph<int> &g, vector<double> &dp, pair<int,int> proh){
  if(dp[cur] >= 0) return dp[cur];

  int n = 0;
  for(auto &e : g[cur]){
    if(make_pair(e.from, e.to) == proh) continue;
    n += 1;
  }

  if(n == 0){

    return INT_MAX;

  }


  double ret = 0;

  for(auto &e : g[cur]){
    if(make_pair(e.from, e.to) == proh) continue;
    ret += solve(e.to, g, dp, proh) / n;
  }

  ret += 1;

  return dp[cur] = ret;
}


