void InverseOfMatrix(ld matrix[N][N], ll order) 
{ 
    ld temp; 


    for (ll i = 0; i < order; i++) { 

        for (ll j = 0; j < 2 * order; j++) { 

            if (j == (i + order)) 
                matrix[i][j] = 1; 
        } 
    } 

    for (ll i = order - 1; i > 0; i--) { 

        if (matrix[i - 1][0] < matrix[i][0]) { 
        {
            for(ll j=0;j<order;j++)
                swap(matrix[i][j], matrix[i-1][j]);
        }
        } 
    } 

    for (ll i = 0; i < order; i++) { 

        for (ll j = 0; j < order; j++) { 

            if (j != i) { 

                temp = matrix[j][i] / matrix[i][i]; 
                for (ll k = 0; k < 2 * order; k++) { 

                    matrix[j][k] -= matrix[i][k] * temp; 
                } 
            } 
        } 
    } 

    for (ll i = 0; i < order; i++) { 

        temp = matrix[i][i]; 
        for (ll j = 0; j < 2 * order; j++) { 

            matrix[i][j] = matrix[i][j] / temp; 
        } 
    } 

    return; 
} 


