const int M = (1<<20)+5;
const int md = 1e9+7;

ll pwr(ll a,ll n,ll m)
{
	ll p=1;
	while(n>0)
	{
		if(n%2==1)
			p=(p*a)%m;
		a=(a*a)%m;
		n=n/2;
	}
	return p;
}

queue<ll> q;
ll vis[M],deg[M];
ld pr[M],dp[M],dp2[M],out[M];
vector<ll> adj[M];

void dfs(ll u)
{
	vis[u] = 1;
	ld mn = 0;
	for(auto v:adj[u])
	{
		if(vis[v] == 0)
			dfs(v);
		dp[u] += dp[v]+1;
		mn = max(mn,dp[v]+1.0);
	}
	if(adj[u].empty())
		return;
	ll sz = adj[u].size();
	if(sz > 1)
	{
		dp2[u] = (dp[u]-mn);
		dp2[u] /= (ld)(sz-1);
	}
	dp[u] /= (ld)(sz);
	dp2[u] = min(dp[u],dp2[u]);
	// cout << u << " " << sz << " " << dp[u] << " " << dp2[u] << "\n";
	return;
}

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	ll n,m,i,u,v;
	ld ans = 1e15;

	cin >> n >> m;
	for(i=1;i<=m;++i)
	{
		cin >> u >> v;
		adj[u].pb(v);
		deg[v]++;
		out[u] += 1.0;
	}
	for(i=1;i<=n;++i)
		dp2[i] = 1e15;
	dfs(1);

	q.push(1);
	pr[1] = 1.0;
	ans = dp[1];
	// cout << ans << endl;

	while(!q.empty())
	{
		u = q.front();
		q.pop();
		ans = min(ans,dp[1]-pr[u]*dp[u]+pr[u]*dp2[u]);
		for(auto v:adj[u])
		{
			deg[v]--;
			pr[v] = pr[v] + (pr[u]/out[u]);
			if(deg[v] == 0)
				q.push(v);
		}
	}

	cout << setprecision(10) << fixed << ans << "\n";
	return 0;
}

