int main(void) {
  ll i, j, k, n, m, s, t, max, now;
  scanf("%lld%lld", &n, &m);
  double p[n], ans, e[n], rp[n], re[n];
  vector<ll> vec[n], rev[n];
  for(i = 0; i < m; ++i) {
    scanf("%lld%lld", &s, &t);
    vec[--s].push_back(--t);
    rev[t].push_back(s);
  }
  for(i = 0; i < n; ++i) p[i] = e[i] = 0.0;
  p[0] = 1.0, e[0] = -1.0;
  for(i = 0; i < n - 1; ++i) for(j = 0; j < vec[i].size(); ++j) p[vec[i][j]] += p[i] / vec[i].size();
  for(i = 0; i < n - 1; ++i) {
    e[i] += 1.0;
    for(j = 0; j < vec[i].size(); ++j) e[vec[i][j]] += e[i] * p[i] / p[vec[i][j]] / vec[i].size();
  }
  ans = e[n - 1] + 1;
  for(i = 0; i < n; ++i) rp[i] = re[i] = 0.0;
  rp[n - 1] = 1.0, re[n - 1] = -1.0;
  for(i = n - 1; i >= 0; --i) for(j = 0; j < rev[i].size(); ++j) rp[rev[i][j]] += rp[i] / rev[i].size();
  for(i = n - 1; i; --i) {
    re[i] += 1.0;
    for(j = 0; j < rev[i].size(); ++j) re[rev[i][j]] += re[i] * rp[i] / rp[rev[i][j]] / rev[i].size();
  }
  for(k = 0; k < n - 1; ++k) if(vec[k].size() != 1) {
    max = 0;
    for(i = 0; i < vec[k].size(); ++i) if(re[vec[k][i]] > max) max = re[vec[k][i]], now = i;
    for(i = 0; i < n; ++i) p[i] = e[i] = 0.0;
    p[0] = 1.0, e[0] = -1.0;
    for(i = 0; i < n - 1; ++i) for(j = 0; j < vec[i].size(); ++j) if(j != now || i != k) p[vec[i][j]] += p[i] / (i == k ? vec[i].size() - 1 : vec[i].size());
    for(i = 0; i < n - 1; ++i) {
      e[i] += 1.0;
      for(j = 0; j < vec[i].size(); ++j) if(j != now || i != k) e[vec[i][j]] += e[i] * p[i] / p[vec[i][j]] / (i == k ? vec[i].size() - 1 : vec[i].size());
    }
    if(ans > e[n - 1] + 1) ans = e[n - 1] + 1;
  }
  printf("%lf", ans);
  return 0;
}

