bool G[MAX_V][MAX_V];
bool dead[MAX_V][MAX_V];

double dfs(int s) {
  if (s == n-1) return 0.0;
  double res = 0;
  int size = 0;
  rep(i, n) {
    if (G[s][i] && !dead[s][i]) {
      res += dfs(i) + 1;
      size++;
    }
  }
  res /= size;
  return res;
}

