long double compute(int n, int from, int to){
    std::fill(Expectation.begin(), Expectation.end(), 0);
    for(int i = n-2; i >= 0; --i){
        Expectation[i] /= (i == from ? In[i] - 1 : In[i]);
        Expectation[i]++;
        for(int j : Edge[i]) if(!(j == from and i == to)) 
                            Expectation[j] += Expectation[i];
    }
    return Expectation[0];
}


