    for(int i = n-2; i >= 0; --i){
        Expectation[i] /= In[i];
        Expectation[i]++;
        for(int j : Edge[i]) Expectation[j] += Expectation[i];
    } Expectation[n] = -1;
    ARG.resize(n-1, n);
    for(int i = n-1; i >= 0; --i){
        for(int j : Edge[i]) if(Expectation[ARG[j]] < Expectation[i]) ARG[j] = i;
