// no blocking: O(m) time to calculate.
// blocking one naively: n choices - O(m) to find in total. For each one, O(m) time. So O(mn).

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n, m;
    cin >> n >> m;
    vector<vector<int>> adj_list(n);
    for (int i = 0; i < m; ++i) {
        int s, t;
        cin >> s >> t;
        --s;
        --t;
        adj_list[s].push_back(t);
    }
    auto get_dists = [&](int forbidden_i, int forbidden_j) {
        vector<double> dists(n);
        for (int i = n-2; i >= 0; --i) {
            double sum_dists = 0;
            if (i != forbidden_i) {
                for (int j : adj_list[i]) {
                    sum_dists += dists[j];
                }
                dists[i] = 1 + sum_dists / adj_list[i].size();
            } else {
                for (int j : adj_list[i]) {
                    if (j != forbidden_j) {
                        sum_dists += dists[j];
                    }
                }
                dists[i] = 1 + sum_dists / (adj_list[i].size() - 1);
            }
        }
        return dists;
    };
    vector<double> real_dists = get_dists(-1, -1);
    double best = real_dists[0];
    for (int k = 0; k < n-1; ++k) {
        double largest_dist = -1;
        int largest_index = -1;
        for (int l : adj_list[k]) {
            if (real_dists[l] > largest_dist) {
                largest_index = l;
                largest_dist = real_dists[l];
            }
        }
        if (adj_list[k].size() <= 1) {
            continue;
        }
        best = min(best, get_dists(k, largest_index)[0]);
    }
    cout << setprecision(20) << best << endl;
    return 0;
}

