  REP(i, M){
    int s, t;
    cin >> s >> t;
    s--;t--;
    g[s].push_back(t);    
  }

  vector<double> dp1(N, 0);
  for(int i = N - 1; i >= 0; i--){
    if(g[i].size() == 0) continue;
    for(int v : g[i]){
      dp1[i] += dp1[v];
    }
    dp1[i] /= g[i].size();
    dp1[i] += 1;
  }

  vector<double> dp2(N, 0);
  dp2[0] = 1.0;
  for(int i = 0; i < N; i++){
    if(g[i].size() == 0) continue;
    double pr = dp2[i] / g[i].size();
    for(int v : g[i]){
      dp2[v] += pr;
    }
  }

  double ans = dp1[0];
  REP(i, N){
    if(g[i].size() <= 1) continue;    
    double tmp1 = 0, tmp2 = 0;
    for(int v : g[i]){
      tmp1 += dp1[v];
      chmax(tmp2, dp1[v]);
    }
    tmp1 -= tmp2;
    tmp1 /= (g[i].size() - 1);
    tmp1 += 1;
    chmin(ans, dp1[0] - (dp1[i] - tmp1) * dp2[i]);    
  }
  cout << fixed << setprecision(10) << ans << endl;

  return 0;
}

