using namespace std;

struct DAGProb {
    int n;
    vector<vector<int>> adj, inv;
    vector<double> dp;
    vector<bool> cans, cant;

    DAGProb(int n) : n(n), adj(n), inv(n), dp(n, numeric_limits<double>::infinity()), cans(n), cant(n) {
        dp.back() = 0;
    }
    void add_arc(int a, int b) {
        adj[a].push_back(b);
        inv[b].push_back(a);
    }
    bool ok() {
        auto f = [&](auto f, int v) -> void {
            for (int s : adj[v]) {
                if (!cans[s]) {
                    cans[s] = true;
                    f(f, s);
                }
            }
        };
        cans[0] = true;
        f(f, 0);
        auto g = [&](auto g, int v) -> void {
            for (int s : inv[v]) {
                if (!cant[s]) {
                    cant[s] = true;
                    g(g, s);
                }
            }
        };
        cant[n - 1] = true;
        g(g, n - 1);
        for (int i = 0; i < n; i++) {
            if (cans[i] && !cant[i]) return false;
        }
        return true;
    }

    double get(int a) {
        if (dp[a] != numeric_limits<double>::infinity()) return dp[a];
        int N = adj[a].size();
        double ret = 0;
        for (int b : adj[a]) {
            ret += (1 + get(b)) / N;
        }
        return dp[a] = ret;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n, m;
    cin >> n >> m;

    vector<pair<int, int>> es;
    DAGProb def(n);
    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;
        a--, b--;
        es.emplace_back(a, b);
        def.add_arc(a, b);
    }
    assert(def.ok());

    double ans = def.get(0);
    for (int i = 0; i < m; i++) {
        DAGProb dp(n);
        for (int j = 0; j < m; j++) {
            if (j != i) {
                dp.add_arc(es[j].first, es[j].second);
            }
        }
        if (!dp.ok()) continue;
        ans = min(ans, dp.get(0));
    }
    cout << setprecision(20) << fixed << ans << endl;
}

