    dp[0][0] = 1;
    for (int i = 0; i < N; i++)
    {
        for (int X = 0; X < N; X++)
        {
            if(dp[i][X]==0) continue;
            for(int u:G[i]){
                dp[u][X+1] += dp[i][X]/G[i].size();
