    for (int x = 1; x < N; x++)
    {
        Pmod += dp[N-1][x];
    }

    for (int x = 1; x < N; x++)
    {
        dp[N-1][x]/= Pmod;
        ans += dp[N-1][x]*x;
    }

    for (int k = 0; k < M; k++)
    {
