                }
            }        
        }

        double ans_tmp = 0;
        DBG(dp_diff[N-1])

        for (int x = 1; x < N; x++)
        {
            ans_tmp += (dp[N-1][x]+dp_diff[N-1][x])*x;
        }
        if(abs(ans_tmp)<=eps) continue;
        DBG(ans_tmp)
        ans = min(ans,ans_tmp);
