double solveG(int y, vector<vector<int>> g){
    vector<double> dp(N+1,0);
    vector<double> pr(N+1,0);
    dp[0] = 0;
    pr[0] = 1;
    for (int u = 0; u < N; u++)
    {
        if(pr[u]==0) continue;
        for(int v:g[u]){
            if(u==Edge[y].first && v==Edge[y].second) continue;
            if(u==Edge[y].first) pr[v] += pr[u]/(g[u].size()-1);
            else pr[v] += pr[u]/g[u].size();
        }
    }


    for (int u = 0; u < N; u++)
    {
        for(auto v:g[u]){
            if(u==Edge[y].first && v==Edge[y].second) continue;
            if(u==Edge[y].first) dp[v] += dp[u]/(g[u].size()-1)+pr[u]/(g[u].size()-1);
            else dp[v] += dp[u]/g[u].size()+pr[u]/g[u].size();
        }
    }
    return dp[N-1];
}

int solve(){
    double ans = N+1;
    for (int i = 0; i <= M; i++)
    {
        if(G[Edge[i].first].size()==1) continue;
        double tmp = solveG(i,G);
        ans = min(ans,tmp);
    }
    cout << fixed << setprecision(10) << ans << endl;
    return 0;
}

int main()
{
    input();
    solve();
    return 0;
}

