void dfs(int id) {
	if (used[id])return;
	used[id] = true;
	vector<ld> res(n, INF);
	if (id == n - 1) {
		fill(res.begin(), res.end(), 0);
		//res[n - 1] = 0;
		memo[id] = res;
		return;
	}
	Rep(i, id + 1, n)res[i] = 0;
	rep(j, G[id].size()) {
		int to = G[id][j];
		dfs(to);
		Rep(i, id + 1, n) {
			res[i] += memo[to][i];
		}
	}
	ld sum = res[n - 1];
	Rep(i, id + 1, n) {
		res[i] /= (ld)G[id].size();
	}
	if (G[id].size() > 1) {
		//cout << id << endl;
		ld len = G[id].size() - 1;
		rep(j, G[id].size()) {
			int to = G[id][j];
			res[id] = min(res[id], (sum - memo[to][n - 1]) / len);
		}
	}
	Rep(i, id, n)res[i]++;
	rep(i, n)res[i] = min(res[i], res[n - 1]);
	memo[id] = res;
	return;
}
