int n, m;
vvi es;

vector<double> ds, ws2;

double go(int v){
    if(v == n-1) return ds[v] = 0;
    if(ds[v] > EPS) return ds[v];
    for(int nv: es[v])
        ds[v] += go(nv);
    return ds[v] = 1 + ds[v] / SZ(es[v]);
}

