    R(n, m);
    es.assign(n, vi());
    FOR(i, m){
        int s, t; R(s, t); --s, --t;
        es[s].EB(t);
    }

    ws2.assign(n, 0);
    ws2[0] = 1;
    FOR(v, n)
        for(int nv: es[v])
            ws2[nv] += ws2[v] / SZ(es[v]);

    ds.assign(n, 0);
    double ans0 = go(0);
    double ans = ans0;
    FOR(s, n){
        if(SZ(es[s]) <= 1) continue;
        double sum = 0, md = 0;
        for(int t: es[s]) sum += ds[t], md = max(md, ds[t]);
        double nd = 1 + (sum - md) / (SZ(es[s]) - 1);
        double v = ans0 + ws2[s] * (nd - ds[s]);
        ans = min(ans, v);
    }

    W(ans);

