        si--; ti--;
        net.at(si).push_back(ti);
        edges.emplace_back(si, ti);
    }

    double ans = n + 1;
    vector<double> exp(n, 0);
    for(int ng = -1; ng < (int)edges.size(); ++ng){
        if(ng != -1 && net.at(edges.at(ng).first).size() == 1 &&
           net.at(edges.at(ng).first).front() == edges.at(ng).second){
            continue;
        }
        vector<double> exp2(n, 0);
        for(int x = n - 2; x >= 0; x--){
            if(ng != -1 && edges.at(ng).first < x){
                exp2.at(x) = exp.at(x);
            }

            double tmp = 0;
            double count = 0;
            for(int nxt : net.at(x)){
                if(ng != -1 && make_pair(x, nxt) == edges.at(ng)){
                    continue;
                }
                tmp += exp2.at(nxt) + 1.0;
                count++;
            }
            exp2.at(x) = tmp / count;
            if(ng == -1){
                exp.at(x) = exp2.at(x);
            }
        }
        ans = min(ans, exp2.at(0));
    }
    printf("%.8f\n", ans);
