void build(int n)
{
    int d,i,j;
    dp[n-1]=0;
    for(i=n-2;i>=0;i--)
    {
        d=0;
        for(j=i+1;j<n;j++)
            if(edge[i][j])dp[i]+=dp[j],d++;
        dp[i]/=d;
        dp[i]+=1;
    }
    return ;
}
