double fun(int s,int d,int n)
{
    int i,j;
    ar[n-1]=0;
    fill(ar,ar+n,0);
    for(i=n-2;i>=0;i--)
    {
        int e=0;
        for(j=i+1;j<n;j++)
            if(edge[i][j] && (i!=s || j!=d))ar[i]+=ar[j],e++;
        if(e==0)
            ar[i]=INF;
        else
            ar[i]/=e;
        ar[i]+=1;
    }
    return ar[0];
}
