#include <bits/stdc++.h>
using namespace std;
typedef long long ll;



int N, M;

vector<int> path[600];
double p[600]; // p[j] = p(0,j)  0からjに到達する確率
double pe[600]; // pe[j] = pe(0,j) = p(0,j) * e(0,j) // 通路数期待値e(0,j)
double re[600]; // re[j] = 通路期待値e(j,N-1)


/*
	A と排他的な部屋 B を仮定する。AかBのどちらかを必ず通る。
	e(0,N-1) = p(0,A)*(e(0,A)+e(A,N-1)) + p(0,B)*(e(0,B)+e(B,N-1))
	         = pe(0,A)+p(0,A)*e(A,N-1) + (定数)

	         pe(0,A) と p(0,A) と e(A,N-1) の変化がEにどう影響するかはこの式で

	         pe(0,A) と p(0,A) は全てのAに対して最初に計算する
	         e(A,N-1) 全てのAに対してゴールから逆に計算する 

	j から k0, k1, k2 への3本の通路が出ていたとする
	通路 j->k0 を削除すると、e(0,N-1) はどう変化するか?
	  変化するのは pe(0,k) と p(0,k)
	  e(k,N-1) は変化しない

	pjk = 1/3
	pjk2 = 1/2
	new_p(0,k0)  = p(0,k0) - p[j]*pjk
	new_pe(0,k0) = pe(0,k0) - pjk*(pe[j]+p[j])
	new_p(0,k1)  = p(0,k1) - pjk*p[j] + pjk2*p[j]
	new_pe(0,k1) = pe(0,k1) - pjk*(pe[j]+p[j]) + pjk2*(pe[j]+p[j])


*/

int main(){
	cin >> N >> M;

	for ( int i = 0; i < M; i++ ){
		int s, t;
		cin >> s >> t;
		s--;
		t--;
		path[s].push_back(t);
	}


	// 部屋0から開始したときの、部屋kの到達率と通路数の期待値を調べる
	for ( int j = 0; j < N; j++ ){
		p[j] = pe[j] = 0.0;
	}
	p[0] = 1.0;
	pe[0] = 0.0;

	for ( int j = 0; j < N-1; j++ ){
		if ( p[j] == 0.0 || path[j].size() == 0 )
			continue;

		double pjk = 1.0 / (path[j].size());
		for ( auto k : path[j] ){
			p[k] += p[j]*pjk;
			pe[k] += pjk*(pe[j]+p[j]); // pe[k] += (jkを通ってkに到達する確率)*(jの通路数期待値+1) // == (p[j]*pjk)*(pe[j]/p[j]+1)
		}
	}

	// 部屋iから開始したときの、部屋N-1の通路数の期待値を調べる
	re[N-1] = 0.0;
	for ( int i = N-2; i >= 0; i-- ){
		double n = path[i].size();
		double ee = 0.0;
		for ( auto k : path[i] ){
			ee += (re[k]+1.0) / n;
		}
		re[i] = ee;
	}

//	for ( int j = 0; j < N; j++ ){
//		cout << j << " : p=" << p[j] << " pe=" << pe[j] << " e=" << (pe[j]/p[j]) << " : re=" << re[j] << endl;
//	}

	//
	double min_newE = pe[N-1];
	for ( int j = 0; j < N; j++ ){
		double n = path[j].size();
		for ( auto k : path[j] ){
			// j->kの道を削除するとどうなるか?
			double e_mod = 0.0; // eの変化分
			double newE = 0.0;
			if ( n == 1.0 ){
				// このpathは削除可能でない
				continue;
			}
			else {
				double pjk = 1.0 / n;
				double pjk2 = 1.0 / (n-1.0);
				for ( auto l : path[j] ){
					// p->new_p, pe->new_pe になったときのEの変化は
					// e_mod = - ( pe + p*re ) + (new_pe + new_p*re )
					//       = + (new_pe-pe) + (new_p-p)*re
					if ( l == k ){
						e_mod = e_mod + ( -pjk*(pe[j]+p[j]) ) + ( -pjk*p[j] )*re[l];
					}
					else {
						e_mod = e_mod + ( (pjk2-pjk)*(pe[j]+p[j]) ) + ( (pjk2-pjk)*p[j] )*re[l];
					}
				}
				newE = pe[N-1] + e_mod;
			}

			//cout << " path " << j << "-" << k << " newE=" << newE << "  e_mod=" << e_mod << endl;
			min_newE = min( min_newE, newE );
		}

	}
	cout << std::setprecision(10) << min_newE << endl;


	return 0;
}

