	for(int i = 1; i <= m; ++i) {
		cin >> a[i] >> b[i];
		vec[a[i]].push_back(b[i]);
	}
	ans = DP(0);
	for(int i = 1; i <= n; ++i) {
		ans = min(ans, DP(i));
	}
	printf("%.9f\n", ans);
}

