vector<double> perc(N,0);
vector<double> frz(N,0);
vector<double> tot(N,0);

void dfs1(ll x, double y, ll z, ll n){
    frz[x]+=(double)y*z;
    double ch = concnt[x];
    REP(i,n)if(dest[x][i]){
        dfs1(i,(double)y/ch,z+1,n);
    }
}

void dfs2(ll x, double y, ll z,ll sta, ll fin){
    if (x==fin) tot[sta]+=y*z;
    else{
        double ch = concnt[x];
        REP(i,fin+1)if(dest[x][i]){
            dfs2(i,(double)y/ch,z+1,sta,fin);
        }
    }
}

int main(){
    ll n, m, s, t; cin >> n >> m;
    REP(i,m){
        cin >> s >> t;s--;t--;
        dest[s][t]=1;
        concnt[s]++;
    }
    perc[0]=1;
    REP(i,n)REP(j,n)if (dest[i][j]){
        perc[j]+= (double)perc[i]/concnt[i];
    }
    dfs1(0,1,0,n);
    REP(i,n) dfs2(i,1,0,i,n-1);
    REP(i,n) frz[i]=(double)frz[i]/perc[i];
    /*REP(i,n) cout << perc[i] << " ";
