    double p0 = frz[n-1];
    double ans = p0;
    REP(i,n){
        if (concnt[i]<=1) continue;
        vector<vector<double>> dell(n,vector<double>(2,0));
        REP(j,n)if (dest[i][j]){
            dell[j][0]=tot[j];
            dell[j][1]=j;
        }
        sort(dell.begin(),dell.end());
        dest[i][dell[dell.size()-1][1]]=0;
        concnt[i]--;
        cnter = 0;
        REP(j,n){
            if (j==0) perc[j]=1;
            else perc[j]=0;
        }
        REP(j,n)REP(k,n)if (dest[j][k]){
            perc[k]+= (double)perc[j]/concnt[j];
        }
        REP(j,n-1) cnter+=perc[j];
        dest[i][dell[dell.size()-1][1]]=1;
        concnt[i]++;
        //cout << i << " " << dell[dell.size()-1][1] << " " << cnter << endl;
        ans = min(ans,cnter);
    }
    cout << setprecision(10) << ans << endl;
}

