#include <stdio.h>
int table[601][601];
double E[601];

int main() {
    int N, M;
    double ans = 1000;
    scanf(" %d %d", &N, &M);
    for (int i = 0; i < M; ++i) {
        int s, t;
        scanf(" %d %d", &s, &t);
        table[s][t] = 1;
        // table[t][s] = 1;
    }
    for (int i = 0; i < N; ++i) {
        E[N] = 0;
        for (int u = N - 1; u > 0; --u) {
            double e = 0;
            int len = 0;
            double max = -1;
            int maxv = 0;
            for (int v = u + 1; v <= N; ++v) {
                if (table[u][v]) {
                    e += E[v];
                    if (max < E[v]) {
                        max = E[v];
                        maxv = v;
                    }
                    len++;
                }
            }
            if (i == u && len > 1) {
                e -= E[maxv];
                len--;
            }
            E[u] = e / len + 1;
        }
        ans = ans > E[1] ? E[1] : ans;
    }
    printf("%f\n", ans);
    return 0;
}

