double tansaku(int n,int i,int cango[][3600],int* num,double* e){
    if(num[i]<2)return 0;
    double E[n+1],Max=0;
    int maxj=0;

    for(int j=0;j<num[i];j++){
        if(Max<e[cango[i][j]]){
            Max=e[cango[i][j]];
            maxj=j;
        }
    }

    for(int j=0;j<i+1;j++)E[j]=0;
    for(int j=i+1;j<n+1;j++)E[j]=e[j];
    for(int j=0;j<num[i];j++){
        if(j!=maxj)E[i]+=E[cango[i][j]];
    }
    E[i]/=(num[i]-1);
    E[i]++;
    for(int j=i-1;j>0;j--){
        for(int k=0;k<num[j];k++){
            E[j]+=E[cango[j][k]];
        }
        E[j]/=num[j];
        E[j]++;
    }
    return E[1];
}

