    int cango[n];
    double e[n+1];
    for(int i=1;i<n+1;i++)e[i]=0;
    int k;
    for(int i=n-1;i>0;i--){
        k=0;
        for(int j=0;j<m;j++){
            if(a[j]==i){
                cango[k]=b[j];
                k++;
            }
