        for(int j=n-2;j>=0;j--)
        {
            double mx = 0.0;
            double ns = 0.0;
            int c=0;
            edge* e = Ge[j];
            for(;e!=NULL;e=e->next)
            {
                if(sc[e->to]==-1.0) continue;
                mx = max(mx,sc[e->to]+1.0);
                ns += sc[e->to]+1.0;
                c++;
            }
            if(ns==0.0) continue;
            if(i==j && c>=2)
            {
                sc[j] = (ns-mx)/(c-1);
            }else
            {
                sc[j] = ns/c;
            }
        }
        ans = min(ans,sc[0]);
    }

    printf("%lf\n", ans);
    return 0;
}

