int main()
{
	int i, N, M, u, w, deg[2][601] = {};
	list *adj[601] = {}, *adj_inv[601] = {}, e[360001], *p;
	scanf("%d %d", &N, &M);
	for (i = 0; i < M; i++) {
		scanf("%d %d", &u, &w);
		e[i*2].v = w;
		e[i*2+1].v = u;
		e[i*2].next = adj[u];
		e[i*2+1].next = adj_inv[w];
		adj[u] = &(e[i*2]);
		adj_inv[w] = &(e[i*2+1]);
		deg[0][u]++;
		deg[1][u]++;
	}

	int q[601], head, tail;
	long double dp[601][601] = {};
	for (i = 1, tail = 0; i <= N; i++) if (deg[0][i] == 0) q[tail++] = i;
	for (head = 0; head < tail; head++) {
		u = q[head];
		if (deg[0][u] != 0) {
			for (p = adj[u]; p != NULL; p = p->next) {
				dp[u][u] += dp[p->v][p->v];
				for (i = 0; i < head; i++) dp[u][q[i]] += dp[p->v][q[i]] / deg[0][u];
			}
			dp[u][u] = dp[u][u] / deg[0][u] + 1.0;
		}

		for (p = adj_inv[u]; p != NULL; p = p->next) {
			deg[1][p->v]--;
			if (deg[1][p->v] == 0) q[tail++] = p->v;
		}
	}

	long double ans = dp[1][1], max, sum;
	if (deg[0][1] > 1) {
		for (p = adj[1], max = 0.0, sum = 0.0; p != NULL; p = p->next) {
			sum += dp[p->v][p->v];
			if (max < dp[p->v][p->v]) max = dp[p->v][p->v];
		}
		if (ans > (sum - max) / (deg[0][1] - 1) + 1.0) ans = (sum - max) / (deg[0][1] - 1) + 1.0;
	}
	for (head--; q[head] != 1; head--);
	for (head--; head >= 0; head--) {
		u = q[head];
