double tansaku(int n,int cango[][3600],int*num,int s,int t){
    double e[n+1];
    for(int i=1;i<n+1;i++)e[i]=0;
    int k;
    for(int i=n-1;i>0;i--){
        k=num[i];
        if(k==0)return 0;
        for(int j=0;j<k;j++){
            e[i]+=(i==s&&cango[i][j]==t)?0:e[cango[i][j]];
        }
        if(i==s)k--;
        if(k==0)return 0;
        e[i]/=k;
        e[i]++;
    }
    return e[1];
}

