        {
          sum += dp[n]
          max = Math.max(max, dp[n])
        }
        dp[j] = sum / g.get(j).size() + 1
        if (j == i && g.get(j).size() > 1)
        {
          dp[j] = (sum - max) / (g.get(j).size() - 1) + 1
        }
      }
