		for (int i = 0; i < n; i++)
			g[i] = new ArrayList<Integer>();
		for (int i = 0; i < m; i++)
			g[ni() - 1].add(ni() - 1);
		double prob[] = new double[n];
		prob[0] = 1;
		for (int i = 0; i < n; i++) {
			for (int v : g[i])
				prob[v] += prob[i] / g[i].size();
		}
		double exp[] = new double[n];

		double ans = 0;
		for (int i = n - 2; i >= 0; i--) {
			double s = 0;
			double mx = 0;
			for (int v : g[i]) {
				s += exp[v];
				mx = Math.max(mx, exp[v]);
			}
			exp[i] = s / g[i].size() + 1;
			if (g[i].size() >= 2) {
				double delta = (s - mx) / (g[i].size() - 1) - s / g[i].size();
				ans = Math.min(ans, delta * prob[i]);
			}
		}
		ans += exp[0];
		out.println(ans);
	}

	// a^b
	long power(long a, long b) {
		long x = 1, y = a;
		while (b > 0) {
			if (b % 2 != 0) {
				x = (x * y) % MOD;
			}
			y = (y * y) % MOD;
			b /= 2;
		}
		return x % MOD;
	}

	private long gcd(long a, long b) {
		while (a != 0) {
			long tmp = b % a;
			b = a;
			a = tmp;
		}
		return b;
	}

