/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        int blocked;
        int[] visited;
        List<Integer>[] graph;
        int[][] edges;
        double count;
        double sum;

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int N = in.nextInt(), M = in.nextInt();
            graph = new List[N];
            for (int i = 0; i < N; i++) {
                graph[i] = new ArrayList();
            }
            visited = new int[N];
            edges = new int[M][2];
            for (int i = 0; i < M; i++) {
                int u = in.nextInt() - 1, v = in.nextInt() - 1;
                edges[i][0] = u;
                edges[i][1] = v;
                graph[u].add(v);
            }
            blocked = -1;
            count = 0;
            sum = 0;
            dfs(0, 0);
            double ans = 0;
            if (count > 0) {
                ans = sum / count;
            }
            for (int i = 0; i < M; i++) {
                blocked = i;
                sum = 0;
                count = 0;
                dfs(0, 0);
                if (count > 0) {
                    ans = Math.min(ans, sum / count);
                }
//            DebugUtils.debug(sum ,count, ans, i);
            }
            out.printLine(ans);
        }

        public void dfs(int node, int depth) {
            if (node == visited.length - 1) {
                sum += depth;
                count++;
                return;
            }
            for (int v : graph[node]) {
                if (blocked != -1 && edges[blocked][0] == node && edges[blocked][1] == v) {
                    continue;
                }
                dfs(v, depth + 1);
            }
        }

    }

    static class OutputWriter {
        PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void printLine(Object... objects) {
            print(objects);
            writer.println();
        }

        public void close() {
            writer.close();
        }

    }

    static class InputReader {
        BufferedReader in;
        StringTokenizer tokenizer = null;

        public InputReader(InputStream inputStream) {
            in = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            try {
                while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                    tokenizer = new StringTokenizer(in.readLine());
                }
                return tokenizer.nextToken();
            } catch (IOException e) {
                return null;
            }
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

import java.util.*;

public class Main implements Runnable {

    private static int MOD = 1_000_000_007;

    public static void main(String[] args) {
        // Run with 32MB stack
        Thread thread = new Thread(null, new Main(), "", 32 * 1024 * 1024);
        thread.start();
    }

    @Override
    public void run() {
        final Scanner scanner = new Scanner(System.in);
        solve(scanner);
    }

    static void solve(Scanner scanner) {
        int N = Integer.parseInt(scanner.next());
        int M = Integer.parseInt(scanner.next());
        List<Integer>[] edges = new List[N];
        for (int i = 0; i < N; i++) {
            edges[i] = new ArrayList<>();
        }
        for (int i = 0; i < M; i++) {
            int s = Integer.parseInt(scanner.next());
            int t = Integer.parseInt(scanner.next());
            edges[s - 1].add(t - 1);
        }

        double[] dp = new double[N];
        for(int i = N - 2; i >= 0; i--) {
            double sum = 0;
            for (int next: edges[i]) {
                sum += dp[next];
            }
            sum /= edges[i].size();
            sum += 1;
            dp[i] = sum;
        }

        double ans = dp[0];
        for (int ni = 0; ni < N - 1; ni++) {
            if (edges[ni].size() == 1) continue;
            int nj = edges[ni].get(0);
            for (int next: edges[ni]) {
                if (dp[nj] < dp[next]) {
                    nj = next;
                }
            }
            // ignore edge (ni -> nj)

            double[] dp2 = new double[N];
            for(int i = N - 2; i >= 0; i--) {
                double sum = 0;
                for (int next: edges[i]) {
                    if (i == ni && next == nj) continue;
                    sum += dp2[next];
                }
                int deg = edges[i].size();
                if (i == ni) deg--;
                sum /= deg;
                sum += 1;
                dp2[i] = sum;
            }

            ans = Math.min(ans, dp2[0]);
        }

        System.out.printf("%.10f\n", ans);
    }
}

import java.io.IOException;
