import java.io.PrintWriter;
import java.util.Arrays;
import java.util.NoSuchElementException;
import java.util.PrimitiveIterator;
import java.util.function.IntBinaryOperator;
import java.util.function.IntFunction;
import java.util.function.IntPredicate;
import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;
import static java.lang.Math.min;



public class Main {
    public static void main(String[] args) {
        StringBuilder out = new StringBuilder();
        solve(out);
        PrintWriter pw = new PrintWriter(System.out);
        pw.println(out);
        pw.flush();
        pw.close();
    }

    public static void solve(StringBuilder out) {
        int n = In.ni();
        int m = In.ni();
        IntArrayList[] edges = new IntArrayList[n];
        IntArrayList[] rev = new IntArrayList[n];
        for (int i = 0; i < n; i++) {
            edges[i] = new IntArrayList();
            rev[i] = new IntArrayList();
        }
        int[] in = new int[n];
        for (int i = 0; i < m; i++) {
            int s = In.ni() - 1;
            int t = In.ni() - 1;
            edges[t].add(s);
            rev[s].add(t);
            in[s]++;
        }
        int[] p = topologicalSort(in, edges);
        double[] dp = new double[n];
        for (int u : p) edges[u].iterator().forEachRemaining((int v) -> {dp[v] += (dp[u] + 1.) / in[v];});
        double min = dp[0];
        double[] cp = new double[n];
        for (int i = 0; i < n; i++) {
            if (in[i] <= 1) continue;
            double max = -1;
            int maxv = -1;
            PrimitiveIterator.OfInt iter = rev[i].iterator();
            while (iter.hasNext()) {
                int j = iter.nextInt();
                if (max < dp[j]) {
                    max = dp[j];
                    maxv = j;
                }
            }
            int fr = maxv, to = i;
            in[i]--;
            Arrays.fill(cp, 0);
            for (int u : p) {
                edges[u].iterator().forEachRemaining((int v) -> {
                    if (u != fr || v != to) {
                        cp[v] += (cp[u] + 1.) / in[v];
                    }
                });
            }
            in[i]++;
            min = min(min, cp[0]);
        }
        out.append(min);
    }

    public static int[] topologicalSort(int[] in, IntArrayList[] edges) {
        int n = in.length;
        int[] degIn = in.clone();
        int[] ret = new int[n];
        IntQueue q = new IntQueue(n);
        for (int i = 0; i < n; i++) if (degIn[i] == 0) q.add(i);
        int idx = 0;
        while (q.size() > 0) {
            int u = q.poll();
            edges[u].iterator().forEachRemaining((int v) -> {if (--degIn[v] == 0) q.add(v);});
            ret[idx++] = u;
        }
        return ret;
    }
}


