	static double dfs(int v, int block) {
		if(v == n-1) {
			return 0.0;
		}
		if(dp[v] != 0) return dp[v];
		double ret = 0;
		int sz = graph[v].size();
		if(sz == 1) {
			ret = dfs(graph[v].get(0),block)+1;
		}
		else {
			double sum = 0;
			double max = 0;
			for(int to:graph[v]) {
				double tmp = dfs(to, block);
				max = max(max,tmp);					
				sum += tmp;
			}
			if(v == block)ret = (sum - max)/(sz - 1) + 1;
			else ret = sum/sz + 1;
		}
		return dp[v] = ret;
	}

