import java.io.*;
import java.util.*;

public class Main {

  static FastScanner sc = new FastScanner();
  static Output out = new Output(System.out);

  static final int[] dx = {0, 1, 0, -1};
  static final int[] dy = {-1, 0, 1, 0};

  static final long MOD = (long) (1e9 + 7);
  static final long INF = Long.MAX_VALUE / 2;

  static final int e5 = (int) 1e5;

  public static class Solver {
    public Solver() {

      int N = sc.nextInt();
      int M = sc.nextInt();

      double[][] dp = new double[N][M+1];

      boolean[][] path = new boolean[N][N];
      for (int i=0; i<M; i++) {
        int a = sc.nextInt()-1;
        int b = sc.nextInt()-1;
        path[a][b] = true;
      }

      int m = 0;

      for (int k=N-1; k>=0; k--) {
        int count = 0;

        for (int l=k+1; l<N; l++) {
          if (!path[k][l]) continue;
          // if (k == i && l == j) continue;

          dp[k][m] += dp[l][m];
          count++;
        }

        if (count > 0) {
          dp[k][m] /= count;
          dp[k][m] += 1;
        } else if (k != N-1) {
          dp[0][m] = INF;
          break;
        }

      }

      m++;

      for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
          if (!path[i][j]) continue;

          for (int k=N-1; k>=0; k--) {
            int count = 0;

            for (int l=k+1; l<N; l++) {
              if (!path[k][l]) continue;
              if (k == i && l == j) continue;

              dp[k][m] += dp[l][m];
              count++;
            }

            if (count > 0) {
              dp[k][m] /= count;
              dp[k][m] += 1;
            } else if (k != N-1) {
              dp[0][m] = INF;
              break;
            }

          }

          m++;
        }
      }

      double ans = INF;
      for (int i=1; i<=M; i++) {
        ans = Math.min(ans, dp[0][i]);
      }

      if (ans == INF) ans = dp[0][0];

      out.println(ans);

    }
  }

  public static void main(String[] args) {
    new Solver();
    out.flush();
  }

  static class FastScanner {
    private InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;


    public void load() {
      try {
        in = new FileInputStream(next());
      } catch (Exception e) {
        e.printStackTrace();
      }
    }

    private boolean hasNextByte() {
      if (ptr < buflen) {
        return true;
      } else {
        ptr = 0;
        try {
          buflen = in.read(buffer);
        } catch (IOException e) {
          e.printStackTrace();
        }
        if (buflen <= 0) {
          return false;
        }
      }
      return true;
    }

    private int readByte() {
      if (hasNextByte()) return buffer[ptr++];
      else return -1;
    }

    private static boolean isPrintableChar(int c) {
      return 33 <= c && c <= 126;
    }

    private void skipUnprintable() {
      while (hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;
    }

    public boolean hasNext() {
      skipUnprintable();
      return hasNextByte();
    }

    public String next() {
      if (!hasNext()) throw new NoSuchElementException();
      StringBuilder sb = new StringBuilder();
      int b = readByte();
      while (isPrintableChar(b)) {
        sb.appendCodePoint(b);
        b = readByte();
      }
      return sb.toString();
    }

    public long nextLong() {
      if (!hasNext()) throw new NoSuchElementException();
      long n = 0;
      boolean minus = false;
      int b = readByte();
      if (b == '-') {
        minus = true;
        b = readByte();
      }
      if (b < '0' || '9' < b) {
        throw new NumberFormatException();
      }
      while (true) {
        if ('0' <= b && b <= '9') {
          n *= 10;
          n += b - '0';
        } else if (b == -1 || !isPrintableChar(b)) {
          return minus ? -n : n;
        } else {
          throw new NumberFormatException();
        }
        b = readByte();
      }
    }

    public int nextInt() {
      return (int) nextLong();
    }

    public int[] nextIntArray(int N, boolean oneBased) {
      if (oneBased) {
        int[] array = new int[N + 1];
        for (int i = 1; i <= N; i++) {
          array[i] = sc.nextInt();
