  Solver(int n, int m, int[][] sts) {
    this.n = n;
    this.m = m;
    this.sts = sts;
  }

  public double solve() {
    graph = new ArrayList<>();
    for (int i = 0; i <= n; i++) {
      graph.add(new ArrayList<>());
    }
    for (int i = 0; i < m; i++) {
      int s = sts[i][0];
      int t = sts[i][1];
      graph.get(s).add(t);
    }

    double[] dpcache = new double[n + 1];

    List<Integer> removeSrc = new ArrayList<>();
    List<Integer> removeDst = new ArrayList<>();
    for (int i = n - 1; i >= 1; i--) {
      double sum = 0.0;
      double max = 0.0;
      int maxIndex = 0;
      int count = 0;
      for (int next : graph.get(i)) {
        double v = dpcache[next];
        sum += v;
        if (v > max) {
          max = v;
          maxIndex = next;
        }
        count++;
      }
      if (count > 1) {
        removeSrc.add(i);
        removeDst.add(maxIndex);
      }
      dpcache[i] = sum / count + 1.0;
    }

    double answer = dpcache[1];
