    // int inf = Integer.MAX_VALUE/2;

    ArrayList<Integer>[] edge;
    ArrayList<Integer>[] redge;
    double[] dp;
    int[] outer;
    void solve(){
        int n = ni();
        int m = ni();
        edge = new ArrayList[n];
        redge = new ArrayList[n];
        for(int i = 0; i < n; i++){
            edge[i] = new ArrayList<>();
            redge[i] = new ArrayList<>();
        }
        outer = new int[n];
        for(int i = 0; i < m; i++){
            int s = ni()-1;
            int t = ni()-1;
            edge[s].add(t);
            redge[t].add(s);
            outer[s]++;
        }
        dp = new double[n];
        f(outer.clone(), n);
        double ans = dp[0];
        for(int i = 0; i < n-1; i++){
            double ma = 0;
            int idx = -1;
            for(int j : edge[i]){
                if(dp[j]>ma){
                    ma = dp[j];
                    idx = j;
                }
            }
            double ret = g(outer.clone(), n, i, idx);
            ans = Math.min(ans, ret);
        }
        out.println(ans);
    }

    void f(int[] outer, int n){
        Deque<Integer> st = new ArrayDeque<>();
        st.push(n-1);
        Arrays.fill(dp, inf);
        dp[n-1] = 0;
        while(!st.isEmpty()){
            int cur = st.pop();
            double sum = 0;
            for(int i : edge[cur]){
                sum += dp[i];
            }
            if(cur!=n-1) dp[cur] = sum / edge[cur].size() + 1;
            for(int i : redge[cur]){
                outer[i]--;
                if(outer[i]==0){
                    st.add(i);
                }
            }
        }
    }

    double g(int[] outer, int n, int s, int t){
        Deque<Integer> st = new ArrayDeque<>();
        st.push(n-1);
        dp = new double[n];
        Arrays.fill(dp, inf);
        dp[n-1] = 0;
        while(!st.isEmpty()){
            int cur = st.pop();
            double sum = 0;
            for(int i : edge[cur]){
                if(cur==s&&i==t){
                    if(edge[cur].size()!=1) continue;
                }
                sum += dp[i];
            }
            int l = edge[cur].size();
            if(cur==s) l = Math.max(1, edge[cur].size()-1);
            if(cur!=n-1) dp[cur] = sum / l + 1;
            for(int i : redge[cur]){
                outer[i]--;
                if(outer[i]==0){
                    st.add(i);
                }
            }
        }
        return dp[0];
    }

    void run() throws Exception
    {
        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        out = new PrintWriter(System.out);
        long s = System.currentTimeMillis();
        solve();
        out.flush();
        if(!INPUT.isEmpty())tr(System.currentTimeMillis()-s+"ms");
    }

