		int N = io.nextInt(), M = io.nextInt();
		ArrayList<ArrayList<Integer>> edge = new ArrayList<>(); // 辺を覚える
		for (@SuppressWarnings("unused")final int i : IntRange.open(N)) edge.add(new ArrayList<>());
		for (@SuppressWarnings("unused")final int i : IntRange.open(M)) {
			int s = io.nextInt() - 1, t = io.nextInt() - 1;
			edge.get(s).add(t);
		}
		double[] E = new double[N];

		double ans = Double.MAX_VALUE;
		for (int i = N - 1;i >= 0;-- i) { // ここが辺を切る場所
			E[i] = 0;
			if (edge.get(i).size() > 1) { // 切っても通れるなら
				double max = 0;
				for (int t : edge.get(i)) {
					E[i] += (E[t] + 1) / (edge.get(i).size() - 1); // 選ぶ確率*その先の頂点の移動回数の期待値+1
					max = Math.max(max, (E[t] + 1) / (edge.get(i).size() - 1));
				}
				E[i] -= max;

				for (int j = i - 1;j >= 0;-- j) {
					E[j] = 0;
					for (int t : edge.get(j)) {
						E[j] += (E[t] + 1) / edge.get(j).size(); // 選ぶ確率*その先の頂点の移動回数の期待値+1
					}
				}
				ans = Math.min(ans, E[0]);
			}
			E[i] = 0;
			for (int t : edge.get(i)) {
				E[i] += (E[t] + 1) / edge.get(i).size(); // 選ぶ確率*その先の頂点の移動回数の期待値+1
			}
		}
		ans = Math.min(ans, E[0]); // 何も切らなかった
		io.println(ans);
	}

