    static class FForkInTheRoad {
        public void solve(int testNumber, MyInput in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            List<int[]> edges = new ArrayList<>();
            for (int i = 0; i < m; i++) {
                int s = in.nextInt() - 1;
                int t = in.nextInt() - 1;
                edges.add(new int[]{s, t});
            }

            List<Integer>[] g = new List[n];

            for (int i = 0; i < n; i++) {
                g[i] = new ArrayList<>();
            }

            for (int[] e : edges) {
                g[e[0]].add(e[1]);
            }

            double[] E0 = new double[n];
            for (int i = n - 2; i >= 0; i--) {
                double sum = 0;
                for (int t : g[i]) {
                    sum += E0[t] + 1;
                }
                E0[i] = sum / g[i].size();
            }

            double ans = E0[0];
            double[] E1 = new double[n];
            for (int j = n - 2; j >= 0; j--) {
                if (g[j].size() == 1) continue;
                double max = 0;
                for (int t : g[j]) {
                    max = Math.max(max, E0[t] + 1);
                }

                for (int i = n - 2; i >= 0; i--) {
                    if (i > j) {
                        E1[i] = E0[i];
                        continue;
                    }
                    if (i == j) {
                        E1[i] = (E0[i] * g[i].size() - max) / (g[i].size() - 1);
                        continue;
                    }
                    double sum = 0;
                    for (int t : g[i]) {
                        sum += E1[t] + 1;
                    }
                    E1[i] = sum / g[i].size();
//            dump(i, sum, max, diff, E1[i]);
                }
                ans = Math.min(ans, E1[0]);
            }
//            ans = Math.min(ans, Math.min(E0[0], E1[0]));
//        dump(E0, E1);
            out.printf("%.10f\n", ans);
        }

    }

    static class MyInput {
        private final BufferedReader in;
        private static int pos;
        private static int readLen;
        private static final char[] buffer = new char[1024 * 8];
        private static char[] str = new char[500 * 8 * 2];
        private static boolean[] isDigit = new boolean[256];
        private static boolean[] isSpace = new boolean[256];
        private static boolean[] isLineSep = new boolean[256];

        static {
            for (int i = 0; i < 10; i++) {
                isDigit['0' + i] = true;
            }
            isDigit['-'] = true;
            isSpace[' '] = isSpace['\r'] = isSpace['\n'] = isSpace['\t'] = true;
            isLineSep['\r'] = isLineSep['\n'] = true;
        }

        public MyInput(InputStream is) {
            in = new BufferedReader(new InputStreamReader(is));
        }

        public int read() {
            if (pos >= readLen) {
                pos = 0;
                try {
                    readLen = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException();
                }
                if (readLen <= 0) {
                    throw new MyInput.EndOfFileRuntimeException();
                }
            }
            return buffer[pos++];
        }

        public int nextInt() {
            int len = 0;
            str[len++] = nextChar();
            len = reads(len, isSpace);
            int i = 0;
            int ret = 0;
            if (str[0] == '-') {
                i = 1;
            }
            for (; i < len; i++) ret = ret * 10 + str[i] - '0';
            if (str[0] == '-') {
                ret = -ret;
            }
            return ret;
        }

        public char nextChar() {
            while (true) {
                final int c = read();
                if (!isSpace[c]) {
                    return (char) c;
                }
            }
        }

        int reads(int len, boolean[] accept) {
            try {
                while (true) {
                    final int c = read();
                    if (accept[c]) {
                        break;
                    }
                    if (str.length == len) {
                        char[] rep = new char[str.length * 3 / 2];
                        System.arraycopy(str, 0, rep, 0, str.length);
                        str = rep;
                    }
                    str[len++] = (char) c;
                }
            } catch (MyInput.EndOfFileRuntimeException e) {
            }
            return len;
        }

        static class EndOfFileRuntimeException extends RuntimeException {
        }

    }
}

