public class Main {

  private static void solve() {
    int n = ni();
    int m = ni();
    int[] from = new int[m];
    int[] to = new int[m];
    for (int i = 0; i < m; i++) {
      from[i] = ni() - 1;
      to[i] = ni() - 1;
    }

    int[][] g = packD(n, from, to);

    double ret = Double.MAX_VALUE;
    for (int i = 0; i < n; i++) {
      double[] dp = new double[n];
      for (int v = n - 2; v >= 0; v--) {
        double sum = 0;
        double max = 0;
        int num = 0;
        for (int u : g[v]) {
          if (dp[u] >= 0) {
            sum += dp[u];
            max = Math.max(max, dp[u]);
            num++;
          }
        }
        if (v == i && num >= 2) {
          num--;
          sum -= max;
        }
        dp[v] = sum / num + 1;
      }
      ret = Math.min(ret, dp[0]);
    }

    System.out.println(ret);
  }


  static int[][] packD(int n, int[] from, int[] to) {
    int[][] g = new int[n][];
    int[] p = new int[n];
    for (int f : from)
      p[f]++;
    for (int i = 0; i < n; i++)
      g[i] = new int[p[i]];
    for (int i = 0; i < from.length; i++) {
      g[from[i]][--p[from[i]]] = to[i];
    }
    return g;
  }


