  static class Node{
    int id;
    int mushi;
    double kai=0;
    double per=0;
    List<KP> kps;
    List<Integer> el;
    Node(int n){
      id=n;
      mushi=-1;
      el=new ArrayList<Integer>();
      kps=new ArrayList<KP>();
    }
    void add(double akai,double aper){
      kps.add(new KP(akai,aper));
    }
    void matome(){
      for(KP kp:kps){
        kai+=kp.kai*kp.per;
        per+=kp.per;
      }
      if(kps.size()!=0){
        kai=kai/per;
      }
    }
    void init(){
      kai=0;
      per=0;
      kps.clear();
    }
    boolean mushinext(){
      mushi++;
      if(mushi<el.size()){
        return true;
      }else{
        mushi=-1;
        return false;
      }
    }
    int elsize(){
      if(mushi==-1){
        return el.size();
      }else{
        return el.size()-1;
      }
    }
    public String toString(){
      return String.valueOf(id)+" : "+String.valueOf(kai)+" , "+String.valueOf(per);
    }
  }
  static class KP{
    double kai;
    double per;
    KP(double k,double p){
      kai=k;per=p;
    }
  }
