import java.util.Arrays;

public class Main {

  private static void solve() {
    int n = ni();
    int m = ni();
    int[] from = new int[m];
    int[] to = new int[m];
    for (int i = 0; i < m; i++) {
      from[i] = ni() - 1;
      to[i] = ni() - 1;
    }
    int[][] g = packD(n, from, to);

    double ret = Double.MAX_VALUE;
    for (int k = 0; k < n; k++) {
      double[] dp = new double[n];
      Arrays.fill(dp, -1);
      dp[n - 1] = 0;

      for (int i = n - 2; i >= 0; i--) {
        double max = -1;
        double sum = 0;
        int cnt = 0;
        for (int v : g[i]) {
          if (dp[v] >= 0) {
            max = Math.max(max, dp[v]);
            sum += dp[v];
            cnt++;
          }
        }
        if (i == k && cnt > 1) {
          dp[i] = (sum - max) / (cnt - 1) + 1;
        } else {
          dp[i] = sum / cnt + 1;
        }
      }
      if (dp[0] >= 0) {
        ret = Math.min(ret, dp[0]);
      }
    }
    System.out.println(ret);


  }

  static int[][] packD(int n, int[] from, int[] to) {
    int[][] g = new int[n][];
    int[] p = new int[n];
    for (int f : from)
      p[f]++;
    for (int i = 0; i < n; i++)
      g[i] = new int[p[i]];
    for (int i = 0; i < from.length; i++) {
      g[from[i]][--p[from[i]]] = to[i];
    }
    return g;
  }


