        static void Main(string[] args)
        {
            //var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
            //Console.SetOut(sw);


            int N, M;
            Input(out N, out M);
            for (var i = 0; i < N; i++) G.Add(new List<int>());
            for (var i = 0; i < M; i++)
            {
                int s, t;
                Input(out s, out t);
                s--; t--;
                G[s].Add(t);
            }
            var tp = Toposo();
            tp.Reverse();
            //Out_Sep(tp);
            var dp = new double[N, N + 1];
            for(var i = 0; i < N; i++)
            {
                for(var j = 0; j < N + 1; j++)
                {
                    dp[i, j] = i == N - 1 ? 0 : INF;
                }
            }

            double ans = INF;
            for(var u = 0; u <= N; u++)
            {
                if (u != N && G[u].Count() <= 1) continue;
                foreach(var v in tp)
                {
                    if (v == N - 1) continue;
                    double cur = 0;
                    double mx = 0;
                    double num = G[v].Count();
                    foreach(var nx in G[v])
                    {
                        cur += dp[nx, u] + 1;
                        mx = Max(mx, dp[nx, u] + 1);
                    }
                    if (v == u)
                    {
                        cur = (cur - mx) / (num - 1);
                    }
                    else { cur /= num; }

                    dp[v, u] = cur;
                }
                //OutL(dp[0, u]);
                ans = Min(ans, dp[0, u]);
            }
            OutL(ans);


            //Console.Out.Flush();
        }
        static List<int> Toposo()
        {
            var ret = new List<int>();
            var node = new Queue<int>();
            var N = G.Count();
            var link = new int[N];
            for(var i = 0; i < N; i++)
            {
                foreach (var nx in G[i]) link[nx]++;
            }
            for(var i = 0; i < N; i++)
            {
                if (link[i] == 0) node.Enqueue(i);
            }

            while (node.Any())
            {
                int v = node.Dequeue();
                ret.Add(v);
                foreach(var nx in G[v])
                {
                    link[nx]--;
                    if (link[nx] == 0)
                    {
                        node.Enqueue(nx);
                    }
                }
            }
            return ret;
        }
