            {
                var dp = new double[N];
                dp[N - 1] = 0;
                for (int i = N - 2; i >= 0; i--)
                {
                    var nexts = new double[graph[i].children.Length];
                    for (int j = 0; j < nexts.Length; j++)
                        nexts[j] = 1 + dp[graph[i].children[j]];
                    Array.Sort(nexts);
                    if (p == i && nexts.Length > 1)
                        dp[i] = nexts.Take(nexts.Length - 1).Average();
                    else
                        dp[i] = nexts.Average();
                }
                e = Math.Min(e, dp[0]);
            }

            return e;
        }
