public static class P {
  public static void Main() {
    var nm = Console.ReadLine().Split().Select(int.Parse).ToArray();
    int n = nm[0];
    int m = nm[1];
    var graph = new List< List < int > >();
    for (int i = 0; i < n; i++) {
      graph.Add(new List< int >());
    }
    for (int i = 0; i < m; i++) {
      var st = Console.ReadLine().Split().Select(int.Parse).ToArray();
      int s = st[0] - 1;
      int t = st[1] - 1;
      graph[s].Add(t);
    }

    var dp = new List < double >();
    dp.AddRange(Enumerable.Repeat(0.0, n));
    for (int i = n - 2; i >= 0; i--) {
      foreach (int j in graph[i]) {
        dp[i] += dp[j];
      }
      dp[i] /= graph[i].Count();
      dp[i] += 1;
    }

    var ep = new List < double >();
    ep.AddRange(Enumerable.Repeat(0.0, n));
    ep[0] = 1;
    for (int i = 0; i < n; i++) {
      foreach (int j in graph[i]) {
        ep[j] += ep[i] / graph[i].Count();
      }
    }

    double full = dp[0];
    double ans = full;
    for (int i = 0; i < n; i++) {
      int sz = graph[i].Count();
      if (sz < 2) continue;
      double sum = 0;
      double max = 0;
      foreach (int j in graph[i]) {
        sum += dp[j];
        max = Max(max, dp[j]);
      }
      double x = sum / sz;
      double y = (sum - max) / (sz - 1);
      ans = Min(ans, full - ep[i] * (x - y));
    }
    Console.WriteLine(ans);
  }
}

using System;
