class F
{
	static void Main()
	{
		Func<int[]> read = () => Console.ReadLine().Split().Select(int.Parse).ToArray();
		var h = read();
		var n = h[0];
		var map = new int[h[1]].Select(_ => read()).ToLookup(r => r[0], r => r[1]);

		var dp = new double[n + 1, n];
		for (int i = n - 1; i > 0; i--)
		{
			dp[i, 0] = map[i].Select(x => dp[x, 0]).Average() + 1;
			for (int j = 1; j < n; j++)
			{
				if (i > j) { dp[i, j] = dp[i, 0]; continue; }
				var es = map[i].Select(x => dp[x, j]).ToArray();
				dp[i, j] = i == j && es.Length > 1 ?
					(es.Sum() - es.Max()) / (es.Length - 1) + 1 :
					es.Average() + 1;
			}
		}
		Console.WriteLine(Enumerable.Range(1, n - 1).Min(j => dp[1, j]));
	}
}

using System;
using System.Collections.Generic;
using CompLib.Util;

public class Program
{
    private int N, M;
    private List<E>[] Edge;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        M = sc.NextInt();
        Edge = new List<E>[N];
        for (int i = 0; i < N; i++)
        {
            Edge[i] = new List<E>();
        }

        for (int i = 0; i < M; i++)
        {
            int s = sc.NextInt() - 1;
            int t = sc.NextInt() - 1;
            Edge[s].Add(new E(t, i));
        }

        // 塞ぐ辺の候補
        List<int> ls = new List<int>();
        // 現在地、塞いだか?
        var dp = new double[N];

        dp[N - 1] = 0;

        for (int i = N - 2; i >= 0; i--)
        {
            double max = double.MinValue;
            int num = -1;
            int cnt = 0;
            double sum = 0;
            foreach (var e in Edge[i])
            {
                sum += dp[e.To];
                cnt++;
                if (max < dp[e.To])
                {
                    max = dp[e.To];
                    num = e.Num;
                }
            }

            dp[i] = 1.0 + sum / cnt;
            ls.Add(num);
        }

        double ans = dp[0];

        foreach (int l in ls)
        {
            var dp2 = new double[N];
            dp2[N - 1] = 0;
            bool f = true;
            for (int i = N - 2; i >= 0; i--)
            {
                double sum = 0;
                int cnt = 0;
                foreach (E e in Edge[i])
                {
                    if (e.Num == l) continue;
                    sum += dp2[e.To];
                    cnt++;
                }

                if (cnt == 0)
                {
                    f = false;
                    break;
                }

                dp2[i] = 1.0 + sum / cnt;
            }

            if (f)
                ans = Math.Min(ans, dp2[0]);
        }

        Console.WriteLine(ans);
    }

    public static void Main(string[] args) => new Program().Solve();
}

