        public object Calc()
        {
            var N = consoleReader.Int;
            var M = consoleReader.Int;
            graph = new GraphBuilder(N, consoleReader, M).ToArray();

            for (int p = 0; p < N - 1; p++)
            {
                var dp = new double[N];
                dp[N - 1] = 0;
                for (int i = N - 2; i >= 0; i--)
                {
                    double ave = 0;
                    if (p == i && graph[i].children.Length > 1)
                    {
                        double max = 0;
                        for (int j = 0; j < graph[i].children.Length; j++)
                        {
                            var next = (1 + dp[graph[i].children[j]]) / (graph[i].children.Length - 1);
                            if (next > max)
                            {
                                ave += max;
                                max = next;
                            }
                            else
                                ave += next;
                        }
                    }
                    else
                    {
                        for (int j = 0; j < graph[i].children.Length; j++)
                            ave += (1 + dp[graph[i].children[j]]) / graph[i].children.Length;
                    }
                    dp[i] = ave;
                }
                e = Math.Min(e, dp[0]);
            }

            return e;
        }
        double e = double.PositiveInfinity;
