        for (int i = 0; i < m; i++) {
            var s = ni() - 1;
            var t = ni() - 1;
            adj[s].Add(t);
        }


        memo = new double?[n];
        double ans = dfs(0, -1, adj);

        for (int i = 0; i < n; i++) {
            memo = new double?[n];
            if (adj[i].Count > 1) {
                double sub = dfs(0, i, adj);
                ans = Math.Min(ans, sub);
            }
        }

        cout.WriteLine("{0:F10}", ans);
    }

    double?[] memo;

    public double dfs(int pos, int blockPos, List<int>[] adj) {
        if (pos == adj.Length) return 0;
        if (!memo[pos].HasValue) {
            double val = 0;

            var degree = adj[pos].Count;
            foreach (var next in adj[pos]) {
                val += 1.0 / degree * (dfs(next, blockPos, adj) + 1.0);
            }

            if (degree > 1 && pos == blockPos) {
                double val2 = 0;
                double max = 0;
                foreach (var next in adj[pos]) {
                    var sub = dfs(next, blockPos, adj) + 1.0;
                    max = Math.Max(sub, max);
                    val2 += sub;
                }
                val2 -= max;
                val2 /= degree - 1;
                val = Math.Min(val, val2);
            }

            memo[pos] = val;
        }
        return memo[pos].Value;
    }
}

