        var dp = new double[N]; dp[N - 1] = 0;
        var p = new double[N]; p[0] = 1;
        for (var i = 0; i < N; i++)
        {
            double c = 1d / edge[i].Count * p[i];
            foreach (var e in edge[i])
                p[e] += c;
        }
        for(var i = N - 1; i >= 0; i--)
        {
            foreach (var e in rev[i])
                dp[e] += 1d / edge[e].Count * (dp[i] + 1);
        }
        var res = dp[0];
        for (var i = 0; i < N; i++)
            if (edge[i].Count > 1)
                foreach (var e in edge[i])
                    chmin(ref res, dp[0] - (dp[i] - (dp[i] * edge[i].Count - dp[e] - 1) / (edge[i].Count - 1)) * p[i]);
        WriteLine(res);
    }

}

