  class Program
  {
    static void Main(string[] args)
    {
      var n = CIn.ReadInt();
      var m = CIn.ReadInt();
      var p = new List<int>[n];

      for (var i = 0; i < n; i++)
      {
        p[i] = new List<int>();
      }

      for (var i = 0; i < m; i++)
      {
        var s = CIn.ReadInt() - 1;
        var t = CIn.ReadInt() - 1;

        p[s].Add(t);
      }

      var ans = (double)n - 1;

      for (var i = 0; i < n - 1; i++)
      {
        var dp = new double[n];

        if (p[i].Count == 1)
        {
          continue;
        }

        for (var j = n - 2; j >= 0; j--)
        {
          var pc = p[j].Count;
          var max = 0.0;

          for (var k = 0; k < pc; k++)
          {
            if (i == j)
            {
              var tmp = dp[p[j][k]] / (pc - 1);
              max = Math.Max(max, tmp);
              dp[j] += tmp;
            }
            else
            {
              dp[j] += dp[p[j][k]] / pc;
            }
          }

          dp[j] += 1 - max;
        }

        ans = Math.Min(ans, dp[0]);
      }

      Console.WriteLine(ans);
    }
  }

