	}
	for i := 0; i < m; i++ {
		s := getNextInt(scanner) - 1
		t := getNextInt(scanner) - 1
		g[s] = append(g[s], t)
	}

	ysp48 := make([]float64, n)
	ms := -1
	mt := -1
	mx := 0.0
	for i := n - 2; i >= 0; i-- {
		for _, to := range g[i] {
			if len(g[i]) > 1 {
				if mx < ysp48[to]/float64(len(g[i])-1) {
					mx = ysp48[to] / float64(len(g[i])-1)
					ms = i
					mt = to
				}
			}
			ysp48[i] += ysp48[to] + 1
		}
		ysp48[i] /= float64(len(g[i]))
	}
	for i := n - 2; i >= 0; i-- {
