	var n, m int
	fmt.Fscan(r, &n, &m)
	to := make([][]int, n)
	for i := 0; i < m; i++ {
		var s, t int
		fmt.Fscan(r, &s, &t)
		s--
		t--
		to[s] = append(to[s], t)
	}

	dp := make([][]float64, n)
	for i := 0; i < n; i++ {
		dp[i] = make([]float64, n)
		for j := 0; j < n-1; j++ {
			dp[i][j] = math.Inf(0)
		}
	}

	for i := n - 1; i >= 0; i-- {
		for j := n - 2; j >= 0; j-- {
			var max, sum float64
			for _, t := range to[j] {
				x := dp[i][t] + 1
				if max < x {
					max = x
				}
				sum += x
			}
			dp[i][j] = sum / float64(len(to[j]))
			if i == j && len(to[j]) >= 2 {
				dp[i][j] = math.Min(dp[i][j], (sum-max)/float64(len(to[j])-1))
			}
		}
	}

	ans := math.Inf(0)
	for i := 0; i < n; i++ {
		if ans > dp[i][0] {
			ans = dp[i][0]
		}
	}
