var sc *bufio.Scanner

func nextStr() string {
	sc.Scan()
	return sc.Text()
}

func nextInt() int {
	sc.Scan()
	i, e := strconv.Atoi(sc.Text())
	if e != nil {
		panic(e)
	}
	return i
}

type node struct {
	sum     int
	pattern int
	next    []int
	prev    []int
}

type edge struct {
	start int
	tail  int
}

func dfs(a, b int) int {
	if a < b {
		a, b = b, a
	}
	if a%b == 0 {
		return b
	}
	return dfs(b, a%b)
}

func calculateExpect(n int, nodes []node) {
	for u := n - 1; u >= 0; u-- {
		multiply := 1
		for _, v := range nodes[u].next {
			multiply = multiply * nodes[v].pattern / dfs(multiply, nodes[v].pattern)
		}
		for _, v := range nodes[u].next {
			if nodes[v].sum == -1 {
				continue
			}
			nodes[u].sum += (nodes[v].sum + nodes[v].pattern) * (multiply / nodes[v].pattern)
			nodes[u].pattern += multiply
		}
	}
}

func main() {
	sc = bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 0), 1000000001*3)
	sc.Split(bufio.ScanWords)
	n, m := nextInt(), nextInt()
	nodes := make([]node, n+1)
	edges := make([]edge, m)
	for mi := 0; mi < m; mi++ {
		s, t := nextInt()-1, nextInt()-1
		edges[mi].start, edges[mi].tail = s, t
		nodes[s].next = append(nodes[s].next, t)
		nodes[t].prev = append(nodes[t].prev, s)
	}
	// to exit(dummy node)
	nodes[n-1].next = []int{n}
	nodes[n-1].pattern = 1
	nodes[n].sum = -1
	nodes[n].pattern = 1

	calculateExpect(n, nodes)

	ans := float64(nodes[0].sum) / float64(nodes[0].pattern)
	for _, e := range edges {
		if len(nodes[e.start].next) == 1 {
			continue
		}
		for ni := 0; ni < n-1; ni++ {
			nodes[ni].sum, nodes[ni].pattern = 0, 0 // initialize
		}
		var nextiRestore int
		for nexti, v := range nodes[e.start].next {
			if v == e.tail {
				nextiRestore = nexti
				nodes[e.start].next[nexti] = n // dummy node
				break
			}
		}
		calculateExpect(n, nodes)
		expect := float64(nodes[0].sum) / float64(nodes[0].pattern)
		if expect < ans {
			ans = expect
		}
		nodes[e.start].next[nextiRestore] = e.tail // restore
	}
	fmt.Println(ans)
}

