    line, isPrefix, err := reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer, line...)
    if !isPrefix { break }
  }
  return string(buffer)
}
func NextIntVec() []int {
  L := strings.Split(NextLine(), " ")
  N := make([]int, len(L))
  for i := range N {
    N[i], _ = strconv.Atoi(L[i])
  }
  return N
}
func Write(s interface{}) {
  fmt.Fprintln(writer, s)
}
func Output() {
  _ = writer.Flush()
}

func Sum(A *[]int) int {
  s := 0
  for _, a := range (*A) {
    s += a
  }
  return s
}

func Max(A *[]int) int {
  m := 0
  for _, a := range (*A) {
    if m < a { m = a }
  }
  return m
}

func main() {
  NM := NextIntVec()
  N, M := NM[0], NM[1]
  G := make([][]int, N)
  for i := range G {
    G[i] = make([]int, 0)
  }
  for i := 0; i < M; i++ {
    ST := NextIntVec()
    s, t := ST[0] - 1, ST[1] - 1
    G[s] = append(G[s], t)
  }
  E := make([][]float64, N)
  for i := range E {
    E[i] = make([]float64, N)
  }
  for i := N - 2; -1 < i; i-- {
    for _, adj := range G[i] {
      E[0][i] += E[0][adj] / float64(len(G[i]))
    }
    E[0][i] += 1.0
  }
  for i := 1; i < N; i++ {
    t := N - 1
    for _, adj := range G[i - 1] {
      if E[0][t] < E[0][adj] { t = adj }
    }
    for j := N - 2; -1 < j; j-- {
      D := float64(len(G[j]))
      if i - 1 == j { D -= 1.0 }
      for _, adj := range G[j] {
        if i - 1 == j && adj == t { continue }
        E[i][j] += E[i][adj] / D
      }
      E[i][j] += 1.0
      if D < 1.0 { E[i][j] = float64(N * N) }
    }
  }
  ans := float64(N)
  for _, e := range E {
    if e[0] < ans { ans = e[0] }
  }
  Write(ans)
  Output()
}

