			memo[pos] = res / edges[pos].length + 1.0;
			return res / edges[pos].length + 1.0;
		}
	}

	double ans = double.max;
	{
		double[long] memo;
		auto r = dfs(0, new bool[](N), memo);
		if (r != -1.0)
			ans = min(ans, r);
	}
	foreach (i; 0..M)
	{
		auto tmp = st[i];
		auto pos = edges[tmp[0]].countUntil(tmp[1]);
		edges[tmp[0]] = edges[tmp[0]].remove(pos);
		double[long] memo;
		auto r = dfs(0, new bool[](N), memo);
		if (r != -1.0)
			ans = min(ans, r);
