void solve(){
	int n = rint, m = rint;
	Node[] nodes;
	foreach(i; 0 .. n) nodes ~= new Node(i, i + 1);
	foreach(j; 0 .. m){
		int a = rint - 1, b = rint - 1;
		nodes[a].kids ~= nodes[b];
	}
	log("kids:", nodes.map!(nd => nd.kids.map!(kid => kid.name)));

	foreach_reverse(nd; nodes){
		if(nd.id == n - 1) nd.value = 0.0;
		else foreach(kid; nd.kids) nd.value += (kid.value + 1.0) / nd.kids.length.to!real;
	}
	foreach(nd; nodes){
		if(nd.id == 0) nd.weight = 1.0;
		foreach(kid; nd.kids) kid.weight += nd.weight / nd.kids.length.to!real;
	}
	log("value:", nodes.map!(nd => nd.value));
	log("weight:", nodes.map!(nd => nd.weight));

	real bestx = 0.0;
	int bestndid, bestkidid;
	foreach(nd; nodes){
		if(nd.kids.length <= 1) continue;
		foreach(kid; nd.kids){
			real x = nd.weight * ((nd.value - (kid.value + 1.0) / nd.kids.length.to!real) 
					* nd.kids.length.to!real / (nd.kids.length - 1).to!real- (kid.value + 1.0))
					/ nd.kids.length.to!real;
