			if(x < bestx){
				bestx = x;
				bestndid = nd.id;
				bestkidid = kid.id;
			}
		}
	}
	log("best:", bestx, bestndid, bestkidid);

	writefln("%10.10f", nodes[0].value + bestx);

}

