void solve(){
	int n = rint, m = rint;
	Node[] nodes;
	foreach(i; 0 .. n) nodes ~= new Node(i, i + 1);
	foreach(j; 0 .. m){
		nodes[rint - 1].kids ~= nodes[rint - 1];
	}

	foreach_reverse(nd; nodes){
		if(nd.id == n - 1) nd.value = 0.0;
		else foreach(kid; nd.kids) nd.value += (kid.value + 1) / nd.kids.length.to!real;
	}
	foreach(nd; nodes){
		if(nd.id == 0) nd.weight = 1.0;
		foreach(kid; nd.kids) kid.weight += nd.weight / nd.kids.length.to!real;
