void main()
{
	auto N = RD;
	auto M = RD;
	auto st = new long[][](M, 2);
	foreach (i; 0..M)
	{
		auto s = RD-1;
		auto t = RD-1;
		st[i] = [s, t];
	}

	auto edges = new long[][](N);
	foreach (j; 0..M)
	{
		edges[st[j][0]] ~= st[j][1];
	}

	double dfs(long pos, bool[] used, double[long] memo)
	{
		if (pos == N-1) return 1.0;
		if (used[pos]) return -1.0;
		if (memo.get(pos, -1.0) != -1.0) return memo[pos];

		used[pos] = true;
		double res = 0.0;
		foreach (v; edges[pos])
		{
			auto r = dfs(v, used, memo);
			//debug writeln("u:", pos, " v:", v, " r:", r);
			if (r == -1.0) return r;
			res += r;
		}
		used[pos] = false;
		if (edges[pos].empty)
		{
			memo[pos] = -1.0;
			return -1.0;
		}
		else if (pos == 0)
		{
			memo[pos] = res / edges[pos].length;
			return res / edges[pos].length;
		}
		else
		{
			memo[pos] = res / edges[pos].length + 1.0;
			return res / edges[pos].length + 1.0;
		}
	}

	double ans = double.max;
	{
		double[long] memo;
		auto r = dfs(0, new bool[](N), memo);
		if (r != -1.0)
			ans = min(ans, r);
	}
	foreach (i; 0..M)
	{
		edges = new long[][](N);
		foreach (j; 0..M)
		{
			if (i == j) continue;
			edges[st[j][0]] ~= st[j][1];
		}
		double[long] memo;
		auto r = dfs(0, new bool[](N), memo);
		if (r != -1.0)
			ans = min(ans, r);
		debug writeln("i:", i, " ans:", ans);

	}

	writefln(FMT_F, ans);
	stdout.flush();
	debug readln();
}

