INF = float("inf")


class Graph(object):
    def __init__(self, N):
        self.N = N
        self.E = [[] for _ in range(N)]
        self.revE = [[] for _ in range(N)]

    def add_edge(self, s, t, w=1):
        self.E[s].append((t, w))
        self.revE[t].append((s, w))


def solve(N: int, M: int, s: "List[int]", t: "List[int]"):
    c = Counter(s)
    g = Graph(N)
    for ss, tt in zip(s, t):
        g.add_edge(ss, tt)

    DP = [0]*N
    for i in range(N-2, -1, -1):
        DP[i] = sum(DP[t] for t, w in g.E[i])/c[i] + 1

    gm = DP[0]
    for i in range(N-2):
        if len(g.E[i]) == 1:
            continue
        dp = DP[:]
        for j in range(i, -1, -1):
            a = tuple(dp[t] for t, w in g.E[j])
            b = sum(a)
            if i == j:
                dp[j] = (b-max(a))/(c[j]-1)
            else:
                dp[j] = b/c[j]
            dp[j] += 1
        gm = min(dp[0], gm)
        # print(dp)
    print(gm)


