import copy
import numpy as np
from scipy.sparse import csr_matrix

def openinput():
    n, m = map(int, input().split())
    s ,t = [], []
    for _ in range(m):
        si, ti = map(int, input().split())
        s.append(si - 1)
        t.append(ti - 1)
    return n, m, s, t

def make_adjacency_matrix(weights, edges, num_of_nodes):
    return csr_matrix((weights, edges), shape=(num_of_nodes, num_of_nodes)).toarray()

def edit_mat(mat, weight, edge_from, edge_to):
    copied = copy.deepcopy(mat)
    copied[edge_from, edge_to] = weight
    return copied

def depth_first_search(mat, start_node):
    to_visit = [(start_node, 0, 1.0)]    # (node, depth, expected_value)
    depth_expecteds = []  # expected value of path length from 0 to n-1
    while to_visit:
        visit, depth, expected = to_visit.pop()
        if visit == n-1:
            depth_expecteds.append(depth * expected)
        else:
            nexts = [v for v, c in enumerate(mat[visit]) if c > 0]
            if nexts:
                for next in nexts:
                    to_visit.append((next, depth+1, expected/len(nexts)))
            else:   # leaf node but not n
                depth_expecteds.append(np.inf)
    return sum(depth_expecteds)





if __name__ == "__main__":
    n, m, s, t = openinput()
    adjacency_matrix = make_adjacency_matrix([1]*m, (s,t), n)

    rawcols = np.where(adjacency_matrix == 1)
    expecteds = []
    for r, c in zip(rawcols[0], rawcols[1]):
        mat = edit_mat(adjacency_matrix, 0, r, c)
        expecteds.append(depth_first_search(mat, 0))

    min_expected = np.min(expecteds)
    if np.isinf(min_expected):
        print(depth_first_search(adjacency_matrix, 0))
    else:
        print(min_expected)

