def to_n_expected(edges, num_of_nodes, recursive_depth=0):
    dp_table = np.zeros(num_of_nodes)
    recursive_shotest = np.inf
    for v in reversed(range(n-1)):
        if recursive_depth < 1:
            max_next = max(edges[v], key= lambda x: dp_table[x])
            edges[v].remove(max_next)
            expected = to_n_expected(edges, num_of_nodes, recursive_depth=1)
            edges[v].append(max_next)
            recursive_shotest = min(recursive_shotest, expected)

        out_degree = len(edges[v])
        if out_degree > 0:
            dp_table[v] = 1 + sum(dp_table[ne] for ne in edges[v]) / out_degree
        else:
            dp_table[v] = np.inf
    return min(recursive_shotest, dp_table[0])

