class Graph(object):
    def __init__(self, N):
        self.N = N
        self.E = [[] for _ in range(N)]
        self.revE = [[] for _ in range(N)]

    def add_edge(self, s, t, w=1):
        self.E[s].append((t, w))
        self.revE[t].append((s, w))


def solve(N: int, M: int, s: "List[int]", t: "List[int]"):
    c = Counter(s)
    g = Graph(N)
    for ss, tt in zip(s, t):
        g.add_edge(ss, tt, 1/c[ss])

    DP = [0]*N
    for i in range(N-2, -1, -1):
        DP[i] = sum(DP[t] for t, w in g.E[i])/c[i] + 1
    # print(DP)

    gm = DP[0]
    for i in range(N-1):
        if len(g.E[i]) == 1:
            continue
        m = 0
        mj = -1
        for j, _ in g.E[i]:
            if m < DP[j]:
                m = DP[j]
                mj = j
