    dp_table = [0]*num_of_nodes

    recursive_expected = []
    for v in range(num_of_nodes-1, 0, -1):
        nexts = next_nodes(adjacency_matrix, v-1)
        if recursive_depth < 1:
            argmax = 0
            for i, next in enumerate(nexts):
                argmax = i if dp_table[i]<dp_table[next] else argmax
            max_next = nexts[argmax]
            edimat = editted_mat(adjacency_matrix, v-1, max_next)
            expected = v_to_n_expected(edimat, num_of_nodes, recursive_depth=1)
            recursive_expected.append(expected)

        num_of_nexts = len(nexts)
        if num_of_nexts > 0:
            dp_table[v-1] = 1 + sum(dp_table[next] for next in nexts) / num_of_nexts
        else:
            dp_table[v-1] = 600
    recursive_expected.append(dp_table[0])
    return min(recursive_expected)

