import copy
import numpy as np
from scipy.sparse import csr_matrix

def openinput() :
    n, m = map(int, input().split())
    s ,t = [], []
    for _ in range(m):
        si, ti = map(int, input().split())
        s.append(si - 1)
        t.append(ti - 1)
    return n, m, s, t

def make_adjacency_matrix(weights, edges, num_of_nodes):
    return csr_matrix((weights, edges), shape=(num_of_nodes, num_of_nodes)).toarray()

def next_nodes(adjacency_matrix, node):
    return [v for (v, e) in enumerate(adjacency_matrix[node]) if e > 0]

def editted_mat(mat, weight, edge_from, edge_to):
    copied = copy.deepcopy(mat)
    copied[edge_from, edge_to] = weight
    return copied

def v_to_n_expected(adjacency_matrix, num_of_nodes, recursive_depth=0):
    dp_table = np.zeros(num_of_nodes)

    recursive_expected = []
    for v in range(num_of_nodes-1, 0, -1):
        nexts = next_nodes(adjacency_matrix, v-1)
        if recursive_depth < 1:
            max_next = nexts[np.argmax(dp_table[next] for next in nexts)]
            edimat = editted_mat(adjacency_matrix, 0, v-1, max_next)
            expected = v_to_n_expected(edimat, num_of_nodes, recursive_depth=1)
            recursive_expected.append(expected)

        num_of_nexts = len(nexts)
        if num_of_nexts > 0:
            dp_table[v-1] = 1 + sum(dp_table[next] for next in nexts) / num_of_nexts
        else:
            dp_table[v-1] = np.inf
    recursive_expected.append(dp_table[0])
    return min(recursive_expected)

if __name__ == '__main__':
