fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let m: usize = sc.read();

    let mut graph = vec![vec![]; n];
    let mut inv = vec![vec![]; n];
    for _ in 0..m {
        let a = sc.read::<usize>() - 1;
        let b = sc.read::<usize>() - 1;
        graph[a].push(b);
        inv[b].push(a);
    }

    let dp = calc(&graph, &inv, (n, n));
    let mut ans = dp[0];
    for next in 0..n {
        if let Some(&max_from) = inv[next]
            .iter()
            .filter(|&&from| graph[from].len() > 1)
            .max_by(|&&from_a, &&from_b| dp[from_a].partial_cmp(&dp[from_b]).unwrap())
        {
            let dp = calc(&graph, &inv, (max_from, next));
            if ans > dp[0] {
                ans = dp[0];
            }
        }
    }
    println!("{}", ans);
}

fn calc(graph: &Vec<Vec<usize>>, inv: &Vec<Vec<usize>>, block: (usize, usize)) -> Vec<f64> {
    let n = graph.len();
    let mut dp = vec![0.0; n];
    for next in (0..n).rev() {
        for &from in inv[next].iter() {
            if (from, next) == block {
                continue;
            }

            let count = if from == block.0 {
                (graph[from].len() - 1) as f64
            } else {
                graph[from].len() as f64
            };
            dp[from] += (dp[next] + 1.0) / count;
        }
    }
    dp
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> IO<R, W> {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: std::ops::Deref<Target = str>>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

