    edges: Vec<Vec<usize>>,
}
impl Graph {
    pub fn dfs(&self, cur: usize, from: usize, ex: &mut Vec<Option<f64>>) -> f64 {
        if ex[cur].is_some() {
            return ex[cur].unwrap();
        }

        let mut e: f64 = 0.0;
        for &to in self.edges[cur].iter() {
            e += self.dfs(to, cur, ex) + 1.0;
        }
        e /= self.edges[cur].len() as f64;
        ex[cur] = Some(e);
        e
    }
}

