fn solve(src: &str) -> String {
    let mut sc = Scanner::from_str(src);

    let n: usize = sc.read();
    let m: usize = sc.read();
    let child = {
        let mut child = vec![vec![]; n];
        for _ in 0..m {
            let v: usize = sc.read();
            let w: usize = sc.read();
            child[v - 1].push(w - 1);
        }
        child
    };
    let mut ans = 1000.;
    for stop in 0..n - 1 {
        let mut to_n: Vec<Option<f64>> = vec![None; n];
        to_n[n-1] = Some(0.);
        for i in (0..n - 1).rev() {
            let mut c_to_n = vec![];
            for &j in &child[i] {
                if let Some(to_n) = to_n[j] {
                    c_to_n.push(to_n + 1.);
                }
            }
            let ctnl = c_to_n.len();
            if ctnl > 0 {
                let s: &f64 = &c_to_n.iter().sum();
                to_n[i] = Some(if i == stop && ctnl > 1 {
                    let m = &c_to_n.iter().fold(0., |m, &v| if m < v { v } else { m });
                    (s - m) / (ctnl as f64 - 1.)
                } else {
                    s / ctnl as f64
                });
            }
        }
        if ans > to_n[0].unwrap() {
            ans = to_n[0].unwrap();
        }
    }

    format!("{}\n", ans)
}
