macro_rules! parse {
    ($it: ident ) => {};
    ($it: ident, ) => {};
    ($it: ident, $var:ident : $t:tt $($r:tt)*) => {
        let $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
    ($it: ident, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
}

#[allow(unused_macros)]
macro_rules! parse_val {
    ($it: ident, [$t:tt; $len:expr]) => {
        (0..$len).map(|_| parse_val!($it, $t)).collect::<Vec<_>>();
    };
    ($it: ident, ($($t: tt),*)) => {
        ($(parse_val!($it, $t)),*)
    };
    ($it: ident, u1) => {
        $it.next().unwrap().parse::<usize>().unwrap() -1
    };
    ($it: ident, $t: ty) => {
        $it.next().unwrap().parse::<$t>().unwrap()
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, n: usize, m: usize, mut st: [(u1, u1); m]);
    let mut g = vec![vec![]; n];
    for &(s, t) in st.iter() {
        g[s].push(t)
    }
    let mut dp = vec![0.; n];
    dfs(0, n - 1, &g, &mut dp, (0, 0));
    let mut ret = dp[0];
    let mut dp1 = vec![0.; n];
    for i in 0..(n - 1) {
        let mut j = 0;
        let mut m = 0.;
        for &ij in g[i].iter() {
            if m < dp[ij] {
                j = ij;
                m = dp[j]
            }
        }
        if j != 0 {
            dfs(0, n - 1, &g, &mut dp1, (i, j));
            ret = ret.min(dp1[0]);
        }
    }
    println!("{}", ret);
}
fn dfs(u: usize, dest: usize, g: &Vec<Vec<usize>>, dp: &mut Vec<f64>, stop: (usize, usize)) {
    if u == dest {
        return;
    }
    let mut count = 0.;
    let mut ret = 0.;
    for &v in g[u].iter() {
        if (u, v) == stop {
            continue;
        }
        count += 1.;
        dfs(v, dest, g, dp, stop);
        ret += dp[v];
    }
    dp[u] = ret / count + 1.
}

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    solve(&s);
}

