        let mut ex_list = vec![];
        for &to in self.edges[cur].iter() {
            ex_list.push(
                self.dfs(to, cur, ex, i) + 1.0
            )
        }

        if i == cur {
            ex_list.sort_by(|a, b| a.partial_cmp(b).unwrap());
            if ex_list.len() > 1 {
                ex_list.pop();
            }
        }

        let e = ex_list.iter().sum::<f64>() / ex_list.len() as f64;
        ex[cur] = Some(e);
        e
    }
}

