const inf: f64 = 1e18;

fn f(graph: &Vec<Vec<usize>>, ignore: (usize, usize)) -> f64 {
    let n = graph.len();
    let mut dp = vec![inf; n];
    dp[n - 1] = 0.0;
    for i in (0..n - 1).rev() {
        let mut count = 0;
        let mut e = 0.0;
        for &k in &graph[i] {
            if ignore != (i, k) {
                count += 1;
                e += dp[k];
            }
        }
        if count != 0 {
            dp[i] = e / count as f64 + 1.0;
        }
    }
    dp[0]
}

use std::fmt::Write;
fn solve<R: BufRead>(parser: &mut Parser<R>) -> String {
    let mut buf = String::new();
    input! {
        parser = parser,
        n: usize,
        m: usize,
        es: [(usize1, usize1); m],
    }
    let mut graph = vec![vec![]; n];
    for &(s, t) in &es {
        graph[s].push(t);
    }
    let mut res = f(&graph, (n, n));
    for &(s, t) in &es {
        let t = f(&graph, (s, t));
        if res > t {
            res = t;
        }
    }
    writeln!(buf, "{:.20}", res);
    buf
}

