use std::io::Read;

fn main() {
    let mut buf = String::new();
    std::io::stdin().read_to_string(&mut buf).unwrap();
    let mut iter = buf.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let m: usize = iter.next().unwrap().parse().unwrap();

    let mut g: Vec<Vec<usize>> = vec![Vec::new(); n];
    let mut s: Vec<usize> = Vec::with_capacity(m);
    let mut t: Vec<usize> = Vec::with_capacity(m);
    for i in 0..m {
        s.push(iter.next().unwrap().parse().unwrap());
        t.push(iter.next().unwrap().parse().unwrap());
        s[i] -= 1;
        t[i] -= 1;
        g[s[i]].push(t[i]);
    }

    let mut arrive: Vec<f32> = vec![0.0; n];
    arrive[0] = 1.0;
    for u in 0..n {
        for v in &g[u] {
            arrive[*v] += arrive[u] / g[u].len() as f32;
        }
    }

    let mut aisle: Vec<f32> = vec![0.0; n];
    for u in (0..n).rev() {
        for v in &g[u] {
            aisle[u] += aisle[*v] + 1.0;
        }
        aisle[u] /= usize::max(1, g[u].len()) as f32;
    }

    let mut ans: f32 = aisle[0];
    for i in 0..m {
        if g[s[i]].len() == 1 { continue; }

        let mut res: f32 = 0.0;
        res += aisle[s[i]] * g[s[i]].len() as f32;
        res -= aisle[t[i]] + 1.0;
        res /= (g[s[i]].len() - 1) as f32;
        res = aisle[s[i]] - res;
        res = aisle[0] - res * arrive[s[i]];
        ans = f32::min(res, ans);
    }

    println!("{:.10}", ans);
}

