fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    input! {
        n: usize,
        m: usize,
        st: [(usize1, usize1); m],
    }
    let mut g = vec![vec![]; n];
    for &(s, t) in &st {
        g[s].push(t);
    }
    let mut dp1 = vec![0.0; n];
    for i in (0..n - 1).rev() {
        let mut sum = 0.0;
        let mut cnt = 0.0;
        for &t in &g[i] {
            sum += dp1[t];
            cnt += 1.0;
        }
        dp1[i] = sum / cnt + 1.0;
    }
    let mut dp2 = vec![0.0; n];
    let mut prob2 = vec![0.0; n];
    prob2[0] = 1.0;
    for i in 0..n - 1 {
        let cnt = g[i].len() as f64;
        for &t in &g[i] {
            prob2[t] += prob2[i] / cnt;
            dp2[t] += (dp2[i] + prob2[i]) / cnt;
        }
    }
    debugln!("dp1 = {:?}", dp1);
    debugln!("dp2 = {:?}", dp2);
    debugln!("prob2 = {:?}", prob2);
    let mut mi = 0.0;
    for i in 0..n {
        let mut sum = 0.0;
        let mut cnt = 0.0;
        for &t in &g[i] {
            sum += dp1[t];
            cnt += 1.0;
        }
        if cnt == 1.0 {
            continue;
        }
        for &t in &g[i] {
            let diff = (sum - dp1[t]) / (cnt - 1.0) - sum / cnt;
            let diff = diff * prob2[i];
            if mi > diff {
                mi = diff;
            }
        }
    }
    puts!("{}\n", mi + dp1[0]);
}

