    let mut dp: Vec<f64> = vec![0f64; n];
    //i+1->n => 1
    //i+1->x->n = 1+avg
    for i in (0..n - 1).rev() {
        let mut cnt = 0;
        for &(s, e) in &paths {
            if s == i + 1 {
                cnt += 1;
                dp[i] += dp[e - 1];
            }
        }
        dp[i] /= cnt as f64;
        dp[i] += 1f64;
    }
    //println!("{:?}", dp);
    let seal_from = dp
        .iter()
        .map(|d| *d)
        .enumerate()
        .fold((0, 0.0 / 0.0), |l, r| {
            if (l.1).partial_cmp(&(r.1)).unwrap_or(Ordering::Less) == Ordering::Greater {
                l
            } else {
                r
            }
        })
        .0;
    let mut dp_sealed: Vec<f64> = Vec::new();
    dp_sealed.push(dp[0]);
    for seal in paths
        .iter()
        .enumerate()
        .filter(|path| (path.1).0 == seal_from + 1)
    {
        dp = vec![0f64; n];
        for i in (0..n - 1).rev() {
            let mut cnt = 0;
            for &(s, e) in &paths {
                if s == i + 1 && &(s, e) != seal.1 {
                    cnt += 1;
                    dp[i] += dp[e - 1];
                }
            }
            dp[i] /= cnt as f64;
            dp[i] += 1f64;
        }
        dp_sealed.push(dp[0]);
        //println!("sealed:{:?},{:?}", seal, dp);
    }
    //println!("dp_seald{:?}", dp_sealed);
    println!("{}", dp_sealed.into_iter().fold(0.0 / 0.0, f64::min));
}

