#[derive(PartialEq,PartialOrd)]
struct Of64(f64);

impl Eq for Of64 {}

impl Ord for Of64 {
    fn cmp(&self, other: &Of64) -> Ordering {
        self.partial_cmp(other).unwrap()
    }
}

fn minf(a: f64, b: f64) -> f64 {
    if a <= b {
        a
    } else {
        b
    }
}

fn solve(f: usize, graph: &Vec<Vec<usize>>) -> f64 {
    let n = graph.len();
    let mut dp = vec![0.0f64; n];
    for i in (0..n-1).rev() {
        let mut total = 0.0;
        let mut wmax = 0.0;
        for &to in &graph[i] {
            total += dp[to];
            wmax = f64::max(wmax, dp[to]);
        }
        let cn = graph[i].len();
        let cnf = cn as f64;
        if f == i && cnf >= 2.0 {
            dp[i] = (total - wmax) / (cnf - 1.0);
        } else {
            dp[i] = total / cnf;
        }
        dp[i] += 1.0;
    }
    dp[0]
}

fn main() {
    input! {
        n: usize, m: usize,
        edges: [(usize1, usize1); m]
    };

    let mut graph = vec![vec![]; n];
    for (u, v) in edges {
        graph[u].push(v);
    }
    let mut best = INF;
    for i in 0..n-1 {
        best = f64::min(best, solve(i, &graph));
    }
    println!("{:.9}", best);
}

use std::cmp::{Ordering, min};
use std::io::{self, BufRead};
use std::ops::{Add, Mul};

fn gcd(x: usize, y: usize) -> usize {
  let (mut a, mut b) = if x < y {
    (y, x)
  } else {
    (x, y)
  };
  while b != 0 {
    let r = a % b;
    a = b;
    b = r;
  }
  a
}

fn lcm_by_gcd(x: usize, y: usize, g: usize) -> usize {
  x * y / g
}

#[derive(Debug, Clone, Copy, Eq)]
struct Rational(usize, usize);

impl Add<Self> for Rational {
  type Output = Self;
  fn add(self, rhs: Self) -> Self::Output {
    let g = gcd(self.1, rhs.1);
    let l = lcm_by_gcd(self.1, rhs.1, g);
    Rational(self.0 * rhs.1 / g + rhs.0 * self.1 / g, l)
  }
}

impl Mul<Self> for Rational {
  type Output = Self;
  fn mul(self, rhs: Self) -> Self::Output {
    let n = self.0 * rhs.0;
    let d = self.1 * rhs.1;
    let g = gcd(n, d);
    Rational(n / g, d / g)
  }
}

impl Ord for Rational {
  fn cmp(&self, rhs: &Self) -> Ordering {
    let g = gcd(self.1, rhs.1);
    let l = self.0 * rhs.1 / g;
    let r = rhs.0 * self.1 / g;
    l.cmp(&r)
  }
}

impl PartialOrd for Rational {
  fn partial_cmp(&self, rhs: &Self) -> Option<Ordering> {
    Some(self.cmp(rhs))
  }
}

impl PartialEq for Rational {
  fn eq(&self, rhs: &Self) -> bool {
    let g = gcd(self.1, rhs.1);
    let l = self.0 * rhs.1 / g;
    let r = rhs.0 * self.1 / g;
    l == r
  }
}

const ZERO: Rational = Rational(0, 1);
const ONE: Rational = Rational(1, 1);

fn main() {
  let stdin = io::stdin();
  let mut lines = stdin.lock().lines();
  let line = lines.next().unwrap().unwrap();
  let vs: Vec<usize> = line.split(' ').map(|x| x.parse().unwrap()).collect();
  let (n, m) = (vs[0], vs[1]);
  let mut es: Vec<Vec<usize>> = vec![Vec::new(); n];
  for _ in 0..m {
    let line = lines.next().unwrap().unwrap();
    let vs: Vec<usize> = line.split(' ').map(|x| x.parse().unwrap()).collect();
    let (s, t) = (vs[0] - 1, vs[1] - 1);
    es[s].push(t);
  }
  for i in 0..n {
    es[i].sort();
  }
  let mut memo0: Vec<Rational> = vec![ZERO; n];
  let mut memo1: Vec<Option<Rational>> = vec![None; n];
  for k in 1..n {
    let i = n - k - 1;
    let count = es[i].len();
    memo0[i] = ONE + Rational(1, count) * es[i].iter().map(|j| memo0[*j]).fold(ZERO, |acc, x| acc + x);
    if count > 1 {
      let mut temp = Vec::new();
      for j in 0..count {
        let x = (0..count).filter(|l| *l != j).map(|l| memo0[es[i][l]]).fold(ZERO, |acc, x| acc + x);
        let r1 = ONE + Rational(1, count - 1) * x;
        temp.push(r1);
        if let Some(y) = memo1[es[i][j]] {
          let r2 = ONE + Rational(1, count) * (x + y);
          temp.push(r2);
        }
      }
      memo1[i] = Some(*temp.iter().min().unwrap());
    }
  }
  let r = if let Some(r) = memo1[0] {
    min(memo0[0], r)
  } else {
    memo0[0]
  };
  let ans = r.0 as f64 / r.1 as f64;
  println!("{}", ans);
}

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };

    let n: usize = sc.read();
    let m: usize = sc.read();
    let mut graph = vec![vec![]; n];
    let mut inverse = vec![vec![]; n];
    for _ in 0..m {
        let a = sc.read::<usize>() - 1;
        let b = sc.read::<usize>() - 1;
        graph[a].push(b);
        inverse[b].push(a);
    }

    let probability = calc_probability(&graph, &inverse, (n, n));
    let mut ans = probability[0];
    for from in 0..n {
        if graph[from].len() == 1 {
            continue;
        }
        if let Some(&next) = graph[from]
            .iter()
            .max_by(|&&next1, &&next2| probability[next1].partial_cmp(&probability[next2]).unwrap())
        {
            let p = calc_probability(&graph, &inverse, (from, next));
            if p[0] < ans {
                ans = p[0];
            }
        }
    }

    println!("{}", ans);
}

fn calc_probability(
    graph: &Vec<Vec<usize>>,
    inverse: &Vec<Vec<usize>>,
    prohibited: (usize, usize),
) -> Vec<f64> {
    let n = inverse.len();
    let mut dp = vec![0.0; n];
    for next in (0..n).rev() {
        for &from in inverse[next].iter() {
            if (from, next) == prohibited {
                continue;
            }
            let s = if from == prohibited.0 {
                graph[from].len() as f64 - 1.0
            } else {
                graph[from].len() as f64
            };
            dp[from] += (dp[next] + 1.0) / s;
        }
    }
    //    println!("{:?} dp={:?}", prohibited, dp);
    dp
}

