impl<R: std::io::Read> Scanner<R> {
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .stdin
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n')
            .take_while(|&b| b != b' ' && b != b'\n')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let m: usize = sc.read();
    let mut graph = vec![vec![]; n];
    let mut inv = vec![vec![]; n];
    for _ in 0..m {
        let a = sc.read::<usize>() - 1;
        let b = sc.read::<usize>() - 1;
        graph[a].push(b);
        inv[b].push(a);
    }

    let p = calc(&graph, &inv, (n, n));
    let mut ans = p[0];
    for from in 0..n {
        if graph[from].len() <= 1 {
            continue;
        }
        let to = *graph[from]
            .iter()
            .max_by(|&&to1, &&to2| p[to1].partial_cmp(&p[to2]).unwrap())
            .unwrap();
        let ans1 = calc(&graph, &inv, (from, to))[0];
        if ans > ans1 {
            ans = ans1;
        }
    }

    println!("{}", ans);
}

fn calc(graph: &Vec<Vec<usize>>, inv: &Vec<Vec<usize>>, (from, to): (usize, usize)) -> Vec<f64> {
    let n = graph.len();
    let mut p = vec![0.0; n];
    for i in (0..n).rev() {
        for &prev in inv[i].iter() {
            if (prev, i) == (from, to) {
                continue;
            }
            let mut count = graph[prev].len() as f64;
            if prev == from {
                count -= 1.0;
            }
            p[prev] += (p[i] + 1.0) / count;
        }
    }
    p
}

