fn average(v: &[f64]) -> f64 {
    v.iter().sum::<f64>() / v.len() as f64
}

fn solve<R: Read, W: Write>(mut sc: Scanner<R>, mut w: BufWriter<W>) {
    let n: usize = sc.read();
    let m: usize = sc.read();
    let edges: Vec<(usize, usize)> = sc.read_vec(m);

    let mut nexts = vec![Vec::new(); n];
    for (u, v) in edges {
        nexts[u - 1].push(v - 1);
    }

    let mut answer = 1e18;
    for r in 0..n - 1 {
        let mut dp = vec![0.0; n];
        for i in (0..n - 1).rev() {
            let mut vals = nexts[i].iter().map(|x| dp[*x]).collect::<Vec<_>>();
            if r == i && vals.len() > 1 {
                vals.sort_by_key(|x| Num(*x));
                vals.pop();
            }
            dp[i] = average(&vals) + 1.0;
        }
        answer.set_min(dp[0]);
    }
    println!("{}", answer);
}

fn run() {
    let stdin = io::stdin();
    let stdout = io::stdout();

    let input = stdin.lock();
    let output = BufWriter::new(stdout.lock());

    solve(Scanner::new(input), output);
}

