const M: i64 = 1_000_000_007;

fn main() {
    let mut sc = Scanner::new();
    let n: usize = sc.cin();
    let m: usize = sc.cin();
    let mut g = vec![vec![]; n];
    for _ in 0..m {
        let s = sc.cin::<usize>() - 1;
        let t = sc.cin::<usize>() - 1;
        g[s].push(t);
    }
    let mut ecands = vec![(n, n)];
    for i in 0..n {
        if g[i].len() <= 1 { continue }
        g[i].sort();
        ecands.push((i, g[i][0]));
    }
    let inf = 9000000.0;
    let mut ans = inf;
    for k in 0..ecands.len() {
        let (sx, tx) = ecands[k];
        let mut dp = vec![0.0f64; n];
        for i in (0..n-1).rev() {
            let deg = {
                if sx == i {
                    g[i].len() - 1
                } else {
                    g[i].len()
                }
            };
            if deg == 0 {
                dp[i] = inf;
            } else {
                let p = 1.0 / (deg as f64);
                dp[i] = 1.0;
                for &j in g[i].iter() {
                    if i == sx && j == tx { continue }
                    dp[i] += dp[j] * p;
                }
            }
        }
        ans = min!(ans, dp[0]);
    }
    put!(ans);
}

use std::io::{self, Write};
use std::str::FromStr;
use std::collections::VecDeque;

struct Scanner { stdin: io::Stdin, buffer: VecDeque<String>, }
impl Scanner {
    fn new() -> Self { Scanner { stdin: io::stdin(), buffer: VecDeque::new() } }
    fn cin<T: FromStr>(&mut self) -> T {
        while self.buffer.len() == 0 {
            let mut line = String::new();
            let _ = self.stdin.read_line(&mut line);
            for w in line.split_whitespace() {
                self.buffer.push_back(String::from(w));
            }
        }
        self.buffer.pop_front().unwrap().parse::<T>().ok().unwrap()
    }
    fn chars(&mut self) -> Vec<char> { self.cin::<String>().chars().collect() }
