            .iter()
            .filter(|&&from| graph[from].len() > 1)
            .max_by(|&&a, &&b| probability[a].partial_cmp(&probability[b]).unwrap())
        {
            Some(&from) => {
                let p = calc_probability(&graph, (from, next));
                if p[n - 1] > 0.0 && p[n - 1] < ans {
