// [0.0, 0.0, 0.5]

fn calc_probability(graph: &Vec<Vec<usize>>, prohibited: (usize, usize)) -> Vec<f64> {
    let n = graph.len();

    let mut dp = vec![0.0; n];
    dp[0] = 1.0;
    let mut p = vec![0.0; n];
    for from in 0..n {
        let s = if from == prohibited.0 && graph[from].contains(&prohibited.1) {
            graph[from].len() - 1
        } else {
            graph[from].len()
        };
        for &next in graph[from].iter() {
            if (from, next) == prohibited {
                continue;
            }
            dp[next] += dp[from] / (s as f64);
            p[next] += (p[from] + dp[from]) / (s as f64);
        }
    }
    p
}

