fn main() {
    let mut buf = String::new();
    std::io::stdin().read_to_string(&mut buf).unwrap();
    let mut iter = buf.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let m: usize = iter.next().unwrap().parse().unwrap();

    let mut g: Vec<Vec<usize>> = vec![Vec::new(); n];
    let mut s: Vec<usize> = Vec::with_capacity(m);
    let mut t: Vec<usize> = Vec::with_capacity(m);
    for i in 0..m {
        s.push(iter.next().unwrap().parse().unwrap());
        t.push(iter.next().unwrap().parse().unwrap());
        s[i] -= 1;
        t[i] -= 1;
        g[s[i]].push(t[i]);
    }

    let mut arrive: Vec<f32> = vec![0.0; n];
    arrive[0] = 1.0;
    for u in 0..n {
        for v in &g[u] {
            arrive[*v] += arrive[u] / g[u].len() as f32;
        }
    }

    let mut aisle: Vec<f32> = vec![0.0; n];
    for u in (0..n).rev() {
        for v in &g[u] {
            aisle[u] += aisle[*v] + 1.0;
        }
        aisle[u] /= cmp::max(1, g[u].len()) as f32;
    }

    let mut ans: f32 = aisle[0];
    for i in 0..m {
        if g[s[i]].len() == 1 { continue; }

        let mut res: f32 = 0.0;
        res += aisle[s[i]] * g[s[i]].len() as f32;
        res -= aisle[t[i]] + 1.0;
        res /= (g[s[i]].len() - 1) as f32;
        res = aisle[s[i]] - res;
        res = aisle[0] - res * arrive[s[i]];
        ans = f32::min(res, ans);
    }

    println!("{:.10}", ans);
}

fn main() {
	let mut s = String::new();
	use std::io::Read;
	std::io::stdin().read_to_string(&mut s).unwrap();
	let mut s = s.split_whitespace();
	let n: usize = s.next().unwrap().parse().unwrap();
	let m: usize = s.next().unwrap().parse().unwrap();
	let mut edges = vec![];
	for _ in 0..m {
		let a = s.next().unwrap().parse::<usize>().unwrap() - 1;
		let b = s.next().unwrap().parse::<usize>().unwrap() - 1;
		edges.push((a, b));
	}
	edges.sort();
	let calc = |invalid| {
		let mut dp = vec![(0., 0.); n];
		let mut visit = vec![false; n];
		dp[0].1 = 1.;
		visit[0] = true;

		let mut li = 0;
		let mut ri = 0;
		while li < edges.len() {
			li = ri;
			let src = edges[li].0;
			while ri < edges.len() && src == edges[ri].0 {
				ri += 1;
			}
			let cnt = ri - li - if li <= invalid && invalid < ri { 1 } else { 0 };
			if cnt == 0 {
				return None;
			}
			let cnt = cnt as f64;
			for i in li..ri {
				if i == invalid {
					continue;
				}
				let to = edges[i].1;
				visit[to] |= visit[src];
				dp[to].0 += (dp[src].0 + dp[src].1) / cnt;
				dp[to].1 += dp[src].1 / cnt;
			}
			li = ri;
		}
		if visit[n - 1] {
			Some(dp[n - 1].0)
		} else {
			None
		}
	};

	let mut ans = 1000.;
