const inf: f64 = 1e18;

fn f(graph: &Vec<Vec<usize>>, ignore: (usize, usize)) -> Vec<f64> {
    let n = graph.len();
    let mut dp = vec![inf; n];
    dp[n - 1] = 0.0;
    for i in (0..n - 1).rev() {
        let mut count = 0;
        let mut e = 0.0;
        for &k in &graph[i] {
            if ignore != (i, k) {
                count += 1;
                e += dp[k];
            }
        }
        if count != 0 {
            dp[i] = e / count as f64 + 1.0;
        }
    }
    dp
}

fn prob(graph: &Vec<Vec<usize>>) -> Vec<f64> {
    let n = graph.len();
    let mut dp = vec![0.0; n];
    dp[0] = 1.0;
    for i in 0..n {
        for &k in &graph[i] {
            dp[k] += dp[i] / graph[i].len() as f64;
        }
    }
    dp
}

