fn solve<R: BufRead>(parser: &mut Parser<R>) -> String {
    let mut buf = String::new();
    input! {
        parser = parser,
        n: usize,
        m: usize,
        es: [(usize1, usize1); m],
    }
    let mut graph = vec![vec![]; n];
    for &(s, t) in &es {
        graph[s].push(t);
    }
    let exp_table = f(&graph, (n, n));
    let prob_table = prob(&graph);
    let origin = exp_table[0];
    let mut res = origin;
    for &(s, t) in &es {
        if graph[s].len() == 1 {
            continue;
        }
        let prob = prob_table[s];
        let exp = exp_table[s];
        let mut new_exp = 0.0;
        for &k in &graph[s] {
            if (s, k) == (s, t) {
                continue;
            }
            new_exp += (exp_table[k] + 1.0) / (graph[s].len() - 1) as f64;
        }
        //// eprintln!("s = {}, t = {}, prob = {}, exp = {}, new_exp = {}", s, t, prob, exp, new_exp);
        let res2 = origin - exp * prob + new_exp * prob;
        //// eprintln!("res2 = {}", res2);
        if res > res2 {
            res = res2;
        }
    }
    /*
    let mut res = f(&graph, (n,n));
    for &(s,t) in &es {
        let t = f(&graph, (s,t));
        if res > t {
            res = t;
        }
    }
    */
    writeln!(buf, "{:.20}", res);
    buf
}

