fn main() {
    let input = read_stdin();
    let tokens = &mut input.split_whitespace();
    let n: usize = scan(tokens);
    let m: usize = scan(tokens);
    let mut nexts = vec![Vec::new(); n];
    for _ in 0..m {
        let a: usize = scan(tokens);
        let b: usize = scan(tokens);
        nexts[a - 1].push(b - 1);
    }
    let mut p: Vec<f64> = vec![0.0; n];
    p[0] = 1.0;
    for i in 0..n {
        let x = p[i] / nexts[i].len() as f64;
        for &j in &nexts[i] {
            p[j] += x;
        }
    }
    let mut e: Vec<f64> = vec![0.0; n];
    let mut max: f64 = 0.0;
    for i in (0..n - 1).rev() {
        let k = nexts[i].len() as f64;
        let mut sum = 0.0;
        for &j in &nexts[i] {
            sum += e[j];
        }
        e[i] = 1.0 + sum / k;
        if nexts[i].len() > 1 {
            for &j in &nexts[i] {
                max = max.max(p[i] * (sum / k - (sum - e[j]) / (k - 1.0)));
            }
        }
    }
    println!("{}", e[0] - max);
}

