    };

    #[derive(PartialEq, PartialOrd)]
    pub struct Total<T>(pub T);

    impl<T: PartialEq> Eq for Total<T> {}

    impl<T: PartialOrd> Ord for Total<T> {
        fn cmp(&self, other: &Total<T>) -> std::cmp::Ordering {
            self.0.partial_cmp(&other.0).unwrap()
        }
    }

    let G = {
        let mut G = vec![std::collections::HashSet::new(); N + 1];
        for i in 0..M { G[s[i]].insert(t[i]); }
        G
    };
    const INF: f64 = 1_000_000_000.0;
    let mut dp = vec![0.0; N + 1];
    for i in (1..N).rev() { dp[i] = G[i].iter().map(|&j| 1.0 + dp[j]).sum::<f64>() / (G[i].len() as f64); }
    let ans = (1..N).map(|k|
        if G[k].len() == 1 { Total(dp[1]) }
        else {
            let l = G[k].iter().map(|&i| i).max_by_key(|&i| Total(dp[i])).unwrap();
            let mut dp2 = vec![0.0; N + 1];
            for i in (1..N).rev() {
                dp2[i] = if i == k {
                    G[i].iter().map(|&j|
                        if j == l { 0.0 }
                        else { 1.0 + dp2[j] }
                    ).sum::<f64>() / ((G[i].len() - 1) as f64)
                } else { G[i].iter().map(|&j| { 1.0 + dp2[j] }).sum::<f64>() / (G[i].len()as f64) };
            }
            Total(dp2[1])
    }).min().unwrap().0;

    println!("{}", ans);
}

macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String {
            bytes
                .by_ref()
                .map(|r| r.unwrap() as char)
                .skip_while(|c| c.is_whitespace())
                .take_while(|c| !c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };

    ($next:expr, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, [ $t:tt ]) => {
        {
            let len = read_value!($next, usize);
            (0..len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
        }
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

