fn search(g: &Vec<HashSet<usize>>) -> (f64, f64) {
    let n = g.len();
    let mut tab = vec![(0.0, 0.0); n];
    tab[0] = (1.0, 0.0);
    for i in 0..n - 1 {
        if g[i].len() == 0 && tab[i].0 > 0.0 {
            return (0.0, 600.0);
        }
        let p = 1.0 / g[i].len() as f64;
        for &c in g[i].iter() {
            tab[c].0 += tab[i].0 * p;
            tab[c].1 += (tab[i].1 + tab[i].0) * p;
        }
    }
    tab[n - 1]
}

