fn main() {
    input! {
        n: usize,
        m: usize,
        st: [(usize1, usize1); m],
    }

    let mut g = vec![vec![]; n];

    for (u, v) in st {
        g[u].push(v);
    }

    let mut ans = 1e10_f64;
    for i in 0..n {
        ans = ans.min(solve(0, &g, i, &mut vec![None; n]));
    }
    println!("{:.12}", ans);
}

fn solve(u: usize, g: &[Vec<usize>], i: usize, tbl: &mut [Option<f64>]) -> f64 {
    if u == tbl.len() - 1 {
        return 0.;
    }

    if let Some(ret) = tbl[u] {
        return ret;
    }

    let cs = g[u]
        .iter()
        .map(|&v| solve(v, g, i, tbl))
        .collect::<Vec<_>>();

    let sum: f64 = cs.iter().sum();
    let mut ret = sum / cs.len() as f64 + 1.;

    if u == i && cs.len() > 1 {
        for i in 0..cs.len() {
            ret = ret.min((sum - cs[i]) / (cs.len() - 1) as f64 + 1.0);
        }
    }

    tbl[u] = Some(ret);
    ret
}

