struct Rec {
    n: usize,
    g: Vec<Vec<usize>>,
    dp: Vec<Vec<Option<f64>>>,
}
impl Rec {
    fn solve(&mut self, s: usize, used: usize) -> f64 {
        if s == self.n-1 {
            return 0.0;
        }

        if let Some(v) = self.dp[s][used] {
            return v;
        }

        let mut minv = 1000000000 as f64;
        let ne = self.g[s].len();

        let p = 1.0 / ne as f64;
        let mut e = 0.0;
        // will not delete
        for i in 0..ne {
            let v = self.g[s][i];
            e += p * (1.0 + self.solve(v, used));
        }
        minv = e;

        if used == 1 {
            self.dp[s][used] = Some(minv);
            return minv;
        }

        if ne == 1 {
            self.dp[s][used] = Some(minv);
            return minv;
        }

        // will delete
        for j in 0..ne { // 消すやつ
            let p = 1.0 / (ne-1) as f64;
            let mut e = 0.0;
            for i in 0..ne {
                if i == j { continue; }
                let v = self.g[s][i];
                e += p * (1.0 + self.solve(v, 1));
            }
            if e < minv {
                minv = e;
            }
        }

        self.dp[s][used] = Some(minv);
        minv
    }
}
fn solve() {
    input!{
        n:usize,m:usize,
        e:[(usize,usize);m]
    }
    let mut g = vec![vec![];n];
    for i in 0..m {
        let (s,t) = e[i];
        g[s-1].push(t-1);
    }

    let mut rec = Rec {
        n: n,
        g: g,
        dp: dvec![None; n,2],
    };

    println!("{}", rec.solve(0, 0));
}

