fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, n: usize, m: usize, mut st: [(u1, u1); m]);
    let mut g = vec![vec![]; n];
    for &(s, t) in st.iter() {
        g[s].push(t)
    }
    let mut ret = std::f64::NAN;
    st.push((0, 0));
    for &stop in st.iter() {
        let r = dfs(0, n - 1, &g, stop);
        ret = ret.min(r);
    }
    println!("{}", ret);
}

fn dfs(u: usize, dest: usize, g: &Vec<Vec<usize>>, stop: (usize, usize)) -> f64 {
    if u == dest {
        return 0.;
    }
    let mut count = 0.;
    let mut ret = 0.;
    for &v in g[u].iter() {
        if (u, v) == stop {
            continue;
        }
        count += 1.;
        ret += dfs(v, dest, g, stop);
    }
    ret / count + 1.
}

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    solve(&s);
}

