use std::io::Read;

fn run() {
    let mut s = String::new();
    std::io::stdin().read_to_string(&mut s).unwrap();
    let mut it = s.trim().split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap();
    let m: usize = it.next().unwrap().parse().unwrap();
    let mut g = vec![vec![]; n];
    for _ in 0..m {
        let s: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;
        let t: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;
        g[s].push(t);
    }
    let mut dp = vec![0.0; n];
    for v in (0..(n - 1)).rev() {
        let p = 1.0 / (g[v].len() as f64);
        dp[v] = 1.0;
        for &u in &g[v] {
            dp[v] += p * dp[u];
        }
    }
    let mut ans = dp[0];
    for v in 0..(n - 1) {
        if g[v].len() == 1 {
            continue;
        }
        let mut dp = dp.clone();
        let mut sum = 0.0;
        for &u in &g[v] {
            sum += dp[u];
        }
        let p = 1.0 / (g[v].len() - 1) as f64;
        for &u in &g[v] {
            let t = 1.0 + (sum - dp[u]) * p;
            if t < dp[v] {
                dp[v] = t;
            }
        }
        for v in (0..v).rev() {
            let p = 1.0 / (g[v].len() as f64);
            dp[v] = 1.0;
            for &u in &g[v] {
                dp[v] += p * dp[u];
            }
        }
        if dp[0] < ans {
            ans = dp[0];
        }
    }
    println!("{:.9}", ans);
}

fn main() {
    run();
}

