use std::cmp::{Ord, Ordering};
#[derive(Clone, Copy, PartialEq, Eq, Debug, Default, Hash)]
pub struct Reverse<T: Ord>(pub T);
impl<T: Ord> PartialOrd for Reverse<T> {
    fn partial_cmp(&self, other: &Reverse<T>) -> Option<Ordering> {
        other.0.partial_cmp(&self.0)
    }
}
impl<T: Ord> Ord for Reverse<T> {
    fn cmp(&self, other: &Reverse<T>) -> Ordering {
        other.0.cmp(&self.0)
    }
}
pub trait SortDesc<T> {
    fn sort_desc(&mut self)
    where
        T: Ord;
    fn sort_desc_by_key<K: Ord, F: FnMut(&T) -> K>(&mut self, f: F);
}
impl<T> SortDesc<T> for [T] {
    fn sort_desc(&mut self)
    where
        T: Ord,
    {
        self.sort();
        self.reverse();
    }
    fn sort_desc_by_key<K: Ord, F: FnMut(&T) -> K>(&mut self, mut f: F) {
        self.sort_by_key(|x| Reverse(f(x)));
    }
}
#[derive(Clone, Copy, PartialEq, PartialOrd, Debug, Default, Hash)]
pub struct Total<T: PartialOrd + PartialEq>(pub T);
impl<T: PartialOrd + PartialEq> Eq for Total<T> {}
impl<T: PartialOrd + PartialEq> Ord for Total<T> {
    fn cmp(&self, other: &Self) -> Ordering {
        self.partial_cmp(other).unwrap()
    }
}

fn calc_exps(adj: &[Vec<usize>], dp: &mut [f64]) {
    for s in (0..adj.len()-1).rev() {
        let len = adj[s].len() as f64;
        dp[s] = 1.0 + adj[s].iter().map(|&t| dp[t]).sum::<f64>() / len;
    }
}

fn main() {
    read!(n = usize, _ = usize);
    let mut adj = vec![vec![]; n];
    readx_loop!(|s = usize_, t = usize_| {
        adj[s].push(t);
    });
    let mut es = vec![0.0; n];
    calc_exps(&adj, &mut es);

    let mut ans = es[0];
    for s in 0..n-1 {
        if adj[s].len() <= 1 {
            continue;
        }
        let t = *adj[s].iter().max_by_key(|&&t| Total(es[t])).unwrap();

        for i in 0..adj[s].len() {
            if adj[s][i] == t {
                adj[s].remove(i);
                break;
            }
        }
        calc_exps(&adj, &mut es);
        if es[0] < ans {
            ans = es[0];
        }
        adj[s].push(t);
    }
    println!("{}", ans);
}

