const M: i64 = 1_000_000_007;

fn main() {
    let mut sc = Scanner::new();
    let n: usize = sc.cin();
    let m: usize = sc.cin();
    let mut g = vec![vec![]; n];
    for _ in 0..m {
        let s = sc.cin::<usize>() - 1;
        let t = sc.cin::<usize>() - 1;
        g[s].push(t);
    }
    let mut ecands = vec![];
    for i in 0..n {
        if g[i].len() <= 1 { continue }
        g[i].sort();
        ecands.push((i, g[i][0]));
    }
    let mut ans;
    {
        let mut dp = vec![0.0f64; n];
        for i in (0..n-1).rev() {
            let deg = g[i].len();
            let p = 1.0 / (deg as f64);
            dp[i] = 1.0;
            for &j in g[i].iter() {
                dp[i] += dp[j] * p;
            }
        }
        ans = dp[0];
    }
    for k in 0..ecands.len() {
        let (sx, tx) = ecands[k];
        let mut dp = vec![0.0f64; n];
        for i in (0..n-1).rev() {
            let deg = {
                if sx == i {
                    g[i].len() - 1
                } else {
                    g[i].len()
                }
            };
            let p = 1.0 / (deg as f64);
            dp[i] = 1.0;
            for &j in g[i].iter() {
                if i == sx && j == tx { continue }
                dp[i] += dp[j] * p;
            }
        }
        ans = min!(ans, dp[0]);
    }
    put!(ans);
}

use std::io::{self, Write};
