use std::collections::VecDeque;

struct Scanner { stdin: io::Stdin, buffer: VecDeque<String>, }
impl Scanner {
    fn new() -> Self { Scanner { stdin: io::stdin(), buffer: VecDeque::new() } }
    fn cin<T: FromStr>(&mut self) -> T {
        while self.buffer.len() == 0 {
            let mut line = String::new();
            let _ = self.stdin.read_line(&mut line);
            for w in line.split_whitespace() {
                self.buffer.push_back(String::from(w));
            }
        }
        self.buffer.pop_front().unwrap().parse::<T>().ok().unwrap()
    }
    fn chars(&mut self) -> Vec<char> { self.cin::<String>().chars().collect() }
    fn vec<T: FromStr>(&mut self, n: usize) -> Vec<T> { (0..n).map(|_| self.cin()).collect() }
}

use std::io::*;
use std::str::FromStr;

#[allow(dead_code)]
fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

fn calc(
    target: usize,
    depth: usize,
    nexts: &Vec<Vec<usize>>,
    memo: &mut Vec<Vec<Option<f64>>>,
) -> f64 {
    let n = nexts.len();
    let target = if target < depth { 0 } else { target };
    if depth == n - 1 {
        return 0.0;
    }
    if let Some(v) = memo[target][depth] {
        return v;
    }
    let mut nrets = vec![];
    let mut sum = 0.0;
    for &t in nexts[depth].iter() {
        let v = 1.0 + calc(target, t, nexts, memo);
        sum += v;
        nrets.push(v);
    }
    let mut ret = sum / nexts[depth].len() as f64;
    if target == depth && nexts[depth].len() != 1 {
        nrets.sort_by(|lhs, rhs| lhs.partial_cmp(rhs).unwrap());
        sum -= nrets.last().unwrap();
        ret = sum / (nexts[depth].len() - 1) as f64;
    }
    memo[target][depth] = Some(ret);
    return ret;
}

fn main() {
    let n = read::<usize>();
    let m = read::<usize>();
    let mut nexts = vec![vec![]; n];
    for _i in 0..m {
        let s = read::<usize>() - 1;
        let t = read::<usize>() - 1;
        nexts[s].push(t);
    }
    let mut memo = vec![vec![None; n]; n];
    let mut ans = 1e+10;
    for i in 0..n {
        let nans = calc(i, 0, &nexts, &mut memo);
        if nans < ans {
            ans = nans;
        }
    }
    println!("{:.8}", ans)
}

use std::collections::BTreeSet;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let m: usize = sc.read();
    let mut dag = vec![BTreeSet::new(); n];
    let mut inv_dag = vec![BTreeSet::new(); n];
    for _ in 0..m {
        let s = sc.read::<usize>() - 1;
        let t = sc.read::<usize>() - 1;
        dag[s].insert(t);
        inv_dag[t].insert(s);
    }

    let dp = calc(&dag, &inv_dag);
    let mut ans = dp[0];
    for from in 0..n {
        if dag[from].len() <= 1 {
            continue;
        }
        if let Some(&next) = dag[from]
            .iter()
            .max_by(|&&next_a, &&next_b| dp[next_a].partial_cmp(&dp[next_b]).unwrap())
        {
            dag[from].remove(&next);
            inv_dag[next].remove(&from);

            ans = ans.min(calc(&dag, &inv_dag)[0]);

            dag[from].insert(next);
            inv_dag[next].insert(from);
        }
    }

    println!("{}", ans);
}

fn calc(dag: &Vec<BTreeSet<usize>>, inv_dag: &Vec<BTreeSet<usize>>) -> Vec<f64> {
    let n = dag.len();
    let mut dp = vec![0.0; n];
    for i in (1..n).rev() {
        let cur = dp[i];
        let next = cur + 1.0;
        for &prev in inv_dag[i].iter() {
            dp[prev] += next / (dag[prev].len() as f64);
        }
    }
    dp
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

fn main() {
	let mut s = String::new();
	use std::io::Read;
	std::io::stdin().read_to_string(&mut s).unwrap();
	let mut s = s.split_whitespace();
	let n: usize = s.next().unwrap().parse().unwrap();
	let m: usize = s.next().unwrap().parse().unwrap();
	let mut edges = vec![];
	for _ in 0..m {
		let a = s.next().unwrap().parse::<usize>().unwrap() - 1;
		let b = s.next().unwrap().parse::<usize>().unwrap() - 1;
		edges.push((a, b));
	}
	edges.sort();
	let calc = |invalid| {
		let mut dp = vec![(0., 0.); n];
		let mut visit = vec![false; n];
		dp[0].1 = 1.;
		visit[0] = true;

		let mut li = 0;
		let mut ri = 0;
		while li < edges.len() {
			li = ri;
			let src = edges[li].0;
			while ri < edges.len() && src == edges[ri].0 {
				ri += 1;
			}
			let cnt = ri - li - if li <= invalid && invalid < ri { 1 } else { 0 };
			if cnt == 0 {
				dp[n - 1].0 = 1000.;
			}
			let cnt = cnt as f64;
			for i in li..ri {
				if i == invalid {
					continue;
				}
				let to = edges[i].1;
				visit[to] |= visit[src];
				dp[to].0 += (dp[src].0 + dp[src].1) / cnt;
				dp[to].1 += dp[src].1 / cnt;
			}
			li = ri;
		}
		if visit[n - 1] {
			Some(dp[n - 1].0)
		} else {
			None
		}
	};

	let mut ans = 1000.;
	for i in 0..=edges.len() {
		if let Some(r) = calc(i) {
			if r < ans {
				ans = r;
			}
		}
	}
	println!("{}", ans);
}

const MAX_N: usize = 600;
const MAX_M: usize = MAX_N * MAX_N / 2;
fn solve() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let m: usize = sc.read();
    let mut edges = vec![vec![]; MAX_M];
    for _ in 0..m {
        let s: usize = sc.read::<usize>() - 1;
        let t: usize = sc.read::<usize>() - 1;
        edges[s].push(t);
    }
    let mut result = 1e10;
    for i in (0..n - 1).rev() {
        let mut dp = vec![1e10; n];
        dp[n - 1] = 0.0;
        for j in (0..n - 1).rev() {
            let mut sum = 0.0;
            let mut max_value = 0.0;
            for &x in edges[j].iter() {
                sum += (1.0 + dp[x]);
                assert!(j < x);
                // println!("x: {}", x);
                if max_value < 1.0 + dp[x] {
                    max_value = 1.0 + dp[x];
                }
            }
            let b = edges[j].len() as f32;
            //println!("{}", b);
            dp[j] = sum / b;
            if i == j && edges[j].len() > 1 {
                let tmp = (sum - max_value) / (b - 1.0);
                if dp[j] > tmp {
                    dp[j] = tmp;
                }
            }
            //println!("i: {}, j: {}, dp[{}]: {}, sum: {}", i, j, j, dp[j], sum);
        }
        if result > dp[0] {
            result = dp[0];
        }
    }
    println!("{}", result);
}

fn main() {
    std::thread::Builder::new()
        .stack_size(64 * 1024 * 1024) // 64MB
        .spawn(|| solve())
        .unwrap()
        .join()
        .unwrap();
}

