use std::io::Read;

fn run() {
    let mut s = String::new();
    std::io::stdin().read_to_string(&mut s).unwrap();
    let mut it = s.trim().split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap();
    let m: usize = it.next().unwrap().parse().unwrap();
    let mut g = vec![vec![]; n];
    for _ in 0..m {
        let s: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;
        let t: usize = it.next().unwrap().parse::<usize>().unwrap() - 1;
        g[s].push(t);
    }
    let mut dp = vec![0.0; n];
    for v in (0..(n - 1)).rev() {
        dp[v] = g[v].iter().fold(0.0, |s, u| s + dp[*u]) / g[v].len() as f64 + 1.0;
    }
    let mut prob = vec![0.0; n];
    prob[0] = 1.0;
    for v in 0..(n - 1) {
        let p = prob[v] / (g[v].len() as f64);
        for &u in &g[v] {
            prob[u] += p;
        }
    }
    let mut ans = dp[0];
    for v in 0..(n - 1) {
        if g[v].len() == 1 {
            continue;
        }
        let d = g[v].len() as f64;
        let s = (dp[v] - 1.0) * d;
        let p = 1.0 / (d - 1.0);
        let a = dp[0] - prob[v] * dp[v];
        for &u in &g[v] {
            let t = a + prob[v] * (1.0 + (s - dp[u]) * p);
            ans = ans.min(t);
        }
    }
    println!("{:.9}", ans);
}

fn main() {
    run();
}

