use std::cmp::{Ord, Ordering};
#[derive(Clone, Copy, PartialEq, Eq, Debug, Default, Hash)]
pub struct Reverse<T: Ord>(pub T);
impl<T: Ord> PartialOrd for Reverse<T> {
    fn partial_cmp(&self, other: &Reverse<T>) -> Option<Ordering> {
        other.0.partial_cmp(&self.0)
    }
}
impl<T: Ord> Ord for Reverse<T> {
    fn cmp(&self, other: &Reverse<T>) -> Ordering {
        other.0.cmp(&self.0)
    }
}
pub trait SortDesc<T> {
    fn sort_desc(&mut self)
    where
        T: Ord;
    fn sort_desc_by_key<K: Ord, F: FnMut(&T) -> K>(&mut self, f: F);
}
impl<T> SortDesc<T> for [T] {
    fn sort_desc(&mut self)
    where
        T: Ord,
    {
        self.sort();
        self.reverse();
    }
    fn sort_desc_by_key<K: Ord, F: FnMut(&T) -> K>(&mut self, mut f: F) {
        self.sort_by_key(|x| Reverse(f(x)));
    }
}
#[derive(Clone, Copy, PartialEq, PartialOrd, Debug, Default, Hash)]
pub struct Total<T: PartialOrd + PartialEq>(pub T);
impl<T: PartialOrd + PartialEq> Eq for Total<T> {}
impl<T: PartialOrd + PartialEq> Ord for Total<T> {
    fn cmp(&self, other: &Self) -> Ordering {
        self.partial_cmp(other).unwrap()
    }
}

fn calc_exps(adj: &[Vec<usize>], dp: &mut [f64]) {
    for s in (0..adj.len()-1).rev() {
        let len = adj[s].len() as f64;
        dp[s] = 1.0 + adj[s].iter().map(|&t| dp[t]).sum::<f64>() / len;
    }
}

fn main() {
    read!(n = usize, _ = usize);
    let mut adj = vec![vec![]; n];
    readx_loop!(|s = usize_, t = usize_| {
        adj[s].push(t);
    });
    let mut es = vec![0.0; n];
    calc_exps(&adj, &mut es);

    let mut edges = vec![];
    for s in 0..n-1 {
        if adj[s].len() <= 1 {
            continue;
        }
        let t = *adj[s].iter().max_by_key(|&&t| Total(es[t])).unwrap();
        edges.push((s, t));
    }

    let mut e = es[0];
    for (s, t) in edges {
        for i in 0..adj[s].len() {
            if adj[s][i] == t {
                adj[s].remove(i);
                break;
            }
        }
        calc_exps(&adj, &mut es);
        if es[0] < e {
            e = es[0];
        }
        adj[s].push(t);
    }
    println!("{}", e);
}

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let m: usize = sc.read();
    let mut graph = vec![vec![]; n];
    let mut inv = vec![vec![]; n];
    for _ in 0..m {
        let s = sc.read::<usize>() - 1;
        let t = sc.read::<usize>() - 1;
        graph[s].push(t);
        inv[t].push(s);
    }

    let p = calc(&graph);
    let mut ans = p[0];
    for i in 0..n {
        if graph[i].len() == 1 {
            continue;
        }
        if let Some(&next) = graph[i]
            .iter()
            .max_by(|&&next_a, &&next_b| p[next_a].partial_cmp(&p[next_b]).unwrap())
        {
            let mut new_graph = vec![vec![]; n];
            for from in 0..n {
                for &to in graph[from].iter() {
                    if (from, to) == (i, next) {
                        continue;
                    }
                    new_graph[from].push(to);
                }
            }

            let p = calc(&new_graph)[0];
            if ans > p {
                ans = p;
            }
        }
    }

    println!("{}", ans);
}

fn calc(graph: &Vec<Vec<usize>>) -> Vec<f64> {
    let n = graph.len();
    let mut p = vec![0.0; n];
    for i in (0..n).rev() {
        let edges = graph[i].len() as f64;
        for &next in graph[i].iter() {
            p[i] += (p[next] + 1.0) / edges;
        }
    }
    p
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> IO<R, W> {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: std::ops::Deref<Target = str>>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}
